const diffHljsLoader = window.__worcaTestHooks?.hljsLoader ?? createHljsLoader();

// A test-only size knob, read once per app.js instance (tests set window.__worcaTestHooks before
// their cache-busted import). Anything but a positive integer keeps the production value.
function testHookInt(name, fallback) {
  const v = window.__worcaTestHooks?.[name];
  return Number.isInteger(v) && v > 0 ? v : fallback;
}

// One markdown pipeline for the whole page — Ask answers AND diff-comment bodies
// (D15): marked + DOMPurify from the vendor routes, the test hook first. This is
// the exact loader the Ask panel construction used to build inline; it is hoisted
// so the comment layer can share it, and createAskPanel now receives it by name.
const loadAskMarkdown = window.__worcaTestHooks?.askMarkdown
  ?? (() => Promise.all([import('/vendor/marked/marked.esm.js'), import('/vendor/dompurify/purify.es.mjs')])
    .then(([m, d]) => ({ marked: m.marked, createDOMPurify: d.default })));
const hdMarkdown = createMarkdownRenderer({ doc: document, load: loadAskMarkdown, hljsLoader: diffHljsLoader });

// Bind markdown-by-contract text (a workspace description, an edit preview, a task
// body) into `el`: rendered through the page's sanitized pipeline when the bundle is
// ready, the same words as plain text otherwise. The document class rides only on a
// rendered body, so the plain fallback keeps the host's own pre-like look. Returns
// true when it rendered; callers that paint before the bundle is ready repaint once
// bindMarkdownReady resolves.
function bindMarkdown(el, text) {
  const out = hdMarkdown.isReady() ? hdMarkdown.render(text) : { kind: 'plain' };
  el.classList.toggle('artifact-markdown', out.kind === 'md');
  if (out.kind === 'md') { el.replaceChildren(out.frag); void hdMarkdown.highlight(el); }
  else el.textContent = String(text ?? '');
  return out.kind === 'md';
}
// Kick the lazy bundle for a surface that binds markdown; resolves true once it can
// render (immediately when it already can), false when it failed to load.
function bindMarkdownReady() {
  if (hdMarkdown.isReady()) return Promise.resolve(true);
  if (hdMarkdown.isFailed()) return Promise.resolve(false);
  return hdMarkdown.ensure();
}
// The renderer as the injectable seam a pure module takes (source-pane.mjs).
const pageMarkdown = (text) => (hdMarkdown.isReady() ? hdMarkdown.render(text) : { kind: 'plain' });

let askPanel = null;           // Ask Worca panel — assigned by the boot mount; every seam uses askPanel?.
let terminalPane = null;       // terminal pane (#573) — assigned by the boot mount; every seam uses terminalPane?.
let newPipelinePrefill = null; // one-shot card → New Pipeline handoff (§10.2 seam 7, consumed by Task 11)
// Engine readiness (GET /api/engines): which engines a usage-limit pause offers. Fetched on demand, refreshed after
// 60 s. null until an answer with an `engines` array arrives — then usageLimitSwitches offers every other engine.
// Every caller's onLoad runs when the answer lands (banner, history bar). A failed or engines-less answer is cached
// for the same 60 s, so a repaint loop never turns into a request loop. Up here, above every painter: painters can
// run before a later `let` line is reached (TDZ).
let engineReady = null; let engineReadyAt = 0; let engineReadyLoading = null; const engineReadyWaiters = new Set();
function readyEngines(onLoad) {
  if (Date.now() - engineReadyAt < 60_000) return engineReady;
  if (typeof onLoad === 'function') engineReadyWaiters.add(onLoad);
  if (!engineReadyLoading) {
    engineReadyLoading = fetch('/api/engines').then((r) => (r.ok ? r.json() : null)).catch(() => null).then((d) => {
      engineReady = Array.isArray(d?.engines) ? d.engines.filter((e) => e.ready).map((e) => e.name) : null;   // null: offer all
      engineReadyAt = Date.now();
      const waiters = [...engineReadyWaiters]; engineReadyWaiters.clear();
      for (const w of waiters) { try { w(); } catch { /* one painter must not stop the others */ } }
    }).finally(() => { engineReadyLoading = null; });
  }
  return engineReady;
}
/** Readiness only matters to a usage-limit pause an engine hit: any other run never asks. */
const readyFor = (pause, onLoad) => (pause?.reason === 'usage_limit' && pause?.limitEngine ? readyEngines(onLoad) : null);

