// Paint one model+effort select pair (and its caption) from a saved selection
// {model,effort}. Shared by the legacy default-stage rows and the dynamic
// per-node rows so the dropdown contents + effort filtering live in one place.
function renderModelEffortPair(modelSel, effortSel, caption, sel = {}) {
  // Model dropdown: "(default model)", then the models grouped — user-defined
  // (global + legacy project) first, plugin-provided second, built-ins third,
  // each group sorted alphabetically by label — then "+ Add model…".
  // Provenance is carried by the optgroup label, not a per-option suffix; only
  // when the same LABEL appears more than once does a plugin option get its
  // plugin name appended (design §9.6, collision-only), and the observed §4.6
  // "cost not verified" flag still marks an option.
  modelSel.innerHTML = '';
  modelSel.appendChild(option('', '(default model)'));
  // D10: New pipeline offers the run engine's models only — another engine's model would be
  // skipped at run time. `sel.engine` names another engine for a caller that has one.
  const engine = sel.engine || state.engine || 'claude';
  const ofEngine = (m) => (m.engine || 'claude') === engine;
  const byLabel = (a, b) => (a.label || a.id).localeCompare(b.label || b.id, undefined, { sensitivity: 'base' });
  const labelCounts = new Map();
  for (const m of state.models) {
    const lc = (m.label || m.id).toLowerCase();
    labelCounts.set(lc, (labelCounts.get(lc) || 0) + 1);
  }
  // A bridged model whose provider is not usable (model-bridge-design.md §8.5)
  // leaves the list — unless it is THIS selection, which is then labelled so.
  const usable = (m) => ofEngine(m) && (!m.needsSignIn || m.id === sel.model);
  const optgroup = (label, models) => {
    if (!models.length) return;
    const og = document.createElement('optgroup');
    og.label = label;
    for (const m of models) {
      const ambiguous = m.custom === 'plugin' && labelCounts.get((m.label || m.id).toLowerCase()) > 1;
      const viaSuffix = m.bridged && !(m.label || m.id).toLowerCase().includes(m.bridged) ? ` · ${m.bridged}` : '';
      og.appendChild(option(m.id,
        m.label + (ambiguous ? ` (${m.plugin})` : '') + viaSuffix + (m.costUnreliable ? ' ⚠cost' : '') + (m.needsSignIn ? ' (needs sign-in)' : '') + credentialSuffix(m.id)));
    }
    modelSel.appendChild(og);
  };
  optgroup('Your models', state.models.filter((m) => m.custom && m.custom !== 'plugin' && m.custom !== 'policy' && usable(m)).sort(byLabel));
  optgroup('Team policy', state.models.filter((m) => m.custom === 'policy' && usable(m)).sort(byLabel));
  optgroup('Plugins', state.models.filter((m) => m.custom === 'plugin' && usable(m)).sort(byLabel));
  // "Hide built-in models" (#422): a hidden built-in leaves the list — unless
  // it is THIS selection, which still resolves and must stay visible.
  optgroup('Built-in', state.models.filter((m) => !m.custom && ofEngine(m) && (!m.hidden || m.id === sel.model)).sort(byLabel));
  modelSel.appendChild(option('__add__', '+ Add model…'));
  modelSel.value = sel.model || '';

  // Effort dropdown: filtered to the selected model's supported efforts. With no
  // model there is no list to offer — which efforts are valid is a property of
  // the model — so the control is disabled. It SAYS so rather than just greying
  // out, because a dead dropdown next to a live one reads as a broken UI.
  const model = modelById(modelSel.value);
  effortSel.innerHTML = '';
  effortSel.appendChild(option('', model ? '(default effort)' : '(pick a model first)'));
  (model ? model.efforts : []).forEach((e) => effortSel.appendChild(option(e, e)));
  effortSel.value = sel.effort && model && model.efforts.includes(sel.effort) ? sel.effort : '';

  modelSel.disabled = false;
  effortSel.disabled = !model;
  effortSel.title = model ? '' : 'Pick a model first — the effort levels on offer are that model’s own.';

  if (caption) {
    const mLabel = model ? model.label : 'default model';
    caption.textContent = `${mLabel} · ${effortSel.value || 'default effort'}`
      + (model && model.needsSignIn ? ' — needs sign-in (Settings › Models › Providers)' : '');
    caption.classList.toggle('err', !!(model && model.needsSignIn));
  }
}

// The built-in Default workflow, client-side. Two jobs: (1) it is the topology
// the accordion paints when GET /api/workflows/wf_default cannot be reached, so a
// server hiccup never leaves the page without agent rows; (2) its labels/colors/
// descriptions are the fallback registry for those five keys when /api/agents
// fails — this is the markup the static #wf-default-stages block used to hold.
const DEFAULT_WF_TOPOLOGY = Object.freeze({
  id: 'wf_default',
  name: 'Default',
  steps: [
    [{ id: 's_clarify', key: 'clarify' }],
    [{ id: 's0_0', key: 'planner' }],
    [{ id: 's1_0', key: 'refiner' }],
    [{ id: 's2_0', key: 'implementer' }],
    [{ id: 's3_0', key: 'reviewer' }],
  ],
  feedbacks: [
    { id: 'fb_refine', from: 's1_0', to: 's1_0' },
    { id: 'fb_review', from: 's3_0', to: 's2_0' },
  ],
});

const DEFAULT_STAGE_META = Object.freeze({
  clarify: { displayName: 'Clarify', color: 'red', description: 'Turns hidden decisions into questions before planning' },
  planner: { displayName: 'Plan', color: 'violet', description: 'Explores the codebase and writes the implementation plan' },
  refiner: { displayName: 'Refine', color: 'green', description: 'Rewrites the latest plan into a tighter version' },
  implementer: { displayName: 'Implement', color: 'peach', description: 'Writes the code from the approved plan, strict TDD' },
  reviewer: { displayName: 'Review', color: 'blue', description: 'Reviews the implementation diff against the plan' },
});

// Registry for the Default workflow's rows, layered weakest-first: the static
// label/color map, then the per-step sidecar flags /api/config already delivered
// (fanOut / questions capability), then the live /api/agents entry. Any one layer
// can be missing and the rows still paint with real names and real capabilities.
function defaultWorkflowRegistry(fetched) {
  const out = {};
  for (const [key, base] of Object.entries(DEFAULT_STAGE_META)) {
    out[key] = { key, ...base, ...(state.stepDefaults[key] || {}), ...((fetched || {})[key] || {}) };
  }
  return { ...(fetched || {}), ...out };
}

// ---------------------------------------------------------------------------
// New-Pipeline workflow selector. Populates #workflowSelect from
// GET /api/workflows; on change, renders per-node model/effort pickers + per-
// feedback cycle inputs for the chosen workflow (or the legacy default stages).
// ---------------------------------------------------------------------------

// --- API wrappers (existing fetch()/safeJson style) ---
// Returns the workflow list, or null on failure — callers must distinguish
// "the server has no saved workflows" ([]) from "the list could not be
// fetched" (null), or a transient failure silently rebuilds the dropdown to
// Default-only and reroutes the next run to wf_default.
async function listWorkflowsApi() {
  try {
    const res = await fetch('/api/workflows');
    const data = await safeJson(res);
    return res.ok && Array.isArray(data.workflows) ? data.workflows : null;
  } catch { return null; }
}

async function getWorkflowApi(id) {
  if (state.workflowCache[id]) return state.workflowCache[id];
  try {
    const q = id === MEMORY_DEFRAG_WORKFLOW_ID ? `?engine=${state.engine}${state.projectDir ? `&projectDir=${encodeURIComponent(state.projectDir)}` : ''}` : '';
    const res = await fetch(`/api/workflows/${encodeURIComponent(id)}${q}`);
    const data = await safeJson(res);
    // Shape gate, both engines: a v2 graph carries `nodes`, a v1 template
    // `steps`. Demanding `steps` (the pre-P8 guard) rejected every stored row
    // once they all became graphs, which painted "Could not load this workflow."
    if (!res.ok || !data || !(Array.isArray(data.nodes) || Array.isArray(data.steps))) return null;
    state.workflowCache[id] = data;
    return data;
  } catch { return null; }
}

async function getAgentsApi() {
  if (Object.keys(state.agents).length) return state.agents;
  try {
    const res = await fetch('/api/agents');
    const data = await safeJson(res);
    const list = res.ok && Array.isArray(data.agents) ? data.agents : [];
    state.agents = Object.fromEntries(list.map((a) => [a.key, a]));
    return state.agents;
  } catch { return state.agents; }
}

// The script registry for the New-pipeline panel, fetched beside /api/agents (spec §8.4). Not cached:
// the workflow itself is re-fetched on every pick too, and a script added on disk must show up without
// a reload. A failed fetch degrades to agent-only loop rows ([]) — it never blocks the panel, because a
// script card carries no per-project tunables here.
async function getScriptsApi() {
  try {
    const res = await fetch('/api/scripts');
    const data = await safeJson(res);
    return res.ok && data && Array.isArray(data.scripts) ? data.scripts : [];
  } catch { return []; }
}

// Enabled-plugin names for workflow-picker labels (§9.3/§6.5). null = plugin
// list not known yet (fetch pending/failed) — workflowPickerLabel then skips
// the conservative "— disabled" flag. Refreshed once per view-open.
let enabledPluginNames = null;
async function loadEnabledPluginNames() {
  try {
    const res = await fetch('/api/plugins');
    const data = await safeJson(res);
    if (res.ok && Array.isArray(data.plugins)) {
      enabledPluginNames = data.plugins.filter((p) => p.enabled).map((p) => p.name);
      return;
    }
  } catch { /* endpoint absent/down -> suffix-free labels */ }
  enabledPluginNames = null;
}

// Fill #workflowSelect with Default + saved names, preserving/falling back to
// the active selection (state.workflowId), then render that workflow's config.
async function loadWorkflowsInto(selectId) {
  const sel = el.workflowSelect;
  if (!sel) return;
  const stale = bumpGen(sel);
  await loadEnabledPluginNames();
  const workflows = await listWorkflowsApi();
  if (stale()) return;                     // a newer rebuild of this picker was issued meanwhile
  if (workflows === null) {
    // List fetch failed: keep whatever the dropdown already shows (do NOT
    // rebuild to Default-only — that would silently reroute the next run) and
    // still render the current selection's config.
    appendLog({ source: 'ui', level: 'error', text: 'workflows: list failed', ts: Date.now() });
    await renderWorkflowConfig(state.workflowId);
    return;
  }
  const isWorkspace = state.runTarget === 'workspace';
  // Auto is a client-side constant (D24): /api/workflows never lists wf_auto and the row stub has no graph.
  const list = [AUTO_WORKFLOW, ...(workflows.length ? workflows : [{ id: 'wf_default', name: 'Default' }])];
  const want = selectId || state.workflowId || AUTO_WORKFLOW_ID;
  sel.innerHTML = '';
  // Simple mode (docs/ui-levels.md) offers Auto and Default only. The workflow already selected
  // stays listed whatever it is: a non-default value is never hidden from the run it applies to.
  const simplePicker = !levelAtLeast('advanced');
  list.forEach((wf) => {
    if (simplePicker && wf.id !== AUTO_WORKFLOW_ID && wf.id !== 'wf_default' && wf.id !== want) return;
    const o = option(wf.id, wf.id === AUTO_WORKFLOW_ID ? wf.name : (workflowPickerLabel(wf, enabledPluginNames) || wf.id));
    // Memory defragment holds exactly one scope, and a workspace run has no single project to
    // resolve `project` against (the server 400s) — so it is disabled on a workspace target.
    if (wf.id === MEMORY_DEFRAG_WORKFLOW_ID && isWorkspace) { o.disabled = true; o.title = 'Memory defragment runs on one project'; }
    sel.appendChild(o);
  });
  // Fall back to Default if the wanted id is gone (a deleted workflow). Memory defragment holds one
  // project scope, so a workspace target SHOWS Default in its place but never persists it.
  const known = list.some((wf) => wf.id === want);
  state.workflowId = !known || (isWorkspace && want === MEMORY_DEFRAG_WORKFLOW_ID) ? 'wf_default' : want;
  sel.value = state.workflowId;
  await renderWorkflowConfig(state.workflowId);
}

// Re-fill both New-Pipeline pickers from the server, dropping the per-id
// workflow memo so a workflow edited in Composer repaints with its saved
// topology. Keeps the active selections (loadWorkflowsInto/loadGuardrailsInto
// preserve state.workflowId / state.guardrailsId when the id still exists).
async function refreshNewPipelinePickers() {
  state.workflowCache = {};
  await loadWorkflowsInto(state.workflowId);
  await loadGuardrailsInto(state.guardrailsId);
}

// Returns the guardrail-set list, or null on failure — callers must distinguish
// "server answered" (built-ins are always present) from "the list could not be
// fetched" (null), or a transient failure silently rebuilds the dropdown to
// Permissive-only and reroutes the next run's policy.
async function listGuardrailsApi() {
  try {
    const res = await fetch('/api/guardrails');
    const data = await safeJson(res);
    return res.ok && Array.isArray(data.guardrails) ? data.guardrails : null;
  } catch { return null; }
}

// Hint: the SELECTED set's summary (raw 5-key counts via guardrailSummary — the
// run.json audit's denyCount additionally includes the Read/Edit expansion +
// lifted repo rules, so the hint speaks in list counts, not audit numbers).
function updateGuardrailsHint() {
  if (!el.guardrailsHint) return;
  const sel = state.guardrailSets.find((g) => g.id === state.guardrailsId) || null;
  if (!sel || sel.id === 'permissive') {
    el.guardrailsHint.textContent = 'Applies to every agent this run spawns. Permissive = no restrictions (the legacy default).';
    return;
  }
  const members = state.runTarget === 'workspace' ? ' across every workspace member' : '';
  el.guardrailsHint.textContent = `This run: ${guardrailSummary(sel.settings)} — applied uniformly${members}.`;
}

// Fill #guardrailsSelect with every named set (built-ins first — server order),
// preserving the active selection (state.guardrailsId). Mirrors loadWorkflowsInto.
async function loadGuardrailsInto(selectId) {
  const sel = el.guardrailsSelect;
  if (!sel) return;
  const stale = bumpGen(sel);
  const sets = await listGuardrailsApi();
  if (stale()) return;                     // a newer rebuild of this picker was issued meanwhile
  if (sets === null) {
    // List fetch failed: keep whatever the dropdown already shows (do NOT
    // rebuild to Permissive-only — that would silently reroute the next run's
    // policy) and note it non-blockingly in the log pane.
    appendLog({ source: 'ui', level: 'error', text: 'guardrails: list failed', ts: Date.now() });
    updateGuardrailsHint();
    return;
  }
  const list = sets.length ? sets : [{ id: 'permissive', name: 'Permissive', settings: null }];
  state.guardrailSets = list;
  const want = selectId || state.guardrailsId || 'permissive';
  sel.innerHTML = '';
  list.forEach((g) => sel.appendChild(option(g.id, g.id === 'permissive' ? 'Permissive (default)' : g.name)));
  // Fall back to the Permissive default if the wanted id is gone (deleted set) —
  // and SAY so via the form's message line: a vanished selection must never
  // silently revert while the user believes it is still selected.
  state.guardrailsId = list.some((g) => g.id === want) ? want : 'permissive';
  if (want !== 'permissive' && state.guardrailsId === 'permissive') {
    setFormMsg(`Guardrail set "${want}" no longer exists — this run will use Permissive (no restrictions).`, 'err');
  }
  sel.value = state.guardrailsId;
  updateGuardrailsHint();
  paintHiddenSettings();
  // A restored non-Permissive set is active state, so Advanced must not hide it.
}

// Render the config UI for one workflow. Default -> show the legacy 4 stage rows
// and hide the dynamic containers. Saved -> fetch topology + registry, render a
// node row per node and a cycle input per feedback.
async function renderWorkflowConfig(workflowId) {
  const isAuto = workflowId === AUTO_WORKFLOW_ID;
  if (el.agentsConfig) el.agentsConfig.hidden = isAuto;
  if (el.hitlRow) el.hitlRow.hidden = !isAuto;
  // Memory defragment (agent memory §7.3 / B11): the ONE run option that workflow needs. Every
  // path that changes the picker ends here, so this single line covers them all.
  if (el.memoryScopeRow) el.memoryScopeRow.hidden = workflowId !== MEMORY_DEFRAG_WORKFLOW_ID;
  // MCP registry (§6.1): a memory-defrag run starts no registry servers, so the control hides at
  // once; the policy-line repaint at the end refetches the preview for every other workflow.
  if (el.mcpRunsField) renderMcpRuns();
  if (isAuto) {
    // Auto picks the agents per run (spec §7.2 / D20): no accordion, one switch. On a project target
    // the switch is per PROJECT like the accordion's rows, read from the project config, and
    // saveHumanInLoop drops the write with no project selected — so disable it there instead of
    // accepting a flip the save discards (.sw-input:disabled + .switch is already styled). On a
    // workspace target it is per RUN (D-W1); agentsEditable() reads the hidden project select, so
    // the workspace arm must not consult it.
    if (el.humanInLoop) {
      if (state.runTarget === 'workspace') {
        // D-W1: a workspace has no stored switch — the value lives for this form only and rides the run body.
        el.humanInLoop.checked = state.wsHumanInLoop !== false;
        el.humanInLoop.disabled = false;
      } else {
        el.humanInLoop.checked = state.config.humanInLoop !== false;   // readRunConfig echoes only `false`
        el.humanInLoop.disabled = !agentsEditable();
      }
    }
    // Reset what the failed-fetch arm resets, so nothing from the previous workflow lingers inside the
    // hidden accordion (#wf-feedback-config and the agents header live INSIDE #agents-config).
    if (el.agentRows) el.agentRows.innerHTML = '';
    if (el.wfFeedbackConfig) { el.wfFeedbackConfig.innerHTML = ''; el.wfFeedbackConfig.hidden = true; }
    setAgentsHeader(null, '');
    return;
  }
  const isDefault = !workflowId || workflowId === 'wf_default';
  const [fetchedWf, fetchedReg, scripts] = await Promise.all([getWorkflowApi(workflowId), getAgentsApi(), getScriptsApi()]);
  // The Default workflow has offline fallbacks for both halves (topology + the
  // five stage metas), so it always paints. A saved workflow has neither: an
  // empty registry is a failed /api/agents fetch, not a real state, and painting
  // rows against it would silently strip capability (labels degrade to raw keys,
  // every questions toggle vanishes), so it is treated like a failed fetch.
  const wf = isDefault ? (fetchedWf || DEFAULT_WF_TOPOLOGY) : fetchedWf;
  const registry = isDefault ? defaultWorkflowRegistry(fetchedReg) : fetchedReg;
  if (!wf || !Object.keys(registry).length) {
    if (el.agentRows) el.agentRows.innerHTML = '<div class="hint">Could not load this workflow.</div>';
    if (el.wfFeedbackConfig) { el.wfFeedbackConfig.innerHTML = ''; el.wfFeedbackConfig.hidden = true; }
    setAgentsHeader(null, '');
    return;
  }
  const runConfig = (state.config.workflows && state.config.workflows[workflowId]) || { nodes: {}, feedbacks: {} };
  // wf_default stores its overrides per ROLE (the legacy `steps` blob the CLI and
  // every older install write); saved workflows store them per node id.
  const rows = buildNodeConfigRows(wf, registry, runConfig,
    isDefault ? { legacySteps: state.config.steps || {} } : {});
  renderAgentRows(rows);
  renderFeedbackRows(buildFeedbackRows(wf, registry, runConfig, scripts));
  // The cycle inputs write through a different endpoint shape per engine
  // (v1 `feedbacks:{…}` vs v2 `wires:{…}`); stamp which one this row set is.
  if (el.wfFeedbackConfig) el.wfFeedbackConfig.dataset.graph = wf.version === 2 ? '1' : '';
  setAgentsHeader(rows, wf.name || workflowId);
  setAgentRowsEnabled(agentsEditable());
  if (currentView() === 'new') schedulePolicyLine();   // the picked models changed with the workflow (board 8)
}

// Per-agent config is stored PER PROJECT, so with no project selected there is
// nowhere to write it. Rows still render (seeing what a workflow will do is
// useful on its own) but every control is disabled and the header says why —
// previously an edit was accepted, silently dropped by the save, and then
// reverted by the re-render, which read as "the control doesn't work".
function agentsEditable() {
  return !!selectedProjectPath();
}

/** Disable (or re-enable) every control in the accordion. */
function setAgentRowsEnabled(enabled) {
  const host = el.agentRows;
  if (!host) return;
  for (const c of host.querySelectorAll('.step-model,.step-fanout,.step-questions,.step-subagent')) {
    // data-locked: a manifest-fixed questions toggle, or a model Settings › Memory pins.
    c.disabled = !enabled || c.dataset.locked === '1';
  }
  for (const e of host.querySelectorAll('.step-effort')) {
    // Keep the model-dependency rule: effort stays disabled without a model.
    if (!enabled) e.disabled = true;
  }
  if (el.wfFeedbackConfig) {
    for (const i of el.wfFeedbackConfig.querySelectorAll('input[data-fb-id]')) i.disabled = !enabled;
  }
}

// Paint the accordion header: the "all defaults / N modified" summary plus the
// two actions, which only appear when they would do something.
function setAgentsHeader(rows, workflowName) {
  const editable = agentsEditable();
  // The picker sits up with the task now, so the header has to say which
  // workflow these rows belong to.
  if (el.agentsWorkflow) el.agentsWorkflow.textContent = workflowName || '';
  if (el.agentsSummary) {
    el.agentsSummary.textContent = !rows ? ''
      : (editable ? agentsHeaderText(rows) : 'select a project to change these');
    el.agentsSummary.classList.toggle('muted', !editable);
  }
  const anyModified = editable && !!rows && rows.some((r) => r.modified);
  if (el.agentsReset) el.agentsReset.hidden = !anyModified;
  if (el.agentsPromote) {
    // A graph BUILT-IN is frozen and never persisted, so it has no row to carry defaults
    // (design D6) — offering the button there would only fail (setWorkflowNodeDefaults throws).
    const canPromote = anyModified && state.workflowId && !isReservedWorkflowId(state.workflowId);
    el.agentsPromote.hidden = !canPromote;
  }
  paintHiddenSettings();
}

// New pipeline × interface mode (docs/ui-levels.md): a setting made in a higher mode keeps
// applying to the run, so it must not vanish. A gated field OUTSIDE the Advanced disclosure that
// holds a non-default value is simply kept on screen; what sits INSIDE the (hidden) disclosure is
// named in one line above Start run, with the switch that reveals it.
function paintHiddenSettings() {
  const note = document.getElementById('level-hidden-note');
  if (!note) return;
  const sourceIsPrompt = !!document.querySelector('#source-seg [data-src="prompt"].on');
  keepVisible(document.getElementById('target-field'), state.runTarget === 'workspace');
  keepVisible(document.getElementById('source-field'), !sourceIsPrompt);
  keepVisible(document.getElementById('branch-fields'), !!(el.featureBranch && el.featureBranch.value.trim()));
  const items = [];
  if (!levelAtLeast('advanced')) {
    const gr = (state.guardrailSets || []).find((g) => g.id === state.guardrailsId);
    if (state.guardrailsId && state.guardrailsId !== 'permissive') items.push(`${(gr && gr.name) || state.guardrailsId} guardrails`);
    const n = Object.values(agentRowsById || {}).filter((r) => r && r.modified).length;
    if (n) items.push(n === 1 ? '1 agent override' : `${n} agent overrides`);
    const hitlRow = document.getElementById('hitl-row');
    if (el.humanInLoop && hitlRow && !hitlRow.hidden && !el.humanInLoop.checked) items.push('Human in the loop off');
  }
  note.hidden = !items.length;
  if (!items.length) return;
  const text = document.getElementById('level-hidden-text');
  text.textContent = '';
  const b = document.createElement('b');
  b.textContent = items.join(' · ');
  text.append('Set in Advanced mode and still applied to this run: ', b, '.');
  const sw = document.getElementById('level-hidden-show');
  sw.textContent = 'Switch to Advanced'; sw.dataset.modeSet = 'advanced';   // same words as the page banner
}

// Build the agents accordion into #agents-rows: one collapsed .agent-row per node
// (accent + name + effective-config caption + modified dot), whose body holds the
// same model/effort/fan-out/questions controls the old always-open .stage-cfg card
// did — same classes and data-node-id, so the delegated change handler and
// renderModelEffortPair are unchanged (newpipeline-ux-design.md §4.2).
function renderAgentRows(rows) {
  const host = el.agentRows;
  if (!host) return;
  host.innerHTML = '';
  agentRowsById = Object.fromEntries(rows.map((r) => [r.nodeId, r]));
  // Rows that vanished (workflow switched) must not keep the accordion open.
  const ids = new Set(rows.map((r) => r.nodeId));
  for (const id of [...openAgentRows]) if (!ids.has(id)) openAgentRows.delete(id);

  rows.forEach((row) => {
    const open = openAgentRows.has(row.nodeId);
    const bodyId = `agent-body-${row.nodeId}`;

    const card = document.createElement('div');
    card.className = 'agent-row' + (open ? ' open' : '');
    card.dataset.nodeId = row.nodeId;

    // --- collapsed head (the whole row is one button: click or Enter/Space) ---
    const head = document.createElement('button');
    head.type = 'button';
    head.className = 'agent-row-head';
    head.dataset.nodeId = row.nodeId;
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    head.setAttribute('aria-controls', bodyId);

    const chev = document.createElement('span');
    chev.className = 'agent-chev';
    chev.setAttribute('aria-hidden', 'true');

    const acc = document.createElement('span');
    acc.className = 'acc' + (row.color ? ' ' + row.color : '');

    const name = document.createElement('span');
    name.className = 'agent-name';
    name.textContent = row.label;
    name.title = row.description || row.label;

    const step = document.createElement('span');
    step.className = 'agent-step';
    step.textContent = row.parallel ? `step ${row.stepIndex + 1} · parallel` : `step ${row.stepIndex + 1}`;

    const sum = document.createElement('span');
    sum.className = 'agent-sum';
    sum.dataset.nodeId = row.nodeId;
    sum.textContent = agentSummaryText(row);

    head.append(chev, acc, name, step, sum);
    if (row.modified) {
      const dot = document.createElement('span');
      dot.className = 'agent-mod';
      dot.title = 'Overrides this workflow’s default';
      dot.textContent = '●';
      head.appendChild(dot);
    }
    card.appendChild(head);

    // --- expanded body: the controls, unchanged in class + data contract ---
    const body = document.createElement('div');
    body.className = 'agent-row-body';
    body.id = bodyId;
    body.hidden = !open;

    // What this agent does, in full. The collapsed head has no room for it, so
    // the blurb lives here where it can wrap instead of being ellipsized away.
    if (row.description) {
      const desc = document.createElement('small');
      desc.className = 'agent-desc';
      desc.textContent = row.description;
      body.appendChild(desc);
    }

    const picks = document.createElement('div');
    picks.className = 'picks';
    const mWrap = document.createElement('div');
    mWrap.className = 'select-wrap';
    const modelSel = document.createElement('select');
    modelSel.className = 'step-model select';
    modelSel.dataset.nodeId = row.nodeId;
    if (row.role) modelSel.dataset.role = row.role;
    modelSel.setAttribute('aria-label', `${row.label} model`);
    mWrap.appendChild(modelSel);
    const eWrap = document.createElement('div');
    eWrap.className = 'select-wrap';
    const effortSel = document.createElement('select');
    effortSel.className = 'step-effort select';
    effortSel.dataset.nodeId = row.nodeId;
    if (row.role) effortSel.dataset.role = row.role;
    effortSel.setAttribute('aria-label', `${row.label} effort`);
    eWrap.appendChild(effortSel);
    const fanWrap = document.createElement('label');
    fanWrap.className = 'fanout-toggle';
    const fanCb = document.createElement('input');
    fanCb.type = 'checkbox';
    fanCb.className = 'step-fanout';
    fanCb.dataset.nodeId = row.nodeId;
    if (row.role) fanCb.dataset.role = row.role;
    fanCb.setAttribute('aria-label', `${row.label} fan-out`);
    fanCb.checked = !!row.fanOut;
    const fanTxt = document.createElement('span');
    fanTxt.textContent = 'Fan-out';
    fanWrap.append(fanCb, fanTxt);
    // Sub-agent model: what this node's Task children run on. Rendered beside
    // Fan-out (whose children it governs) and, like it, offered on every agent —
    // the row's own fan-out toggle is what decides whether it bites.
    const sWrap = document.createElement('div');
    sWrap.className = 'select-wrap';
    const subSel = document.createElement('select');
    subSel.className = 'step-subagent select';
    subSel.dataset.nodeId = row.nodeId;
    if (row.role) subSel.dataset.role = row.role;
    subSel.setAttribute('aria-label', `${row.label} sub-agent model`);
    subSel.title = 'Model for the sub-agents this node spawns (needs fan-out)';
    renderSubagentModelSelect(subSel, row.subagentModel);
    sWrap.appendChild(subSel);
    picks.append(mWrap, eWrap, fanWrap, sWrap);
    // Model and effort are advanced (the accordion's own level); the three below are expert
    // (docs/ui-levels.md). One that deviates from its default stays on screen at any mode.
    const rowDef = row.def || {};
    keepVisible(tagLevel(fanWrap, 'expert'), !!row.fanOut !== !!rowDef.fanOut);
    keepVisible(tagLevel(sWrap, 'expert'), (row.subagentModel || '') !== (rowDef.subagentModel || ''));
    // Only a Claude run has a sub-agent model to pick: Codex has its own spawn_agent, Copilot's sub-agents run on the
    // node's own model, and Cursor has none.
    if (state.engine !== 'claude') sWrap.hidden = true;
    if (row.askQuestions !== null && row.askQuestions !== undefined) {
      const qWrap = document.createElement('label');
      qWrap.className = 'fanout-toggle questions-toggle';
      if (row.questionsLocked) {
        qWrap.title = row.askQuestions ? 'Always on for this agent' : 'Always off for this agent';
      }
      const qCb = document.createElement('input');
      qCb.type = 'checkbox';
      qCb.className = 'step-questions';
      qCb.dataset.nodeId = row.nodeId;
      if (row.role) qCb.dataset.role = row.role;
      qCb.setAttribute('aria-label', `${row.label} questions`);
      qCb.checked = !!row.askQuestions;
      qCb.disabled = !!row.questionsLocked;
      // Marked so re-enabling the accordion (project selected) cannot un-lock an
      // agent whose questions setting is fixed by its manifest.
      if (row.questionsLocked) qCb.dataset.locked = '1';
      const qTxt = document.createElement('span');
      qTxt.textContent = 'Questions';
      qWrap.append(qCb, qTxt);
      keepVisible(tagLevel(qWrap, 'expert'), !row.questionsLocked && !!row.askQuestions !== !!rowDef.askQuestions);
      picks.appendChild(qWrap);
    }
    body.appendChild(picks);

    // Where this row's values come from when nothing is overridden — the answer
    // to "what does 'default' actually mean here", without opening a doc.
    const origin = document.createElement('small');
    origin.className = 'agent-origin';
    origin.textContent = row.pinned ? PINNED_PAIR_TEXT : defaultOriginText(row);
    body.appendChild(origin);
    // A pick of the other engine was healed off this run's row (D10) but stays stored and is
    // re-sent on save: say so, so it is never invisible — picking a model here replaces it.
    if (row.enginePair && row.enginePair.model) {
      const entry = modelById(row.enginePair.model);
      // The model's own engine; a pick the catalog no longer holds belongs to an engine this run is not on.
      const owner = entry ? engineLabel(entry.engine || 'claude') : null;
      const kept = document.createElement('small');
      kept.className = 'agent-kept-pick hint';
      kept.textContent = owner
        ? `Your ${owner} pick ${entry.label || row.enginePair.model} is kept for ${owner} runs — choose a model here to replace it.`
        : `Your pick ${row.enginePair.model} is kept for runs on its own engine — choose a model here to replace it.`;
      body.appendChild(kept);
    }

    card.appendChild(body);
    // The collapsed head IS this row's caption (`sum` above), so the controls get
    // no second one — renderModelEffortPair's caption slot stays empty and
    // paintRowSummary keeps the head in step with the live selects.
    renderModelEffortPair(modelSel, effortSel, null, { model: row.model, effort: row.effort });
    if (row.pinned) lockPinnedPair(modelSel, effortSel);
    host.appendChild(card);
  });
  applyFreeDailyToNewView();   // a :free model among the rows may need the allowance warning
}

// Fill a sub-agent model dropdown. '' is "unset" — the run resolves it to the
// auto default (the agent picks per spawn), so the blank option says exactly
// that instead of masquerading as a value. 'inherit' is the stored opt-out
// (children ride the CLI's own resolution: agent frontmatter, else this node's
// model); 'auto' is the stored form of the default.
function renderSubagentModelSelect(sel, value) {
  const label = (v) => (v === 'auto' ? 'subs: agent picks' : `subs: ${v}`);
  sel.innerHTML = '';
  sel.appendChild(option('', 'subs: default (agent picks)'));
  for (const v of state.subagentModels) sel.appendChild(option(v, label(v)));
  sel.value = state.subagentModels.includes(value) ? value : '';
}

// Repaint one row's collapsed caption from what its controls currently show, so
// the head never lags the selects between a change and the save's re-render.
function paintRowSummary(row, body) {
  const head = el.agentRows && el.agentRows.querySelector(`.agent-sum[data-node-id="${row.nodeId}"]`);
  if (!head) return;
  head.textContent = agentSummaryText({ ...row, ...liveRowValues(row, body) });
}

// Settings › Memory owns a Memory defragment run's model + effort (node-tunables.mjs `pinned`):
// shown, never edited here. `data-locked` keeps setAgentRowsEnabled from re-enabling them.
const PINNED_PAIR_TEXT = 'Set in Settings › Memory — every Memory defragment run uses this model, whatever this project picked.';
function lockPinnedPair(modelSel, effortSel) {
  for (const s of [modelSel, effortSel]) {
    s.disabled = true;
    s.dataset.locked = '1';
    s.title = 'Set in Settings › Memory';
  }
}

// One line naming what this row falls back to once its override is gone — the
// answer to "what does 'default' actually mean here", without opening a doc.
function defaultOriginText(row) {
  if (!row.def.model) return 'No model set for this workflow — falls back to the CLI’s own default.';
  const m = modelById(row.def.model);
  const label = m ? m.label : row.def.model;
  return `This workflow’s default: ${label}${row.def.effort ? ` · ${row.def.effort}` : ''}.`;
}

// Build the feedback-loop cycle counts as the accordion's LAST row (§4.2, D4):
// one number input per loop, keyed by data-fb-id, collapsed by default because 3
// cycles is the sensible default nobody needs to see. A workflow with no loops
// renders no row at all.
function renderFeedbackRows(rows) {
  const host = el.wfFeedbackConfig;
  if (!host) return;
  host.innerHTML = '';
  host.hidden = !rows.length;
  if (!rows.length) return;

  const open = openAgentRows.has(FEEDBACK_ROW_ID);
  const card = document.createElement('div');
  card.className = 'agent-row' + (open ? ' open' : '');
  card.dataset.nodeId = FEEDBACK_ROW_ID;

  const head = document.createElement('button');
  head.type = 'button';
  head.className = 'agent-row-head';
  head.dataset.nodeId = FEEDBACK_ROW_ID;
  head.setAttribute('aria-expanded', open ? 'true' : 'false');
  head.setAttribute('aria-controls', 'agent-body-feedbacks');

  const chev = document.createElement('span');
  chev.className = 'agent-chev';
  chev.setAttribute('aria-hidden', 'true');
  const acc = document.createElement('span');
  acc.className = 'acc neutral'; // not an agent: no registry colour to carry
  const name = document.createElement('span');
  name.className = 'agent-name';
  name.textContent = 'Feedback loops';
  const sum = document.createElement('span');
  sum.className = 'agent-sum';
  sum.textContent = rows.map((r) => `${r.label} ×${r.maxCycles}`).join(' · ');
  head.append(chev, acc, name, sum);
  card.appendChild(head);

  const body = document.createElement('div');
  body.className = 'agent-row-body';
  body.id = 'agent-body-feedbacks';
  body.hidden = !open;

  const h = document.createElement('div');
  h.className = 'hint';
  h.style.margin = '0 0 8px';
  h.textContent = 'Max cycles before the loop gates to you.';
  body.appendChild(h);

  rows.forEach((row) => {
    const field = document.createElement('div');
    field.className = 'field fb-field';

    const label = document.createElement('label');
    label.textContent = `${row.label} — max cycles`;
    label.setAttribute('for', `fb-${row.fbId}`);
    field.appendChild(label);

    const input = document.createElement('input');
    input.id = `fb-${row.fbId}`;
    input.className = 'input';
    input.type = 'number';
    input.min = '1';
    input.value = String(row.maxCycles);
    input.dataset.fbId = row.fbId;
    field.appendChild(input);

    body.appendChild(field);
  });

  card.appendChild(body);
  host.appendChild(card);
}

// Workflow change: remember the selection and re-render its config.
if (el.workflowSelect) {
  el.workflowSelect.addEventListener('change', async () => {
    state.workflowId = el.workflowSelect.value || 'wf_default';
    saveActiveWorkflow(state.workflowId);
    await renderWorkflowConfig(state.workflowId);
  });
}

/** Write the picker's Memory scope into state AND the segmented control. Used by the seg itself and
 *  by the Ask card handoff, whose proposal carries the scope it wants restructured (B17). */
function setMemoryScope(scope) {
  state.memoryScope = scope === 'project' ? 'project' : 'global';
  for (const b of el.memoryScopeSeg ? el.memoryScopeSeg.querySelectorAll('button[data-scope]') : []) {
    const on = b.dataset.scope === state.memoryScope;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
}

// Memory scope (Memory defragment only): a two-way segmented control, remembered per session.
if (el.memoryScopeSeg) {
  el.memoryScopeSeg.addEventListener('click', (e) => {
    const btn = e.target.closest && e.target.closest('button[data-scope]');
    if (!btn) return;
    setMemoryScope(btn.dataset.scope);
  });
}

// Engine (harness bridge §10.4): per run, never remembered — every New pipeline starts on Claude.
function setRunEngine(engine) {
  const prev = state.engine;
  state.engine = ENGINE_NAMES.includes(engine) ? engine : 'claude';
  for (const b of el.engineSeg ? el.engineSeg.querySelectorAll('button[data-engine]') : []) {
    const on = b.dataset.engine === state.engine;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
  paintEngineHints();
  showEngineRefusal(null);
  // D10: the agent rows offer the run engine's models only — repaint them for the new engine. The Sets
  // picker too: another engine names set skills as its .agents/skills mount would.
  if (prev !== state.engine) {
    void renderWorkflowConfig(state.workflowId);
    if (currentView() === 'new') schedulePolicyLine();
  }
}

function runSlotDefaults() { return state.runDefaults?.steps?.[state.engine] || null; }
function paintEngineHints() {
  if (el.engineHint) {
    el.engineHint.hidden = state.engine === 'claude';
    const project = Object.values(state.runDefaults?.steps?.[state.engine] || {}).some((s) => s?.source === 'project');
    el.engineHint.textContent = state.engine === 'copilot'
      ? 'GitHub Copilot CLI runs this pipeline, including titles and summaries, on its default model unless the run names one. Sign in once with copilot login.'
      : state.engine === 'cursor'
      ? `Cursor runs this pipeline. Helper jobs (titles, summaries) run on Claude. Step models: ${project ? 'project Settings' : 'Settings › Models › Cursor'}.`
      : `Codex runs this pipeline, including titles and summaries. Models: ${project ? 'project Settings' : 'Settings › Models › Codex'}`;
  }
  if (el.engineDefaultHint) {
    const source = state.runDefaults?.engine?.value === state.engine ? state.runDefaults.engine.source : null;
    el.engineDefaultHint.textContent = source === 'project' ? 'Default from project' : source === 'user' ? 'Default from your settings' : '';
    el.engineDefaultHint.hidden = !el.engineDefaultHint.textContent;
  }
}
let runDefaultsGen = 0;
async function loadRunDefaults(projectDir) {
  const gen = ++runDefaultsGen;
  let data = null;
  try { const res = await fetch(projectDir ? `/api/run-defaults?projectDir=${encodeURIComponent(projectDir)}` : '/api/run-defaults'); data = res.ok ? await safeJson(res) : null; } catch {}
  if (gen !== runDefaultsGen) return;
  const prevSteps = JSON.stringify(state.runDefaults?.steps ?? null);
  state.runDefaults = data?.engine && ENGINE_NAMES.includes(data.engine.value) ? data : null;
  if (state.runDefaults && !state.engineTouched) setRunEngine(data.engine.value); else paintEngineHints();
  // The rows show the slot defaults: repaint them only when those changed (setRunEngine repaints
  // on an engine change itself). An idle repaint re-arms the policy/MCP preview debounce.
  if (JSON.stringify(state.runDefaults?.steps ?? null) !== prevSteps) void renderWorkflowConfig(state.workflowId);
}

/** The gate's 409 under the form, with the consent when it lifts the refusal; null clears
 *  both. The consent is for one attempt: it never outlives the refusal that offered it. */
function showEngineRefusal(data) {
  if (!el.engineRefusal) return;
  el.engineRefusal.hidden = !data;
  el.engineRefusalText.textContent = data ? data.error || '' : '';
  el.engineAllowRow.hidden = !(data && data.overridable);
  if (!data || !data.overridable) el.engineAllowUnguarded.checked = false;
}

if (el.engineSeg) {
  for (const b of el.engineSeg.querySelectorAll('button[data-engine]')) {
    if (!isBetaEngine(b.dataset.engine)) continue;
    const beta = document.createElement('span');
    beta.className = 'badge violet beta-badge';
    beta.textContent = 'Beta';
    b.append(beta);
  }
  el.engineSeg.addEventListener('click', (e) => {
    const btn = e.target.closest && e.target.closest('button[data-engine]');
    if (!btn) return;
    state.engineTouched = true;
    setRunEngine(btn.dataset.engine);
  });
}

// Guardrails change: remember the run's set and refresh the summary hint.
if (el.guardrailsSelect) {
  el.guardrailsSelect.addEventListener('change', () => {
    state.guardrailsId = el.guardrailsSelect.value || 'permissive';
    state.guardrailsTouched = true;         // a team default never overrides a deliberate pick
    showEngineRefusal(null); // the refusal and any consent were for the OLD guardrail set
    updateGuardrailsHint();
    schedulePolicyLine();
  });
}

async function saveStep(role, model, effort, fanOut, askQuestions, subagentModel) {
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectDir, step: role, model, effort, fanOut, askQuestions, subagentModel }),
    });
    const data = await safeJson(res);
    if (!res.ok) {
      appendLog({ source: 'ui', level: 'error', text: `config: ${data.error || res.status}`, ts: Date.now() });
      await renderWorkflowConfig(state.workflowId); // revert UI to the last persisted state
      return;
    }
    state.config = data.config || state.config;
  } catch (e) {
    appendLog({ source: 'ui', level: 'error', text: `config error: ${e.message}`, ts: Date.now() });
  }
}

// What a row's controls CURRENTLY show. The visible state is the truth: reading
// it back (rather than the last-rendered row data, or state.config, which lags an
// in-flight save) is what keeps a toggle from reverting a model picked a moment
// earlier. A disabled questions box is the agent's locked value, never the user's.
function liveRowValues(row, body) {
  const host = body || (el.agentRows
    && el.agentRows.querySelector(`.agent-row[data-node-id="${row.nodeId}"] .agent-row-body`));
  if (!host) return {};
  const out = {};
  const m = host.querySelector('.step-model');
  const e = host.querySelector('.step-effort');
  const f = host.querySelector('.step-fanout');
  const q = host.querySelector('.step-questions');
  const sa = host.querySelector('.step-subagent');
  if (m) out.model = m.value === '__add__' ? row.model : m.value;
  if (e) out.effort = e.value;
  if (f) out.fanOut = f.checked;
  if (q && !q.disabled) out.askQuestions = q.checked;
  if (sa) out.subagentModel = sa.value;
  return out;
}

// Persist one accordion row, pruning any value that matches its resolved default
// back to "inherit" (§4.5) so the stored run-config stays sparse and the row
// stops showing as modified. Routes to the per-ROLE writer for the built-in
// Default workflow and the per-NODE writer for a saved one. `next` carries only
// what the user just changed; everything else rides along at what the row's
// controls currently show.
async function saveAgentRow(row, next, body) {
  if (!row) return;
  // Defence in depth: the controls are disabled without a project, but if one
  // is ever reached anyway, say so rather than letting the save no-op and the
  // re-render quietly undo the edit. Same wording as the submit guard.
  if (!agentsEditable()) {
    setFormMsg('Select a project first (or add one).', 'err');
    await renderWorkflowConfig(state.workflowId);
    return;
  }
  const patch = pruneNodeSelection(row, { ...liveRowValues(row, body), ...next });
  if (row.role) {
    await saveStep(row.role, patch.model, patch.effort, patch.fanOut, patch.askQuestions, patch.subagentModel);
  } else {
    await saveNode(state.workflowId, row.nodeId, patch.model, patch.effort, patch.fanOut, patch.askQuestions,
      patch.subagentModel);
  }
  await renderWorkflowConfig(state.workflowId); // repaint captions, dots + header
}

// Persist one node's model/effort to the per-project run-config for the active
// workflow (CONV-2): PATCH /api/config { projectDir, workflowId, nodes:{ [nodeId]:{model,effort} } }.
async function saveNode(workflowId, nodeId, model, effort, fanOut, askQuestions, subagentModel) {
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectDir, workflowId, nodes: { [nodeId]: { model, effort, fanOut, askQuestions, subagentModel } } }),
    });
    const data = await safeJson(res);
    if (!res.ok) {
      appendLog({ source: 'ui', level: 'error', text: `config: ${data.error || res.status}`, ts: Date.now() });
      return;
    }
    if (data.config) state.config = data.config;
  } catch (e) {
    appendLog({ source: 'ui', level: 'error', text: `config error: ${e.message}`, ts: Date.now() });
  }
}

// Persist one feedback loop's cycle count (CONV-2): PATCH /api/config
// { projectDir, workflowId, feedbacks:{ [fbId]:{maxCycles} } }.
async function saveFeedback(workflowId, fbId, maxCycles) {
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectDir, workflowId, feedbacks: { [fbId]: { maxCycles } } }),
    });
    const data = await safeJson(res);
    if (!res.ok) {
      appendLog({ source: 'ui', level: 'error', text: `config: ${data.error || res.status}`, ts: Date.now() });
      return;
    }
    if (data.config) state.config = data.config;
  } catch (e) {
    appendLog({ source: 'ui', level: 'error', text: `config error: ${e.message}`, ts: Date.now() });
  }
}

// Persist one loop wire's cycle budget: PATCH /api/config
// { projectDir, workflowId, wires:{ [wireId]:{maxCycles} } }. The v1 twin above
// posts `feedbacks:{…}` and stays until the v1 engine dies in P8.
async function saveWire(workflowId, wireId, maxCycles) {
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectDir, workflowId, wires: { [wireId]: { maxCycles } } }),
    });
    const data = await safeJson(res);
    if (!res.ok) { appendLog({ source: 'ui', level: 'error', text: `config: ${data.error || res.status}`, ts: Date.now() }); return; }
    if (data.config) state.config = data.config;
  } catch (e) {
    appendLog({ source: 'ui', level: 'error', text: `config error: ${e.message}`, ts: Date.now() });
  }
}

// Persist the active workflow selection (CONV-2): PATCH /api/config { projectDir, activeWorkflowId }.
async function saveActiveWorkflow(workflowId) {
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectDir, activeWorkflowId: workflowId }),
    });
    const data = await safeJson(res);
    if (res.ok && data.config) state.config = data.config;
    scheduleOnboardingRefresh();   // a picked workflow ticks "Explore the built-in workflows"
  } catch (e) {
    notify({ tone: 'err', title: 'Could not select the workflow', detail: e.message, key: 'select-workflow' });
  }
}

// Persist the Auto "Human in the loop" switch: PATCH /api/config { projectDir, humanInLoop }.
// A workspace target keeps it for this form only — checked FIRST, because selectedProjectPath()
// reads the hidden project select and would PATCH an unrelated project.
async function saveHumanInLoop(on) {
  if (state.runTarget === 'workspace') { state.wsHumanInLoop = !!on; return; }   // D-W1: no PATCH
  const projectDir = selectedProjectPath();
  if (!projectDir) return;
  try {
    const res = await fetch('/api/config', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectDir, humanInLoop: !!on }) });
    const data = await safeJson(res);
    if (!res.ok) appendLog({ source: 'ui', level: 'error', text: `human in the loop: ${data.error || res.status}`, ts: Date.now() });
    else if (data.config) state.config = data.config;
  } catch (e) {
    if (el.humanInLoop) el.humanInLoop.checked = !on;   // the switch shows what is stored
    notify({ tone: 'err', title: 'Could not change human-in-the-loop', detail: e.message, key: 'human-in-loop' });
  }
}
if (el.humanInLoop) el.humanInLoop.addEventListener('change', () => saveHumanInLoop(el.humanInLoop.checked));

// "+ Add model…" in any model dropdown: restore the selection and jump to the
// global Models view with the create editor open (models are added GLOBALLY —
// configurable-models-design.md §4.9; the old per-project window.prompt flow
// is gone).
function goAddModel(restore) {
  if (typeof restore === 'function') restore();
  mvState.editing = null;
  mvState.openCreate = true;
  mvState.openShare = false;
  // "+ Add model…" on a Codex or Cursor run starts a model of that engine (D10); the editor applies `engine`.
  mvState.prefill = state.engine !== 'claude' ? { id: '', engine: state.engine } : null;
  mvState.openEditorOnLoad = true;         // survives the view switch: loadModelsView opens it
  showView('settings', 'models');
}

// Delegated change handler for every config control inside #pipeline-config.
// Each control carries the node id of its accordion row; agentRowsById supplies
// that row's resolved defaults, so saveAgentRow can prune a redundant selection
// back to "inherit" and route to the right writer (per-role for wf_default, per
// node id for a saved workflow). Feedback cycle inputs carry data-fb-id instead.
el.pipelineConfig.addEventListener('change', (e) => {
  const t = e.target;

  // Feedback cycle inputs (number inputs, not selects).
  if (t instanceof HTMLInputElement && t.dataset.fbId) {
    const n = Math.max(1, Math.round(Number(t.value) || 1));
    t.value = String(n); // normalize the field
    const write = el.wfFeedbackConfig && el.wfFeedbackConfig.dataset.graph === '1' ? saveWire : saveFeedback;
    write(state.workflowId, t.dataset.fbId, n).then(() => renderWorkflowConfig(state.workflowId));
    return;
  }

  const row = agentRowsById[t.dataset ? t.dataset.nodeId : ''];
  if (!row) return;

  const body = t.closest ? t.closest('.agent-row-body') : null;

  if (t instanceof HTMLInputElement && t.type === 'checkbox') {
    if (!t.classList.contains('step-fanout') && !t.classList.contains('step-questions')) return;
    paintRowSummary(row, body);
    return void saveAgentRow(row, t.classList.contains('step-fanout')
      ? { fanOut: !!t.checked }
      : { askQuestions: !!t.checked }, body);
  }

  if (!(t instanceof HTMLSelectElement)) return;

  if (t.classList.contains('step-model')) {
    if (t.value === '__add__') return goAddModel(() => renderWorkflowConfig(state.workflowId));
    // A new model invalidates the old effort (the dropdown is filtered by it), so
    // the effort resets and the row's options are repainted immediately — the
    // save's own re-render lands a moment later.
    saveAgentRow(row, { model: t.value, effort: '' }, body);
    const effortSel = body && body.querySelector('.step-effort');
    if (effortSel) renderModelEffortPair(t, effortSel, null, { model: t.value, effort: '' });
    paintRowSummary(row, body);
    schedulePolicyLine();                      // an off-list model is a team-policy note (board 8)
  } else if (t.classList.contains('step-effort')) {
    saveAgentRow(row, { effort: t.value }, body);
    paintRowSummary(row, body);
  } else if (t.classList.contains('step-subagent')) {
    saveAgentRow(row, { subagentModel: t.value }, body);
    paintRowSummary(row, body);
  }
});

// Expand/collapse one accordion row. The whole head is a <button>, so keyboard
// activation (Enter/Space) arrives here as a click for free.
if (el.agentsConfig) {
  el.agentsConfig.addEventListener('click', (e) => {
    const head = e.target.closest ? e.target.closest('.agent-row-head') : null;
    if (!head || !el.agentsConfig.contains(head)) return;
    const card = head.closest('.agent-row');
    const body = card && card.querySelector('.agent-row-body');
    if (!body) return;
    const open = body.hidden; // about to open
    body.hidden = !open;
    card.classList.toggle('open', open);
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) openAgentRows.add(head.dataset.nodeId);
    else openAgentRows.delete(head.dataset.nodeId);
  });
}

// "Reset": drop every per-project override for this workflow, so each row falls
// back to the workflow's defaults and then the agent registry (§4.5).
if (el.agentsReset) {
  el.agentsReset.addEventListener('click', async () => {
    const projectDir = selectedProjectPath();
    if (!projectDir) return;
    const workflowId = state.workflowId || 'wf_default';
    try {
      const res = await fetch(
        `/api/config/workflow?projectDir=${encodeURIComponent(projectDir)}&workflowId=${encodeURIComponent(workflowId)}`,
        { method: 'DELETE' },
      );
      const data = await safeJson(res);
      if (!res.ok) {
        appendLog({ source: 'ui', level: 'error', text: `config: ${data.error || res.status}`, ts: Date.now() });
        return;
      }
      if (data.config) state.config = data.config;
      await renderWorkflowConfig(workflowId);
    } catch (err) {
      appendLog({ source: 'ui', level: 'error', text: `config error: ${err.message}`, ts: Date.now() });
    }
  });
}

// "Save as workflow defaults": promote this project's overrides into the
// workflow itself (§4.4/§4.8), then clear them — the effective config is
// unchanged, but it now travels with the workflow to every other project and
// through export/share. Disabled for wf_default, which cannot store defaults.
if (el.agentsPromote) {
  el.agentsPromote.addEventListener('click', async () => {
    const projectDir = selectedProjectPath();
    const workflowId = state.workflowId;
    if (!projectDir || !workflowId || isReservedWorkflowId(workflowId)) return;
    const rows = Object.values(agentRowsById);
    if (!rows.length) return;
    const defaults = Object.fromEntries(rows.map((r) => [r.nodeId, effectiveDefaultsOf(r)]));
    try {
      const res = await fetch(`/api/workflows/${encodeURIComponent(workflowId)}/defaults`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ defaults }),
      });
      const data = await safeJson(res);
      if (!res.ok) {
        appendLog({ source: 'ui', level: 'error', text: `workflow defaults: ${data.error || res.status}`, ts: Date.now() });
        return;
      }
      // The cached template still carries the OLD defaults; drop it so the
      // reset below repaints against what was just persisted.
      delete state.workflowCache[workflowId];
      el.agentsReset.click(); // clearing the now-redundant overrides is the second half
    } catch (err) {
      appendLog({ source: 'ui', level: 'error', text: `workflow defaults error: ${err.message}`, ts: Date.now() });
    }
  });
}

// One row's effective settings as a workflow-defaults block: only what deviates
// from the agent registry is worth storing, and a locked/absent questions toggle
// is never the user's to promote.
function effectiveDefaultsOf(row) {
  const out = {};
  if (row.model) {
    out.model = row.model;
    if (row.effort) out.effort = row.effort;
  }
  out.fanOut = !!row.fanOut;
  if (row.askQuestions !== null && !row.questionsLocked) out.askQuestions = !!row.askQuestions;
  // Omitted when unset: sanitizeNodeDefaults drops an empty value anyway, and
  // sending '' would make "promote" look like it stores an inherit.
  if (row.subagentModel) out.subagentModel = row.subagentModel;
  return out;
}

// ---------------------------------------------------------------------------
// Log window
// ---------------------------------------------------------------------------
const MAX_LOG_LINES = testHookInt('maxLogLines', 4000);

// Build one .log-line node from a normalized log record. (Same DOM shape the
// old global appendLog produced: ts/src/msg spans + lvl class.)
function buildLogLine({ source, level, text, ts, sub, path, kind }) {
  const line = document.createElement('div');
  line.className = logLineClass(level, sub);

  const t = document.createElement('span');
  t.className = 'log-ts';
  t.textContent = logLineTime(ts);

  const s = document.createElement('span');
  s.className = 'log-src';
  s.textContent = source ? `[${source}]` : '';

  // An artifact line with a path becomes a link: the delegated handler on the log
  // pane opens it in the viewer (resolving the run from the pane's _artifactCtx).
  let m;
  if (level === 'artifact' && path) {
    m = document.createElement('a');
    m.className = 'log-msg log-artifact';
    m.href = '#';
    m.dataset.path = String(path);
    if (kind) m.dataset.kind = String(kind);
  } else {
    m = document.createElement('span');
    m.className = 'log-msg';
  }
  m.textContent = String(text);

  line.append(t, s, m);
  return line;
}

// Keystroke-to-repaint delay for the log search box.
const LOG_SEARCH_DEBOUNCE_MS = 120;

// Copy already-filtered log records to the clipboard and flash the button.
//
// Serializes from the MODEL, never from the DOM: a log line spaces its
// ts/src/msg spans with a flex `gap` rather than whitespace, so a native
// selection-copy would run them together ("12:34:56[planner]text").
// navigator.clipboard needs a secure context — localhost qualifies — but a
// hidden-textarea fallback keeps the button working anywhere.
async function copyLogToClipboard(btn, recs) {
  const text = serializeLog(recs);
  if (!text) {
    // A filtered-empty pane: silence looks like a dead button, and the STALE
    // clipboard content would pass for the filtered log on the next paste.
    flashCopyBtn(btn, 'nothing to copy');
    return;
  }
  let ok = true;
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
    else ok = legacyCopy(text);
  } catch {
    ok = legacyCopy(text);
  }
  flashCopyBtn(btn, ok ? 'copied' : 'copy failed');
}

// Save/flash/restore a copy button's label. `dataset.label` survives repeated
// clicks so a flash can never become the button's permanent label.
function flashCopyBtn(btn, msg) {
  const prev = btn.dataset.label || btn.textContent;
  btn.dataset.label = prev;
  btn.textContent = msg;
  clearTimeout(btn._copyTimer);
  btn._copyTimer = setTimeout(() => { btn.textContent = btn.dataset.label || 'copy'; }, 1200);
}

// Copy a branch name from a history-card head. The button is icon-only, so
// feedback is a brief copy→check icon swap (class-driven) instead of the text
// flash flashCopyBtn does; the title mirrors it for hover/AT users.
async function copyBranchToClipboard(btn, branch, restTitle = 'Copy branch name') {
  let ok = true;
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(branch);
    else ok = legacyCopy(branch);
  } catch {
    ok = legacyCopy(branch);
  }
  btn.classList.toggle('copied', ok);
  btn.title = ok ? 'Copied' : 'Copy failed';
  clearTimeout(btn._copyTimer);
  btn._copyTimer = setTimeout(() => {
    btn.classList.remove('copied');
    btn.title = restTitle;
  }, 1200);
}

function legacyCopy(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

// A "── Cycle N ──" rule marking where a feedback loop rewound and re-ran the
// same steps. Without it a re-run is indistinguishable from its first pass,
// since a re-run keeps its stepIndex and only bumps its cycle.
function buildLogSeparator(label) {
  const el = document.createElement('div');
  el.className = 'log-sep';
  el.textContent = label;
  return el;
}

// ONE DOM cap for the streaming append and the filter repaint. Counts RECORD
// lines only (the model cap counts records too — counting separators made the
// two caps diverge and over-evict), evicts oldest-first, and drops a separator
// left leading the pane: a rule above the first line labels nothing.
function trimLogDom(logEl) {
  const lines = logEl.getElementsByClassName('log-line'); // live collection
  while (lines.length > MAX_LOG_LINES) logEl.removeChild(logEl.firstElementChild);
  while (logEl.firstElementChild && logEl.firstElementChild.classList.contains('log-sep')) {
    logEl.removeChild(logEl.firstElementChild);
  }
}

// Append `rec` to a log pane, preceded by a cycle separator when its NODE opens
// a higher ordinal (see cycleSeparatorBefore). `state` is the per-node cursor
// from newCycleState(); anything else (a first call passing null) starts a fresh
// one. Returns the state the NEXT append must pass.
function appendLogRec(logEl, rec, state) {
  const cursor = state instanceof Map ? state : newCycleState();
  const sep = cycleSeparatorBefore(cursor, rec);
  if (sep) logEl.appendChild(buildLogSeparator(sep));
  logEl.appendChild(buildLogLine(rec));
  return cursor;
}

// One scroll pin per pane per FRAME — at most ONE forced layout per frame
// total, not one per line. The pin's scrollHeight read forces a synchronous
// layout of the pane's document (~2ms at the 4k-line cap, ~90% of the measured
// per-line cost, and it fired TWICE per line: card pane + detail pane; the
// FIRST read in a flush pays the layout, later reads in the same flush are
// clean). Claude's stdout arrives in bursts, so per-line pins made a burst
// cost per-LINE what it should cost per-FRAME. Appends stay synchronous —
// only the geometry read/write coalesces. Panes dedupe through the Map key;
// the run rides along as the value so the flush can RE-CHECK r.autoscroll:
// the switch can flip OFF in the ≤1 frame between a line arriving and the
// flush, and a stale pin must not yank a just-frozen viewport to the bottom.
// A pane rebuilt before the flush re-schedules through its own repaint's
// autoscroll call, and pinning a detached node is a harmless no-op. Where rAF
// is absent (jsdom under node:test, which is not pretendToBeVisual), the 16ms
// timer stands in.
const pendingScrollPins = new Map();   // logEl -> its run (flush re-checks r.autoscroll)
let scrollPinScheduled = false;
function schedulePinToBottom(logEl, r) {
  if (!logEl) return;
  pendingScrollPins.set(logEl, r);
  if (scrollPinScheduled) return;
  scrollPinScheduled = true;
  const flush = () => {
    scrollPinScheduled = false;
    const entries = [...pendingScrollPins];
    pendingScrollPins.clear();
    for (const [el, run] of entries) {
      if (el && (!run || run.autoscroll !== false)) el.scrollTop = el.scrollHeight;
    }
  };
  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(flush);
  else setTimeout(flush, 16);
}

// Mirror r.autoscroll onto a card's switch (class + aria). One-way: model → DOM.
// `el` lets a caller target a host of its own (the detail's Logs section); defaults
// to r.el, which is always null now that the list card is gone.
function syncAutoscrollSwitch(r, el) {
  const host = el || (r && r.el);
  if (!r || !host) return;
  const sw = host.querySelector('.switch.autoscroll');
  if (!sw) return;
  const on = r.autoscroll !== false;
  sw.classList.toggle('on', on);
  sw.setAttribute('aria-checked', String(on));
}

// Toggle a run's auto-scroll. Enabling does NOT jump to the bottom: per the product
// decision, re-enabling holds the current position and only the NEXT arriving line
// follows (that pin happens in onLog → maybeAutoscrollLog). Disabling freezes the log.
function setAutoscroll(r, on) {
  if (!r) return;
  r.autoscroll = !!on;
  syncAutoscrollSwitch(r);
}

// S4: the newest captured line of a RUNNING script card feeds its footer's live band. Only a
// script node's own lines count (agents stream at log speed and have no live band), the map is
// O(1) per line, and the graph repaint is coalesced — the `log` frame itself never repaints the
// detail (handleServerMessage's skipDetail), so this is the one narrow path that does.
const LIVE_LINE_MS = 250;
const LIVE_LINE_MAX = 240;      // the band is ONE ellipsised line; a log line can be 64 KiB (the runner's cap)
function noteLiveLine(r, rec) {
  if (!rec || rec.nodeId == null || rec.sub || !isGraphRun(r)) return;
  const nodes = (r.stepper && r.stepper.graph && Array.isArray(r.stepper.graph.nodes)) ? r.stepper.graph.nodes : [];
  const node = nodes.find((n) => n && n.id === rec.nodeId);
  if (!node || node.kind !== 'script') return;
  // trimEnd, not /\s+$/: that regex is quadratic on a long blank run that is not at the end (1 s per 64 KiB line).
  const text = String(rec.text).trimEnd().slice(0, LIVE_LINE_MAX);
  if (!text) return;
  if (!r._lastLines) r._lastLines = new Map();
  const executionId = rec.executionId != null ? rec.executionId : null;
  const prev = r._lastLines.get(rec.nodeId);
  if (prev && prev.text === text && prev.executionId === executionId) return;
  r._lastLines.set(rec.nodeId, { text, executionId });
  if (r._liveLineTimer) return;
  r._liveLineTimer = setTimeout(() => {
    r._liveLineTimer = null;
    r._decorSeq = (r._decorSeq || 0) + 1;
    if (rdOpenRun() === r && runDetailState.screen) paintRdGraph(runDetailState.screen, r);
  }, LIVE_LINE_MS);
}

/** nodeId -> text for the reducer. A line stands only for the EXECUTION that wrote it: when a loop
 *  re-runs the card, the new execution starts blank instead of wearing the previous one's last line. */
function liveLinesOf(r) {
  if (!r._lastLines || !r._lastLines.size) return null;
  const running = new Set((Array.isArray(r.active) ? r.active : []).map((a) => a && a.executionId).filter(Boolean));
  const out = new Map();
  for (const [nodeId, v] of r._lastLines) if (v.executionId == null || running.has(v.executionId)) out.set(nodeId, v.text);
  return out;
}

// Per-run log: push to the model; the open run page mirrors the line into its own pane.
// Filtering is render-time only: the model keeps every line, so changing a
// filter never loses history.
function onLog(r, msg) {
  const text = msg.text;
  if (text === undefined || text === null) return;
  const rec = {
    ts: msg.ts != null ? msg.ts : Date.now(), source: msg.source, level: msg.level, text, sub: !!msg.sub,
    ...(msg.nodeId != null ? { nodeId: msg.nodeId } : {}),
    ...(msg.executionId != null ? { executionId: msg.executionId } : {}),
    ...(msg.stepIndex != null ? { stepIndex: msg.stepIndex } : {}),
    ...(msg.cycle != null ? { cycle: msg.cycle } : {}),
    ...(msg.stream ? { stream: msg.stream } : {}),
    ...(msg.path != null ? { path: msg.path } : {}),
    ...(msg.kind != null ? { kind: msg.kind } : {}),
  };
  r.logLines.push(rec);
  if (r.logLines.length > MAX_LOG_LINES) r.logLines.shift();
  noteLiveLine(r, rec);

  // §5.9: mirror the same record into the OPEN detail's pane. Hooked on the
  // writer, not on the `log` frame type, so the six producers that call onLog
  // directly (onExec, onArtifact, the answer/stop/pause/resume failure paths)
  // reach the detail too. rdAppendLogFrame re-reads r.logLines' tail, which the
  // push above just wrote, and no-ops unless this run's detail is open.
  if (rdOpenRun() === r) rdAppendLogFrame(r);
}

// ── Log filtering (source / level / step) ───────────────────────────────────

// Fill one filter <select> with an "all" option + the facet values, preserving
// the current selection (a value that vanished from the facets falls back to all).
function fillFilterSelect(sel, allLabel, values, current, labelOf) {
  if (!sel) return;
  sel.innerHTML = '';
  const all = document.createElement('option');
  all.value = '';
  all.textContent = allLabel;
  sel.appendChild(all);
  for (const v of values) {
    const opt = document.createElement('option');
    opt.value = String(v);
    opt.textContent = labelOf ? labelOf(v) : String(v);
    sel.appendChild(opt);
  }
  sel.value = values.some((v) => String(v) === String(current)) ? String(current) : '';
}

// (Re)populate a run card's three filter dropdowns from the lines seen so far.
// `root` targets a host of its own; r.el (the default) is always null now.
// Returns true when the pane was fully repainted (see below), false otherwise.
function paintLogFilters(r, root = r.el) {
  if (!root) return false;
  const facets = logFacets(r.logLines);
  const selSource = root.querySelector('.log-f-source');
  const selLevel = root.querySelector('.log-f-level');
  const selStep = root.querySelector('.log-f-step');
  const selCycle = root.querySelector('.log-f-cycle');
  fillFilterSelect(selSource, 'all sources', facets.sources, r.logFilter.source);
  fillFilterSelect(selLevel, 'all levels', facets.levels, r.logFilter.level);
  // The step select is RE-PURPOSED as the node select once the run logged node
  // ids (v2 graph runs): data-axis tells readLogFilterFrom which axis it holds.
  // v1 records (stepIndex, no nodeId) keep today's `step N` options.
  const labelOf = nodeLabelLookup(r.stepper);
  // P6a seam: a footer-row click (applyRunLogFilter / focusLogExecution) can name
  // a node BEFORE that node has logged a line — the graph host is painted from the
  // ledger, the facets only from `r.logLines`. Keep the node axis live for such a
  // pick and offer the node as its own option, so the model's value is
  // representable in the DOM; otherwise the reconcile below reads `node: ''` back
  // out of a step-axis select and silently wipes the pick on the very next paint.
  // This is exactly the honesty loadLiveLogs' __setLogFilter gives the History bar.
  const wantNode = String(r.logFilter.node || '');
  const nodeFacets = facets.nodes || [];
  if (nodeFacets.length || wantNode) {
    selStep.dataset.axis = 'node';
    selStep.title = 'Filter by node'; selStep.setAttribute('aria-label', 'Filter by node');
    const nodeValues = wantNode && !nodeFacets.some((n) => String(n) === wantNode)
      ? [...nodeFacets, wantNode] : nodeFacets;
    fillFilterSelect(selStep, 'all nodes', nodeValues, wantNode, (id) => labelOf(id));
  } else {
    selStep.dataset.axis = 'step';
    selStep.title = 'Filter by step'; selStep.setAttribute('aria-label', 'Filter by step');
    fillFilterSelect(selStep, 'all steps', facets.steps, r.logFilter.step, (i) => `step ${i + 1}`);
  }
  paintExecChip(r, root);
  // Cycles are the loop's own 1-based counter, so unlike steps they are NOT
  // shifted for display.
  fillFilterSelect(selCycle, 'all cycles', facets.cycles, r.logFilter.cycle, (c) => `cycle ${c}`);
  r._logFacetKeys = facetKeys(facets);
  // A selection whose value vanished from the facets (log rotation, rebuild)
  // fell back to "all" in the DOM; mirror that into the model and repaint so
  // the pane never stays filtered by a value the dropdowns no longer show.
  // Search is free text — no facet can vanish from it, so reconciliation must
  // never touch it. The DOM box may be a fresh empty clone (rebuild) or
  // mid-keystroke ahead of the debounce; the model owns the term here.
  const effective = { ...readLogFilterFrom(root), search: r.logFilter.search };
  if (effective.source !== r.logFilter.source
    || effective.level !== r.logFilter.level
    || String(effective.step) !== String(r.logFilter.step)
    // `|| ''` on BOTH sides: a filter object built before the node key existed
    // (undefined) must read as "all", not force a repaint on every paint. The
    // EXECUTION axis is deliberately not compared: paintExecChip above writes the
    // chip's dataset from r.logFilter.execution, so readLogFilterFrom can only
    // read that same value back — and a chip has no facets to fall out of.
    || String(effective.node || '') !== String(r.logFilter.node || '')
    || String(effective.cycle) !== String(r.logFilter.cycle)) {
    r.logFilter = effective;
    repaintFilteredLog(r, root);
    return true;
  }
  return false;
}

/** `Planner #2` / `Implementer #2 · Add schema` for the execution chip. The row
 *  is matched by executionId ONLY (never `|| s.key`): today's bookend rows are
 *  key-only, and a v1 row's key is a phase name. Unknown -> the raw id. */
function executionChipText(r, executionId) {
  const row = (Array.isArray(r.steps) ? r.steps : []).find((s) => s && s.executionId === executionId);
  if (!row) return String(executionId || '');
  const head = `${nodeLabelLookup(r.stepper)(row.nodeId)} #${row.ordinal ?? row.cycle ?? 1}`;
  return row.kind === 'task' ? `${head} · ${row.title || 'task'}` : head;
}

/** Mirror r.logFilter.execution into the chip on one bar (`r` is any holder of
 *  {logFilter, steps, stepper} — the History panel passes a saved state). */
function paintExecChip(r, root) {
  const chip = root && root.querySelector('.log-f-exec');
  if (!chip) return;
  const id = r.logFilter.execution || '';
  chip.hidden = !id;
  chip.dataset.executionId = id;
  if (id) chip.querySelector('.lfe-text').textContent = executionChipText(r, id);
}

/** The execution chip's two rules, bound ONCE per bar (the card's, the Running
 *  detail's, History's). `read()` returns the owner's filter object; `write(patch)`
 *  applies a patch to it and repaints every bar that shows it.
 *  - a click on the chip clears the execution axis;
 *  - a MANUAL node/step or cycle pick clears it too (adj-d §4): the chip narrows
 *    to one execution and a broader pick must not stay hidden behind it. The
 *    patch carries the bar's fresh DOM values because the owner's own change
 *    handler may run AFTER this one (the detail's is bound per section) and
 *    would otherwise find its select re-filled from the stale model. */
function wireExecChip(bar, { read, write }) {
  bar.addEventListener('click', (e) => {
    if (!(e.target.closest && e.target.closest('.log-f-exec'))) return;
    e.stopPropagation();
    write({ execution: '' });
  });
  bar.addEventListener('change', (e) => {
    if (!(e.target.closest && e.target.closest('.log-f-step, .log-f-cycle'))) return;
    if (!read().execution) return;
    write({ ...readLogFilterFrom(bar, read().search), execution: '' });
  });
}

// Cheap incremental check for onLog: only rebuild the dropdowns when `rec`
// introduces a facet value they don't offer yet.
function facetKeys(facets) {
  return new Set([
    ...facets.sources.map((s) => `s:${s}`),
    ...facets.levels.map((l) => `l:${l}`),
    ...facets.steps.map((i) => `t:${i}`),
    ...facets.cycles.map((c) => `c:${c}`),
    ...(facets.nodes || []).map((n) => `n:${n}`),
  ]);
}
// The live-card empty-state note ('(no lines match the filter)') is plain text
// stamped with data-empty; incremental appends must clear it first.
function clearLogPlaceholder(logEl) {
  if (logEl.dataset.empty) { logEl.textContent = ''; delete logEl.dataset.empty; }
}

// Re-render a log pane from the model through the current filter (called on a
// filter change; live appends stay incremental via onLog). `root` targets a host
// of its own; r.el (the default) is always null now.
function repaintFilteredLog(r, root = r.el) {
  if (!r || !root) return;
  const logEl = root.querySelector('.log');
  if (!logEl) return;
  // Every pane that renders log lines passes through here — the dashboard card,
  // the open run detail, a finished run's card — so this is where the artifact
  // link context belongs. onLog only ever stamped the CARD's pane, and only on a
  // live line, so `.log-artifact` links in the detail (rdLogBox) and on any
  // finished card were silently inert: the delegated handler walks up for
  // _artifactCtx, finds none, and does nothing at all.
  logEl._artifactCtx = { run: r, runId: r.pipelineId || r.id, record: r.record || null };
  // Auto-scroll OFF freezes the viewport: carry the position across the
  // wipe+rebuild (the browser clamps if the filtered content is shorter).
  // ON keeps its pin-to-bottom via maybeAutoscrollLog below.
  const savedTop = logEl.scrollTop;
  logEl.innerHTML = '';
  delete logEl.dataset.empty;
  const visible = compileLogFilter(r.logFilter);
  // One fragment, one reflow — appending 4000 nodes into the live document
  // per debounce tick is where search jank came from.
  const frag = document.createDocumentFragment();
  let shown = 0;
  let cycleState = newCycleState();
  for (const rec of r.logLines) {
    if (!visible(rec)) continue;
    cycleState = appendLogRec(frag, rec, cycleState);
    shown++;
  }
  logEl.appendChild(frag);
  // Hand the streaming path in onLog the per-node cursor the next separator must
  // compare against, so a live append after a repaint agrees with the repaint.
  r._cycleState = cycleState;
  trimLogDom(logEl);
  if (shown === 0 && r.logLines.length) {
    logEl.textContent = '(no lines match the filter)';
    logEl.dataset.empty = '1';
  }
  if (r.autoscroll === false && savedTop) logEl.scrollTop = savedTop;
}

function onArtifact(r, msg) {
  if (msg && msg.kind) {
    if (!Array.isArray(r.artifacts)) r.artifacts = [];
    const rec = {
      kind: msg.kind,
      path: msg.path || '',
      nodeId: msg.nodeId ?? null,
      stepKey: msg.executionId ?? null,   // stepKey := executionId (WS field name)
      cycle: msg.cycle ?? null,
    };
    // A rewritten file is re-indexed and re-emitted, and hydration may already
    // have seeded the same file from the server — one row per file either way,
    // carrying the newest attribution.
    // rec.path is absolute; an existing entry may be either — and several rows can
    // suffix-match it, so bind to the CLOSEST rather than the first.
    const at = closestArtifactIndex(r.artifacts, rec.path, (a) => a.kind === rec.kind);
    // Attribution is all the event carries, and `bytes` is not attribution — it is
    // a property of the FILE, which only the hydrated server row knows (sizing a
    // row costs a statSync, so the WS event deliberately omits it). Replacing the
    // row wholesale dropped the size chip the moment a file was rewritten, and
    // hydrateRunArtifacts skips any row a live event already delivered, so it never
    // came back. Carry it: a size from the last index is stale only by the delta of
    // one rewrite, which beats the row claiming no size at all.
    if (at >= 0) r.artifacts[at] = { ...(r.artifacts[at].bytes != null ? { bytes: r.artifacts[at].bytes } : {}), ...rec };
    else r.artifacts.push(rec);
  }
  // A step that indexes a whole FOLDER emits one event per file — a deck audit
  // takes a screenshot per slide, so 43 arrive back to back and bury the run's
  // narrative. Log the first few of such a run and drop the rest; the Artifacts
  // tab above still receives every one of them.
  //
  // Counted, not de-duplicated: suppressing every adjacent same-kind event
  // swallows distinct deliverables, because deckExport emits deck.html,
  // deck.standalone.html and deck.pdf consecutively as one kind from one node.
  // The threshold is the Artifacts tab's own BULK_KIND_THRESHOLD, so what
  // collapses in the list is what goes quiet in the log.
  // Keyed by EXECUTION as well as kind and node: the build/audit loop re-enters
  // the same node on every fix cycle, and a key of kind+node alone stays over the
  // threshold for the rest of the run — so cycle 2 would log none of its 43
  // screenshots instead of its own first few.
  // No log line for a kind nobody can open — a link to the run DIR or to the
  // deleted questions scratch file only ever 404s. The engine skips the same
  // kinds when it persists, so the live pane and History agree.
  if (!isBrowsableKind(msg.kind)) return;
  // ONE slot keyed by the burst reset its count whenever the key
  // changed, so two executions sweeping folders CONCURRENTLY (a workspace fan-out
  // of an extraFiles-declaring agent; _indexExtraFiles awaits between files, so
  // they interleave) flipped the key on every event and nothing was ever
  // suppressed. A Map counts each burst on its own. Bounded by the run's distinct
  // (kind, execution, node) triples, which is what a burst IS.
  const key = `${msg.kind || ''}\u0000${msg.executionId ?? ''}\u0000${msg.nodeId ?? ''}`;
  if (!r._artifactRuns) r._artifactRuns = new Map();
  const seen = (r._artifactRuns.get(key) || 0) + 1;
  r._artifactRuns.set(key, seen);
  if (seen > BULK_KIND_THRESHOLD) return;
  onLog(r, {
    source: 'artifact',
    level: 'artifact',
    text: `${msg.kind || 'file'}: ${msg.path || ''}`,
    ts: Date.now(),
    path: msg.path || '',
    kind: msg.kind || '',
  });
}

// The engine pruned index rows for files that are gone — the audit deletes and
// recreates shots/ every cycle, so a fix cycle that cuts a slide drops one. The
// client list only ever grew, so the browser kept rendering the pruned row and
// clicking it 404s from a route that resolves only among indexed rows.
function onArtifactGone(r, msg) {
  const paths = msg && Array.isArray(msg.paths) ? msg.paths : [];
  if (!paths.length || !Array.isArray(r.artifacts) || !r.artifacts.length) return;
  let removed = 0;
  for (const p of paths) {
    // EVERY row for the file, not just the closest: a re-kind leaves the same path
    // under two kinds (onArtifact's dedupe is kind-scoped), and the engine prunes
    // the superseded one — dropping a single row here left the file listed twice
    // and counted twice in the per-node badge. For the file-is-gone case, removing
    // all of its rows is equally right.
    for (let at = closestArtifactIndex(r.artifacts, p); at >= 0; at = closestArtifactIndex(r.artifacts, p)) {
      r.artifacts.splice(at, 1);
      removed += 1;
    }
  }
  // Repaint NOW rather than waiting for the next state frame: a run that has
  // finished sends no more, so the stale row would stay clickable for the life of
  // the page. rdUpdateSections self-guards on there being an open screen.
  if (removed && rdOpenRun() === r) rdUpdateSections(r);
}

// Non-run-scoped UI notices (config/answer/install errors). There is no global
// log surface anymore, so route these to the console; keep the {source,level,
// text,ts} shape for call-site compatibility.
function appendLog({ source, level, text }) {
  if (text === undefined || text === null) return;
  const tag = source ? `[${source}]` : '';
  if (level === 'error') console.error(`worca ${tag} ${text}`);
  else console.log(`worca ${tag} ${text}`);
}

// (fmtTime moved to log-line.mjs as logLineTime: the rendered line and the
// clipboard serializer must format a timestamp identically, and log-line.mjs is
// the pure module both go through.)

// ---------------------------------------------------------------------------
// Questions (clarify) and gates. The full question/gate UI is built INLINE into
// the run page's .qpanel slot (no global question card). onQuestion stores the
// pending question; the frame hook repaints the run page and the Runs row.
// ---------------------------------------------------------------------------
function onQuestion(r, msg) {
  r.pendingQuestion = msg;
  r._decorSeq = (r._decorSeq || 0) + 1;   // isLive(r) reads pendingQuestion
  // A new question supersedes any half-finished answer attempt.
  r._answering = false;
  alerts.onQuestion(alertRun(r), msg);
}

// The `?` glyph used in the panel head. Built fresh each call (a node can only
// live in one place in the DOM).
function questionIcon() {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('width', '17');
  svg.setAttribute('height', '17');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  // The question bubble every question surface shares (the Q&A / Clarify tab icon too):
  // a speech bubble so the mark reads at 15-17px, with the question mark inside it.
  const bubble = document.createElementNS(NS, 'path');
  bubble.setAttribute('d', 'M5 4.5h14a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-6.5L8 21v-3.5H5a2 2 0 0 1-2-2v-9a2 2 0 0 1 2-2z');
  bubble.setAttribute('stroke-linejoin', 'round');
  bubble.setAttribute('stroke-width', '1.8');
  const path = document.createElementNS(NS, 'path');
  path.setAttribute('d', 'M9.9 9.1a2.2 2.2 0 1 1 3.2 2c-.7.4-1.1.9-1.1 1.6');
  path.setAttribute('stroke-linecap', 'round');
  const circle = document.createElementNS(NS, 'circle');
  circle.setAttribute('cx', '12');
  circle.setAttribute('cy', '14.9');
  circle.setAttribute('r', '.5');
  circle.setAttribute('fill', 'currentColor');
  circle.setAttribute('stroke-width', '1.4');
  svg.append(bubble, path, circle);
  return svg;
}

// The 14px play triangle both primary panel buttons carry (clarify Submit,
// workflow Accept & run). Built fresh each call, like questionIcon().
function playIcon() {
  const NS = 'http://www.w3.org/2000/svg';
  const play = document.createElementNS(NS, 'svg');
  play.setAttribute('width', '14');
  play.setAttribute('height', '14');
  play.setAttribute('viewBox', '0 0 24 24');
  play.setAttribute('fill', 'currentColor');
  const tri = document.createElementNS(NS, 'path');
  tri.setAttribute('d', 'M6 4l14 8-14 8V4Z');
  play.appendChild(tri);
  return play;
}

// Filter a clarify question's options down to the real ones (the contract pads
// to 3 slots with '' — drop empty/whitespace).
function realOptions(q) {
  const opts = Array.isArray(q && q.options) ? q.options : [];
  return opts.filter((o) => typeof o === 'string' && o.trim() !== '');
}

// Build the question/gate panel into `root`'s .qpanel from r.pendingQuestion, un-hide it, and wire
// its inputs. Idempotent: re-building replaces the content. Only the run page mounts one (the list
// card just points at it), so the caller passes the run page's subtree.
function renderQpanel(r, root) {
  if (!root) return;
  const panel = root.querySelector('.qpanel');
  if (!panel) return;
  disposeQpanel(panel);                       // a workflow body owns a graph mount + ResizeObserver
  const pq = r.pendingQuestion;
  panel.innerHTML = '';
  panel.classList.toggle('qpanel-workflow', !!(pq && pq.kind === 'workflow'));
  if (!pq) {
    panel.classList.add('hidden');
    return;
  }

  // D6: one lookup, five registrants. A payload whose kind has no registrant falls
  // back to clarify — the same arm the old `else` was.
  const kind = askKindOf(pq);
  const renderer = askRendererFor(kind) || askRendererFor('clarify');
  if (!renderer) { panel.classList.add('hidden'); return; }
  panel.dataset.kind = kind;                  // the run page lays each kind out on its own
  const ctx = askCtxFor(r, panel);

  // ----- head -----
  const head = document.createElement('div');
  head.className = 'qpanel-head';
  head.appendChild(questionIcon());
  const title = document.createElement('b');
  title.textContent = renderer.title(pq, ctx);
  head.appendChild(title);
  const countText = renderer.count(pq, ctx);
  if (countText != null) {
    const count = document.createElement('span');
    count.className = 'qcount';
    count.textContent = countText;
    head.appendChild(count);
  }
  panel.appendChild(head);

  // Un-hide BEFORE the workflow body measures: a hidden host has no layout width in
  // a browser, and renderWorkflowBody calls handle.relayout() the moment it attaches.
  if (kind === 'workflow') panel.classList.remove('hidden');
  renderer.render(panel, pq, ctx);

  panel.classList.remove('hidden');
}

/** The `ctx` every registered renderer receives (index §P3). `mode` tells a body
 *  whether it is the run page's panel or another host's. */
function askCtxFor(r, panel) {
  return {
    doc: document,
    run: r,
    mode: panel.closest && panel.closest('.run-card') ? 'card' : 'detail',
    fileUrl: (index) => askFileUrl(r, r.pendingQuestion, index),
    submit: (payload) => postAnswer(r, payload),
  };
}

/** `GET /api/runs/:id/ask-files/:askId/:index` — the ask's file snapshot, addressed
 *  by index, never by path. `pq.askId` is the ROUTE token (P2 E1), a sanitized twin
 *  of `pq.id`: the real question id is `questions-x:n_impl:1-r1`, colons and all, and
 *  is never a path segment. Returns null when there is nothing to address — the file
 *  widgets draw their .af-nofile tile for that (X14). */
function askFileUrl(r, pq, index) {
  if (!r || !pq || !pq.askId) return null;
  return `/api/runs/${encodeURIComponent(r.runId)}/ask-files/${encodeURIComponent(pq.askId)}/${encodeURIComponent(index)}`;
}

/** A panel body that owns resources (the workflow graph) registers panel.__dispose; run it before any rebuild. */
function disposeQpanel(panel) {
  if (panel && typeof panel.__dispose === 'function') { try { panel.__dispose(); } catch { /* never block a repaint */ } }
  if (panel) panel.__dispose = null;
}
/** A34: the paths that destroy panel DOM WITHOUT renderQpanel/clearQpanel (openRunDetail,
 *  closeRunDetail) all go through destroyGraphMounts — dispose there. */
function disposeQpanelsIn(root) {
  if (!root || typeof root.querySelectorAll !== 'function') return;
  for (const p of root.querySelectorAll('.qpanel')) disposeQpanel(p);
}

// Clarify questions with at least a question string. (questions may be [] when
// the planner had nothing to ask — handled separately with a note.)
function realQuestions(pq) {
  return (Array.isArray(pq && pq.questions) ? pq.questions : []).filter(
    (q) => q && typeof q.question === 'string' && q.question.trim() !== ''
  );
}

function renderClarifyBody(r, panel, pq) {
  const questions = realQuestions(pq);

  // r._answers maps a stable per-question key -> chosen value (option text or
  // free-text or ''). Rebuilt each render so it tracks the current markup.
  // ALSO stamped on the panel node: submitAnswer reads the SUBMITTED panel's copy;
  // r._answers stays as the no-panel fallback.
  r._answers = [];
  panel.__answers = r._answers;
  lastClarifyRun = r;

  // "N of M answered" (spec §5.4). Counts the panel's own slots. `slots` is the array
  // this render just stamped on `panel`.
  const answered = document.createElement('span');
  answered.className = 'qanswered';
  const recount = () => {
    const slots = panel.__answers || [];
    const done = slots.filter((s) => typeof s.choice === 'string' && s.choice.trim() !== '').length;
    answered.textContent = `${done} of ${slots.length} answered`;
  };

  if (questions.length === 0) {
    const note = document.createElement('div');
    note.className = 'gate-intro';
    note.textContent =
      'No specific questions — you can submit an empty answer to let the pipeline proceed.';
    panel.appendChild(note);
  }

  questions.forEach((q, i) => {
    const block = document.createElement('div');
    block.className = 'qblock';

    const text = document.createElement('div');
    text.className = 'qtext';
    const qn = document.createElement('span');
    qn.className = 'qn';
    qn.textContent = String(i + 1);
    text.appendChild(qn);
    text.appendChild(document.createTextNode(q.question));
    block.appendChild(text);

    const opts = realOptions(q);
    const slot = { id: q.id, question: q.question, choice: '' };
    r._answers.push(slot);

    // allowFreeText === false => options-only (no free-text input). Absent or
    // true keeps the input. When suppressed, slot.choice can only be set by an
    // option click; if none is picked it stays '' (submit yields '' gracefully).
    const showFree = q.allowFreeText !== false;

    const optsWrap = document.createElement('div');
    optsWrap.className = 'qopts';

    let free = null;
    if (showFree) {
      free = document.createElement('input');
      free.className = 'qfree';
      free.type = 'text';
      free.placeholder = 'Or type your own answer… (e.g. "B but change the port")';
    }

    // Night mode (Step 14): the agent's confidence per option (one bar each, keyed by
    // option order) and its recommendation, which is preselected — the user can change it.
    const conf = Array.isArray(q.confidence) && q.confidence.length === opts.length ? q.confidence : null;
    const rec = conf && typeof q.recommended === 'string' && opts.includes(q.recommended) ? q.recommended : null;
    const select = (btn, optText) => {
      // Select this option, clear siblings + the free-text field (if present).
      optsWrap.querySelectorAll('.qopt').forEach((b) => {
        const on = b === btn;
        b.classList.toggle('sel', on);
        b.setAttribute('aria-pressed', String(on));
        delete b.dataset.preset;           // a real pick: the "Answered" pill may show
      });
      if (free) {
        free.value = '';
        free.classList.remove('has');
      }
      slot.choice = optText;
      recount();
    };
    opts.forEach((optText, optIdx) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'qopt';
      btn.setAttribute('aria-pressed', 'false');
      // A/B/C/D key (MAX_CLARIFY_OPTIONS is 4) so a free-text answer can refer
      // back to an option by name, e.g. "B but change the port". The stylesheet
      // draws it as the option's key square, so the label is the option alone.
      btn.dataset.key = String.fromCharCode(65 + optIdx);
      const label = document.createElement('span');
      label.className = 'qopt-txt';
      label.textContent = optText;
      btn.appendChild(label);
      if (optText === rec) {
        const badge = document.createElement('span');
        badge.className = 'qrec';
        badge.textContent = 'Recommended';
        btn.appendChild(badge);
      }
      if (conf) {
        const bar = document.createElement('span');
        bar.className = 'qconf';
        bar.setAttribute('aria-label', `${conf[optIdx]}% confidence`);
        const fill = document.createElement('span');
        fill.className = 'qconf-fill';
        fill.style.width = `${conf[optIdx]}%`;
        bar.appendChild(fill);
        btn.appendChild(bar);
      }
      btn.addEventListener('click', () => select(btn, optText));
      optsWrap.appendChild(btn);
      // Preselected, not answered: data-preset keeps the "Answered" pill off until a real click.
      if (optText === rec) { select(btn, optText); btn.dataset.preset = '1'; }
    });
    if (opts.length) block.appendChild(optsWrap);

    // Free-text input: typing clears any option selection and becomes the choice.
    if (free) {
      free.addEventListener('input', () => {
        const v = free.value;
        free.classList.toggle('has', v.trim() !== '');
        if (v.trim() !== '') {
          optsWrap.querySelectorAll('.qopt').forEach((b) => {
            b.classList.remove('sel');
            b.setAttribute('aria-pressed', 'false');
          });
        }
        slot.choice = v;
        recount();
      });
      block.appendChild(free);
    }

    panel.appendChild(block);
  });

  // ----- foot: submit -----
  const foot = document.createElement('div');
  foot.className = 'qpanel-foot';
  foot.appendChild(answered);
  recount();
  const submit = document.createElement('button');
  submit.type = 'button';
  submit.className = 'btn-go';
  submit.appendChild(playIcon());
  submit.appendChild(document.createTextNode('Submit'));
  foot.appendChild(submit);
  panel.appendChild(foot);
}

function renderGateBody(r, panel, pq) {
  const issues = Array.isArray(pq.issues) ? pq.issues : [];

  const intro = document.createElement('div');
  intro.className = 'gate-intro';
  intro.textContent = `This cycle reached its limit${gateWireCopy(r, pq.wireId)}${issues.length ? ' with open issues' : ''}. Approve another cycle to keep iterating, or continue with what you have.`;
  tagLevel(intro, 'advanced');
  // Simple mode reads the same decision without the vocabulary (docs/ui-levels.md: a blocking
  // prompt is never hidden, only simplified). Twin elements, so a mode change needs no re-render.
  const plain = document.createElement('div');
  plain.className = 'gate-intro';
  plain.dataset.maxLevel = 'simple';
  plain.textContent = issues.length
    ? 'The agents reviewed their own work and still see problems. Let them try once more, or carry on with what they have?'
    : 'The agents have used the attempts they are allowed. Let them try once more, or carry on with what they have?';
  panel.append(intro, plain);

  if (issues.length) {
    const list = document.createElement('ul');
    list.className = 'issues';
    issues.forEach((iss) => {
      const sev = String((iss && iss.severity) || 'suggestion').toLowerCase();
      const li = document.createElement('li');
      li.className = `issue sev-${sev}`;

      const ihead = document.createElement('div');
      ihead.className = 'issue-head';
      const sevEl = document.createElement('span');
      sevEl.className = 'issue-sev';
      sevEl.textContent = sev;
      const titleEl = document.createElement('span');
      titleEl.className = 'issue-title';
      titleEl.textContent = (iss && iss.title) || '(untitled issue)';
      ihead.append(sevEl, titleEl);
      li.appendChild(ihead);

      if (iss && iss.detail) {
        const det = document.createElement('div');
        det.className = 'issue-detail';
        det.textContent = iss.detail;
        li.appendChild(det);
      }
      if (iss && iss.location) {
        const loc = document.createElement('div');
        loc.className = 'issue-loc';
        loc.textContent = iss.location;
        li.appendChild(loc);
      }
      list.appendChild(li);
    });
    panel.appendChild(list);
  }

  const foot = document.createElement('div');
  foot.className = 'qpanel-foot gate-actions';
  const cont = document.createElement('button');
  cont.type = 'button';
  cont.className = 'btn gate-continue';
  cont.textContent = "Don't approve another cycle and continue";
  const another = document.createElement('button');
  another.type = 'button';
  another.className = 'btn btn-primary gate-another';
  another.textContent = 'I approve another cycle';
  foot.append(cont, another);
  panel.appendChild(foot);
}

// Recovery prompt: a node hit a recoverable error (auth / rate-limit / quota /
// network). Show the cause and let the user fix it then Retry, or park the run
// with Pause run — nothing here ends a run, only Stop does.
function renderRecoveryBody(r, panel, pq) {
  const rec = pq.recovery || {};
  const intro = document.createElement('div');
  intro.className = 'gate-intro';
  const hint = rec.cls === 'auth'
    ? 'Re-authenticate (e.g. run `claude setup-token` or `/login`), then Retry.'
    : 'Fix the problem (wait out a limit, restore connectivity, top up credit), then Retry.';
  intro.textContent = `This step could not reach the model. ${hint} Or pause the run and come back later — only Stop ends it.`;
  panel.appendChild(intro);

  if (rec.message) {
    const msg = document.createElement('div');
    msg.className = 'issue-detail';
    msg.textContent = rec.message;
    panel.appendChild(msg);
  }

  const foot = document.createElement('div');
  foot.className = 'qpanel-foot gate-actions';
  // The give-up option comes from the failure policy's row (options ride the
  // prompt): 'pause' parks the run, 'abort' ends it. Older payloads carry none.
  const giveUp = (Array.isArray(rec.options) && rec.options.find((o) => o && o.id !== 'retry')) || { id: 'pause' };
  const pause = document.createElement('button');
  pause.type = 'button';
  pause.className = giveUp.id === 'abort' ? 'btn recovery-abort' : 'btn recovery-pause';
  pause.textContent = giveUp.id === 'abort' ? 'Abort run' : 'Pause run';
  pause.title = giveUp.id === 'abort'
    ? 'End the run here with this error. The worktree is torn down.'
    : 'Park the run here with this error as the reason. Nothing is discarded — Resume retries the step later.';
  const retry = document.createElement('button');
  retry.type = 'button';
  retry.className = 'btn btn-primary recovery-retry';
  retry.textContent = 'Retry';
  foot.append(pause, retry);
  panel.appendChild(foot);
}

// ---- the `workflow` arm (spec §7.4): Auto's proposal, the shared body plus this host's
// tunables table and buttons. Both mounted panels (card + detail) keep their own renderer
// and their own edit state on the panel node (panel.__wf), like panel.__answers.
function renderWorkflowBody(r, panel, pq) {
  const w = pq.workflow || {};
  const base = w.nodes || {};
  const wf = { name: w.name || '', nodes: {}, handle: null };   // nodes: edits only (diff against `base`)
  panel.__wf = wf;
  const classifyRows = (r.subAgents || []).filter((s) => s && s.subagentType === 'auto-classify');
  // B5: resume() does not rehydrate sub-agent rows, so after a resume the rows undercount; the
  // proposal's own costUsd (restored from the resume point) is the floor.
  const costUsd = Math.max(classifyRows.reduce((sum, s) => sum + (Number(s.costUsd) || 0), 0), Number(w.costUsd) || 0);
  const body = document.createElement('div');
  body.className = 'qbody';
  const handle = renderAutoProposal(w, { doc: document, order: ['name', 'warnings'], costUsd, rounds: w.round, onName: (v) => { wf.name = v; } });
  wf.handle = handle;
  panel.__dispose = () => { handle.destroy(); wf.handle = null; };
  body.appendChild(handle.el);
  // A23: what the user asked for last round, from this client's memory (the payload carries no echo).
  if (r._autoRevise && (w.round || 1) > 1) {
    const note = document.createElement('div'); note.className = 'qnote';
    const b = document.createElement('b'); b.textContent = `Round ${w.round - 1} revised: `;
    note.append(b, document.createTextNode(`\u201c${r._autoRevise}\u201d`));
    handle.el.insertBefore(note, handle.parts.name);
  }
  // The name row reads "Workflow: <name>" (the label is this host's; the shared body and the chat card keep the bare name).
  const nameRowEl = handle.parts.name.querySelector('.ask-wfcard-namerow');
  if (nameRowEl) { const lab = document.createElement('span'); lab.className = 'wf-namelabel'; lab.textContent = 'Workflow:'; nameRowEl.prepend(lab); }
  // ---- the workflow preview: always visible, the whole thing opens a large pan/zoom popup
  const agentCount = Object.keys(base).length;
  const preview = document.createElement('button');
  preview.type = 'button'; preview.className = 'wf-preview';
  preview.setAttribute('aria-label', 'Open the workflow in a larger view');
  preview.appendChild(handle.parts.graph);
  const hint = document.createElement('span'); hint.className = 'wf-preview-hint'; hint.textContent = 'Enlarge';
  preview.appendChild(hint);
  preview.addEventListener('click', stopBubble((ev) => openWorkflowPopup(w, wf, handle, ev.currentTarget)));
  handle.el.insertBefore(preview, handle.parts.warnings || null);
  // ---- Customize agents, then Why this? — plain rows, no chips
  const disclose = (title, nodes, { open = false } = {}) => {
    const els = nodes.filter(Boolean); if (!els.length) return null;
    const d = document.createElement('details'); d.className = 'wf-disc'; d.open = open;
    const sm = document.createElement('summary'); sm.textContent = title; d.appendChild(sm);
    const inner = document.createElement('div'); inner.className = 'wf-disc-body'; inner.append(...els); d.appendChild(inner);
    return d;
  };
  const facts = document.createElement('dl'); facts.className = 'wf-facts';
  const fact = (k, ...v) => { const dt = document.createElement('dt'); dt.textContent = k; const dd = document.createElement('dd'); dd.append(...v); facts.append(dt, dd); };
  const looks = [w.taskKind, w.size, ...(w.signals || []).filter((x) => !/^fingerprint:/i.test(x) && !/cards? read$/i.test(x))].filter(Boolean);
  if (looks.length) fact('Classified as', looks.join(' \u00b7 '));
  fact('Saved as', handle.parts.match);
  fact('Classifier cost', `\u2248 $${(Number(costUsd) || 0).toFixed(2)}${w.round > 1 ? ` \u00b7 ${w.round} rounds` : ''}`);
  const table = buildTunablesTable(w, wf, handle);
  const discs = [
    tagLevel(disclose('Customize agents', [table], { open: agentCount > 1 }), 'expert'),   // accept-as-proposed is the simple path
    disclose('Why this?', [facts]),
  ].filter(Boolean);
  const discBox = document.createElement('div'); discBox.className = 'wf-discs'; discBox.append(...discs);
  handle.el.appendChild(discBox);
  // ---- revise box + foot
  const ta = document.createElement('textarea');
  ta.className = 'qfree qfree-area'; ta.rows = 3; ta.hidden = true;
  ta.placeholder = 'What should change? e.g. "drop the manual web check, add a plan review"';
  ta.setAttribute('aria-label', 'Revision request');
  body.appendChild(ta);
  const foot = document.createElement('div'); foot.className = 'qpanel-foot';
  const mk = (cls, text) => { const b = document.createElement('button'); b.type = 'button'; b.className = cls; b.textContent = text; return b; };
  const cancel = mk('qcancel wf-cancel', 'Cancel run');
  const revise = tagLevel(mk('qopen wf-revise', 'Revise'), 'advanced');
  const send = mk('qopen wf-send', 'Send'); send.hidden = true;
  const accept = mk('btn-go wf-accept', 'Accept & run');
  accept.dataset.busyLabel = 'Starting…';                 // A31: setPanelBusy's primary swap reads it
  accept.prepend(playIcon());
  const stop = (fn) => (e) => { e.stopPropagation(); fn(); };   // the #run-detail delegates sit above this node
  cancel.addEventListener('click', stop(async () => {
    const ok = await confirmModal({ title: 'Cancel this run?', message: 'The run stops now. Nothing is saved — no workflow row is written.', confirmLabel: 'Cancel run', cancelLabel: 'Keep', danger: true });
    if (ok) postAnswer(r, { decision: 'cancel' });
  }));
  revise.addEventListener('click', stop(() => { ta.hidden = !ta.hidden; send.hidden = ta.hidden; if (!ta.hidden) ta.focus(); }));
  send.addEventListener('click', stop(async () => {
    const text = ta.value.trim().slice(0, 4096);
    if (!text) { ta.classList.add('qfree-err'); ta.focus(); return; }
    // Record the echo only once the server has it: a failed POST leaves the panel
    // usable, and the next round must not quote text that never arrived (A23).
    if (await postAnswer(r, { decision: 'revise', text })) r._autoRevise = text;
  }));
  ta.addEventListener('input', () => ta.classList.remove('qfree-err'));
  accept.addEventListener('click', stop(() => {
    const nodes = {};
    for (const [id, sel] of Object.entries(wf.nodes)) {
      const diff = {};
      for (const k of ['model', 'effort', 'fanOut', 'askQuestions']) if (sel[k] !== undefined && sel[k] !== (base[id] || {})[k]) diff[k] = sel[k];
      // A model change carries its effort even when it equals the base's: the resolver drops a
      // row's authored effort whenever the overlay names a model without one (workflows.mjs:664),
      // so `{model}` alone would run with NO effort while this table showed one (B1). The model
      // `change` handler always writes `sel.effort` next to `sel.model` (buildTunablesTable).
      if (diff.model !== undefined && sel.effort !== undefined) diff.effort = sel.effort;
      if (Object.keys(diff).length) nodes[id] = diff;
    }
    postAnswer(r, { decision: 'accept', name: handle.getName(), nodes });
  }));
  foot.append(cancel, revise, send, accept);
  body.appendChild(foot);
  panel.appendChild(body);
  handle.relayout();                                        // measure now that the body is attached (0 => 702 default)
}

const stopBubble = (fn) => (e) => { e.stopPropagation(); fn(e); };   // the run-detail delegates sit above the panel

// The large workflow view: the same graph in monitor mode (drag to pan, ⌘/ctrl+scroll or the buttons to zoom).
// Reads the tunables edited so far, so the chips match the table. Esc, the × or a click outside closes it.
function openWorkflowPopup(w, wf, handle, opener) {
  const m = w.manifest || { graph: { nodes: [], wires: [] } };
  const bands = proposalBands(w, wf.nodes);
  const ov = document.createElement('div');
  ov.className = 'viewer-modal wf-pop'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true'); ov.setAttribute('aria-label', 'Workflow');
  const card = document.createElement('div'); card.className = 'card wf-pop-card';
  const head = document.createElement('div'); head.className = 'wf-pop-head';
  const title = document.createElement('h2'); title.textContent = `Workflow: ${handle.getName() || 'untitled'}`;
  const close = document.createElement('button'); close.type = 'button'; close.className = 'btn btn-ghost btn-mini'; close.textContent = 'Close';
  head.append(title, close);
  const canvas = document.createElement('div'); canvas.className = 'wf-pop-canvas gv-host';
  const foot = document.createElement('div'); foot.className = 'wf-pop-hint'; foot.textContent = 'drag to pan \u00b7 \u2318/ctrl+scroll to zoom';
  card.append(head, canvas, foot); ov.appendChild(card);
  document.body.appendChild(ov);

  const view = createGraphView(canvas, {
    doc: document, mode: 'monitor', portsFn: manifestPortsFn(m), agents: manifestAgents(m), zoomMin: 0.3, zoomMax: 2.5,
    scale: FLOW_SCALE, layout: 'flow', band: (n) => bands[n.id] || null, order: Array.isArray(w.order) && w.order.length ? [...w.order] : null,
  });
  view.render(manifestTemplate(m), {});
  const nav = document.createElement('div'); nav.className = 'gv-nav';
  const btn = (label, glyph, fn) => { const b = document.createElement('button'); b.type = 'button'; b.className = 'gv-nav-btn'; b.setAttribute('aria-label', label); b.title = label; b.textContent = glyph; b.addEventListener('click', fn); nav.appendChild(b); };
  const zoom = (mult) => view.zoomAbout(view.getTransform().z * mult, canvas.clientWidth / 2, canvas.clientHeight / 2);
  // Centre the graph and let it grow to fill the popup (the shared fit never magnifies past 1x; here the point is a large view).
  const fit = () => {
    const r = { width: canvas.clientWidth, height: canvas.clientHeight };   // the canvas box (the stage's own height follows the rows)
    if (!(r.width > 0 && r.height > 0)) return;
    const lay = view.relayout(r.width / 1.4);     // lay the rows out for a world 1.4x narrower, then scale up to fill
    if (!lay) return;
    // the card boxes come straight from the flow layout (world units), not from the DOM
    let x0 = Infinity; let y0 = Infinity; let x1 = -Infinity; let y1 = -Infinity;
    for (const p of Object.values(lay.pos)) {
      x0 = Math.min(x0, p.x); y0 = Math.min(y0, p.y); x1 = Math.max(x1, p.x + lay.cardW); y1 = Math.max(y1, p.y + p.h + lay.bottomBand);
    }
    if (!(x1 > x0)) return;
    const pad = 32; const bw = x1 - x0 + 2 * pad; const bh = y1 - y0 + 2 * pad;
    const z = Math.max(0.3, Math.min(r.width / bw, r.height / bh, 2.5));
    view.setTransform({ x: (r.width - (x1 - x0) * z) / 2 - x0 * z, y: (r.height - (y1 - y0) * z) / 2 - y0 * z, z });
  };
  btn('Zoom in', '+', () => zoom(1.2)); btn('Zoom out', '\u2212', () => zoom(1 / 1.2)); btn('Fit workflow to view', '\u25a1', fit);
  canvas.appendChild(nav);
  const pan = view.createNav({});
  fit();

  const onKey = (e) => { if (e.key === 'Escape') { e.stopPropagation(); shut(); } };
  function shut() {
    document.removeEventListener('keydown', onKey, true);
    pan.destroy(); view.destroy(); ov.remove();
    if (opener && opener.isConnected) opener.focus();
  }
  document.addEventListener('keydown', onKey, true);
  close.addEventListener('click', shut);
  ov.addEventListener('click', (e) => { if (e.target === ov) shut(); });
  close.focus();
}

// The tunables table: one row per dispatch-ordered agent. Columns 1fr · 160 · 160 · 90 · 100.
function buildTunablesTable(w, wf, handle) {
  const models = Array.isArray(w.models) ? w.models : [];
  const table = document.createElement('table');
  table.className = 'qtune';
  table.innerHTML = '<colgroup><col><col style="width:160px"><col style="width:160px"><col style="width:90px"><col style="width:100px"></colgroup>'
    + '<thead><tr><th>agent</th><th>model</th><th>effort</th><th>fan-out</th><th>questions</th></tr></thead>';
  const tb = document.createElement('tbody');
  const cur = (id) => ({ ...(w.nodes[id] || {}), ...(wf.nodes[id] || {}) });
  const set = (id, patch) => { wf.nodes[id] = { ...(wf.nodes[id] || {}), ...patch }; handle.setNodeTunables(id, patch); };
  const sel = (label, opts, value) => {
    const wrap = document.createElement('span'); wrap.className = 'select-wrap';
    const s = document.createElement('select'); s.setAttribute('aria-label', label);
    for (const [v, t] of opts) s.appendChild(option(v, t));
    s.value = value; wrap.appendChild(s); return { wrap, s };
  };
  // `locked` = disabled for good (A34): data-locked="1" keeps setPanelBusy's restore from re-enabling it.
  const sw = (label, on, locked, onChange) => {
    const l = document.createElement('label'); l.className = 'qtune-sw';
    const cb = document.createElement('input'); cb.type = 'checkbox'; cb.className = 'sw-input'; cb.checked = !!on; cb.setAttribute('aria-label', label);
    if (locked) { cb.disabled = true; cb.dataset.locked = '1'; }
    cb.addEventListener('change', () => onChange(cb.checked));
    const knob = document.createElement('span'); knob.className = 'switch switch-sm';
    const t = document.createElement('span'); t.className = 'qtune-sw-t'; t.textContent = label.replace(/ for .*$/, '');
    l.append(cb, knob, t); return l;
  };
  const lockEffort = (s, locked) => { s.disabled = locked; if (locked) s.dataset.locked = '1'; else delete s.dataset.locked; };
  const effortsOf = (mid) => models.find((m) => m.id === mid)?.efforts || [];
  // Only a model's OWN efforts are selectable: sanitizeProposalAnswer keeps `effort` only when the
  // resolved model lists it — `effort: ''` on a set model is silently dropped, so a choosable
  // "default" would lie. A node whose effort is unset shows a DISABLED `default` placeholder.
  const fillEffort = (s, mid, value) => {
    const list = effortsOf(mid);
    const kids = mid ? list.map((e) => option(e, e)) : [option('', 'default')];
    const picked = mid && list.includes(value) ? value : '';
    if (mid && !picked) { const ph = option('', 'default'); ph.disabled = true; kids.unshift(ph); }
    s.replaceChildren(...kids); s.value = picked;              // '' selects the placeholder
    lockEffort(s, !mid);
  };
  for (const id of Array.isArray(w.order) ? w.order : Object.keys(w.nodes || {})) {
    const n = w.nodes[id]; if (!n) continue;
    const tr = document.createElement('tr'); tr.dataset.nodeId = id;
    const name = document.createElement('td'); name.textContent = n.label || n.key || id; name.title = name.textContent; tr.appendChild(name);
    const tdModel = document.createElement('td'); const tdEffort = document.createElement('td');
    const model = sel(`Model for ${name.textContent}`, [['', 'default'], ...models.map((m) => [m.id, m.label || m.id])], n.model || '');
    const effort = sel(`Effort for ${name.textContent}`, [], '');
    fillEffort(effort.s, n.model || '', n.effort || '');
    model.s.addEventListener('change', () => {
      const mid = model.s.value;
      // the mockup's rule over the model's REAL efforts: keep the current one if offered, else its
      // second, else its first — so a set model always posts a valid effort, never the placeholder
      const list = effortsOf(mid);
      const keep = list.includes(cur(id).effort) ? cur(id).effort : (list[1] || list[0] || '');
      fillEffort(effort.s, mid, keep);
      set(id, { model: mid, effort: mid ? keep : '' });
    });
    effort.s.addEventListener('change', () => set(id, { effort: effort.s.value }));
    tdModel.dataset.label = 'Model'; tdEffort.dataset.label = 'Effort';
    tdModel.appendChild(model.wrap); tdEffort.appendChild(effort.wrap); tr.append(tdModel, tdEffort);
    const tdFan = document.createElement('td'); tdFan.className = 'qtune-sw-cell';
    const fan = sw(`Fan-out for ${name.textContent}`, n.fanOut, !n.canFanOut, (on) => set(id, { fanOut: on }));
    if (n.fanOutLocked) fan.title = 'Runs per project on a workspace';   // canFanOut is false too ⇒ checked + locked
    tdFan.appendChild(fan); tr.appendChild(tdFan);
    const tdQ = document.createElement('td'); tdQ.className = 'qtune-sw-cell';
    if (n.asksQuestions) tdQ.appendChild(sw(`Questions for ${name.textContent}`, n.askQuestions, n.questionsLocked, (on) => set(id, { askQuestions: on })));
    else tdQ.textContent = '\u2014';
    tr.appendChild(tdQ);
    tb.appendChild(tr);
  }
  table.appendChild(tb);
  return table;
}

// ---- the `form` arm (ask-forms design §6). The panel head and foot are the
// house chrome; everything between them is renderAskForm's detached tree.

/** The ONE fetch behind ctx.loadText for a LIVE run: a text-class preview file,
 *  by index. The renderer module never fetches (its "no fetch in a view module"
 *  rule); it declares what it needs and this resolves it. */
async function askLoadText(r, ask, index) {
  const url = askFileUrl(r, ask, index);
  if (!url) throw new Error(`ask file ${index}: no snapshot`);   // X14; the widget tiles instead
  const res = await fetch(url);
  if (!res.ok) throw new Error(`ask file ${index}: ${res.status}`);
  return res.text();
}

/** Mount the form into `panel` and stash the handle per panel (the card and the
 *  detail hold one each — W6). */
function askFormHost(r, panel, ask) {
  const body = document.createElement('div');
  body.className = 'qbody';
  const answered = document.createElement('span');
  answered.className = 'qanswered';
  // progress() counts REQUIRED fields only; a form whose fields are all optional
  // (each with a default) has nothing to count, and "0 of 0 answered" reads as broken.
  const paintProgress = (p) => {
    answered.textContent = p.total ? `${p.done} of ${p.total} answered` : '';
    answered.hidden = !p.total;
  };
  const handle = renderAskForm(ask, {
    doc: document,
    fileUrl: (index) => askFileUrl(r, ask, index),
    loadText: (index) => askLoadText(r, ask, index),
    markdown: pageMarkdown,
    highlight: (el) => hdMarkdown.highlight(el),
    onChange: () => paintProgress(handle.progress()),
  });
  panel.__askForm = handle;
  panel.__dispose = () => { handle.dispose(); panel.__askForm = null; };
  body.appendChild(handle.el);
  paintProgress(handle.progress());

  const foot = document.createElement('div');
  foot.className = 'qpanel-foot';
  foot.appendChild(answered);
  const submit = document.createElement('button');
  submit.type = 'button';
  submit.className = 'btn-go';
  submit.appendChild(playIcon());
  submit.appendChild(document.createTextNode('Submit'));
  foot.appendChild(submit);
  body.appendChild(foot);
  panel.appendChild(body);
  // The markdown bundle is lazy; repaint the tracked boxes once it can render.
  bindMarkdownReady().then((ok) => { if (ok) handle.paintMarkdown(); });
  return handle;
}

registerAskRenderer('form', {
  title: (pq, ctx) => (typeof pq.title === 'string' && pq.title.trim() !== ''
    ? pq.title
    : `${(activeNodes(ctx.run)[0] || {}).label || 'Pipeline'} needs your input`),
  count: (pq) => { const n = askFormFieldCount(pq); return `${n} field${n === 1 ? '' : 's'}`; },
  render: (panel, pq, ctx) => { askFormHost(ctx.run, panel, pq); },
  collect: (panel) => {
    const handle = panel && panel.__askForm;
    if (!handle) return null;
    const out = handle.collect();
    // The marks always show the LAST verdict: a clean local collect clears a
    // previous 422's marks before the answer leaves; a failing one replaces them.
    handle.setErrors(out.errors);
    if (out.errors.length) return null;
    return { values: out.values };
  },
  setErrors: (panel, errors) => {
    const handle = panel && panel.__askForm;
    if (handle) handle.setErrors(errors);
  },
});

/** How many answer fields a form ask currently shows. Uses the SHARED layout walk
 *  so the chip and the renderer can never disagree. */
function askFormFieldCount(pq) {
  const layout = Array.isArray(pq && pq.layout) ? pq.layout : [];
  const seeded = {};
  const props = ((pq && pq.answerSchema) || {}).properties || {};
  for (const [k, s] of Object.entries(props)) if (s && s.default !== undefined) seeded[k] = s.default;
  return visibleAnswerFields(layout, seeded).length;
}

// renderClarifyBody stamps BOTH panel.__answers and r._answers; the panel copy is
// authoritative (card + detail are mounted at once). This holds the last-rendered
// run only so a collect() with no panel node keeps today's behaviour.
let lastClarifyRun = null;
function askFallbackAnswers() { return lastClarifyRun ? lastClarifyRun._answers : null; }

// ---- the four legacy registrants (D6). The bodies above are UNCHANGED; these are
// adapters, so the six suites that pin their markup keep passing untouched.
registerAskRenderer('clarify', {
  title: (pq, ctx) => (pq.kind === 'questions'
    ? `${pq.agent || 'Agent'} has questions`
    // The ACTIVE agent names the panel (the v1 phase vocabulary is gone).
    : `${(activeNodes(ctx.run)[0] || {}).label || 'Pipeline'} needs your input`),
  count: (pq) => { const n = realQuestions(pq).length; return `${n} question${n === 1 ? '' : 's'}`; },
  render: (panel, pq, ctx) => renderClarifyBody(ctx.run, panel, pq),
  // `panel` is null only for a caller that has no panel node; r._answers is the
  // no-panel fallback renderClarifyBody keeps writing.
  collect: (panel) => ({
    answers: ((panel && panel.__answers) || askFallbackAnswers() || []).map((s) => ({
      id: s.id, question: s.question,
      choice: typeof s.choice === 'string' ? s.choice.trim() : '',
    })),
  }),
});
registerAskRenderer('gate', {
  title: () => 'Cycle gate',
  render: (panel, pq, ctx) => renderGateBody(ctx.run, panel, pq),
});
registerAskRenderer('recovery', {
  title: (pq) => `${(((pq.recovery || {}).cls) || 'recoverable').replace('_', ' ')} error — action needed`,
  render: (panel, pq, ctx) => renderRecoveryBody(ctx.run, panel, pq),
});
registerAskRenderer('workflow', {
  title: (pq) => `Auto proposes a workflow · round ${(pq.workflow && pq.workflow.round) || 1}`,
  count: () => 'workflow',
  render: (panel, pq, ctx) => renderWorkflowBody(ctx.run, panel, pq),
});

// Gather the answer from the panel that was submitted and POST it. The shape is
// the registered renderer's business; a renderer that returns null has refused
// (it has already marked its own fields) and nothing is posted.
function submitAnswer(r, panel = null) {
  const renderer = askRendererFor(askKindOf(r && r.pendingQuestion)) || askRendererFor('clarify');
  if (!renderer) return;
  const payload = renderer.collect(panel);
  if (payload == null) return;
  postAnswer(r, payload);
}

// POST /api/answer for a run's pending question. On a transport/HTTP error we
// log to the card and re-enable the panel; on 200 we DON'T assume the run
// resumed (the server returns 200 even for a stale id) — we disable the panel,
// show a "Resuming…" affordance, set r._answering, and KEEP r.pendingQuestion.
// The panel is cleared only when the next phase/state event confirms resume.
// Returns TRUE only when the POST came back 200 — the workflow panel's Revise
// echo is recorded off that, so a failed send never claims a round the server
// never saw. Every other caller ignores the return.
async function postAnswer(r, payload) {
  if (!r || !r.pendingQuestion) return false;
  // Re-entrancy guard: an answer is already in flight for this run. Without
  // this a synthetic/double click (or a re-triggered handler) could fire a
  // second POST before maybeResume clears _answering.
  if (r._answering) return false;
  // Never post for a dead run.
  if (r._finished || isTerminalStatus(r.status)) return false;
  const id = r.pendingQuestion.id;
  const runId = r.runId;

  setPanelBusy(r, true);
  r._answering = true;

  try {
    const res = await fetch('/api/answer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ runId, id, payload }),
    });
    // Gate 3 said no. That is an ANSWER outcome, not a transport failure: the
    // question stays open, the panel keeps every typed value, and the renderer
    // marks the offending fields. pendingQuestion is deliberately untouched.
    if (res.status === 422) {
      const body = await safeJson(res);
      const errors = Array.isArray(body.errors) ? body.errors : [];
      r._answering = false;
      setPanelBusy(r, false);
      const renderer = askRendererFor(askKindOf(r.pendingQuestion));
      if (renderer) for (const panel of qpanelsFor(r)) renderer.setErrors(panel, errors);
      onLog(r, { source: 'ui', level: 'error',
        text: `answer rejected: ${errors.length} field${errors.length === 1 ? '' : 's'} to fix`, ts: Date.now() });
      return false;
    }
    if (!res.ok) {
      const err = await safeJson(res);
      r._answering = false;
      setPanelBusy(r, false);
      onLog(r, { source: 'ui', level: 'error', text: `answer failed: ${err.error || res.status}`, ts: Date.now() });
      return false;
    }
    // 200: keep pendingQuestion; wait for the next phase/state to confirm resume.
    return true;
  } catch (e) {
    r._answering = false;
    setPanelBusy(r, false);
    onLog(r, { source: 'ui', level: 'error', text: `answer error: ${e.message}`, ts: Date.now() });
    return false;
  }
}

// Single source of truth for "this run is over". The server's terminal statuses
// are done|error|stopped; the remaining synonyms are accepted defensively. Used
// by liveRuns (to exclude finished runs) and postAnswer (to refuse a late POST).
function isTerminalStatus(status) {
  const s = String(status || '').toLowerCase();
  return s === 'done' || s === 'error' || s === 'stopped' || s === 'aborted' || s === 'failed' || s === 'complete' || s === 'completed' || s === 'interrupted';
}

// Every mounted .qpanel for a run: the run page's, when it is open on this run (the list card
// carries no panel; it only points at the run page).
function qpanelsFor(r) {
  const out = [];
  const screen = runDetailState.screen;
  if (screen && runDetailState.runId === r.runId) {
    const detail = screen.querySelector('.qpanel');
    if (detail) out.push(detail);
  }
  return out;
}

// Disable/enable the panels' interactive controls and reflect a "Resuming…"
// state on the primary button while an answer is in flight / awaiting resume.
function setPanelBusy(r, busy) {
  for (const panel of qpanelsFor(r)) {
    // A25: the workflow arm's table has selects and its revise box is a textarea.
    // A34: a control locked for good (data-locked) stays disabled through the busy -> idle restore.
    panel.querySelectorAll('button, input, select, textarea').forEach((node) => { node.disabled = busy || node.dataset.locked === '1'; });
    // A draggable <li> is none of button/input/select/textarea, so the sweep above
    // cannot reach the rank rows. Marker-scoped so nothing else in the panel moves.
    panel.querySelectorAll('[data-af-drag]').forEach((node) => { node.draggable = !busy; });
    const primary = panel.querySelector('.btn-go, .gate-another');
    if (primary && busy && !primary.dataset.label) {
      primary.dataset.label = primary.textContent;
      primary.textContent = primary.dataset.busyLabel || 'Resuming…';
    } else if (primary && !busy && primary.dataset.label) {
      primary.textContent = primary.dataset.label;
      delete primary.dataset.label;
    }
  }
}

// Empty + hide a run's qpanels and drop its attention ring. Used on resume and
// from finishRun's terminal path.
function clearQpanel(r) {
  for (const panel of qpanelsFor(r)) {
    disposeQpanel(panel);
    // A stale `.qpanel-workflow` would make the delegates swallow a later clarify Submit in this node.
    panel.classList.remove('qpanel-workflow');
    panel.__wf = null;
    panel.__askForm = null;                    // disposeQpanel already ran handle.dispose()
    panel.innerHTML = '';
    panel.classList.add('hidden');
    // The identity stamp paintRdQuestions keys its rebuild on. Emptying the panel
    // without dropping it would make a re-asked question with the SAME id read as
    // "already painted", leaving the detail permanently blank.
    delete panel.dataset.qid;
  }
  if (r.el) r.el.classList.remove('attention');
  const screen = runDetailState.screen;
  if (screen && runDetailState.runId === r.runId) {
    const host = screen.querySelector('.rd-questions');
    if (host) host.hidden = true;
  }
}

// ---------------------------------------------------------------------------
// Done / error — converge to a single idempotent terminal path.
//
// The server fires BOTH `error` and `done` on an error, and a stop emits
// state(stopped) -> done. finishRun is guarded by r._finished so the second
// call no-ops. On finish we paint the terminal stepper, drop the card from the
// live view, refresh History for that project, then client-evict the heavy
// fields (logLines/el) while keeping the model in the map so a duplicate
// hello/event won't recreate it fresh.
// ---------------------------------------------------------------------------
function finishRun(r, status) {
  if (r._finished) return;
  r._finished = true;
  r._finishedAs = status;   // onDone re-arms a run that finished as paused (it is stopped later)
  scheduleOnboardingRefresh();
  r._decorSeq = (r._decorSeq || 0) + 1;   // isLive(r) reads _finished/status/pendingQuestion
  r.status = status;
  r.pendingQuestion = null;
  r._answering = false;
  // No `done` frame carries a timestamp (the orchestrator emits {status,
  // pipelineDir} and bufferEvent tags only runId, ui/server.mjs:308-313), so the
  // arrival time is the only honest "finished at" the client can show. Read by the
  // detail Overview's terminal copy (§5.7).
  r.finishedAtMs = Date.now();

  // Clear the card's qpanel + attention before it drops out.
  if (r.el) clearQpanel(r);

  // A paused run is parked in Running (resumable), NOT a finished result: it does
  // NOT linger (no green/red "seen me" marker, never acknowledged-to-drop), keeps
  // its card + log for an in-place Resume, and keeps the user on its focus tab.
  const paused = status === 'paused';

  // Orchestration pipeline finishing LIVE → it lingers (greyed) until opened once.
  const willLinger = !paused && isPipelineRun(r);
  if (willLinger) markLingering(r.runId);  // no-op if already acknowledged

  // A run that finishes while its DETAIL page is open keeps the page until History
  // has its finished row; then rdHandOffOpen moves it to the saved run (same tab).
  // Dropping state.selectedRunId here would switch off `acknowledgeRun`'s repaint
  // guard at the wrong moment.
  // Lingering/acknowledgement is untouched: markLingering above still runs, and
  // the lingerer is acknowledged the next time its detail is opened (showView's
  // running branch, which reads state.selectedRunId — on Back that is '' by then,
  // exactly as before D8).

  // The row leaves the live count (liveRuns excludes terminal statuses).
  renderRunningView();   // the Runs list keeps the lingerer / paused run as a live row
  updateNavCounts();
  renderPipelineTabs();
  // History is machine-wide + decoupled from the project picker now; if the user
  // is looking at it, force-refetch so the just-finished pipeline surfaces with no
  // stale-cache flash (and re-triggers Phase-2 PR enrichment). A paused run's History
  // row is deduped behind its live row, so refreshing is still correct.
  if (inRunsView()) loadHistoryView({ force: true });

  // Evict heavy fields ONLY for non-lingerers AND non-paused; lingerers + paused
  // keep their logLines so the open page and Resume have the log context.
  if (!willLinger && !paused) { r.logLines = []; r.el = null; }
}

function onDone(r, msg) {
  // A cost pause carries the reason code ('cost_pipeline' | 'cost_total') that
  // drives the card banner, the status pill, and the resume gating. Assigned
  // unconditionally so a later reasonless done clears it, matching the server's
  // own entry.pauseReason reset in wireRun.
  r.pauseReason = msg.reason || null;
  // An 'error' pause also carries the cause it parked on; assigned unconditionally
  // for the same reason as the code above — a later reasonless done must clear it.
  r.pauseDetail = msg.detail || null;
  r.limitEngine = msg.limitEngine || null;
  // A paused run already finished once, as paused. Its stop (or a settle from elsewhere) sends a
  // terminal done on the same runId: finish it again, for real. Never on an `error` frame: onError
  // stays guarded, so a stray error after the pause cannot turn the parked run red.
  if (r._finished && r._finishedAs === 'paused' && RD_TERMINAL.includes(msg.status)) r._finished = false;
  finishRun(r, msg.status || 'done');
  // Nothing else picks up the FINAL spend delta: a non-cost `done` broadcasts no
  // budget-changed, and startBudgetTick refetches only while runs are live. Without
  // this the delta — and the `blocked` flip it can cause — waited for a reload, so
  // Start stayed enabled and the click hit the raw 403 instead of the creation gate.
  refreshBudget();
}

function onError(r) {
  finishRun(r, 'error');
}

// ---------------------------------------------------------------------------
// Form: source toggle, file loading
// ---------------------------------------------------------------------------
function syncSourceToggle() {
  const val = (el.sourceRadios.find((r) => r.checked) || {}).value || 'prompt';
  const plugin = !!state.activePluginSource;
  el.promptPane.classList.toggle('hidden', plugin || val !== 'prompt');
  el.markdownPane.classList.toggle('hidden', plugin || val !== 'markdown');
  if (el.pluginSourcePane) el.pluginSourcePane.classList.toggle('hidden', !plugin);
  refreshMentionHighlights();
}
el.sourceRadios.forEach((r) => r.addEventListener('change', syncSourceToggle));

// Segmented Task-source toggle. The .seg buttons are the visible control; the
// hidden radios (input[name="source"]) remain the source of truth read at submit.
$$('#source-seg button[data-src]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const src = btn.dataset.src;
    state.activePluginSource = null;
    $$('#source-seg button[data-plugin-src]').forEach((b) => { b.classList.remove('on'); b.setAttribute('aria-pressed', 'false'); });
    $$('#source-seg button[data-src]').forEach((b) => {
      const on = b === btn;
      b.classList.toggle('on', on);
      b.setAttribute('aria-pressed', String(on));
    });
    const radio = el.sourceRadios.find((r) => r.value === src);
    if (radio) radio.checked = true;
    syncSourceToggle();
  });
});

// --- Pluggable task sources (plugins). /api/sources is fetched on every
// New-Pipeline open (self-heals after install/enable — no cache invalidation
// seam needed); plugin sources append segment buttons after Prompt/Markdown.
// FEATURE-OFF: with zero plugins the endpoint lists only prompt+markdown, this
// renders NOTHING, and the segment + submit body are byte-identical to today.
async function loadTaskSources() {
  let sources = [];
  try {
    const res = await fetch('/api/sources');
    const data = await safeJson(res);
    if (res.ok && Array.isArray(data.sources)) sources = data.sources;
  } catch { /* endpoint absent/down -> legacy-only */ }
  state.pluginSources = sources.filter((s) => s && s.type === 'plugin');
  $$('#source-seg button[data-plugin-src]').forEach((b) => b.remove());   // idempotent rebuild
  for (const src of state.pluginSources) {
    const b = document.createElement('button');
    b.type = 'button';
    b.dataset.pluginSrc = `${src.plugin}/${src.sourceId}`;
    b.setAttribute('aria-pressed', 'false');
    b.textContent = src.displayName || src.sourceId;
    b.addEventListener('click', () => selectPluginSource(src, b));
    el.sourceSeg.appendChild(b);
  }
  // Active source vanished (uninstalled/disabled)? Fall back to the radios.
  const fresh = state.activePluginSource && state.pluginSources.find((s) =>
    s.plugin === state.activePluginSource.plugin && s.sourceId === state.activePluginSource.sourceId);
  if (state.activePluginSource && !fresh) {
    state.activePluginSource = null;
    el.pluginSourcePane.replaceChildren();
    syncSourceToggle();
  } else if (fresh && fresh !== state.activePluginSource
      && JSON.stringify(fresh) !== JSON.stringify(state.activePluginSource)) {
    // Same source, CHANGED payload — its `profiles` roster is the usual thing
    // that moves behind the pane's back (added/removed in Plugins settings).
    // Re-point and re-mount, or the profile bar keeps offering a stale list.
    // `fresh` is a new object on EVERY fetch, so equality is by value: an
    // unchanged source keeps the mounted pane (and the user's search, results
    // and picked task) instead of rebuilding it on each return to this view.
    state.activePluginSource = fresh;
    mountPluginSourcePane(fresh);
  }
}

// The pane's injected `call`: one connector op via POST /api/sources/call.
// `profile` is the project's binding for a multi-profile source (undefined
// otherwise) — without it the connector would run against whichever instance
// the server defaulted to.
function sourceCall(src, profile) {
  return async (op, args) => {
    const res = await fetch('/api/sources/call', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ plugin: src.plugin, sourceId: src.sourceId, op, args: args || {}, profile }),
    });
    const data = await safeJson(res);
    if (!res.ok || data.ok === false) {
      throw new Error((data.error && data.error.message) || data.error || `HTTP ${res.status}`);
    }
    return data.result;
  };
}

function selectPluginSource(src, btn) {
  state.activePluginSource = src;
  $$('#source-seg button').forEach((b) => {
    const on = b === btn;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', String(on));
  });
  syncSourceToggle();
  mountPluginSourcePane(src);
}

// Which project/workspace a binding hangs off, in the shape both binding routes
// accept. null when nothing is selected yet.
function bindingScopeRef() {
  if (state.runTarget === 'workspace') {
    const id = (el.workspaceSelect && el.workspaceSelect.value) || '';
    return id ? { workspaceId: id } : null;
  }
  const dir = selectedProjectPath();
  return dir ? { projectDir: dir } : null;
}

function bindingScopeLabel() {
  if (state.runTarget === 'workspace') {
    const ws = state.workspaces.find((w) => w && w.id === (el.workspaceSelect && el.workspaceSelect.value));
    return (ws && ws.name) || 'this workspace';
  }
  return selectedProjectName() || 'this project';
}

/**
 * The profile this project/workspace pulls from, or null when the user still
 * has to say. Only multi-profile sources ask; everything else resolves to
 * undefined and behaves exactly as it did before profiles existed.
 * @returns {Promise<{profile?:string, gate?:object}|null>} null = no scope yet
 */
async function resolveSourceProfile(src) {
  if (!src.multiProfile) return { profile: undefined };
  const ref = bindingScopeRef();
  if (!ref) return null;
  const qs = new URLSearchParams({ ...ref, plugin: src.plugin, sourceId: src.sourceId });
  const { ok, status, data } = await pluginApi('GET', `/api/source-bindings?${qs.toString()}`);
  // An HTTP failure is NOT "no binding": rendering the first-time gate on a
  // transient 500 invites the user to overwrite a correct standing binding.
  // Throw so the caller's retry branch handles it like a network error.
  if (!ok) throw new Error((data && data.error) || `HTTP ${status}`);
  if (data.profile) return { profile: data.profile, via: data.via };
  return {
    gate: {
      source: src,
      profiles: src.profiles || [],
      via: data.via || 'none',
      candidates: data.candidates || [],
      scopeLabel: bindingScopeLabel(),
    },
    ref,
  };
}

// validateConfig gate first (= "Test connection"); then the declarative pane.
async function mountPluginSourcePane(src) {
  const host = el.pluginSourcePane;
  // A caller that lost the pane while it awaited (an onPick/retry resolving
  // after the user switched sources) must not claim it back and orphan the
  // current owner's loop. Synchronous, so it cannot race the claim below.
  if (state.activePluginSource !== src) return;
  // Claim the pane BEFORE the first await. Every mount takes a run id, and any
  // older mount still in flight (a slow binding fetch, the SSO poll loop) stands
  // down at its next owns() check. Source identity alone is NOT enough: the
  // same src object is remounted when the project changes, and the binding is
  // per-project — an old project's late resolve must never paint (or pin a
  // profile for) the newly selected project's pane.
  const run = (Number(host.dataset.gateRun) || 0) + 1;
  host.dataset.gateRun = String(run);
  const owns = () => host.isConnected && host.dataset.gateRun === String(run)
    && state.activePluginSource === src;
  // Tear the previous pane down BEFORE the first await, not after it resolves:
  // while the binding fetch is in flight the old scope's task list, picked
  // task and resolved profile would otherwise stay live and SUBMITTABLE — a
  // Start in that window runs the new project against the old project's
  // tracker, the exact silent-wrong-tracker mistake bindings exist to prevent.
  state.activePluginProfile = null;
  host.replaceChildren(Object.assign(document.createElement('small'),
    { className: 'hint', textContent: `Checking ${src.displayName}…` }));
  // A multi-profile source cannot be asked anything until it is known WHICH
  // instance to ask, so the binding is resolved before the connection check.
  // A FAILED resolve (server briefly unreachable mid project switch) must not
  // resurrect the previous scope's pane either — error box with retry.
  let resolved;
  try {
    resolved = await resolveSourceProfile(src);
  } catch (err) {
    if (!owns()) return;
    state.activePluginProfile = null;
    const box = document.createElement('div');
    box.className = 'sp-config-missing';
    box.appendChild(Object.assign(document.createElement('p'),
      { className: 'hint err', textContent: `Could not resolve the source profile: ${err.message}` }));
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.className = 'btn btn-ghost btn-mini';
    retry.textContent = 'Retry';
    retry.addEventListener('click', () => mountPluginSourcePane(src));
    box.appendChild(retry);
    host.replaceChildren(box);
    return;
  }
  if (!owns()) return;
  if (!resolved) {
    host.replaceChildren(Object.assign(document.createElement('small'),
      { className: 'hint', textContent: 'Select a project first — the source profile is bound to it.' }));
    return;
  }
  if (resolved.gate) {
    host.replaceChildren(renderProfileGate(resolved.gate, {
      onPick: async (profile) => {
        const r = await pluginApi('PUT', '/api/source-bindings',
          { ...resolved.ref, plugin: src.plugin, sourceId: src.sourceId, profile });
        if (!r.ok) return notify({ tone: 'err', title: 'Could not save the profile binding', detail: r.data.error || '', key: 'profile-binding' });
        mountPluginSourcePane(src);
      },
    }));
    return;
  }
  state.activePluginProfile = resolved.profile || null;
  // The resolved profile stays on screen above the pane: "which tracker am I
  // about to read from" has to be answerable at a glance, not only on the run
  // that first bound it. Switching it rebinds the scope, same as the gate.
  const bar = src.multiProfile ? renderProfileBar({
    source: src,
    profiles: src.profiles || [],
    profile: resolved.profile,
    via: resolved.via,
    scopeLabel: bindingScopeLabel(),
  }, {
    onChange: async (profile) => {
      const ref = bindingScopeRef();
      if (!ref) return;
      const r = await pluginApi('PUT', '/api/source-bindings',
        { ...ref, plugin: src.plugin, sourceId: src.sourceId, profile });
      if (!r.ok) return notify({ tone: 'err', title: 'Could not save the profile binding', detail: r.data.error || '', key: 'profile-binding' });
      mountPluginSourcePane(src);
    },
  }) : null;
  const call = sourceCall(src, resolved.profile);
  // Above EVERY outcome: a failed connection check is one of the likeliest
  // moments to discover the wrong profile is bound, so the switcher has to be
  // reachable from the error and waiting states too.
  const show = (...nodes) => { host.replaceChildren(); if (bar) host.appendChild(bar); host.append(...nodes); };
  const hint = (text, cls = 'hint') => Object.assign(document.createElement('small'), { className: cls, textContent: text });
  const failBox = (message) => {
    const box = document.createElement('div');
    box.className = 'sp-config-missing';
    const msg = document.createElement('p');
    msg.className = 'hint err';
    msg.textContent = message;
    const link = document.createElement('a');
    link.href = '#settings/plugins';
    link.textContent = 'Open Plugins settings';
    link.addEventListener('click', (e) => { e.preventDefault(); location.hash = 'settings/plugins'; });
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.className = 'btn btn-ghost btn-mini';
    retry.textContent = 'Test connection';
    retry.addEventListener('click', () => mountPluginSourcePane(src));
    box.append(msg, link, retry);
    return box;
  };
  host.replaceChildren(hint(`Checking ${src.displayName} configuration…`));
  const started = Date.now();
  for (;;) {
    let v;
    try { v = await call('validateConfig', {}); }
    catch (e) { v = { ok: false, errors: [{ message: e.message }] }; }
    if (!owns()) return;   // user switched away / remounted meanwhile
    if (v && v.ok === true) break;
    // { pending } is setup legitimately mid-flight (an SSO sign-in the
    // connector just launched in a browser) — NOT a failure. Show the
    // connector's own message neutrally and keep polling, exactly like the
    // settings pane's Connect, so the pane flips to the inputs by itself
    // once the sign-in completes.
    if (v && v.pending && Date.now() - started <= CONNECT_MAX_MS) {
      show(hint(v.message || `Waiting for ${src.displayName} to connect…`));
      await new Promise((r) => setTimeout(r, CONNECT_POLL_MS));
      if (!owns()) return;
      continue;
    }
    const detail = v && v.pending
      ? 'timed out waiting for the sign-in — press Test connection to try again'
      : ((v && v.errors) || []).map((x) => x.message).join('; ') || 'connection check failed';
    show(failBox(`${src.displayName} is not connected: ${detail}`));
    return;
  }
  void bindMarkdownReady();                    // a task body is markdown; have the bundle ready for the preview
  show(renderSourcePane(src, { call, renderMarkdown: pageMarkdown }));
}

// ---------------------------------------------------------------------------
// Advanced disclosure (§4.6): the agents accordion, guardrails and mock mode.
// It is ALWAYS collapsed on arrival — it never opens itself and carries no
// summary line. Nothing in it is lost by being closed: an agent override is
// stated by the accordion the moment you open it, and the config-load error
// hint lives in the main column precisely because this section stays shut.
// ---------------------------------------------------------------------------

// Mock switch. The visible .switch mirrors the hidden #mock checkbox, which is
// what the submit handler reads (el.mock.checked).
const mockSwitch = $('#mock-switch');
function paintMock(on) {
  el.mock.checked = on;
  mockSwitch.classList.toggle('on', on);
  mockSwitch.setAttribute('aria-checked', String(on));
}
function toggleMock() {
  if (serverMock.on) return;                 // locked on: the server mocks every run anyway
  paintMock(!el.mock.checked);
}

// The server's mock mode (WS hello `serverMock`, server.mjs#serverMockMode): a server started
// with WORCA_MOCK=1 / ORCH_MOCK=1 mocks EVERY run whatever body.mock says, so the switch is
// locked on and the sidebar shows the MOCK pill. `choice` keeps the per-run pick the lock
// covered, restored when a restarted server comes back without it.
const SERVER_MOCK_TITLE = 'Server started with WORCA_MOCK=1 — all runs are mock.';
const serverMock = { on: false, choice: false };
function applyServerMock(on) {
  on = on === true;
  const pill = document.getElementById('side-mock-pill');
  if (pill) pill.hidden = !on;
  if (!mockSwitch || on === serverMock.on) return;
  if (on) serverMock.choice = el.mock.checked;
  serverMock.on = on;
  paintMock(on || serverMock.choice);
  mockSwitch.classList.toggle('disabled', on);
  if (on) {
    mockSwitch.setAttribute('aria-disabled', 'true');
    mockSwitch.title = SERVER_MOCK_TITLE;
  } else {
    mockSwitch.removeAttribute('aria-disabled');
    mockSwitch.removeAttribute('title');
  }
}
if (mockSwitch) {
  mockSwitch.addEventListener('click', toggleMock);
  mockSwitch.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
      e.preventDefault();
      toggleMock();
    }
  });
}

// File-picker buttons trigger their (hidden) <input type=file>.
$$('.pick[data-pick]').forEach((btn) => {
  btn.addEventListener('click', () => {
    if (btn.dataset.pick === 'md') el.mdFile.click();
    else if (btn.dataset.pick === 'extras') el.extras.click();
  });
});

el.mdFile.addEventListener('change', async () => {
  const f = el.mdFile.files && el.mdFile.files[0];
  if (!f) return;
  el.mdFileName.textContent = f.name;
  try {
    const text = await f.text();
    el.promptMarkdown.value = text;
    scheduleMentionHighlight(el.promptMarkdown);
  } catch (e) {
    el.mdFileName.textContent = `failed to read: ${e.message}`;
  }
});

// Selected extra files live in this array, not in the <input>: a FileList is
// read-only, and both per-file removal and re-picking the same file after a
// removal need mutable state. The input is only the OS picker trigger.
let extrasFiles = [];

function renderExtrasPills() {
  el.extrasPills.textContent = '';
  el.extrasPills.hidden = extrasFiles.length === 0;
  for (const f of extrasFiles) {
    const pill = document.createElement('span');
    pill.className = 'extra-pill';
    const name = document.createElement('span');
    name.className = 'extra-pill-name';
    name.textContent = f.name;
    name.title = f.name;
    const x = document.createElement('button');
    x.type = 'button';
    x.className = 'extra-pill-x';
    x.setAttribute('aria-label', `Remove ${f.name}`);
    x.textContent = '×';
    x.addEventListener('click', () => {
      extrasFiles = extrasFiles.filter((e) => e !== f);
      renderExtrasPills();
    });
    pill.append(name, x);
    el.extrasPills.appendChild(pill);
  }
  el.extrasNote.textContent = extrasFiles.length
    ? `${extrasFiles.length} file(s) will be uploaded and copied into the pipeline's extras/ folder.`
    : 'Leave empty and the run gets no extra files.'; // must match index.html's initial state
  rebuildMentionIndex();
  refreshMentionHighlights();
}

el.extras.addEventListener('change', () => {
  const picked = el.extras.files ? [...el.extras.files] : [];
  for (const f of picked) {
    const at = extrasFiles.findIndex((e) => e.name === f.name);
    if (at >= 0) extrasFiles[at] = f; // same name re-picked: newest wins
    else extrasFiles.push(f);
  }
  el.extras.value = ''; // so picking the same file again still fires `change`
  renderExtrasPills();
});

// ---------------------------------------------------------------------------
// @-mention autocomplete: typing "@" in a prompt textarea pops up the attached
// extra files; pick by mouse or ArrowUp/Down + Enter/Tab. One shared popup
// serves both the prompt and the markdown textareas.
// ---------------------------------------------------------------------------
const mentionPopup = document.createElement('div');
mentionPopup.id = 'mention-popup';
mentionPopup.className = 'mention-popup';
mentionPopup.hidden = true;
document.body.appendChild(mentionPopup);

// Popup state: which textarea it serves, the candidate names, the highlighted
// row, and where the "@token" being completed starts in the textarea value.
const mention = { ta: null, items: [], sel: 0, start: 0 };

function closeMentionPopup() {
  mention.ta = null;
  mention.items = [];
  mentionPopup.hidden = true;
  mentionPopup.textContent = '';
}

// The "@token" under the caret, or null. The "@" must start a word (begin of
// text or after whitespace/punctuation) and the token can't contain spaces.
function mentionTokenAt(ta) {
  const upToCaret = ta.value.slice(0, ta.selectionStart ?? 0);
  const at = upToCaret.lastIndexOf('@');
  if (at < 0) return null;
  if (at > 0 && !/[\s([{'"`,;:]/.test(upToCaret[at - 1])) return null;
  const token = upToCaret.slice(at + 1);
  if (/\s/.test(token)) return null;
  return { start: at, token };
}

// Caret viewport coordinates via a hidden mirror div (textareas expose no
// caret rect). Best-effort: with no layout engine it degrades to the
// textarea's top-left corner, and the popup is clamped to the viewport.
function mentionAnchor(ta, tokenStart) {
  const rect = ta.getBoundingClientRect();
  let x = rect.left, y = rect.bottom;
  try {
    const cs = window.getComputedStyle(ta);
    const mirror = document.createElement('div');
    for (const p of ['fontFamily', 'fontSize', 'fontWeight', 'lineHeight', 'letterSpacing',
      'paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft', 'borderWidth', 'boxSizing']) {
      mirror.style[p] = cs[p];
    }
    mirror.style.position = 'fixed';
    mirror.style.visibility = 'hidden';
    mirror.style.whiteSpace = 'pre-wrap';
    mirror.style.overflowWrap = 'break-word';
    mirror.style.width = `${rect.width}px`;
    mirror.textContent = ta.value.slice(0, tokenStart);
    const marker = document.createElement('span');
    marker.textContent = '@';
    mirror.appendChild(marker);
    document.body.appendChild(mirror);
    const lineH = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.4 || 18;
    x = rect.left + marker.offsetLeft - ta.scrollLeft;
    y = rect.top + marker.offsetTop + lineH - ta.scrollTop;
    mirror.remove();
  } catch { /* jsdom / measurement failure: anchor to the textarea itself */ }
  return { x, y };
}

function renderMentionPopup() {
  mentionPopup.textContent = '';
  mention.items.forEach((name, i) => {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'mention-item' + (i === mention.sel ? ' sel' : '');
    item.textContent = name;
    // mousedown, not click: it fires before the textarea loses focus.
    item.addEventListener('mousedown', (e) => {
      e.preventDefault();
      applyMention(name);
    });
    mentionPopup.appendChild(item);
  });
  mentionPopup.hidden = mention.items.length === 0;
  if (mention.items.length) {
    const { x, y } = mentionAnchor(mention.ta, mention.start);
    const maxX = Math.max(0, (window.innerWidth || 0) - 330);
    mentionPopup.style.left = `${Math.min(x, maxX)}px`;
    mentionPopup.style.top = `${y + 4}px`;
  }
}

function applyMention(name) {
  const ta = mention.ta;
  const caret = ta.selectionStart ?? ta.value.length;
  const before = ta.value.slice(0, mention.start);
  const after = ta.value.slice(caret);
  const inserted = `@${name} `;
  ta.value = before + inserted + after;
  const pos = before.length + inserted.length;
  ta.setSelectionRange(pos, pos);
  closeMentionPopup();
  ta.focus();
  scheduleMentionHighlight(ta);
}

function refreshMentionPopup(ta) {
  const tok = mentionTokenAt(ta);
  const names = extrasFiles.map((f) => f.name);
  if (!tok || !names.length) return closeMentionPopup();
  const q = tok.token.toLowerCase();
  // Prefix matches first, then substring matches — both case-insensitive.
  const starts = names.filter((n) => n.toLowerCase().startsWith(q));
  const contains = q ? names.filter((n) => !n.toLowerCase().startsWith(q) && n.toLowerCase().includes(q)) : [];
  const items = [...starts, ...contains];
  if (!items.length) return closeMentionPopup();
  mention.ta = ta;
  mention.start = tok.start;
  mention.sel = Math.min(mention.sel, items.length - 1);
  if (mention.items.join('\n') !== items.join('\n')) mention.sel = 0;
  mention.items = items;
  renderMentionPopup();
}

function attachMentionAutocomplete(ta) {
  ta.addEventListener('input', () => refreshMentionPopup(ta));
  ta.addEventListener('click', () => refreshMentionPopup(ta));
  ta.addEventListener('blur', () => { if (mention.ta === ta) closeMentionPopup(); });
  ta.addEventListener('keydown', (e) => {
    if (mentionPopup.hidden || mention.ta !== ta) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const n = mention.items.length;
      mention.sel = (mention.sel + (e.key === 'ArrowDown' ? 1 : n - 1)) % n;
      renderMentionPopup();
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault();
      applyMention(mention.items[mention.sel]);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      closeMentionPopup();
    }
  });
}

attachMentionAutocomplete(el.prompt);
attachMentionAutocomplete(el.promptMarkdown);

// ---------------------------------------------------------------------------
// @-mention highlighting: a mention that names a currently-attached extra file
// renders blue; everything else stays normal ink. A textarea cannot colour part
// of its own text, so each one is wrapped in a `.ta-hl` and given a `.ta-hl-back`
// backdrop that mirrors the same characters. The textarea sits on top with
// transparent glyphs — it keeps the caret, selection, spellcheck, undo stack and
// `.value` semantics; only the colour comes from underneath.
// ---------------------------------------------------------------------------

// Same left-boundary class mentionTokenAt uses (app.js:4610, verified
// character-for-character), so "bob@example.com" is never a mention.
// Deliberately duplicated rather than extracted: hoisting a shared const would
// mean editing the autocomplete block this feature is not otherwise touching.
const MENTION_LEFT_BOUNDARY = /[\s([{'"`,;:]/;
// Punctuation that may TRAIL a mention — but only when it is itself terminal.
const MENTION_RIGHT_PUNCT = /[)\]}'"`,;:.!?]/;
// Past this, colouring is dropped and the backdrop becomes a plain mirror: a
// pasted novel must not turn every keystroke into a full re-layout.
const MENTION_HL_MAX_CHARS = 20000;

// A mention ends cleanly at end-of-text, at whitespace, or at trailing
// punctuation that is followed by end-of-text, whitespace, or more punctuation.
// Punctuation glued to more name characters belongs to a LONGER name, so with
// only "a.txt" attached, "@a.txt.bak" must light up nothing at all — it names a
// file that is not here, and painting its prefix blue is exactly the false claim
// this feature exists to prevent. The same test keeps "@a.txt.", "@a.txt,",
// "@a.txt...", "(@a.txt)" and '"@a.txt".' blue.
function mentionEndsCleanly(text, end) {
  if (end >= text.length) return true;
  const c = text[end];
  if (/\s/.test(c)) return true;
  if (!MENTION_RIGHT_PUNCT.test(c)) return false;
  const n = text[end + 1];
  return n === undefined || /\s/.test(n) || MENTION_RIGHT_PUNCT.test(n);
}

// Rebuilt only when the attachment set changes — never on the keystroke path.
// Buckets are keyed by first character and sorted longest-first so the greedy
// match is the first hit, not a search.
let mentionIndex = { byFirstChar: new Map() };

function rebuildMentionIndex() {
  const byFirstChar = new Map();
  for (const f of extrasFiles) {
    const n = f && f.name;
    if (!n) continue;
    const bucket = byFirstChar.get(n[0]);
    if (bucket) bucket.push(n); else byFirstChar.set(n[0], [n]);
  }
  for (const bucket of byFirstChar.values()) bucket.sort((a, b) => b.length - a.length);
  mentionIndex = { byFirstChar };
}

// Flat [start, end, start, end, ...] ranges of valid mentions, each including
// the leading "@". One left-to-right pass: indexOf skips ordinary text at native
// speed and real work happens only at an "@", bounded by the number of attached
// names sharing the next character. Progress is guaranteed: a match sets
// i = end - 1 where end >= i + 2, so the next indexOf starts strictly ahead.
function scanMentions(text) {
  const marks = [];
  const { byFirstChar } = mentionIndex;
  if (!byFirstChar.size || !text) return marks;
  let i = text.indexOf('@');
  while (i >= 0) {
    if (i === 0 || MENTION_LEFT_BOUNDARY.test(text[i - 1])) {
      const bucket = byFirstChar.get(text[i + 1]);       // undefined when "@" is last
      if (bucket) {
        for (const name of bucket) {                    // longest first
          const end = i + 1 + name.length;
          if (text.startsWith(name, i + 1) && mentionEndsCleanly(text, end)) {
            marks.push(i, end);
            i = end - 1;                                // resume past the match
            break;
          }
        }
      }
    }
    i = text.indexOf('@', i + 1);
  }
  return marks;
}

// Resolved through `window.` like the ResizeObserver sites in this file
// (app.js:1831, :1937): a bare lookup would miss a window-only test stub, and
// jsdom 29.1.1 has no rAF at all (measured) — hence the macrotask fallback.
const mentionRaf = (fn) =>
  (typeof window.requestAnimationFrame === 'function'
    ? window.requestAnimationFrame(fn)
    : setTimeout(fn, 0));

// One repaint per frame per textarea, at most.
function scheduleMentionHighlight(ta) {
  const st = ta && ta._mentionHl;
  if (!st || st.queued) return;
  st.queued = true;
  mentionRaf(() => { st.queued = false; repaintMentionHighlight(ta); });
}

// `marks` is a flat [start, end, start, end, ...] list of ranges to paint blue,
// each range including its leading "@". Task 2 fills it in; here it is empty.
function paintMentionBackdrop(back, text, marks) {
  const nodes = [];
  let at = 0;
  for (let k = 0; k < marks.length; k += 2) {
    if (marks[k] > at) nodes.push(document.createTextNode(text.slice(at, marks[k])));
    const span = document.createElement('span');
    span.className = 'mention-ok';
    span.textContent = text.slice(marks[k], marks[k + 1]);   // textContent, never innerHTML
    nodes.push(span);
    at = marks[k + 1];
  }
  if (at < text.length) nodes.push(document.createTextNode(text.slice(at)));
  // A textarea reserves a line box for the caret position after a trailing
  // newline, and shows one line when empty; a `white-space:pre-wrap` div drops
  // the line box that would follow its LAST forced break. Add <br> in exactly
  // those two cases and NOT otherwise: an unconditional <br> makes the backdrop
  // one line-height TALLER than the textarea for every prompt that does not end
  // in a newline, which breaks `ta.scrollHeight === back.scrollHeight` — the
  // only reliable metric-drift detector this feature has. One <br> is enough
  // for any number of trailing newlines, because only the final break's line
  // box is dropped. <br> contributes nothing to textContent, so
  // `back.textContent === ta.value` stays exactly true either way.
  if (!text || text.endsWith('\n')) nodes.push(document.createElement('br'));
  // Spread bound: the 20 000-char cap (Task 4) and a minimum mention length of
  // 2 chars ("@" + a 1-char name) cap `marks` at 6 667 pairs, so `nodes` peaks
  // near 13 335 — an order of magnitude under V8's ~65 535 argument limit.
  back.replaceChildren(...nodes);
}

// The backdrop is `overflow:hidden`, which is still programmatically scrollable.
function syncMentionScroll(ta) {
  const st = ta._mentionHl;
  if (st.back.scrollTop !== ta.scrollTop) st.back.scrollTop = ta.scrollTop;
  if (st.back.scrollLeft !== ta.scrollLeft) st.back.scrollLeft = ta.scrollLeft;
}

// An overflowing textarea grows a scrollbar out of its own content width
// (::-webkit-scrollbar is 10px here, style.css:769, and the rule is unqualified
// so it applies to textareas). The backdrop does not scroll and so keeps that
// strip, wrapping a column later than the textarea — a full line of divergence,
// not a nudge. Hand it back the same width: with padding 13px 15px
// (style.css:280) and paddingRight = 15 + 10, the backdrop's content box is
// borderBox - 3 - 15 - 25 = borderBox - 43, and the textarea's is
// clientWidth - 30 = (borderBox - 3 - 10) - 30 = borderBox - 43. Identical.
//
// offsetWidth and clientWidth are INTEGER-ROUNDED but the border is 1.5px a side
// (style.css:279), so their difference for one and the same box reads 3 or 4
// depending on where the fractional border edges snap. Taking that literally
// writes a phantom 1px gutter with no scrollbar present, narrowing the
// backdrop's content box and moving a wrap point — exactly the drift this
// function exists to stop. The real scrollbar is 10px, so anything under 4px is
// rounding noise. Under jsdom every geometry read is 0, `raw` is negative, and
// nothing is written.
function syncMentionGutter(ta) {
  const st = ta._mentionHl;
  const raw = ta.offsetWidth - ta.clientWidth - st.borderX;
  const gutter = raw >= 4 ? Math.round(raw) : 0;
  if (gutter !== st.gutter) {
    st.gutter = gutter;
    st.back.style.paddingRight = `${st.padRight + gutter}px`;
  }
}

function repaintMentionHighlight(ta) {
  const st = ta._mentionHl;
  if (!st) return;
  const text = ta.value;
  const marks = text.length > MENTION_HL_MAX_CHARS ? [] : scanMentions(text);
  const marksKey = marks.length ? marks.join(',') : '';
  // Compared, never concatenated: a redundant trigger (a pane revealed, extras
  // re-rendered with an unchanged set) must not allocate a copy of the prompt
  // just to decide to do nothing.
  if (text !== st.text || marksKey !== st.marksKey) {
    paintMentionBackdrop(st.back, text, marks);
    st.text = text;
    st.marksKey = marksKey;
  }
  syncMentionGutter(ta);
  syncMentionScroll(ta);
}

// Geometry-only refresh: no scan, no DOM rebuild. The metrics can change with
// no `input` and no hook — dragging the resize grip, or a window resize adding
// or removing the scrollbar. (.grid.single is minmax(0,864px) at style.css:260,
// so the column really does narrow below an 864px viewport.)
function syncMentionMetrics(ta) {
  if (!ta || !ta._mentionHl) return;
  syncMentionGutter(ta);
  syncMentionScroll(ta);
}

function attachMentionHighlight(ta) {
  if (!ta || ta._mentionHl) return;                       // idempotent
  const cs = window.getComputedStyle(ta);                 // window.* — bare throws under jsdom
  const num = (v) => parseFloat(v) || 0;                  // jsdom returns "0" / "medium" / ""
  const wrap = document.createElement('div');
  wrap.className = 'ta-hl';
  const back = document.createElement('div');
  back.className = 'ta-hl-back';
  back.setAttribute('aria-hidden', 'true');               // the textarea is the accessible copy
  // The margin must ride on the wrapper, or the textarea starts 11px below the
  // backdrop's top edge (the backdrop is inset:0 on the wrapper's PADDING box,
  // which excludes margins). `cs` is LIVE in a browser, so this loop must run
  // BEFORE `ta.style.margin = '0px'` below — do not reorder. (jsdom snapshots
  // it, so jsdom would not catch the mistake.) The wrapper is inline-block (see
  // the CSS block), so this margin does not collapse away the way a block
  // wrapper's would.
  for (const side of ['Top', 'Right', 'Bottom', 'Left']) {
    wrap.style[`margin${side}`] = cs[`margin${side}`] || '0px';
  }
  // In place: #markdown-pane keeps a sibling ".md file" row after its textarea,
  // and the accordion suite pins the prompt's position in the form.
  ta.parentNode.insertBefore(wrap, ta);
  wrap.append(back, ta);                                  // backdrop first: it stacks below
  ta.style.margin = '0px';
  const st = ta._mentionHl = {
    back,
    queued: false,
    text: null,
    marksKey: null,
    gutter: 0,
    padRight: num(cs.paddingRight),
    borderX: num(cs.borderLeftWidth) + num(cs.borderRightWidth),
  };
  ta.addEventListener('input', () => scheduleMentionHighlight(ta));
  ta.addEventListener('scroll', () => syncMentionScroll(ta));
  // A ResizeObserver on the textarea covers the grip drag and every reflow that
  // changes its border box. Resolved through `window.` and typeof-guarded, like
  // app.js:1831 / :1937 / :8514 — jsdom 29.1.1 has none (measured), and the one
  // test that stubs it sets window.ResizeObserver only. (Full-page zoom is NOT
  // covered and does not need to be: it scales device pixels, not the CSS-px
  // boxes both layers are laid out in.)
  if (typeof window.ResizeObserver === 'function') {
    st.ro = new window.ResizeObserver(() => syncMentionMetrics(ta));
    st.ro.observe(ta);
  }
  scheduleMentionHighlight(ta);
}

// Both textareas at once: called whenever the answer changed for reasons other
// than typing — files added or removed, a pane or the view revealed.
function refreshMentionHighlights() {
  scheduleMentionHighlight(el.prompt);
  scheduleMentionHighlight(el.promptMarkdown);
}

attachMentionHighlight(el.prompt);
attachMentionHighlight(el.promptMarkdown);

// A webfont swap changes the line count without changing the textarea's box, so
// no ResizeObserver fires — but a scrollbar can appear or vanish. jsdom has no
// document.fonts at all (measured), hence the truthiness guard before the
// optional chain.
if (document.fonts && typeof document.fonts.ready?.then === 'function') {
  document.fonts.ready.then(() => {
    syncMentionMetrics(el.prompt);
    syncMentionMetrics(el.promptMarkdown);
  }).catch(() => { /* font loading is best-effort; the next keystroke re-syncs */ });
}

// Read a File as base64 (without the data: URL prefix).
function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || '');
      const comma = result.indexOf(',');
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.onerror = () => reject(reader.error || new Error('read failed'));
    reader.readAsDataURL(file);
  });
}

// Collect the selected extra files as [{ name, dataBase64 }] for upload.
async function collectExtras() {
  const files = [...extrasFiles];
  const out = [];
  for (const f of files) {
    try {
      const dataBase64 = await fileToBase64(f);
      out.push({ name: f.name, dataBase64 });
    } catch {
      /* skip unreadable file */
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Project registry: dropdown + inline add-form + delete.
// ---------------------------------------------------------------------------
const LAST_PROJECT_KEY = 'worca-cc.lastProject';

// --- Pipeline-tab lifecycle state (client-only; see plan §2 fact 2) ---
const ACK_RUNS_KEY = 'worca-cc.ackRuns';        // runIds the user has seen post-finish
const LINGER_RUNS_KEY = 'worca-cc.lingerRuns';  // runIds that finished LIVE and are not yet acknowledged

function loadIdSet(key) {
  try {
    const v = JSON.parse(localStorage.getItem(key) || '[]');
    return new Set(Array.isArray(v) ? v : []);
  } catch { return new Set(); }
}
const acknowledged = loadIdSet(ACK_RUNS_KEY);
const lingering = loadIdSet(LINGER_RUNS_KEY);

function persistIdSet(key, set) {
  try { localStorage.setItem(key, JSON.stringify([...set])); } catch { /* private mode */ }
}

// First `hello` of THIS session guard (Step 7). Not reset on reconnect.
let helloSeeded = false;

function markLingering(runId) {
  if (!runId || acknowledged.has(runId) || lingering.has(runId)) return;
  lingering.add(runId);
  persistIdSet(LINGER_RUNS_KEY, lingering);
}

function acknowledgeRun(runId) {
  if (!runId || acknowledged.has(runId)) return;
  acknowledged.add(runId);
  persistIdSet(ACK_RUNS_KEY, acknowledged);
  if (lingering.delete(runId)) persistIdSet(LINGER_RUNS_KEY, lingering);
  // Drop the now-acknowledged row from the tabs; its History row now stands for it.
  renderPipelineTabs();
  updateNavCounts();                           // an acknowledged failure leaves Needs you at once
  if (inRunsView()) scheduleRunsPaint();       // its live row turns into its History row
}

function selectedProjectPath() {
  const v = el.projectSelect.value;
  return !v || v === '__add__' ? '' : v;
}

function selectedProjectName() {
  const opt = el.projectSelect.selectedOptions && el.projectSelect.selectedOptions[0];
  return opt && opt.dataset ? opt.dataset.name || '' : '';
}

async function loadProjects(selectName) {
  try {
    const res = await fetch('/api/projects');
    const data = await safeJson(res);
    state.projects = data && Array.isArray(data.projects) ? data.projects : [];
  } catch {
    state.projects = [];
  }
  renderProjectOptions(selectName);
}

function renderProjectOptions(selectName) {
  const want = selectName || localStorage.getItem(LAST_PROJECT_KEY) || '';
  el.projectSelect.innerHTML = '';

  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.disabled = true;
  placeholder.textContent = state.projects.length ? 'Select a project…' : 'No projects yet';
  el.projectSelect.appendChild(placeholder);

  state.projects.forEach((p) => {
    const opt = document.createElement('option');
    opt.value = p.path;
    opt.dataset.name = p.name;
    opt.textContent = p.exists ? p.name : `${p.name} (missing)`;
    el.projectSelect.appendChild(opt);
  });

  const add = document.createElement('option');
  add.value = '__add__';
  add.textContent = '+ Add project…';
  el.projectSelect.appendChild(add);

  // Restore by index (not value) so duplicate paths can't pick the wrong name.
  const idx = state.projects.findIndex((p) => p.name === want);
  if (idx >= 0) el.projectSelect.selectedIndex = idx + 1; // +1 past the placeholder
  else placeholder.selected = true;

  onProjectChanged();
}

function onProjectChanged() {
  const path = selectedProjectPath();
  showEngineRefusal(null); // the refusal and any consent were for the OLD project's context
  state.engineTouched = false;
  // #527: a new project starts with no sync answer; the row stays hidden until branches-fresh.
  state.sync = freshSyncState(state.sync.gen + 1);
  syncHasRemote = null;
  paintBranches();
  // The source profile is bound to the PROJECT, so a different project may pull
  // from a different tracker: re-resolve rather than keep listing the old one's.
  if (state.activePluginSource && state.activePluginSource.multiProfile) {
    mountPluginSourcePane(state.activePluginSource);
  }
  if (path) {
    state.projectDir = path;
    localStorage.setItem(LAST_PROJECT_KEY, selectedProjectName());
    const cfgLoad = loadConfig(path); // its tail repaints the workflow/guardrail pickers (:1821-1822)
    void loadRunDefaults(path);
    refreshBranches(path);            // — a prefill caller MUST await it or be clobbered
    schedulePolicyLine();             // team policy notes for the new target (design board 8)
    return cfgLoad;
  } else {
    schedulePolicyLine();
    state.projectDir = '';
    // No project yet: still load the built-in models so the picker isn't empty.
    const cfgLoad = loadConfig('');
    void loadRunDefaults('');
    refreshBranches('');
    return cfgLoad;
  }
}

// Seed any branch <select> with a single placeholder option. Empty value === "let
// the server default to current HEAD". Returns the option for in-place updates.
// We always seed one so the select is never blank (m3) and always communicates
// state — loading, the auto default, or an error (m2).
function seedBranchPlaceholder(select, text) {
  if (!select) return null;
  select.innerHTML = '';
  const opt = document.createElement('option');
  opt.value = '';
  opt.textContent = text;
  select.appendChild(opt);
  return opt;
}

const RUN_BRANCH_WORD = { done: 'finished', error: 'ended with an error', stopped: 'stopped', interrupted: 'interrupted', paused: 'paused', running: 'running', starting: 'starting', created: 'starting', pausing: 'pausing' };
const PREVIOUS_BRANCH = '__previous__';

// Populate any branch <select> from /api/branches for `projectDir`, pre-selecting
// the repo's current branch (HEAD). Empty value still falls back to HEAD on submit.
async function populateBranchSelect(select, projectDir) {
  if (!select) return;
  // Per-select request generation (review of PR #376): three un-guarded callers
  // (project change, target change, prefill) raced, and whichever fetch resolved
  // LAST rebuilt the options — wiping a source branch the prefill had just set.
  // A response for a superseded request is dropped.
  const gen = (select._branchGen = (select._branchGen || 0) + 1);
  const stale = () => select._branchGen !== gen;
  if (!projectDir) { seedBranchPlaceholder(select, 'current branch (auto)'); syncPreviousBranchOption(select); return; }
  const placeholder = seedBranchPlaceholder(select, 'Loading branches…');
  try {
    const r = await fetch(`/api/branches?projectDir=${encodeURIComponent(projectDir)}`);
    if (stale()) return;
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const data = await r.json();
    if (stale()) return;
    // `opt.selected = true` is selectedNESS, not the `selected` ATTRIBUTE, so nothing below is
    // `defaultSelected`; remember HEAD on the select so removing a temporary leading option
    // (PREVIOUS_BRANCH) can put the selection back on it.
    select.dataset.current = data.current || '';
    const branches = Array.isArray(data.branches) ? data.branches : [];
    if (!branches.length) { placeholder.textContent = 'current branch (auto)'; syncPreviousBranchOption(select); return; }
    paintBranchOptions(select, data);
    syncPreviousBranchOption(select);
    // Phase 2 (#527): fire-and-forget; the cached list above is already usable.
    void freshBranchPhase(select, projectDir, gen, stale);
  } catch {
    if (stale()) return;
    // m2: surface the failure instead of leaving a silently-empty select. The
    // empty value still makes the server fall back to HEAD on submit.
    placeholder.textContent = 'current branch (auto — branch list unavailable)';
    syncPreviousBranchOption(select);
  }
}

/** The option body of a branch <select>: clears it (auto placeholder first), then the
 *  "Branches", "Run branches" and (#527) "Remote only" groups. Stamps the list signature so a
 *  fresh answer that adds nothing leaves an open <select> alone. */
function paintBranchOptions(select, data) {
  const branches = Array.isArray(data.branches) ? data.branches : [];
  seedBranchPlaceholder(select, 'current branch (auto)');
  const runBranches = Array.isArray(data.runs) ? data.runs : [];
  const isRun = new Set(runBranches.map((r) => r.branch));
  const plain = document.createElement('optgroup'); plain.label = 'Branches';
  for (const b of branches) {
    if (isRun.has(b)) continue;
    const opt = document.createElement('option');
    opt.value = b; opt.textContent = b;
    if (b === data.current) opt.selected = true;
    plain.appendChild(opt);
  }
  if (plain.children.length) select.appendChild(plain);
  if (runBranches.length) {
    const grp = document.createElement('optgroup'); grp.label = 'Run branches';
    for (const r of runBranches) {
      const opt = document.createElement('option');
      opt.value = r.branch; opt.textContent = `${r.branch} — ${r.title || r.pipelineId} · ${RUN_BRANCH_WORD[r.status] || r.status}`;
      if (r.branch === data.current) opt.selected = true;
      grp.appendChild(opt);
    }
    select.appendChild(grp);
  }
  const only = remoteOnlyNames(data);
  if (only.length) {
    const grp = document.createElement('optgroup'); grp.label = 'Remote only';
    for (const b of only) {
      const opt = document.createElement('option');
      opt.value = b; opt.textContent = `${b} — on ${data.remote.name}`; opt.dataset.remoteOnly = '1';
      grp.appendChild(opt);
    }
    select.appendChild(grp);
  }
  select.dataset.branchSig = branchListSig(data);
}

/** Remote branch names with no local twin (the "Remote only" group). */
function remoteOnlyNames(data) {
  const remote = data && data.remote && Array.isArray(data.remote.branches) ? data.remote : null;
  if (!remote) return [];
  const have = new Set(Array.isArray(data.branches) ? data.branches : []);
  return remote.branches.filter((b) => typeof b === 'string' && b && !have.has(b));
}
const branchListSig = (data) => JSON.stringify([data.branches || [], data.runs || [], remoteOnlyNames(data)]);

/** Phase 2 of populateBranchSelect (#527): fetch the remote (45 s shared TTL, negative-cached
 *  offline) and swap in the fresh list. Never awaited by callers; the gen guard drops it when a
 *  newer populate (project change) has started. */
async function freshBranchPhase(select, projectDir, gen, stale) {
  const v = select.value;
  const base = v && v !== PREVIOUS_BRANCH ? v : (select.dataset.current || '');
  let fresh = null;
  try {
    const fr = await fetch(`/api/branches?projectDir=${encodeURIComponent(projectDir)}&fresh=1${base ? `&base=${encodeURIComponent(base)}` : ''}`);
    if (stale() || !fr.ok) return;
    fresh = await fr.json();
  } catch { return; }
  if (stale() || !fresh || !Array.isArray(fresh.branches)) return;
  // Rebuilding the options of an OPEN native <select> closes it under the person's cursor, and
  // this answer can land up to 8 s after load. Repaint only when the list really changed.
  if (select.dataset.branchSig !== branchListSig(fresh)) {
    const keep = select.value;                     // may be a prefilled value that is not in the list
    paintBranchOptions(select, fresh);
    if (keep && keep !== PREVIOUS_BRANCH && ![...select.options].some((o) => o.value === keep)) {
      const opt = document.createElement('option'); opt.value = keep; opt.textContent = keep;
      select.appendChild(opt);                     // keep Ask / chain prefills intact
    }
    syncPreviousBranchOption(select);              // re-adds __previous__ when it applies
    // Restore ANY previous choice, '' ("current branch (auto)") included: paintBranchOptions
    // re-selects data.current, which would turn an explicit "auto" into a named branch.
    if (typeof keep === 'string' && [...select.options].some((o) => o.value === keep)) select.value = keep;
  }
  // jsdom rejects Node's CustomEvent; the house idiom is window.CustomEvent.
  select.dispatchEvent(new window.CustomEvent('branches-fresh', { detail: fresh }));
}

// Back-compat shim for the single #sourceBranch (existing call sites in
// onProjectChanged are unchanged). setBranchPlaceholder is no longer needed
// (its callers move to seedBranchPlaceholder / are removed in setRunTarget).
function refreshBranches(projectDir) {
  // In workspace mode the single select is the disabled "current branch (auto)"
  // stand-in; filling it with ONE project's branches would claim a source the
  // run will not use (each member branches off its own HEAD).
  if (state.runTarget === 'workspace') return showWorkspaceBranchPlaceholder();
  return populateBranchSelect(el.sourceBranch, projectDir);
}

// ---- Sync before run (#527): the pill, Sync and Auto-sync under Source branch --------------
// Project mode paints from the fresh list's SyncBlock (or a no-network GET /api/sync); workspace
// mode paints one pill per member and the shared row from the worst member.

/** The base the run would start from: '' / "the run before it" mean HEAD's branch. */
function effectiveBase() {
  const v = el.sourceBranch ? el.sourceBranch.value : '';
  if (!v || v === PREVIOUS_BRANCH) return (el.sourceBranch && el.sourceBranch.dataset.current) || '';
  return v;
}

// false once the fresh list said this project has no such remote: a branch change then needs no status read.
let syncHasRemote = null;

// ---- Branches table (design v3): one layout for a project (one row) or a workspace (a row each).

/** "Use branches from": this run's choice once touched, else the project's (every member's) own beforeRun. */
function shownAutoSync() {
  if (state.sync.autoSync !== null) return state.sync.autoSync;
  if (state.runTarget === 'workspace') return membersBeforeRun();
  return state.sync.block?.settings?.beforeRun ?? true;
}
/** Is there a remote to start from anywhere in the table? Without one there is nothing to choose. */
function syncApplies() {
  if (state.runTarget === 'workspace') return Object.values(state.sync.members).some((b) => b && b.remote);
  // "Branch off the run before it": that start is the previous run's branch, not HEAD's.
  if (el.sourceBranch && el.sourceBranch.value === PREVIOUS_BRANCH) return false;
  return !!(state.sync.block && state.sync.block.remote);
}

const OUTCOME_ICONS = {
  ok: '<circle cx="12" cy="12" r="9"/><path d="M8 12.5l2.7 2.6L16 9.6"/>',
  behind: '<circle cx="12" cy="12" r="9"/><path d="M12 7.5v8.5M8.2 12.6L12 16.4l3.8-3.8"/>',
  dirty: '<path d="M4.5 19.5h4l10-10-4-4-10 10v4z"/><path d="M12.8 7.2l4 4"/>',
  diverged: '<circle cx="6.5" cy="5.5" r="2"/><circle cx="17.5" cy="5.5" r="2"/><circle cx="12" cy="18.5" r="2"/><path d="M6.5 7.5v1.5a3 3 0 0 0 3 3h5a3 3 0 0 0 3-3V7.5M12 12v4.5"/>',
  offline: '<path d="M3.5 3.5l17 17"/><path d="M9 7.3A5.5 5.5 0 0 1 16.6 11h.4a3.5 3.5 0 0 1 2.6 5.8M15.5 18H7a4 4 0 0 1-1.2-7.8"/>',
  blocked: '<circle cx="12" cy="12" r="9"/><path d="M5.7 5.7l12.6 12.6"/>',
  local: '<rect x="4" y="5" width="16" height="11" rx="1.5"/><path d="M2.5 19.5h19"/>',
  branch: '<circle cx="6" cy="5.5" r="2"/><circle cx="6" cy="18.5" r="2"/><circle cx="18" cy="7.5" r="2"/><path d="M6 7.5v9M18 9.5c0 4-3 5.6-7.5 6.3"/>',
  chevDown: '<path d="M6 9l6 6 6-6"/>',
  chevUp: '<path d="M6 15l6-6 6 6"/>',
  // The Projects sync bar only (projectBarModel): listRowModel never names these.
  noRemote: '<circle cx="12" cy="12" r="9"/><path d="M8 12h8"/>',
  spin: '<path d="M12 3.5a8.5 8.5 0 1 0 8.5 8.5"/>',
};
/** Paint one "What the run gets" cell from a runOutcomeModel. Text only ever via textContent. */
function paintOutcomeCell(host, m, { onRetry = null, busy = false } = {}) {
  if (!host) return;
  host.className = `bt-outcome tone-${m.tone}`;
  host.dataset.icon = m.icon;
  const icon = document.createElement('span');
  icon.className = 'bt-icon';
  if (OUTCOME_ICONS[m.icon]) {
    icon.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${OUTCOME_ICONS[m.icon]}</svg>`;
  }
  const words = document.createElement('span');
  words.className = 'bt-words';
  const text = document.createElement('span');
  text.className = 'bt-text'; text.textContent = m.text;
  words.appendChild(text);
  if (m.note) {
    const note = document.createElement('span');
    note.className = 'bt-note'; note.textContent = m.note;
    words.appendChild(note);
  }
  host.replaceChildren(icon, words);
  if (m.retry && onRetry) {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'btn btn-mini bt-retry'; btn.textContent = busy ? 'Retrying…' : 'Retry';
    btn.disabled = busy;
    btn.addEventListener('click', onRetry);
    host.appendChild(btn);
  }
}

/** The project row's outcome: Checking… until the fresh list answers, then the SyncBlock in words. */
function projectOutcome() {
  if (el.sourceBranch && el.sourceBranch.value === PREVIOUS_BRANCH) {
    return { icon: 'none', tone: 'muted', text: 'Starts from the branch of the run before it', note: '', retry: false, blocked: false };
  }
  const block = syncHasRemote === false ? null : (state.sync.block || undefined);
  return runOutcomeModel(block, { origin: shownAutoSync(), base: effectiveBase() });
}

/** New branch hint: the real names the run creates — one per project in a workspace, suffixed. */
function paintFeatureHint() {
  if (!el.featureBranchHint) return;
  const f = el.featureBranch ? el.featureBranch.value.trim() : '';
  const ws = state.runTarget === 'workspace' ? state.workspaces.find((w) => w && w.id === state.selectedWorkspaceId) : null;
  const paths = ws && Array.isArray(ws.projectPaths) ? ws.projectPaths : [];
  if (!f) {
    el.featureBranchHint.textContent = paths.length > 1
      ? 'Leave empty and Worca will propose one for each project.'
      : 'Leave empty and Worca will propose one.';
    return;
  }
  if (state.runTarget !== 'workspace' || !paths.length) { el.featureBranchHint.textContent = `Creates ${f}.`; return; }
  // Mirrors run-harness _resolveMemberBranches: `${feature}-${slugify(projectName)}`, sanitized.
  const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-{2,}/g, '-').replace(/^-+|-+$/g, '') || 'untitled';
  const names = paths.map((p) => `${f}-${slug(wsBasename(p))}`);
  el.featureBranchHint.textContent = `Creates ${names.length === 1 ? names[0] : `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`}.`;
}

/** Repaint the whole Branches block: the choice, the context, every row's outcome, the blocked line. */
function paintBranches() {
  if (!el.btProjectRow) return;
  const ws = state.runTarget === 'workspace';
  const origin = shownAutoSync();
  if (el.branchesModeWrap) el.branchesModeWrap.hidden = !syncApplies();
  el.branchesMode?.querySelectorAll('button[data-mode]').forEach((b) => {
    const on = (b.dataset.mode === 'origin') === origin;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', String(on));
  });
  let blocked = '';
  if (ws) {
    const w = state.workspaces.find((x) => x && x.id === state.selectedWorkspaceId);
    const n = w && Array.isArray(w.projectPaths) ? w.projectPaths.length : 0;
    if (el.branchesCtx) el.branchesCtx.textContent = w ? `${w.name || w.id} · ${n} project${n === 1 ? '' : 's'}` : '';
    if (el.btProjectName) el.btProjectName.textContent = 'Every project';
    if (el.btProjectOutcome) paintOutcomeCell(el.btProjectOutcome, { icon: 'none', tone: 'muted', text: 'Each project starts from its current branch', note: '' });
    el.wsSourceBranches?.querySelectorAll('.ws-src-row[data-project-key]').forEach((row) => {
      const key = row.dataset.projectKey;
      if (paintMemberRow(key)?.blocked && !blocked) blocked = wsMemberName(key);
    });
  } else {
    const name = selectedProjectName();
    if (el.branchesCtx) el.branchesCtx.textContent = name || '';
    if (el.btProjectName) el.btProjectName.textContent = name || '—';
    const m = selectedProjectPath() ? projectOutcome() : { icon: 'none', tone: 'muted', text: 'Pick a project first', note: '' };
    paintOutcomeCell(el.btProjectOutcome, m, { onRetry: () => { void syncNow(); }, busy: state.sync.busy });
    if (m.blocked) blocked = name || 'This project';
  }
  if (el.branchesBlocked) {
    el.branchesBlocked.hidden = !blocked;
    el.branchesBlocked.textContent = blocked ? `${blocked} can’t start from origin yet.` : '';
  }
  state.sync.blocked = blocked;
  paintFeatureHint();
}
const paintSyncRowNow = paintBranches;

/** GET /api/sync for the current base (no network: the list fetch already fetched). */
async function refreshSyncStatusQuiet() {
  const base = effectiveBase();
  const projectDir = selectedProjectPath();
  if (!base || !projectDir || state.runTarget === 'workspace' || syncHasRemote === false) return;
  const gen = ++state.sync.gen;
  // Never keep ANOTHER branch's state: a base the server will not sync (e.g. "plus+branch"), a 400,
  // a 500 or a lost connection paints Unknown. The same base keeps its last answer on a failed read.
  const unknown = () => {
    const prev = state.sync.block;
    if (prev && prev.base === base && prev.state !== 'unknown') return;
    state.sync.block = { base, remote: (prev && prev.remote) || 'origin', state: 'unknown', settings: prev && prev.settings };
    paintSyncRowNow();
  };
  if (!isSyncableBranchName(base)) { unknown(); return; }   // no request: it would only log a 400
  try {
    const res = await fetch(`/api/sync?projectDir=${encodeURIComponent(projectDir)}&base=${encodeURIComponent(base)}&details=1`);
    const data = await safeJson(res);
    if (gen !== state.sync.gen) return;
    if (!res.ok || !(data && data.sync)) { unknown(); return; }
    // A status read reports the server's standing fetch failure itself (stale), so Offline survives it.
    state.sync.block = data.sync;
    paintSyncRowNow();
  } catch { if (gen === state.sync.gen) unknown(); }
}

/** Sync button and the dialog's Sync (project mode). Returns the block the dialog repaints with. */
async function syncNow() {
  const base = effectiveBase();
  const projectDir = selectedProjectPath();
  if (!base || !projectDir || state.sync.busy) return state.sync.block;
  state.sync.busy = true;
  paintSyncRowNow();
  const same = () => effectiveBase() === base && selectedProjectPath() === projectDir;
  const offline = () => {
    if (same() && state.sync.block) state.sync.block = { ...state.sync.block, stale: true, fetchError: { kind: 'failed' } };
  };
  let out = state.sync.block;
  try {
    const res = await fetch('/api/sync', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectDir, base, mode: 'ff' }) });
    const data = await safeJson(res);
    // A 4xx is a refusal (e.g. a base the server will not sync), not a failed fetch.
    if (!res.ok || !data || !data.sync) { if (!(res.status >= 400 && res.status < 500)) offline(); out = state.sync.block; }
    else {
      out = data.sync;
      // Whatever gen is: the server's own project-sync-changed frame usually lands first, and this
      // answer is the only record of why nothing moved (sync.ff).
      if (same()) {
        ++state.sync.gen;
        state.sync.block = data.sync;
        const copy = ffRefusalCopy(data.sync.ff, base, data.sync.remote || 'origin');
        if (copy) setFormMsg(copy, 'warn');
      }
    }
  } catch { offline(); out = state.sync.block; }
  finally {
    state.sync.busy = false;
    paintSyncRowNow();
  }
  // No refreshBranches: it re-selects HEAD's branch, and a fast-forward renames nothing.
  return out;
}

// ---- workspace members ----
function wsMemberName(key) {
  // The registered project name, as the Projects list shows it; the folder name only as a fallback.
  const p = state.projects.find((x) => x && x.key === key);
  if (p && p.name) return p.name;
  const ws = state.workspaces.find((w) => w && w.id === state.selectedWorkspaceId);
  const i = ws && Array.isArray(ws.projectKeys) ? ws.projectKeys.indexOf(key) : -1;
  return i >= 0 ? wsBasename(ws.projectPaths[i]) : key;
}
function wsMemberSelect(key) {
  return el.wsSourceBranches ? [...el.wsSourceBranches.querySelectorAll('select.ws-src-select')].find((s) => s.dataset.projectKey === key) || null : null;
}
/** Will this member sync before the run? The touched choice for every member, else its own beforeRun. */
function memberAutoSync(key) {
  if (state.sync.autoSync !== null) return state.sync.autoSync;
  const b = state.sync.members[key];
  return !(b && b.settings && b.settings.beforeRun === false);
}
/** Paint one member row's "What the run gets". Returns its model (blocked rows stop Start). */
function paintMemberRow(key) {
  const row = el.wsSourceBranches ? [...el.wsSourceBranches.querySelectorAll('.ws-src-row')].find((r) => r.dataset.projectKey === key) : null;
  const cell = row ? row.querySelector('.bt-outcome') : null;
  if (!cell) return null;
  const sel = row.querySelector('select');
  let m;
  if (row.dataset.missing === '1') m = { icon: 'blocked', tone: 'muted', text: 'Folder missing · skipped', note: '' };
  else if (el.wsSourcePrevious && el.wsSourcePrevious.classList.contains('on')) m = { icon: 'none', tone: 'muted', text: 'Starts from the branch of the run before it', note: '' };
  else {
    const v = sel ? sel.value : '';
    m = runOutcomeModel(key in state.sync.members ? state.sync.members[key] : undefined,
      { origin: memberAutoSync(key), base: v && v !== PREVIOUS_BRANCH ? v : ((sel && sel.dataset.current) || '') });
  }
  paintOutcomeCell(cell, m, { onRetry: () => { void syncMember(key); }, busy: row.dataset.busy === '1' });
  return m;
}
/** Untouched choice in workspace mode shows what the run will do: every member's own beforeRun. */
function membersBeforeRun() {
  return Object.values(state.sync.members).filter(Boolean).every((b) => !b.settings || b.settings.beforeRun !== false);
}
async function syncMember(key) {
  const sel = wsMemberSelect(key);
  const cur = state.sync.members[key];
  const ws = state.workspaces.find((w) => w && w.id === state.selectedWorkspaceId);
  const i = ws && Array.isArray(ws.projectKeys) ? ws.projectKeys.indexOf(key) : -1;
  if (!sel || i < 0) return cur;
  const v = sel.value;
  const base = v && v !== PREVIOUS_BRANCH ? v : (sel.dataset.current || '');
  const row = sel.closest('.ws-src-row');
  if (row) { row.dataset.busy = '1'; paintMemberRow(key); }
  try {
    const res = await fetch('/api/sync', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectDir: ws.projectPaths[i], base, mode: 'ff' }) });
    const data = await safeJson(res);
    // A 4xx is a refusal (e.g. a base the server will not sync), not a failed fetch.
    if (!res.ok || !data || !data.sync) return cur && !(res.status >= 400 && res.status < 500) ? { ...cur, stale: true, fetchError: { kind: 'failed' } } : cur;
    if (sel.isConnected) state.sync.members[key] = data.sync;
    return data.sync;
  } catch { return cur; }
  finally {
    if (row) delete row.dataset.busy;
    if (sel.isConnected) paintBranches();
  }
}
/** The sync dialog's "This project" section: GET/PUT /api/projects/:key/sync/settings.
 *  onSaved(view) lets the opener repaint what follows the project's settings. */
function projectSyncPrefs(key, onSaved = () => {}) {
  const url = `/api/projects/${encodeURIComponent(key)}/sync/settings`;
  return {
    async load() {
      const res = await fetch(url);
      const data = await safeJson(res);
      if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
      return data;
    },
    async save(patch) {
      const res = await fetch(url, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(patch) });
      const data = await safeJson(res);
      if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
      onSaved(data);
      return data;
    },
  };
}
function selectedProjectKey() {
  const path = selectedProjectPath();
  const p = path ? state.projects.find((x) => x && x.path === path) : null;
  return p ? p.key : '';
}
// "Use branches from Origin · latest | Local copy": this run's choice, for every row at once.
el.branchesMode?.querySelectorAll('button[data-mode]').forEach((b) => {
  b.addEventListener('click', () => {
    // autoSync !== null means "the person made the choice for this run".
    state.sync.autoSync = b.dataset.mode === 'origin';
    paintBranches();
  });
});
el.featureBranch?.addEventListener('input', paintFeatureHint);
if (el.sourceBranch) {
  el.sourceBranch.addEventListener('branches-fresh', (e) => {
    if (state.runTarget === 'workspace') return;
    const detail = e.detail || {};
    if (!detail.remote) {
      syncHasRemote = false;
      ++state.sync.gen;
      state.sync.block = null;
      paintSyncRowNow();
      return;
    }
    syncHasRemote = true;
    // The fresh request named the base when it STARTED; a prefill or a pick may have changed it.
    if (detail.sync && detail.sync.base === effectiveBase()) {
      ++state.sync.gen;
      state.sync.block = detail.sync;
      paintSyncRowNow();
    } else void refreshSyncStatusQuiet();
  });
  el.sourceBranch.addEventListener('change', () => {
    if (state.runTarget === 'workspace') return;
    if (el.sourceBranch.value === PREVIOUS_BRANCH) { paintBranches(); return; }
    paintBranches();
    void refreshSyncStatusQuiet();
  });
}
/** After an accepted start: "Use branches from" was a choice for that run only. */
function resetSyncChoice() {
  state.sync.autoSync = null;
  paintBranches();
}

el.projectSelect.addEventListener('change', () => {
  if (el.projectSelect.value === '__add__') {
    openAddProject();
    return;
  }
  hideAddProject();
  onProjectChanged();
});

function openAddProject() {
  el.addProject.classList.remove('hidden');
  el.newProjectName.value = '';
  el.newProjectPath.value = '';
  setAddMsg('');
  el.newProjectName.focus();
}

function hideAddProject() {
  el.addProject.classList.add('hidden');
}

function setAddMsg(text, kind) {
  el.addProjectMsg.textContent = text || '';
  el.addProjectMsg.className = 'hint' + (kind ? ' ' + kind : '');
}

el.addProjectCancel.addEventListener('click', () => {
  hideAddProject();
  renderProjectOptions(localStorage.getItem(LAST_PROJECT_KEY) || '');
});

el.addProjectSave.addEventListener('click', async () => {
  const name = el.newProjectName.value.trim();
  const projPath = el.newProjectPath.value.trim();
  if (!name) return setAddMsg('Name is required.', 'err');
  if (!projPath) return setAddMsg('Path is required.', 'err');
  el.addProjectSave.disabled = true;
  try {
    const res = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, path: projPath }),
    });
    const data = await safeJson(res);
    if (!res.ok) {
      setAddMsg(data.error || `HTTP ${res.status}`, 'err');
      return;
    }
    state.projects = Array.isArray(data.projects) ? data.projects : state.projects;
    hideAddProject();
    renderProjectOptions(name); // auto-select the newly added project
  } catch (e) {
    setAddMsg(e.message, 'err');
  } finally {
    el.addProjectSave.disabled = false;
  }
});

// --- Folder selector (Browse…): native OS dialog, in-app modal fallback ----
let folderState = { path: '', parent: null, home: '' };

// New Pipeline's inline form: one picked folder fills it (as before); several open the
// review list — the form hides, and on close the dropdown selects the first added project
// (the single Save's auto-select), else it falls back to the last project.
function newPipelinePicks(paths) {
  routePickedFolders(paths, {
    single: applyPickedFolder,
    many: (list) => {
      hideAddProject();
      openProjectBulkModal(list, {
        onDone: ({ added }) => renderProjectOptions(added[0] || localStorage.getItem(LAST_PROJECT_KEY) || ''),
      });
    },
  });
}

function browseNewProjectInWorca() {
  return openFolderBrowser(el.newProjectPath.value.trim(), applyPickedFolder, { multiple: true, onSelectMany: newPipelinePicks });
}

el.newProjectBrowse.addEventListener('click', async () => {
  el.newProjectBrowse.disabled = true;
  setAddMsg('');
  try {
    const data = await pickFolder('project', { multiple: true });   // never throws
    if (data.status === 'picked' && pickedPaths(data).length) newPipelinePicks(pickedPaths(data));
    else if (data.status === 'canceled') { /* user dismissed the dialog */ }
    else if (data.status === 'busy') setAddMsg('A folder dialog is already open — finish or cancel it first.', 'err');
    else await browseNewProjectInWorca();                            // unsupported / error -> in-app fallback
  } finally {
    el.newProjectBrowse.disabled = false;
  }
});
// Worca's own browser, straight away: multi-select where the native dialog has none (Windows).
if (el.newProjectBrowseMany) el.newProjectBrowseMany.addEventListener('click', () => { void browseNewProjectInWorca(); });

// Fill the path field; prefill an EMPTY name with the folder's basename.
function applyPickedFolder(path) {
  el.newProjectPath.value = path;
  if (!el.newProjectName.value.trim()) {
    const base = path.replace(/[\\/]+$/, '').split(/[\\/]/).pop();
    if (base) el.newProjectName.value = base;
  }
}

// The in-app browser is shared by every Browse… button, so each opener names
// where "Select this folder" lands. Default sink = the add-project fields.
let folderSink = applyPickedFolder;
// Multi mode: set only by an opener that passes { multiple: true, onSelectMany }.
// Ticked folders (path -> name) survive navigation; every open starts empty.
let folderManySink = null;
const folderPicks = new Map();

async function openFolderBrowser(seedPath, onSelect, { multiple = false, onSelectMany = null } = {}) {
  folderSink = onSelect || applyPickedFolder;
  folderManySink = multiple && typeof onSelectMany === 'function' ? onSelectMany : null;
  folderPicks.clear();
  el.folderBrowser.classList.toggle('multi', !!folderManySink);
  if (el.folderBrowserTitle) el.folderBrowserTitle.textContent = folderManySink ? 'Select folders' : 'Select a folder';
  syncFolderPicks();
  el.folderBrowser.classList.remove('hidden');
  // A stale or mistyped seed path from the text field 400s; fall back to home.
  // Only the SEED gets this retry — navigation failures keep the current
  // listing (loadFolders shows the error) instead of yanking the user home.
  if (!(await loadFolders(seedPath)) && seedPath) await loadFolders('');
}

// Footer state for multi mode: the count line and "Add N selected"; hidden in single mode.
function syncFolderPicks() {
  if (!el.folderSelectMany) return;
  const multi = !!folderManySink;
  const n = folderPicks.size;
  el.folderSelectMany.classList.toggle('hidden', !multi);
  el.folderPickCount.classList.toggle('hidden', !multi);
  el.folderSelectMany.disabled = n === 0;
  el.folderSelectMany.textContent = n ? `Add ${n} selected` : 'Add selected';
  el.folderPickCount.textContent = n === 1 ? '1 folder selected' : `${n} folders selected`;
  // One primary action: in multi mode "Add N selected" is it, "Select this folder" steps back.
  el.folderSelect.classList.toggle('btn-primary', !multi);
  el.folderSelect.classList.toggle('btn-ghost', multi);
}

function closeFolderBrowser() {
  el.folderBrowser.classList.add('hidden');
}

/** Load a listing into the modal. Returns true on success. */
async function loadFolders(path) {
  setFolderMsg('');
  try {
    const res = await fetch(`/api/fs/dirs?path=${encodeURIComponent(path || '')}`);
    const data = await safeJson(res);
    if (!res.ok) {
      setFolderMsg(data.error || `HTTP ${res.status}`, 'err');
      return false;
    }
    folderState = data;
    renderFolders(data);
    return true;
  } catch (e) {
    setFolderMsg(e.message, 'err');
    return false;
  }
}

// Limited listing (a hosted Worca, terminal and actions off): say so, and offer each allowed
// folder, since Up stops at them. The server refuses anything outside (403 FS_OUTSIDE_ALLOWED).
function renderFolderScope(data) {
  if (!el.folderScope) return;
  el.folderScope.textContent = '';
  el.folderScope.classList.toggle('hidden', !data.limited);
  if (!data.limited) return;
  el.folderScope.append('This hosted Worca only browses its own data and projects folders.');
  const roots = Array.isArray(data.roots) ? data.roots : [];
  if (roots.length < 2) return;
  for (const r of roots) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'btn btn-ghost btn-mini folder-root';
    b.textContent = r.replace(/[\\/]+$/, '').split(/[\\/]/).pop() || r;
    b.title = r;
    b.addEventListener('click', () => loadFolders(r));
    el.folderScope.append(' ', b);
  }
}

function renderFolders(data) {
  el.folderCurrent.textContent = data.path;
  el.folderCurrent.title = data.path;
  el.folderUp.disabled = !data.parent;
  renderFolderScope(data);
  el.folderList.textContent = '';
  if (!data.dirs.length) {
    const li = document.createElement('li');
    li.className = 'folder-empty hint';
    li.textContent = 'No subfolders.';
    el.folderList.appendChild(li);
    return;
  }
  for (const d of data.dirs) {
    const li = document.createElement('li');
    if (folderManySink) {
      li.className = 'folder-row';
      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.className = 'folder-pick';
      cb.checked = folderPicks.has(d.path);
      cb.setAttribute('aria-label', `Select ${d.name}`);
      cb.addEventListener('change', () => {
        if (cb.checked) folderPicks.set(d.path, d.name); else folderPicks.delete(d.path);
        syncFolderPicks();
      });
      li.appendChild(cb);
    }
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'folder-item';
    btn.textContent = d.name;
    btn.addEventListener('click', () => loadFolders(d.path));
    li.appendChild(btn);
    el.folderList.appendChild(li);
  }
}

function setFolderMsg(text, kind) {
  el.folderMsg.textContent = text || '';
  el.folderMsg.className = 'hint' + (kind ? ' ' + kind : '');
}

el.folderUp.addEventListener('click', () => { if (folderState.parent) loadFolders(folderState.parent); });
el.folderHome.addEventListener('click', () => loadFolders(''));
el.folderSelect.addEventListener('click', () => {
  if (folderState.path) folderSink(folderState.path);
  closeFolderBrowser();
});
el.folderSelectMany.addEventListener('click', () => {
  const sink = folderManySink;
  const paths = [...folderPicks.keys()];
  closeFolderBrowser();
  if (sink && paths.length) sink(paths);
});
el.folderBrowserClose.addEventListener('click', closeFolderBrowser);
// Backdrop click (the overlay itself, not the inner card) and Escape close it,
// matching the viewer modal's behavior.
el.folderBrowser.addEventListener('click', (e) => {
  if (e.target === el.folderBrowser) closeFolderBrowser();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !el.folderBrowser.classList.contains('hidden')) closeFolderBrowser();
});

// NOTE: New Pipeline has no inline project-delete. Removing a project is rare
// and destructive, so it lives in the Projects view (deleteProject, with the
// app's confirmModal) — mirroring workspaces, whose removal has always lived in
// the Workspaces view. The picker's hint links there.

// ===========================================================================
// WORKSPACES — target selector, management view, creation wizard, scan WS.
// All workspace paths are opt-in; project-mode behavior is byte-identical.
// ===========================================================================
const LAST_TARGET_KEY = 'worca-cc.runTarget';
const LAST_WORKSPACE_KEY = 'worca-cc.lastWorkspace';

const wsBasename = (p) => {
  if (!p) return '';
  const parts = String(p).replace(/[\\/]+$/, '').split(/[\\/]/);
  return parts[parts.length - 1] || String(p);
};

// ---- Target selector (New Pipeline) ----------------------------------------

// Toggle Project vs Workspace target. Persists the choice; in workspace mode
// lazy-loads options and re-points the config panel at the built-in models.
function setRunTarget(target) {
  const t = target === 'workspace' ? 'workspace' : 'project';
  state.runTarget = t;
  showEngineRefusal(null); // the refusal and any consent were for the OLD target's context
  state.engineTouched = false;
  localStorage.setItem(LAST_TARGET_KEY, t);
  // A workspace run has no project layer: its default engine is the user's (review I3).
  void loadRunDefaults(t === 'workspace' ? '' : (state.projectDir || ''));
  schedulePolicyLine();                     // debounced: reads the target selects once they settle

  // Segmented buttons + hidden radios (source of truth read at submit).
  $$('#target-seg button[data-target]').forEach((b) => {
    const on = b.dataset.target === t;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', String(on));
  });
  const radio = (el.targetRadios || []).find((r) => r.value === t);
  if (radio) radio.checked = true;

  // Panes are mutually exclusive; only the visible pane's value is read at submit.
  if (el.targetProjectPane) el.targetProjectPane.classList.toggle('hidden', t !== 'project');
  if (el.targetWorkspacePane) el.targetWorkspacePane.classList.toggle('hidden', t !== 'workspace');

  // Source-branch field: in workspace mode swap the single dropdown for one
  // per-project dropdown each defaulting to that project's current branch (HEAD).
  if (t === 'workspace') {
    // The single dropdown STAYS, disabled, stating what will happen ("current
    // branch (auto)") until a workspace with members replaces it with one
    // picker each — an empty column reads as a broken control, and the field
    // vanishing entirely made the row jump.
    showWorkspaceBranchPlaceholder();
    // Config panel: no projectDir → built-in models/efforts; workflow picker still works.
    loadConfig('');
    ensureWorkspaceOptions();
    // The binding scope just changed from a project to a workspace; the project
    // mode branch below re-resolves via onProjectChanged().
    if (state.activePluginSource && state.activePluginSource.multiProfile) {
      mountPluginSourcePane(state.activePluginSource);
    }
  } else {
    // Restore the single project-driven dropdown; clear the per-project list.
    if (el.btProjectRow) el.btProjectRow.hidden = false;
    if (el.sourceBranch) el.sourceBranch.disabled = false;
    if (el.wsSourceBranches) { el.wsSourceBranches.classList.add('hidden'); el.wsSourceBranches.innerHTML = ''; }
    // Restore the project-driven branch list + config for the selected project.
    onProjectChanged();
  }
  syncPreviousBranchEverywhere();
  paintBranches();
}

// Workspace mode with nothing to pick per member yet: keep the field occupied by
// a disabled dropdown that says what the run will do. Its value is never read —
// the submit handler deletes sourceBranch in workspace mode.
function showWorkspaceBranchPlaceholder() {
  if (el.btProjectRow) el.btProjectRow.hidden = false;
  if (!el.sourceBranch) return;
  // #527: a project-mode fresh answer still in flight must not repaint the stand-in.
  el.sourceBranch._branchGen = (el.sourceBranch._branchGen || 0) + 1;
  state.sync = freshSyncState(state.sync.gen + 1);
  paintBranches();
  seedBranchPlaceholder(el.sourceBranch, 'current branch (auto)');
  el.sourceBranch.disabled = true;
  el.sourceBranch.title = "Set per project once a workspace is chosen; each defaults to its current branch.";
}

// Render the member chips for the currently-selected workspace.
function renderWorkspaceMembers() {
  const host = el.wsMembers;
  if (!host) return;
  host.innerHTML = '';
  const ws = state.workspaces.find((w) => w && w.id === state.selectedWorkspaceId);
  if (!ws || !Array.isArray(ws.projectPaths)) return;
  ws.projectPaths.forEach((p, i) => {
    const chip = document.createElement('span');
    chip.className = 'chip';
    const missing = Array.isArray(ws.exists) && ws.exists[i] === false;
    if (missing) chip.classList.add('missing');
    chip.textContent = wsBasename(p) + (missing ? ' (missing)' : '');
    host.appendChild(chip);
  });
}

// Render one source-branch dropdown per member of the selected workspace, each
// keyed by projectKey and defaulted to that project's current branch (HEAD).
function renderWorkspaceSourceBranches() {
  const host = el.wsSourceBranches;
  if (!host) return;
  host.innerHTML = '';
  // #527: the old member selects are gone (their late branches-fresh checks isConnected).
  state.sync.members = {};
  const ws = state.workspaces.find((w) => w && w.id === state.selectedWorkspaceId);
  if (!ws || !Array.isArray(ws.projectPaths) || !ws.projectPaths.length) {
    host.classList.add('hidden');
    showWorkspaceBranchPlaceholder(); // nothing per-member to show: keep the field occupied
    syncPreviousBranchEverywhere();
    paintBranches();
    return;
  }
  host.classList.remove('hidden');
  // Real per-member pickers now exist, so the disabled stand-in would only be a
  // dead control sitting above live ones.
  if (el.btProjectRow) el.btProjectRow.hidden = true;
  ws.projectPaths.forEach((p, i) => {
    const key = (Array.isArray(ws.projectKeys) && ws.projectKeys[i]) || '';
    const missing = Array.isArray(ws.exists) && ws.exists[i] === false;

    // Same three cells as the project row (design v3): Project · Start from · What the run gets.
    const row = document.createElement('div');
    row.className = 'bt-row ws-src-row';
    row.setAttribute('role', 'row');
    row.dataset.projectKey = key;

    const name = document.createElement('span');
    name.className = 'bt-name ws-src-name';
    name.setAttribute('role', 'cell');
    name.id = `bt-name-${i}`;
    name.textContent = (key ? wsMemberName(key) : wsBasename(p)) + (missing ? ' (missing)' : '');

    const wrap = document.createElement('div');
    wrap.className = 'select-wrap';
    wrap.setAttribute('role', 'cell');
    const sel = document.createElement('select');
    sel.className = 'select ws-src-select';
    sel.dataset.projectKey = key;
    sel.setAttribute('aria-labelledby', name.id);
    wrap.appendChild(sel);

    const outcome = document.createElement('div');
    outcome.className = 'bt-outcome';
    outcome.setAttribute('role', 'cell');

    row.append(name, wrap, outcome);
    host.appendChild(row);

    if (missing) {
      sel.disabled = true;
      sel.dataset.missing = '1';
      row.dataset.missing = '1';
      seedBranchPlaceholder(sel, 'current branch (auto)');
      paintMemberRow(key);
    } else {
      paintMemberRow(key);   // Checking… until its fresh list answers
      sel.addEventListener('branches-fresh', (e) => {
        if (!sel.isConnected || state.runTarget !== 'workspace' || !key) return;
        const d = e.detail || {};
        state.sync.members[key] = d.remote && d.sync ? d.sync : null;
        paintBranches();
      });
      sel.addEventListener('change', async () => {
        // A new pick: re-read that member's status (no network) when it has a remote.
        const v = sel.value;
        const prev = state.sync.members[key];
        if (!prev || !v || v === PREVIOUS_BRANCH) return;
        // As refreshSyncStatusQuiet: never keep ANOTHER branch's state after a refused or failed read.
        const unknown = () => {
          if (!sel.isConnected || sel.value !== v || (prev.base === v && prev.state !== 'unknown')) return;
          state.sync.members[key] = { base: v, remote: prev.remote || 'origin', state: 'unknown', settings: prev.settings };
          paintBranches();
        };
        if (!isSyncableBranchName(v)) { unknown(); return; }
        try {
          const res = await fetch(`/api/sync?projectDir=${encodeURIComponent(p)}&base=${encodeURIComponent(v)}&details=1`);
          const data = await safeJson(res);
          if (!sel.isConnected || sel.value !== v) return;
          if (!res.ok || !(data && data.sync)) { unknown(); return; }
          // The status read carries the server's standing fetch failure (stale), so Offline survives a pick.
          state.sync.members[key] = data.sync.remote ? data.sync : null;
          paintBranches();
        } catch { unknown(); }
      });
      populateBranchSelect(sel, p); // async; defaults to HEAD per the clarification
    }
  });
  syncPreviousBranchEverywhere();
  paintBranches();
}

// Populate #workspaceSelect from state.workspaces (loading them if empty).
// Workspaces with any missing member are rendered disabled "+ (incomplete)".
// Restores LAST_WORKSPACE_KEY when valid.
async function ensureWorkspaceOptions({ keepMembers = false } = {}) {
  const sel = el.workspaceSelect;
  if (!sel) return;
  if (!state.workspaces.length) await loadWorkspaces();
  const shown = state.selectedWorkspaceId;

  sel.innerHTML = '';
  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.disabled = true;
  placeholder.textContent = state.workspaces.length ? 'Select a workspace…' : 'No workspaces yet';
  sel.appendChild(placeholder);

  const want = state.selectedWorkspaceId || localStorage.getItem(LAST_WORKSPACE_KEY) || '';
  let restored = false;
  for (const w of state.workspaces) {
    if (!w || !w.id) continue;
    const incomplete = Array.isArray(w.exists) && w.exists.some((e) => !e);
    const opt = document.createElement('option');
    opt.value = w.id;
    opt.dataset.name = w.name || '';
    opt.textContent = (w.name || w.id) + (incomplete ? ' (incomplete)' : '');
    if (incomplete) opt.disabled = true;
    sel.appendChild(opt);
    if (!incomplete && w.id === want) { opt.selected = true; restored = true; }
  }
  if (restored) {
    state.selectedWorkspaceId = want;
    localStorage.setItem(LAST_WORKSPACE_KEY, want);
  } else {
    state.selectedWorkspaceId = '';
    placeholder.selected = true;
  }
  // A background list refresh (keepMembers) leaves a still-selected workspace's member rows and
  // branch picks alone; only a changed selection repaints them.
  if (keepMembers && state.selectedWorkspaceId && state.selectedWorkspaceId === shown) return;
  renderWorkspaceMembers();
  renderWorkspaceSourceBranches();
}

if (el.targetSeg) {
  $$('#target-seg button[data-target]').forEach((btn) => {
    btn.addEventListener('click', () => setRunTarget(btn.dataset.target));
  });
}
if (el.workspaceSelect) {
  el.workspaceSelect.addEventListener('change', () => {
    state.selectedWorkspaceId = el.workspaceSelect.value || '';
    if (state.selectedWorkspaceId) localStorage.setItem(LAST_WORKSPACE_KEY, state.selectedWorkspaceId);
    // D-W1: Human in the loop is per run on a workspace — a new workspace starts it on again. This
    // listener does not re-run renderWorkflowConfig, so repaint the switch here.
    state.wsHumanInLoop = true;
    if (state.runTarget === 'workspace' && state.workflowId === AUTO_WORKFLOW_ID && el.humanInLoop) el.humanInLoop.checked = true;
    renderWorkspaceMembers();
    renderWorkspaceSourceBranches();
    schedulePolicyLine();                   // team policy notes for the new target (design board 8)
    // Same as onProjectChanged: a workspace has its own binding (or inherits
    // one from its members), so the resolved profile can differ.
    if (state.activePluginSource && state.activePluginSource.multiProfile) {
      mountPluginSourcePane(state.activePluginSource);
    }
  });
}

// ---- Workspaces data load --------------------------------------------------

// Fetch /api/workspaces into state.workspaces. Clears a stale remembered
// selection (and falls back to project target) when its id is gone. Degrades
// gracefully to [] when the route 404s / errors.
async function loadWorkspaces() {
  try {
    const res = await fetch('/api/workspaces');
    const data = await safeJson(res);
    state.workspaces = res.ok && Array.isArray(data.workspaces) ? data.workspaces : [];
  } catch {
    state.workspaces = [];
  }
  // A re-scan still running (a reload, another tab's change): follow it on the page.
  for (const w of state.workspaces) if (w && w.rescan && w.rescan.runId) trackWsRescan(w.id, w.rescan);
  // Stale selection guard: a remembered workspace id not in the fetched list is
  // cleared, and we fall back to project target.
  const remembered = localStorage.getItem(LAST_WORKSPACE_KEY) || '';
  if (remembered && !state.workspaces.some((w) => w && w.id === remembered)) {
    localStorage.removeItem(LAST_WORKSPACE_KEY);
    if (state.selectedWorkspaceId === remembered) state.selectedWorkspaceId = '';
    if (state.runTarget === 'workspace') setRunTarget('project');
  }
  return state.workspaces;
}

// ---- Workspaces management view --------------------------------------------

function setWsMsg(text, kind) {
  reportStatus(el.wsMsg, 'form-msg', text, kind);
}

// ---- Workspaces list ----------------------------------------------------------------------
// The Projects page's shape: one card headed "Workspaces · N", one row per workspace — name,
// a one-line summary (size, metrics home, what needs attention), the stale badge, a chevron —
// and the whole row opens the workspace page. Nothing on the row edits anything.
function renderWorkspaces() {
  const host = el.wsList;
  if (!host) return;
  host.innerHTML = '';
  if (!state.workspaces.length) {
    host.appendChild(histEmpty('No workspaces yet — create one to scan a set of projects.'));
    return;
  }
  const card = document.createElement('section');
  card.className = 'card saved-card';
  const head = document.createElement('div');
  head.className = 'saved-head';
  const b = document.createElement('b');
  b.textContent = 'Workspaces';
  const cnt = document.createElement('span');
  cnt.className = 'cnt';
  cnt.textContent = String(state.workspaces.length);
  head.append(b, cnt, syncCheckedNodes());
  const list = document.createElement('div');
  list.className = 'saved-list';
  // What is known before /scopes answers: this session's payload or the persisted copy paints the
  // summary at once; a workspace neither knows reads "checking metrics…" rather than a summary
  // that reads as final.
  const known = peekTmScopes();
  const knownById = new Map(((known && known.workspaces) || []).map((w) => [w.id, w]));
  for (const w of state.workspaces) list.appendChild(buildWorkspaceRow(w, knownById.get(w.id)));
  card.append(head, list);
  host.appendChild(card);
  paintWsMetricsRows();
  paintWsPolicyLines();                     // team policy (design board 6): the policy home line on the page
  paintSyncChips();
  void refreshSyncChips();
}

function buildWorkspaceRow(w, known) {
  const item = document.createElement('div');
  item.className = 'ws-item';
  item.dataset.workspaceId = w.id || '';
  const row = document.createElement('div');
  row.className = 'ws-row';
  row.setAttribute('role', 'button');
  row.tabIndex = 0;
  row.setAttribute('aria-label', `Open ${w.name || w.id}`);
  const main = document.createElement('div');
  main.className = 'ws-main';
  const name = document.createElement('div');
  name.className = 'ws-name';
  name.textContent = w.name || w.id || '(unnamed)';
  if (Array.isArray(w.exists) && w.exists.some((e) => !e)) {
    const stale = document.createElement('span');
    stale.className = 'ws-stale badge red';
    stale.textContent = 'missing projects';
    name.append(' ', stale);
  }
  // Design board 1 (collapsed rollup): the name and one sentence with the counts, then a strip
  // with an icon per project and the metrics summary. paintSyncChips fills the sync parts;
  // paintWsMetricsRows rewrites .ws-projects on every team-metrics frame.
  const roll = document.createElement('span');
  roll.className = 'ws-rollup tone-muted';
  const rollDot = document.createElement('span'); rollDot.className = 'ws-rollup-dot'; rollDot.setAttribute('aria-hidden', 'true');
  const rollTxt = document.createElement('span'); rollTxt.className = 'ws-rollup-txt'; rollTxt.textContent = 'Checking…';
  roll.append(rollDot, rollTxt);
  const head = document.createElement('div');
  head.className = 'ws-head-line';
  head.append(name, roll);
  const strip = document.createElement('div');
  strip.className = 'ws-strip';
  const members = document.createElement('span');
  members.className = 'ws-strip-members';
  const sep = document.createElement('span');
  sep.className = 'ws-strip-sep'; sep.setAttribute('aria-hidden', 'true'); sep.textContent = '|';
  const sum = document.createElement('small');
  sum.className = 'ws-projects';
  sum.replaceChildren(known ? renderWsSummary(known, { doc: document }) : renderWsSummary(w, { doc: document, pending: true }));
  strip.append(members, sep, sum);
  main.append(head, strip);
  const actions = document.createElement('div');
  actions.className = 'ws-actions';
  const syncAll = document.createElement('button');
  syncAll.type = 'button'; syncAll.className = 'btn btn-primary btn-mini ws-sync-all'; syncAll.hidden = true;
  const n = Array.isArray(w.projectPaths) ? w.projectPaths.length : 0;
  const toggle = document.createElement('button');
  toggle.type = 'button'; toggle.className = 'btn btn-mini ws-toggle';
  toggle.setAttribute('aria-expanded', 'false');
  toggle.textContent = `Show ${n} project${n === 1 ? '' : 's'}`;
  const open = document.createElement('button');
  open.type = 'button';
  open.className = 'proj-open ws-open';
  open.setAttribute('aria-label', 'Open workspace details');
  open.innerHTML = CHEVRON_RIGHT_SVG;   // static markup
  actions.append(syncAll, toggle, open);
  row.append(main, actions);
  // The project table sits outside the row, so its buttons never open the workspace page.
  const table = document.createElement('div');
  table.className = 'ws-table';
  table.hidden = true;
  table.id = `ws-table-${w.id}`;
  toggle.setAttribute('aria-controls', table.id);
  item.append(row, table);
  if (!known) item.setAttribute('aria-busy', 'true');
  return item;
}
// workspaceId → open (true) / closed (false), once someone pressed Show/Hide. Untouched: open
// only when a member has diverged, the one state that wants a look before the next run.
const wsTableOpen = new Map();

// workspaceId → last "Route all members" payload. Routing emits one team-metrics-changed per
// member, and each repaint rebuilds the metrics block — the per-member result list (the only
// place push failures are named, §4.6b) must survive those repaints.
const wsRouteResults = new Map();

// The metrics side of every open workspace surface: the row summaries, and the open page's
// Team block + Overview card. Called on render and on every team-metrics-changed frame.
async function paintWsMetricsRows(force = false) {
  const data = await loadTmScopes({ force });
  const byId = new Map(data.workspaces.map((w) => [w.id, w]));
  for (const item of document.querySelectorAll('#ws-list .ws-item')) {
    const w = byId.get(item.dataset.workspaceId);
    const sum = item.querySelector('.ws-projects');
    const own = state.workspaces.find((x) => x && x.id === item.dataset.workspaceId);
    // Not in the payload (nothing enabled anywhere, or the call failed): the plain summary.
    if (sum) sum.replaceChildren(renderWsSummary(w || { projectPaths: (own && own.projectPaths) || [], home: { state: 'unset' }, members: [] }, { doc: document }));
    item.removeAttribute('aria-busy');
  }
  paintWdMetrics(byId.get(wsDetail?.id));
}
// The open workspace page's metrics block (the members table with the home actions) and its
// METRICS HOME card. `w` is the /scopes workspace entry, or undefined when the payload lacks it.
function paintWdMetrics(w) {
  if (!wsDetail || !wsDetail.screen) return;
  const screen = wsDetail.screen;
  const own = state.workspaces.find((x) => x && x.id === wsDetail.id);
  const meta = screen.querySelector('.pd-meta .ws-projects');
  if (meta) meta.replaceChildren(renderWsSummary(w || { projectPaths: (own && own.projectPaths) || [], home: { state: 'unset' }, members: [] }, { doc: document }));
  const body = screen.querySelector('.wd-team-metrics .pd-team-body');
  if (body) {
    body.replaceChildren(w ? renderWsMetricsRow(w, { doc: document }) : renderWsMetricsRow({ projectPaths: (own && own.projectPaths) || [], home: { state: 'unset' }, members: [] }, { doc: document }));
    const saved = wsRouteResults.get(wsDetail.id);
    const out = body.querySelector('.ws-route-results');
    if (saved && out) {
      out.replaceChildren(saved.error
        ? Object.assign(document.createElement('small'), { className: 'hint err', textContent: saved.error })
        : renderRouteResults(saved, { doc: document }));
    }
  }
  const card = screen.querySelector('.pd-ov-card-metrics');
  if (card) {
    const home = (w && w.home) || { state: 'unset' };
    const silent = ((w && w.members) || []).filter((x) => x.state !== 'home' && !x.recordsOn).length;
    card.querySelector('.pd-ov-value').textContent = home.state === 'unset' ? 'No home' : home.slug;
    const sub = card.querySelector('.pd-ov-sub');
    sub.textContent = home.state === 'unset' ? 'workspace runs are not recorded'
      : home.state !== 'ok' ? (home.detail || 'the metrics home is stale')
        : [home.runs != null ? `${home.runs} workspace run${home.runs === 1 ? '' : 's'}` : '', silent ? `${silent} not recording` : ''].filter(Boolean).join(' · ') || 'recording';
    sub.classList.toggle('pd-ov-attn', home.state !== 'unset' && (home.state !== 'ok' || silent > 0));
  }
}

async function openWsHomeSheet(workspaceId) {
  const w = (await loadTmScopes({ force: true })).workspaces.find((x) => x.id === workspaceId);
  if (!w) return;
  // metrics-scan answers 400 when a member folder is missing — exactly when the page shows
  // "missing projects" — so an unchecked r.ok opened an empty picker with no explanation.
  const r = await fetch('/api/workspaces/metrics-scan', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectPaths: w.projectPaths }) }).catch(() => null);
  const j = r ? await safeJson(r) : null;
  // Same defence renderWsMetricsRow applies (`const home = ws.home || { state: 'unset' }`): a
  // workspace with no home at all has no `home` object, and `w.home.path` would throw here.
  const home = w.home || { state: 'unset', path: null };
  const body = renderMetricsHomePicker(Array.isArray(j?.members) ? j.members : [], { selectedPath: home.path ?? null, doc: document });
  if (!r || !r.ok) {
    body.prepend(Object.assign(document.createElement('small'), { className: 'hint err', textContent: j?.error || 'Could not check the members' }));
  }
  let chosen = home.path ?? null;
  body.addEventListener('change', (e) => { if (e.target.name === 'tm-home') chosen = e.target.value; });
  // "Enable now…" inside the sheet: enable, then reopen the sheet with fresh scan results.
  body.addEventListener('click', (e) => {
    const b = e.target.closest('.tm-enable-now');
    if (!b) return;
    const proj = state.projects.find((p) => p.path === b.closest('.wiz-row').dataset.path);
    if (!proj) { b.replaceWith(Object.assign(document.createElement('small'), { className: 'hint', textContent: 'Add this project on the Projects page to enable it' })); return; }
    closePluginModal();
    openTmEnableDialog(proj.key, { mode: 'here', onDone: () => openWsHomeSheet(workspaceId) });
  });
  pluginModal('Metrics home', body, [
    ['Clear home', 'btn btn-ghost btn-mini', async () => { await patchWsHome(workspaceId, null); }],
    ['Cancel', 'btn btn-ghost btn-mini', () => closePluginModal()],
    ['Save', 'btn btn-primary btn-mini', async () => { await patchWsHome(workspaceId, chosen); }],
  ]);
}
async function patchWsHome(id, metricsProject) {
  const r = await fetch(`/api/workspaces/${encodeURIComponent(id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ metricsProject }) }).catch(() => null);
  if (r && r.ok) { closePluginModal(); await paintWsMetricsRows(true); return; }
  const j = r ? await safeJson(r) : null;
  const list = document.querySelector('#plugin-modal .tm-home-list');
  if (!list) return;
  // #555 D10: one error line, reused, instead of a new node per failed save.
  let err = list.parentElement.querySelector('.tm-home-err');
  if (!err) { err = Object.assign(document.createElement('small'), { className: 'hint err tm-home-err' }); list.after(err); }
  err.textContent = (j && j.error) || 'Could not save the metrics home.';
}

// Delegated actions on the workspaces list: a row (or its chevron) opens the page.
if (el.wsList) {
  const openWsRow = (row) => {
    const item = row.closest('.ws-item');
    if (!item || !item.dataset.workspaceId) return;
    wsReturnFocus = item.dataset.workspaceId;          // Back / Esc come home to this row
    location.hash = `workspaces/${item.dataset.workspaceId}`;
  };
  el.wsList.addEventListener('click', (e) => {
    const row = e.target.closest && e.target.closest('.ws-row[role="button"]');
    if (row) openWsRow(row);
  });
  el.wsList.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
    const row = e.target.closest && e.target.closest('.ws-row[role="button"]');
    if (!row || e.target !== row) return;
    e.preventDefault();
    openWsRow(row);
  });
}

// ---------------------------------------------------------------------------
// Workspace page (#workspaces/<id>[/map|/team]) — the project page's twin: the same two-screen
// slide, the same header card, pills and stat cards (it rides the pd- classes), and all
// editing — description, re-scan, delete, metrics home, policy home, routing, the map's overrides —
// lives here.
// ---------------------------------------------------------------------------
const WS_TABS = ['overview', 'map', 'team', 'actions'];
// workspaces-changed actions that can change the Map tab: an override (P5 routes) or a scan's save.
const WD_MAP_ACTIONS = new Set(['map', 'scan-created', 'scan-updated', 'members']);   // members: a removal prunes the map
function parseWsParam(param = '') {
  const s = String(param || '');
  if (!s) return null;
  const i = s.indexOf('/');
  const id = i === -1 ? s : s.slice(0, i);
  const tab = i === -1 ? '' : s.slice(i + 1);
  return { id, tab: WS_TABS.includes(tab) && tab !== 'overview' ? tab : 'overview' };
}
const wsParamFor = (id, tab = 'overview') => (WS_TABS.includes(tab) && tab !== 'overview' ? `${id}/${tab}` : id);
const workspaceById = (id) => state.workspaces.find((x) => x && x.id === id) || null;

let wsDetail = null;        // { id, screen } while a page is open
let wsReturnFocus = '';     // the id of the row that opened the page; closeWsDetail hands focus back

// #workspaces entry: refetch the list, paint it, then route the page half of the hash. In-view
// hops (list <-> page, tab <-> tab) skip the fetch — showView calls routeWsDetail directly.
let workspacesLoadToken = 0;
async function loadWorkspacesView() {
  const token = ++workspacesLoadToken;
  await loadWorkspaces();
  if (token !== workspacesLoadToken || currentShownView !== 'workspaces') return;
  renderWorkspaces();
  const [view, param] = parseHash();
  if (view === 'workspaces') routeWsDetail(param, { instant: true });
}
// A workspaces-changed frame while the page is open: rebuild the list under the user and keep the
// open page — unless its workspace went away, which closes it with a note. `action` is the frame's
// action: a map override or a finished scan also reloads a built Map tab (WD_MAP_ACTIONS).
async function refreshWorkspacesPage(action = null) {
  await loadWorkspaces();
  if (currentShownView !== 'workspaces') return;
  renderWorkspaces();
  if (!wsDetail) return;
  const w = workspaceById(wsDetail.id);
  if (w) {
    paintWsHeader(wsDetail.screen, w);
    refreshWdOverview();
    if (WD_MAP_ACTIONS.has(action)) await refreshWdMap();
    return;
  }
  const name = wsDetail.name;
  showView('workspaces', '');
  setWsMsg(`workspace "${name}" was removed`, 'err');
}

function routeWsDetail(param, { instant = false } = {}) {
  const parsed = parseWsParam(param);
  if (!parsed) { closeWsDetail({ instant }); return; }
  const w = workspaceById(parsed.id);
  if (!w) {
    closeWsDetail({ instant });
    setWsMsg(`workspace "${parsed.id}" is not registered here`, 'err');
    return;
  }
  if (wsDetail && wsDetail.id === parsed.id) { activateWsTab(parsed.tab); return; }
  openWsDetail(w, parsed, { instant });
}

function openWsDetail(w, parsed, { instant = false } = {}) {
  const host = el.wsDetail;
  const shell = el.wsShell;
  if (!host || !shell) return;
  wsDetail = null;
  host.innerHTML = '';
  host.scrollTop = 0;
  // A re-scan box the user already saw end is not shown again.
  const rescan = wsRescans.get(w.id);
  if (rescan && rescan.seen && WS_RESCAN_ENDED.has(rescan.state)) wsRescans.delete(w.id);
  const screen = $('#ws-detail-tpl').content.firstElementChild.cloneNode(true);
  host.appendChild(screen);
  wsDetail = { id: w.id, name: w.name, screen };
  screen.querySelector('.pd-back').addEventListener('click', () => { location.hash = 'workspaces'; });
  screen.querySelector('.ws-rescan').addEventListener('click', () => { void rescanWorkspace(workspaceById(w.id)); });
  screen.querySelector('.ws-delete').addEventListener('click', () => { void deleteWorkspaceFromPage(w.id); });
  paintWsHeader(screen, w);
  initWdTabs(screen, w);
  activateWsTab(parsed.tab);
  if (instant) shell.classList.add('no-anim');
  shell.classList.add('detail-open');
  host.setAttribute('aria-hidden', 'false');
  host.removeAttribute('inert');
  const list = shell.querySelector('.ws-screen-list');
  if (list) { list.setAttribute('aria-hidden', 'true'); list.setAttribute('inert', ''); }
  screen.querySelector('.pd-back').focus({ preventScroll: true });
  if (instant) rafSafe(() => shell.classList.remove('no-anim'));
}

function paintWsHeader(screen, w) {
  screen.querySelector('.pd-title').textContent = w.name || w.id || '(unnamed)';
  const stale = screen.querySelector('.pd-row1 .ws-stale');
  if (stale) stale.hidden = !(Array.isArray(w.exists) && w.exists.some((e) => !e));
  const meta = screen.querySelector('.pd-meta .ws-projects');
  if (meta) {
    const known = (peekTmScopes()?.workspaces || []).find((x) => x.id === w.id);
    meta.replaceChildren(known ? renderWsSummary(known, { doc: document }) : renderWsSummary(w, { doc: document, pending: true }));
  }
}

function closeWsDetail({ instant = false } = {}) {
  const shell = el.wsShell;
  const host = el.wsDetail;
  if (!shell || !host) return;
  if (!shell.classList.contains('detail-open')) { wsReturnFocus = ''; wsDetail = null; return; }
  wsDetail = null;
  host.setAttribute('aria-hidden', 'true');
  const list = shell.querySelector('.ws-screen-list');
  if (list) { list.removeAttribute('aria-hidden'); list.removeAttribute('inert'); }
  const back = wsReturnFocus;
  wsReturnFocus = '';
  if (back && el.wsList && !instant) {
    const row = el.wsList.querySelector(`.ws-item[data-workspace-id="${cssEscape(back)}"] .ws-row`);
    if (row) row.focus({ preventScroll: true });
  }
  host.setAttribute('inert', '');
  if (instant) {
    shell.classList.add('no-anim');
    shell.classList.remove('detail-open');
    host.innerHTML = '';
    rafSafe(() => shell.classList.remove('no-anim'));
    return;
  }
  shell.classList.remove('detail-open');
  const clear = () => { if (!wsDetail) host.innerHTML = ''; };
  const onEnd = (e) => {
    if (e.target !== host || e.propertyName !== 'transform') return;
    host.removeEventListener('transitionend', onEnd);
    clear();
  };
  host.addEventListener('transitionend', onEnd);
  const t = setTimeout(() => { host.removeEventListener('transitionend', onEnd); clear(); }, 600);
  if (t && typeof t.unref === 'function') t.unref();
}

// ---- tabs ----
const WD_TABS = [
  { key: 'overview', label: 'Overview', level: 'simple', badge: () => null, visible: () => true, build: (sec, id) => buildWdOverview(sec, id) },
  { key: 'map', label: 'Map', level: 'advanced', badge: () => null, visible: () => true, build: (sec, id) => buildWdMap(sec, id) },
  { key: 'team', label: 'Team', level: 'expert', badge: () => null, visible: () => true, build: (sec, id) => buildWdTeam(sec, id) },
  { key: 'actions', label: 'Actions', level: 'advanced', badge: () => null, visible: () => true, build: (sec, id) => buildWdActions(sec, id) },
];
function initWdTabs(screen, w) {
  initDetailTabs(screen, WD_TABS.map((t) => ({ ...t, icon: PD_TAB_ICONS[t.key] })), w, {
    tabsSel: '.pd-tabs', secsSel: '.pd-sections',
    tabClass: 'pd-tab', secClass: 'pd-sec', badgeClass: 'pd-tab-badge',
    idPrefix: 'wd',
    buildArgs: () => [w.id],
    initial: () => 'overview',
  });
  // Hash-first pills, the project page's idiom: the tab goes into the URL so Back and deep links
  // agree with the screen; the hashchange echo lands in routeWsDetail -> activateWsTab.
  screen.querySelector('.pd-tabs').addEventListener('click', (e) => {
    const btn = e.target.closest && e.target.closest('button[data-sec]');
    if (!btn || !wsDetail) return;
    const target = `workspaces/${wsParamFor(wsDetail.id, btn.dataset.sec)}`;
    if (location.hash.slice(1) !== target) location.hash = target;
  });
}
function activateWsTab(tab) {
  const tabs = detailTabsOf(wsDetail && wsDetail.screen);
  if (!tabs) return;
  tabs.activate(tabs.cells.has(tab) ? tab : 'overview');
}

// ---- Overview tab: the stat cards, the projects, the description ----
function buildWdOverview(sec, id) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-overview', 'wd-sec-overview');
  const w = workspaceById(id);
  if (!w) return;
  const paths = Array.isArray(w.projectPaths) ? w.projectPaths : [];
  const missing = Array.isArray(w.exists) ? w.exists.filter((e) => !e).length : 0;
  const grid = document.createElement('div');
  grid.className = 'pd-ov-grid';
  // "On disk" is the normal case, so the sub names the members instead and only a missing one is called out.
  const shortNames = paths.map((path, i) => {
    const k = Array.isArray(w.projectKeys) ? w.projectKeys[i] : null;
    const pr = k ? projectByKey(k) : null;
    return wsShortName((pr && pr.name) || basenameOf(path), w.name);
  });
  const projCard = pdStatCard('projects', 'PROJECTS', String(paths.length), missing ? `${missing} missing on disk` : shortNames.join(' · '));
  if (missing) projCard.querySelector('.pd-ov-sub').classList.add('pd-ov-missing');
  grid.appendChild(projCard);
  // The Workspaces list's rollup sentence, as a card: the worst state up front, Sync all (N).
  grid.appendChild(pdBranchCard('branches', 'BRANCHES'));
  // The team half: one card each, filled by the scopes painters; a click lands on the Team tab.
  for (const which of ['metrics', 'policy']) {
    const card = pdStatCard(which, which === 'metrics' ? 'METRICS HOME' : 'POLICY HOME', '…', 'checking…', { tag: 'button' });
    card.classList.add('pd-ov-link');
    card.title = 'Open the Team tab';
    card.addEventListener('click', () => { location.hash = `workspaces/${wsParamFor(id, 'team')}`; });
    grid.appendChild(tagLevel(card, 'expert'));
  }
  // The date alone at card size (a full timestamp wraps to two lines); the time and the creation date ride the sub.
  const [upDate, upTime] = w.updatedAt ? String(fmtDate(w.updatedAt)).split(', ') : ['—', ''];
  grid.appendChild(pdStatCard('updated', 'UPDATED', upDate, [upTime, w.createdAt ? `created ${String(fmtDate(w.createdAt)).split(', ')[0]}` : ''].filter(Boolean).join(' · ')));
  sec.appendChild(grid);
  // wsDetail is set before the tab builds, so the card can paint at once (and again per status read).
  paintPdBranchCards();
  void refreshSyncChips();

  // Projects: every member once, each a hop to its project page (a registered one).
  const members = document.createElement('section');
  members.className = 'card wd-members';
  const mh = document.createElement('div');
  mh.className = 'card-head';
  const mb = document.createElement('b'); mb.textContent = 'Projects';
  const mc = document.createElement('span'); mc.className = 'badge'; mc.textContent = String(paths.length);
  const madd = document.createElement('button'); madd.type = 'button'; madd.className = 'btn-ghost btn-mini wd-members-add'; madd.textContent = 'Add projects';
  mh.append(mb, mc, madd);
  const mlist = document.createElement('div');
  mlist.className = 'wd-member-list';
  paths.forEach((path, i) => {
    const key = Array.isArray(w.projectKeys) ? w.projectKeys[i] : null;
    const proj = key ? projectByKey(key) : state.projects.find((p) => p.path === path);
    const exists = Array.isArray(w.exists) ? w.exists[i] !== false : true;
    const row = document.createElement(proj && proj.key ? 'button' : 'div');
    row.className = 'wd-member';
    if (row.tagName === 'BUTTON') { row.type = 'button'; row.dataset.key = proj.key; row.title = 'Open the project page'; }
    const name = document.createElement('div');
    name.className = 'wd-member-name';
    name.textContent = (proj && proj.name) || basenameOf(path);
    if (!exists) { const miss = document.createElement('span'); miss.className = 'proj-missing'; miss.textContent = 'missing'; name.append(' ', miss); }
    const p = document.createElement('div');
    p.className = 'proj-path';
    p.textContent = path;
    p.title = path;
    row.append(name, p);
    if (row.tagName === 'BUTTON') { const chev = document.createElement('span'); chev.className = 'wd-member-chev'; chev.innerHTML = CHEVRON_RIGHT_SVG; row.appendChild(chev); }
    // Remove sits BESIDE the row (the row itself is a button for a registered project).
    const item = document.createElement('div');
    item.className = 'wd-member-item';
    const rm = document.createElement('button');
    rm.type = 'button'; rm.className = 'btn-ghost btn-mini wd-member-remove'; rm.textContent = 'Remove';
    rm.dataset.path = path;
    rm.disabled = paths.length <= 2;
    rm.title = rm.disabled ? 'A workspace keeps at least two projects' : `Remove ${name.firstChild ? name.firstChild.textContent : basenameOf(path)} from this workspace`;
    item.append(row, rm);
    mlist.appendChild(item);
  });
  members.append(mh, mlist);
  const rescan = wsRescans.get(id);
  if (rescan) members.appendChild(renderWsRescan(rescan));
  sec.appendChild(members);

  // Description: markdown by contract (the scanner template), edited in place.
  const desc = document.createElement('section');
  desc.className = 'card ws-desc wd-desc';
  const dh = document.createElement('div');
  dh.className = 'card-head';
  const db = document.createElement('b'); db.textContent = 'Description';
  const edit = document.createElement('button'); edit.type = 'button'; edit.className = 'btn-ghost btn-mini ws-edit'; edit.textContent = 'Edit description';
  dh.append(db, edit);
  const view = document.createElement('div');
  view.className = 'ws-desc-view viewer';
  if (w.description) bindMarkdown(view, w.description);
  else { view.classList.remove('artifact-markdown'); view.textContent = '(no description yet — re-scan to generate one)'; }
  const pane = document.createElement('div');
  pane.className = 'ws-desc-edit';
  pane.hidden = true;
  pane.innerHTML = '<div class="md-tabs" role="tablist" aria-label="Description editor">'
    + '<button type="button" class="md-tab ws-desc-tab" role="tab" data-mode="text" aria-selected="true">Text</button>'
    + '<button type="button" class="md-tab ws-desc-tab" role="tab" data-mode="preview" aria-selected="false">Preview</button></div>'
    + '<textarea class="ws-desc-input textarea" rows="10" spellcheck="false"></textarea>'
    + '<div class="ws-desc-preview md-preview viewer" hidden></div>'
    + '<div class="actions" style="justify-content:flex-end;margin-top:10px">'
    + '<button type="button" class="ws-desc-cancel btn btn-ghost btn-mini">Cancel</button>'
    + '<button type="button" class="ws-desc-save btn btn-primary btn-mini">Save</button></div>';   // static markup
  desc.append(dh, view, pane);
  sec.appendChild(desc);
  // Sets from member projects (docs/skills.md; a workspace attaches no sets of its own): the servers and skills a run on
  // this workspace gets — its members' sets and the workspace policy's Team set — each with the member(s) that bring it.
  const mcp = tagLevel(document.createElement('div'), 'advanced');
  mcp.className = 'wd-mcp';
  sec.appendChild(mcp);
  const memberProjects = paths.map((p, i) => {
    const k = Array.isArray(w.projectKeys) ? w.projectKeys[i] : null;
    const pr = k ? projectByKey(k) : null;
    return k ? { key: k, name: (pr && pr.name) || basenameOf(p) } : null;
  }).filter(Boolean);
  void paintMcpResolution(mcp, { target: { workspaceId: id }, title: w.name || w.id, members: memberProjects, api: mcpApi });
  if (!hdMarkdown.isReady()) void bindMarkdownReady().then((ok) => { if (ok) repaintWsDescription(); });
  void paintWsMetricsRows();
  void paintWsPolicyLines();
}
// The Overview reads the workspace row; repaint it (and the header) when the row changes and
// the tab is built. Never while the editor holds a draft — the description panel would be lost.
function refreshWdOverview() {
  if (!wsDetail || !wsDetail.screen) return;
  const sec = wsDetail.screen.querySelector('.pd-sec[data-sec="overview"]');
  if (!sec || sec.dataset.loaded !== '1') return;
  const pane = sec.querySelector('.ws-desc-edit');
  if (pane && !pane.hidden) {
    // Never repaint under an open editor. When the description changed underneath the draft (a
    // scan finished), say so — Save would replace the new text with the draft.
    const w = workspaceById(wsDetail.id);
    if (w && typeof wsDetail.editBase === 'string' && (w.description || '') !== wsDetail.editBase) {
      setWdError(wsDetail.screen, 'The description changed while you were editing (a scan finished). Cancel shows it; Save replaces it with your draft.');
    }
    return;
  }
  buildWdOverview(sec, wsDetail.id);
}
// The description is markdown; the bundle loads lazily, so the first paint may be plain. Repaint
// the view alone once it is ready — not the page, so the editor state survives.
function repaintWsDescription() {
  if (!wsDetail || !wsDetail.screen) return;
  const w = workspaceById(wsDetail.id);
  const view = wsDetail.screen.querySelector('.ws-desc-view');
  if (w && w.description && view && !view.classList.contains('artifact-markdown')) bindMarkdown(view, w.description);
}

// ---- Team tab: the members table with the metrics home, and the policy home line ----
function buildWdTeam(sec, id) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-team', 'wd-sec-team');
  const panel = (which, title, hint) => {
    const card = document.createElement('section');
    card.className = `card pd-team-card wd-team-${which}`;
    card.dataset.workspaceId = id;
    const head = document.createElement('div');
    head.className = 'card-head';
    const b = document.createElement('b'); b.textContent = title;
    const h = document.createElement('small'); h.className = 'hint'; h.textContent = hint;
    head.append(b, h);
    const body = document.createElement('div');
    body.className = 'pd-team-body';
    body.appendChild(Object.assign(document.createElement('small'), { className: 'hint', textContent: 'checking…' }));
    card.append(head, body);
    return card;
  };
  sec.append(
    panel('metrics', 'Team metrics', 'Where this workspace\'s runs are recorded, and what each member records.'),
    panel('policy', 'Team policy', 'The member whose policy governs workspace runs on this machine.'),
  );
  const own = workspaceById(id);
  const body = sec.querySelector('.wd-team-metrics .pd-team-body');
  if (body && own) body.replaceChildren(renderWsMetricsPending(own, { doc: document }));
  void paintWsMetricsRows();
  void paintWsPolicyLines();
}

// ---- Map tab: the scan's interconnection map (spec D17) ----
// GET /api/workspaces/:id/map when the tab is built and on a map / scan frame (WD_MAP_ACTIONS).
// Filters live on wsDetail and die with the page.
let wdMapToken = 0;
function buildWdMap(sec, id) {
  sec.innerHTML = '';
  sec.classList.add('wd-sec-map');
  sec.appendChild(Object.assign(document.createElement('small'), { className: 'hint', textContent: 'Loading…' }));
  // (mapFocus: defensive — a reopened page is a new wsDetail; this covers a builder retry on the same page.)
  if (wsDetail) { wsDetail.map = null; wsDetail.mapError = ''; wsDetail.mapFilters = emptyMapFilters(); wsDetail.mapFocus = null; }
  void loadWdMap(id);
}
// The newest request wins: an older answer that lands last is dropped (wdMapToken).
async function loadWdMap(id) {
  const token = ++wdMapToken;
  let payload = null;
  let error = '';
  try {
    const res = await fetch(`/api/workspaces/${encodeURIComponent(id)}/map`);
    const data = await safeJson(res);
    if (res.ok && data && typeof data === 'object') payload = data;
    else error = (data && data.error) || `HTTP ${res.status}`;
  } catch (err) {
    error = (err && err.message) || 'could not load the map';
  }
  if (token !== wdMapToken || !wsDetail || wsDetail.id !== id) return;
  if (payload) wsDetail.map = payload;
  wsDetail.mapError = error;
  paintWdMap();
  // An override's keyboard target (wdMapMutation) waits for the first paint of a map loaded after
  // its answer: its own reload, or a frame's newer one that overtook it. An older load that still
  // paints (it began before the answer) shows the old table and must not take it.
  const pending = wsDetail.mapFocus;
  if (pending && token >= pending.from) { wsDetail.mapFocus = null; focusWdMapRow(pending.edge, pending.action); }
}
// Reload the Map tab when it has been built; never builds it (a lazy tab stays lazy).
function refreshWdMap() {
  const sec = wsDetail && wsDetail.screen && wsDetail.screen.querySelector('.pd-sec[data-sec="map"]');
  if (!sec || sec.dataset.loaded !== '1') return Promise.resolve();
  return loadWdMap(wsDetail.id);
}
// Repaint from wsDetail.map + filters. The add-form draft, the horizontal scroll of the graph and
// of the edge table (its last column holds the actions) and the focused control survive the
// repaint (a frame can land while the user types).
function paintWdMap({ focus = '' } = {}) {
  const sec = wsDetail && wsDetail.screen && wsDetail.screen.querySelector('.pd-sec[data-sec="map"]');
  if (!sec) return;
  const draft = {};
  for (const f of sec.querySelectorAll('.wm-add-form [name]')) draft[f.name] = f.value;
  const active = document.activeElement && sec.contains(document.activeElement) ? document.activeElement : null;
  const again = wdMapFocusSelector(active);
  const scroll = sec.querySelector('.wm-graph-scroll');
  const left = scroll ? scroll.scrollLeft : 0;
  const tableScroll = sec.querySelector('.wm-table-scroll');
  const tableLeft = tableScroll ? tableScroll.scrollLeft : 0;
  const data = { ...(wsDetail.map || { map: null, edges: [] }), workspace: workspaceById(wsDetail.id), error: wsDetail.mapError || '' };
  sec.replaceChildren(renderMapTab(data, { doc: document, filters: wsDetail.mapFilters || emptyMapFilters() }));
  for (const f of sec.querySelectorAll('.wm-add-form [name]')) {
    if (!(f.name in draft)) continue;
    if (f.tagName === 'SELECT' && ![...f.options].some((o) => o.value === draft[f.name])) continue;
    f.value = draft[f.name];
  }
  const next = sec.querySelector('.wm-graph-scroll');
  if (next && left) next.scrollLeft = left;
  const nextTable = sec.querySelector('.wm-table-scroll');
  if (nextTable && tableLeft) nextTable.scrollLeft = tableLeft;
  const target = (focus && sec.querySelector(focus)) || (again && sec.querySelector(again)) || null;
  if (target && typeof target.focus === 'function') target.focus({ preventScroll: true });
}
// A selector that finds the focused control again in the repainted tab ('' = nothing to restore):
// an add-form field, a filter select, a row action, a graph pair, a coverage chip, or one of the
// tab's single buttons. A frame (another window, a finished scan) repaints under the keyboard.
function wdMapFocusSelector(el) {
  if (!el || !el.closest) return '';
  const q = (v) => `"${cssEscape(String(v || ''))}"`;
  if (el.closest('.wm-add-form') && el.name) return `.wm-add-form [name=${q(el.name)}]`;
  if (el.matches('select.wm-filter')) return `select.wm-filter[data-filter=${q(el.dataset.filter)}]`;
  const act = el.matches('.wm-actions button') && [...el.classList].find((c) => /^wm-(confirm|reject|clear|del)$/.test(c));
  if (act) return `.wm-row[data-edge=${q(el.dataset.edge)}] .${act}`;
  if (el.matches('.wm-pair')) return `.wm-pair[data-from=${q(el.dataset.from)}][data-to=${q(el.dataset.to)}]`;
  if (el.matches('.wm-chip')) return `.wm-chip[data-value=${q(el.dataset.value)}]`;
  if (el.matches('button.wm-filter[data-filter="all"]')) return 'button.wm-filter[data-filter="all"]';
  const one = ['wm-add', 'wm-regen', 'wm-rescan', 'wm-pair-chip'].find((c) => el.classList.contains(c));
  return one ? `.${one}` : '';
}
function setWdMapFilters(patch, focus = '') {
  if (!wsDetail) return;
  wsDetail.mapFilters = patch === null ? emptyMapFilters() : { ...emptyMapFilters(), ...(wsDetail.mapFilters || {}), ...patch };
  paintWdMap({ focus });
}
// A pair in the graph (click, Enter or Space): filter the table to it; the same pair again clears.
function toggleWdMapPair(from, to) {
  const cur = wsDetail && wsDetail.mapFilters && wsDetail.mapFilters.pair;
  const same = cur && cur.from === from && cur.to === to;
  setWdMapFilters({ pair: same ? null : { from, to } }, `.wm-pair[data-from="${cssEscape(from)}"][data-to="${cssEscape(to)}"]`);
}
// A filter button: a coverage chip or a graph node (member, toggles), the pair chip, Clear filters.
function clickWdMapFilter(node) {
  const key = node.dataset.filter;
  const value = node.dataset.value || '';
  if (key === 'all') return setWdMapFilters(null, 'select.wm-filter[data-filter="member"]');
  if (key === 'pair') return setWdMapFilters({ pair: null }, 'select.wm-filter[data-filter="member"]');
  if (key !== 'member') return;
  const cur = (wsDetail && wsDetail.mapFilters && wsDetail.mapFilters.member) || '';
  setWdMapFilters({ member: cur === value ? '' : value }, node.classList.contains('wm-chip') ? `.wm-chip[data-value="${cssEscape(value)}"]` : '');
}
// One override call (P5 routes). The button is busy while it runs and a second press is ignored;
// an error lands on the page header (or on `onError`), gives a button that held the keyboard its
// focus back, and on a 404 (the edge or the workspace is gone) also reloads the tab; success
// clears it, runs `onOk`, reloads the list (the description may have been re-rendered) and the
// Map tab, and puts the keyboard back on the pressed row or button (`wsDetail.mapFocus`, taken
// by the first newer paint in loadWdMap).
async function wdMapMutation(btn, url, opts, { onError = null, onOk = null } = {}) {
  const screen = wsDetail && wsDetail.screen;
  if (!screen || (btn && btn.disabled)) return false;
  const fail = (text) => (onError ? onError(text) : setWdError(screen, text));
  const edge = (btn && btn.dataset && btn.dataset.edge) || '';
  // The pressed control, for the keyboard: a row action (with its edge) or a single button.
  const action = (btn && btn.classList && [...btn.classList].find((c) => /^wm-(confirm|reject|clear|del|add|regen)$/.test(c))) || '';
  const hadFocus = Boolean(btn) && document.activeElement === btn;
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(url, opts);
    const data = await safeJson(res);
    if (!res.ok) {
      fail((data && data.error) || `HTTP ${res.status}`);
      if (res.status === 404) void refreshWdMap();
      return false;
    }
    setWdError(screen, '');
    if (onOk) onOk(data);
    // The keyboard goes back to the row (or the pressed single button) in the first paint of a map
    // loaded AFTER this answer: our own reload, or a frame's newer reload that overtook it (newest
    // wins) — loadWdMap takes it.
    if (action && wsDetail) wsDetail.mapFocus = { edge, action, from: wdMapToken + 1 };
    await refreshWorkspacesPage();
    await refreshWdMap();
    return true;
  } catch (err) {
    fail((err && err.message) || 'request failed');
    return false;
  } finally {
    if (btn && btn.isConnected) {
      btn.disabled = false;
      // A refused press keeps its button: hand the keyboard back to it (Chrome drops the focus of a
      // button that turns disabled), unless the press did not hold the focus or the user moved on.
      const cur = document.activeElement;
      if (hadFocus && (!cur || cur === document.body || !cur.isConnected)) btn.focus({ preventScroll: true });
    }
  }
}
// After an override the tab is rebuilt: a keyboard user whose control went away stays where it was
// — on the same row: the same action if the row still has it, else Clear (never the opposite
// verdict, so a second Enter cannot flip what was just decided), else its first action; on the
// same single button (Add edge); else on the tab panel (initDetailTabs gives it tabindex 0).
function focusWdMapRow(edge, action = '') {
  const sec = wsDetail && wsDetail.screen && wsDetail.screen.querySelector('.pd-sec[data-sec="map"]');
  const cur = document.activeElement;
  if (!sec || (cur && cur !== document.body && cur.isConnected)) return;
  const row = edge ? sec.querySelector(`.wm-row[data-edge="${cssEscape(edge)}"]`) : null;
  const pick = (sel) => (row ? row.querySelector(sel) : null);
  const target = (action && pick(`.wm-actions .${action}`)) || pick('.wm-actions .wm-clear') || pick('.wm-actions button')
    || (!edge && action ? sec.querySelector(`.${action}`) : null) || sec;
  target.focus({ preventScroll: true });
}
const wdMapUrl = (tail = '') => `/api/workspaces/${encodeURIComponent(wsDetail.id)}/map${tail}`;
const WD_JSON_HEADERS = { 'Content-Type': 'application/json' };
function setWdEdgeState(btn, state) {
  return wdMapMutation(btn, wdMapUrl(`/edges/${encodeURIComponent(btn.dataset.edge || '')}`),
    { method: 'PUT', headers: WD_JSON_HEADERS, body: JSON.stringify({ state }) });
}
function deleteWdManualEdge(btn) {
  return wdMapMutation(btn, wdMapUrl(`/edges/${encodeURIComponent(btn.dataset.edge || '')}`), { method: 'DELETE' });
}
function addWdManualEdge(btn) {
  const box = btn.closest('.wm-add-box');
  if (!box) return Promise.resolve(false);
  // The LIVE add box: a frame may repaint the tab while the request runs, so the answer (an error
  // to show, or a saved form to clear) goes to the box on screen, not to the one that was pressed.
  const liveBox = () => (wsDetail && wsDetail.screen && wsDetail.screen.querySelector('.pd-sec[data-sec="map"] .wm-add-box')) || box;
  const val = (name) => ((box.querySelector(`[name="${name}"]`) || {}).value || '').trim();
  const say = (text) => { const msg = liveBox().querySelector('.wm-add-msg'); if (msg) { msg.textContent = text; msg.hidden = !text; } };
  const body = { from: val('wm-from'), to: val('wm-to'), kind: val('wm-kind'), display: val('wm-display'), detail: val('wm-detail') };
  if (!body.from || !body.to || body.from === body.to) { say('Pick two different projects'); return Promise.resolve(false); }
  if (!body.display) { say('Name the edge'); return Promise.resolve(false); }
  say('');
  return wdMapMutation(btn, wdMapUrl('/edges'), { method: 'POST', headers: WD_JSON_HEADERS, body: JSON.stringify(body) }, {
    onError: say,
    onOk: () => {
      const live = liveBox();
      for (const n of ['wm-display', 'wm-detail']) { const f = live.querySelector(`[name="${n}"]`); if (f) f.value = ''; }
    },
  });
}
function regenerateWdDescription(btn) {
  return wdMapMutation(btn, wdMapUrl('/render'), { method: 'POST', headers: WD_JSON_HEADERS, body: '{}' });
}

// Delegated actions on the workspace page: the metrics home sheet and routing, the policy home
// sheet and routing, the description editor, a member row, the Map tab.
if (el.wsDetail) {
  el.wsDetail.addEventListener('click', async (e) => {
    if (!wsDetail) return;
    // The second click of a double-click lands on the repainted Map tab: a different verdict or another row.
    if (e.detail > 1 && e.target.closest('.wm-actions, .wm-add, .wm-regen, .wm-filters, .wm-coverage, .wm-graph')) return;
    const id = wsDetail.id;
    const w = workspaceById(id);
    const member = e.target.closest && e.target.closest('.wd-member[data-key]');
    if (member) { location.hash = `projects/${member.dataset.key}`; return; }
    if (e.target.closest('.wd-members-add')) return void openWsAddMembers(id);
    const rmBtn = e.target.closest('.wd-member-remove');
    if (rmBtn) return void removeWsMember(id, rmBtn.dataset.path);
    if (e.target.closest('.ws-home-change')) return void openWsHomeSheet(id);
    // Team policy line (team-policy design board 6).
    if (e.target.closest('.wsp-home-change')) return void openWsPolicyHomeSheet(id);
    if (e.target.closest('.wsp-open')) { location.hash = `team-policy/workspace:${id}`; return; }
    if (e.target.closest('.wsp-route')) {
      const b = e.target.closest('.wsp-route'); b.disabled = true;
      try {
        const r = await fetch(`/api/workspaces/${encodeURIComponent(id)}/policy-route`, { method: 'POST' });
        const j = await safeJson(r);
        wsPolicyRouteResults.set(id, r.ok && j ? j : { error: j?.error || 'routing failed' });
      } catch (err) {
        wsPolicyRouteResults.set(id, { error: err?.message || 'routing failed' });
      } finally {
        b.disabled = false;
      }
      tpCache.at = 0;
      await paintWsPolicyLines(true);
      return;
    }
    if (e.target.closest('.ws-route')) {
      const b = e.target.closest('.ws-route'); b.disabled = true;
      try {
        const r = await fetch(`/api/workspaces/${encodeURIComponent(id)}/metrics-route`, { method: 'POST' });
        const j = await safeJson(r);
        wsRouteResults.set(id, r.ok && j ? j : { error: j?.error || 'routing failed' });
      } catch (err) {
        wsRouteResults.set(id, { error: err?.message || 'routing failed' });
      } finally {
        b.disabled = false;
      }
      await paintWsMetricsRows(true); // fresh counts + the saved result list
      return;
    }
    const pair = e.target.closest('.wm-pair');
    if (pair) { toggleWdMapPair(pair.dataset.from, pair.dataset.to); return; }
    const filt = e.target.closest('button.wm-filter, .wm-node.wm-filter');
    if (filt) { clickWdMapFilter(filt); return; }
    const act = e.target.closest('.wm-confirm, .wm-reject, .wm-clear');
    if (act) { void setWdEdgeState(act, act.classList.contains('wm-confirm') ? 'confirmed' : act.classList.contains('wm-reject') ? 'rejected' : null); return; }
    if (e.target.closest('.wm-del')) { void deleteWdManualEdge(e.target.closest('.wm-del')); return; }
    if (e.target.closest('.wm-add')) { void addWdManualEdge(e.target.closest('.wm-add')); return; }
    if (e.target.closest('.wm-regen')) { void regenerateWdDescription(e.target.closest('.wm-regen')); return; }
    const rescan = e.target.closest('.wm-rescan');
    if (rescan) {                       // rescanWorkspace disables only the header's Re-scan
      if (rescan.disabled) return;
      rescan.disabled = true;
      try { await rescanWorkspace(w); } finally { if (rescan.isConnected) rescan.disabled = false; }
      return;
    }
    if (e.target.closest('.ws-edit')) { openWsEdit(wsDetail.screen, w); return; }
    const tab = e.target.closest('.ws-desc-tab');
    if (tab) { setMdEditMode(wsDetail.screen.querySelector('.ws-desc-edit'), tab.dataset.mode === 'preview'); return; }
    if (e.target.closest('.ws-desc-cancel')) { closeWsEdit(wsDetail.screen); setWdError(wsDetail.screen, ''); refreshWdOverview(); return; }
    if (e.target.closest('.ws-desc-save')) { void saveWsDescription(wsDetail.screen, w); }
  });
  // Map tab: the four filter selects, and Enter / Space on a focused graph pair.
  el.wsDetail.addEventListener('change', (e) => {
    const s = e.target.closest && e.target.closest('select.wm-filter');
    if (!s || !wsDetail || !['member', 'kind', 'confidence', 'state'].includes(s.dataset.filter)) return;
    setWdMapFilters({ [s.dataset.filter]: s.value }, `select.wm-filter[data-filter="${s.dataset.filter}"]`);
  });
  el.wsDetail.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
    const pair = e.target.closest && e.target.closest('.wm-pair');
    if (!pair || !wsDetail) return;
    e.preventDefault();
    toggleWdMapPair(pair.dataset.from, pair.dataset.to);
  });
}

// ---- member changes: POST /api/workspaces/:id/members {add:[paths]} | {remove:path} ----
// The id never changes; runs already started keep their own members. 409 while a run or scan
// of the workspace is live. After a change the page says what to check next.
// The automatic re-scan after a member change (server afterMembersChanged): a Workspace scan run
// of the new set — graphs, the map and a new description — followed on the Projects card with the
// wizard's loader look (spinner, status, a stage track) and a link to the run.
// id -> { runId, state: running|done|failed|stopped|paused|skipped, reason, cleared, seen }
// An ended entry the page has shown (seen) is dropped when the page is next opened.
const wsRescans = new Map();
const WS_RESCAN_ENDED = new Set(['done', 'failed', 'stopped', 'skipped']);
const WS_RESCAN_ENDS = {
  description: 'done', 'rescan-failed': 'failed', 'rescan-stopped': 'stopped', 'rescan-paused': 'paused',
};

function subscribeRescan(runId) {
  const ws = state.ws;
  if (ws && ws.readyState === 1) { try { ws.send(JSON.stringify({ type: 'subscribe', runId })); } catch { /* ignore */ } }
}

/** Start (or keep) following a workspace's re-scan: {runId, paused?} or {skipped: reason}. A run
 *  already followed keeps its own state. */
function trackWsRescan(id, rescan, cleared = null) {
  const cur = wsRescans.get(id);
  if (rescan.runId && cur && cur.runId === rescan.runId) { if (cleared) cur.cleared = cleared; return; }
  wsRescans.set(id, rescan.runId
    ? { runId: rescan.runId, state: rescan.paused ? 'paused' : 'running', reason: '', cleared: cleared || [] }
    : { runId: null, state: 'skipped', reason: String(rescan.skipped || ''), cleared: cleared || [] });
  if (rescan.runId && !rescan.paused) subscribeRescan(rescan.runId);
}

/** A run frame landed: repaint the loader following that run (after the frame is applied). */
function pokeWsRescanRun(runId) {
  for (const [id, r] of wsRescans) if (r.runId === runId && r.state === 'running') setTimeout(() => paintWsRescan(id), 0);
}

/** The paused re-scan this page follows was resumed (a new entry, a new runId). */
function resumeWsRescan(id, runId) {
  const r = wsRescans.get(id);
  if (!r || r.state !== 'paused') return;
  Object.assign(r, { runId, state: 'running', seen: false });
  subscribeRescan(runId);
  paintWsRescan(id);
}

function endWsRescan(id, how, runId = null) {
  const r = wsRescans.get(id);
  if (!r || (runId && r.runId && r.runId !== runId)) return;
  r.state = how;
  r.seen = false;   // an end the page has not shown yet
  paintWsRescan(id);
}

/** The scan run's stages from its own stepper, each with done / active from its ledger rows ('start'
 *  while one runs: dotState). Bookends are left out: the preflight and done steps, and the graph's
 *  Task and End nodes. */
function wsRescanStages(runId) {
  const run = runId ? runs.get(runId) : null;
  const steps = run && run.stepper && Array.isArray(run.stepper.steps) ? run.stepper.steps : [];
  const records = run && Array.isArray(run.steps) ? run.steps : [];
  const out = [];
  for (const step of steps) {
    if (!step || step.kind === 'preflight' || step.kind === 'done') continue;
    for (const n of step.nodes || []) {
      if (n.uiPhase === 'task' || n.uiPhase === 'end') continue;
      const mine = records.filter((x) => x && x.nodeId === n.id);
      out.push({ id: n.id, label: n.label || n.id,
        active: mine.some((x) => ['act', 'ask'].includes(dotState(x))), done: mine.length > 0 && mine.every((x) => dotState(x) === 'done') });
    }
  }
  return out;
}

function renderWsRescan(r) {
  if (WS_RESCAN_ENDED.has(r.state)) r.seen = true;
  const box = document.createElement('div');
  box.className = `wd-rescan is-${r.state}`;
  box.setAttribute('role', 'status');
  box.setAttribute('aria-live', 'polite');
  const lead = document.createElement('div');
  lead.className = 'wd-rescan-lead';
  if (r.state === 'running') {
    lead.appendChild(Object.assign(document.createElement('div'), { className: 'spinner wd-rescan-spinner' }));
  } else {
    lead.appendChild(Object.assign(document.createElement('span'), { className: 'wd-rescan-mark', textContent: r.state === 'done' ? '✓' : '!' }));
  }
  const body = document.createElement('div');
  body.className = 'wd-rescan-body';
  const LABEL = {
    running: 'Members changed — re-scanning the workspace', done: 'Workspace re-scanned', failed: 'Re-scan failed',
    stopped: 'Re-scan stopped', paused: 'Re-scan paused', skipped: 'Members changed — not re-scanned',
  };
  const SUB = {
    running: 'A Workspace scan run rebuilds the graphs, the map and the description.',
    done: 'The map and the description were refreshed from the new member set.',
    failed: 'Use Re-scan to refresh the map and the description.',
    stopped: 'Use Re-scan to refresh the map and the description.',
    paused: 'Resume it under Running, or use Re-scan.',
    skipped: `${r.reason || 'The scan could not start'} — use Re-scan once that is fixed.`,
  };
  const label = document.createElement('div');
  label.className = 'status-label';
  label.textContent = LABEL[r.state] || LABEL.running;
  const sub = document.createElement('div');
  sub.className = 'status-sub';
  sub.textContent = SUB[r.state] || '';
  body.append(label, sub);
  if (r.state === 'running') {
    const stages = wsRescanStages(r.runId);
    if (stages.length) {
      const track = document.createElement('div');
      track.className = 'wiz-phase-track wd-rescan-phases';
      for (const st of stages) {
        const span = document.createElement('span');
        span.dataset.phase = st.id; span.textContent = st.label;
        if (st.active) span.classList.add('active');
        else if (st.done) span.classList.add('done');
        track.appendChild(span);
      }
      body.appendChild(track);
    }
  }
  if (r.runId && r.state !== 'done') {
    const open = document.createElement('a');
    open.className = 'wd-rescan-open';
    open.href = `#running/${r.runId}`;
    open.textContent = 'Open the scan run';
    body.appendChild(open);
  }
  const hint = document.createElement('small');
  hint.className = 'hint wd-rescan-hint';
  hint.textContent = 'Check the Team tab for members off the metrics or policy home.'
    + (r.cleared && r.cleared.length ? ` The ${r.cleared.join(' and ')} home was cleared — choose a new one there.` : '');
  body.appendChild(hint);
  box.append(lead, body);
  return box;
}

/** Repaint just the loader (the rest of the page, and an open description editor, are left alone). */
function paintWsRescan(id) {
  if (!wsDetail || wsDetail.id !== id || !wsDetail.screen) return;
  const card = wsDetail.screen.querySelector('.wd-members');
  const r = wsRescans.get(id);
  if (!card || !r) return;
  const next = renderWsRescan(r);
  const cur = card.querySelector('.wd-rescan');
  if (cur) cur.replaceWith(next); else card.appendChild(next);
}

async function postWsMembers(id, body) {
  const r = await fetch(`/api/workspaces/${encodeURIComponent(id)}/members`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  }).catch((err) => ({ ok: false, status: 0, json: async () => ({ error: err.message }) }));
  const data = await safeJson(r);
  if (!r.ok) return { error: data.error || `HTTP ${r.status}` };
  const i = state.workspaces.findIndex((x) => x && x.id === id);
  if (i >= 0 && data.workspace) state.workspaces[i] = data.workspace;
  const cleared = Array.isArray(data.clearedHomes) ? data.clearedHomes : [];
  if (data.rescan && (data.rescan.runId || data.rescan.skipped)) trackWsRescan(id, data.rescan, cleared);
  if (wsDetail && wsDetail.id === id) { setWdError(wsDetail.screen, ''); refreshWdOverview(); }
  tpCache.at = 0;
  void paintWsMetricsRows(true);
  void paintWsPolicyLines(true);
  return { ok: true };
}

// Add: the registered projects that are not members yet, as checkboxes.
function openWsAddMembers(id) {
  const w = workspaceById(id);
  if (!w) return;
  const have = new Set(w.projectPaths || []);
  const candidates = state.projects.filter((p) => p && p.path && !have.has(p.path) && p.exists !== false);
  const body = document.createElement('div');
  body.className = 'wd-add-list';
  const chosen = new Set();
  if (!candidates.length) {
    body.appendChild(Object.assign(document.createElement('small'), { className: 'hint', textContent: 'Every registered project is already a member — add a project to Worca first, then add it here.' }));
  }
  for (const p of candidates) {
    const row = document.createElement('label');
    row.className = 'wd-add-row';
    const box = document.createElement('input');
    box.type = 'checkbox'; box.value = p.path;
    const name = document.createElement('span'); name.className = 'wd-member-name'; name.textContent = p.name || basenameOf(p.path);
    const path = document.createElement('span'); path.className = 'proj-path'; path.textContent = p.path;
    row.append(box, name, path);
    body.appendChild(row);
  }
  // The header's Close is the way out; the one action adds the picks, or — with nothing to pick —
  // leads to the Projects page and starts its own Add project flow (folder picker / clone).
  const actions = candidates.length ? [['Add', 'btn btn-primary btn-mini', async () => {
    if (!chosen.size) return;
    const r = await postWsMembers(id, { add: [...chosen] });
    if (r.ok) { closePluginModal(); return; }
    body.querySelector('.wd-add-err')?.remove();
    body.appendChild(Object.assign(document.createElement('small'), { className: 'hint err wd-add-err', textContent: r.error }));
  }]] : [['Add project', 'btn btn-primary btn-mini', () => {
    closePluginModal();
    location.hash = 'projects';
    void addProjectFlow();
  }]];
  pluginModal('Add projects', body, actions);
  const addBtn = [...el.pluginModalActions.querySelectorAll('button')].find((b) => b.textContent === 'Add');
  if (addBtn) addBtn.disabled = true;
  body.addEventListener('change', (e) => {
    if (e.target.type !== 'checkbox') return;
    if (e.target.checked) chosen.add(e.target.value); else chosen.delete(e.target.value);
    if (addBtn) addBtn.disabled = !chosen.size;
  });
}

// Remove: confirm (naming a home it clears), then post; an error lands on the page header.
async function removeWsMember(id, path) {
  const w = workspaceById(id);
  if (!w || !path) return;
  const proj = state.projects.find((p) => p.path === path);
  const name = (proj && proj.name) || basenameOf(path);
  const homes = [w.metricsProject === path ? 'metrics' : '', w.policyProject === path ? 'policy' : ''].filter(Boolean);
  const ok = await confirmModal({
    title: 'Remove project', danger: true, confirmLabel: 'Remove',
    message: `Remove ${name} from "${w.name || w.id}"?\n\nThe project itself is untouched, and runs already started keep their members.`
      + (homes.length ? `\n\n${name} is the ${homes.join(' and ')} home — it is cleared.` : ''),
  });
  if (!ok) return;
  const r = await postWsMembers(id, { remove: path });
  if (r.error && wsDetail && wsDetail.id === id) setWdError(wsDetail.screen, r.error);
}

function openWsEdit(screen, w) {
  if (!screen || !w) return;
  const pane = screen.querySelector('.ws-desc-edit');
  const input = screen.querySelector('.ws-desc-input');
  if (input) input.value = w.description || '';
  // What the draft started from: refreshWdOverview compares it when the list refreshes underneath.
  if (wsDetail) wsDetail.editBase = w.description || '';
  if (pane) { pane.hidden = false; setMdEditMode(pane, false); }
  if (input) input.focus();
}

// Text / Preview for a markdown editor (`host` holds the tabs, a textarea and a
// .md-preview). Preview renders the CURRENT draft through the same sanitized pipeline
// as the saved body; the textarea keeps the raw markdown, so Text loses nothing. The
// comment composer (buildHdComposer) is the same idiom, with its own classes.
function setMdEditMode(host, preview) {
  if (!host) return;
  const ta = host.querySelector('textarea');
  const pv = host.querySelector('.md-preview');
  for (const b of host.querySelectorAll('.md-tab')) b.setAttribute('aria-selected', String((b.dataset.mode === 'preview') === preview));
  if (ta) ta.hidden = preview;
  if (pv) pv.hidden = !preview;
  if (!preview) { if (ta) { try { ta.focus(); } catch { /* detached */ } } return; }
  if (pv) {
    const text = ta ? ta.value.trim() : '';
    bindMarkdown(pv, text);            // '' leaves it :empty → the CSS "Nothing to preview yet" hint
    void bindMarkdownReady().then((ok) => { if (ok && !pv.hidden && !pv.classList.contains('artifact-markdown') && text) bindMarkdown(pv, text); });
  }
}

function closeWsEdit(screen) {
  const pane = screen && screen.querySelector('.ws-desc-edit');
  if (pane) pane.hidden = true;
}

// Save an edited description: PATCH /api/workspaces/:id { description }. JSON-safe
// (JSON.stringify); the textarea value is read via .value, written via .textContent.
async function saveWsDescription(screen, w) {
  if (!screen || !w) return;
  const input = screen.querySelector('.ws-desc-input');
  const description = input ? input.value : '';
  const saveBtn = screen.querySelector('.ws-desc-save');
  if (saveBtn) saveBtn.disabled = true;
  try {
    const res = await fetch(`/api/workspaces/${encodeURIComponent(w.id)}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ description }),
    });
    const data = await safeJson(res);
    if (!res.ok) { setWdError(screen, data.error || `HTTP ${res.status}`); return; }
    const updated = data.workspace || { ...w, description };
    const i = state.workspaces.findIndex((x) => x && x.id === w.id);
    if (i >= 0) state.workspaces[i] = updated;
    setWdError(screen, '');
    closeWsEdit(screen);
    refreshWdOverview();
    void refreshWdMap();              // the description is 'edited' now: the Map tab offers Regenerate
  } catch (err) {
    setWdError(screen, err.message);
  } finally {
    if (saveBtn) saveBtn.disabled = false;
  }
}
// The page's own error line, on the header (the project page's .pd-error idiom).
function setWdError(screen, text) {
  const e = screen && screen.querySelector('.pd-error');
  if (!e) return;
  e.textContent = text || '';
  e.hidden = !text;
}

// Re-scan: start the Workspace scan run over the saved workspace and follow it on Running; the
// run replaces the description when it finishes (D12). 409 (a live run) stays on the page.
async function rescanWorkspace(w) {
  if (!w || !wsDetail) return;
  const screen = wsDetail.screen;
  const btn = screen.querySelector('.ws-rescan');
  if (btn) btn.disabled = true;
  // Re-scan also refreshes member discovery (§4.8) — the home is changed from the page.
  await fetch('/api/workspaces/metrics-scan', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectPaths: w.projectPaths || [] }),
  }).catch(() => {});
  try {
    const res = await fetch(`/api/workspaces/${encodeURIComponent(w.id)}/scan`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}',
    });
    const data = await safeJson(res);
    if (!res.ok || !data.runId) { setWdError(screen, data.error || `HTTP ${res.status}`); return; }
    beginScanRun(data, w.name || w.id);
  } catch (err) {
    setWdError(screen, err.message);
  } finally {
    if (btn && btn.isConnected) btn.disabled = false;
  }
}

// Delete, from the page: confirm, then DELETE. 200 closes the page and removes the row;
// 409 (live run/scan) keeps the page and shows data.error on its header.
async function deleteWorkspaceFromPage(id) {
  const w = workspaceById(id);
  if (!w || !wsDetail) return;
  const screen = wsDetail.screen;
  const schedNote = await scheduleDependentsNote(`workspaceId=${encodeURIComponent(w.id)}`, 'Deleting the workspace cancels them.');
  const ok = await confirmModal({
    title: 'Delete workspace', danger: true, confirmLabel: 'Delete',
    message: `Delete workspace "${w.name || w.id}"?\n\nThis removes its history store and best-effort branch cleanup. This cannot be undone.${schedNote}`,
  });
  if (!ok || !wsDetail) return;
  const btn = screen.querySelector('.ws-delete');
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`/api/workspaces/${encodeURIComponent(w.id)}`, { method: 'DELETE' });
    const data = await safeJson(res);
    if (res.status === 409) { setWdError(screen, data.error || 'Workspace has a live run or scan.'); return; }
    if (!res.ok) { setWdError(screen, data.error || `HTTP ${res.status}`); return; }
    state.workspaces = state.workspaces.filter((x) => !(x && x.id === w.id));
    if (state.selectedWorkspaceId === w.id) state.selectedWorkspaceId = '';
    if (localStorage.getItem(LAST_WORKSPACE_KEY) === w.id) localStorage.removeItem(LAST_WORKSPACE_KEY);
    const warnings = Array.isArray(data.warnings) ? data.warnings : [];
    renderWorkspaces();
    // The list entry (showView) clears the message line on the way in: route first, note after.
    showView('workspaces', '');
    setWsMsg(warnings.length ? `Deleted. Warnings: ${warnings.join('; ')}` : 'Workspace deleted.', warnings.length ? 'warn' : 'ok');
  } catch (err) {
    setWdError(screen, err.message);
  } finally {
    if (btn && btn.isConnected) btn.disabled = false;
  }
}

if (el.wsCreateBtn) el.wsCreateBtn.addEventListener('click', () => { location.hash = 'workspace-create'; });

// ---- Workspace scan models (D15–D18): the scan agent (a catalog model + effort) and its project
// agents (a sub-agent alias + effort). One painter for Create workspace and Settings › General.
const SCAN_AGENT_ALIASES = [['sonnet', 'Sonnet'], ['opus', 'Opus'], ['fable', 'Fable']];
const SCAN_EFFORTS = ['medium', 'high', 'xhigh', 'max'];
const SCAN_MODELS_FALLBACK = { scanModel: 'claude-sonnet-5', scanEffort: 'medium', agentModel: 'sonnet', agentEffort: 'medium' };
const WIZ_MODEL_IDS = { scanModel: 'wiz-scan-model', scanEffort: 'wiz-scan-effort', agentModel: 'wiz-agent-model', agentEffort: 'wiz-agent-effort' };
const WS_SCAN_SETTINGS_IDS = { scanModel: 'wsScanModel', scanEffort: 'wsScanEffort', agentModel: 'wsAgentModel', agentEffort: 'wsAgentEffort' };
let wizModelCatalog = [];
// The wizard's Models column paint in flight (enterWizard): Scan awaits it, so a quick click never
// sends the four still-empty selects (the scan route answers 400 to an empty pick).
let wizModelsPainted = Promise.resolve();
let wsScanCatalog = [];

/** The pick a surface starts from: the stored one over the server's default (else Sonnet · medium). */
function scanModelsFrom(data) {
  const def = data && data.workspaceScanDefault && typeof data.workspaceScanDefault === 'object' ? data.workspaceScanDefault : SCAN_MODELS_FALLBACK;
  const stored = data && data.workspaceScan && typeof data.workspaceScan === 'object' ? data.workspaceScan : null;
  return { ...def, ...(stored || {}), scanEffort: (stored ? stored.scanEffort : def.scanEffort) || '' };
}

/** The scan agent's effort list is its model's own (the pair rule); a model the catalog does not
 *  know (a failed GET) keeps the value it had. '' = the model's default. */
function paintScanEffort(ids, keep, catalog) {
  const sm = document.getElementById(ids.scanModel);
  const se = document.getElementById(ids.scanEffort);
  if (!sm || !se) return;
  const m = catalog.find((x) => x && x.id === sm.value);
  const efforts = m ? (Array.isArray(m.efforts) ? m.efforts : []) : (keep ? [keep] : []);
  se.innerHTML = '';
  if (!efforts.length) se.appendChild(option('', '(model default)'));
  for (const e of efforts) se.appendChild(option(e, e));
  se.value = efforts.includes(keep) ? keep : (efforts.includes('medium') ? 'medium' : (efforts[0] || ''));
}

/** Paint the four selects. The scan model list is the Auto card's (buildAutoModelOptions) without
 *  its "(default)" row — a scan always names its model. */
function paintScanModelPickers(ids, pick, catalog) {
  const sm = document.getElementById(ids.scanModel);
  const am = document.getElementById(ids.agentModel);
  const ae = document.getElementById(ids.agentEffort);
  if (!sm || !am || !ae) return;
  const stale = !!pick.scanModel && catalog.length > 0 && !catalog.some((m) => m && m.id === pick.scanModel);
  buildAutoModelOptions(sm, pick.scanModel || '', catalog, stale);
  if (sm.options[0] && sm.options[0].value === '') sm.remove(0);
  sm.value = pick.scanModel || '';
  paintScanEffort(ids, pick.scanEffort || '', catalog);
  am.innerHTML = '';
  for (const [v, label] of SCAN_AGENT_ALIASES) am.appendChild(option(v, label));
  am.value = pick.agentModel;
  ae.innerHTML = '';
  for (const e of SCAN_EFFORTS) ae.appendChild(option(e, e));
  ae.value = pick.agentEffort;
}

/** The four selects as the POST shape. */
function readScanModelPickers(ids) {
  const v = (k) => document.getElementById(ids[k])?.value || '';
  return { scanModel: v('scanModel'), scanEffort: v('scanEffort'), agentModel: v('agentModel'), agentEffort: v('agentEffort') };
}

// ---- Creation wizard -------------------------------------------------------

// Reset the ephemeral wizard state.
function resetWizard() {
  state.wizard = { name: '', selectedPaths: [], starting: false };
}

// Every entry starts clean: the wizard only collects a name and the projects.
async function enterWizard() {
  resetWizard();
  if (el.wizName) el.wizName.value = '';
  if (!state.projects.length) await loadProjects();
  renderWizardProjects();
  wizModelsPainted = paintWizardModels();
}

// The Models column starts from Settings › Runs › Workspaces every time the wizard opens.
async function paintWizardModels() {
  let data = {};
  try {
    const [catalog, res] = await Promise.all([fetchTitleModelCatalog(), fetch('/api/settings')]);
    wizModelCatalog = catalog;
    if (res.ok) data = await safeJson(res);
  } catch { /* the fallback pick below */ }
  let pick = scanModelsFrom(data);
  // A stored scan model that left the catalog is never offered as this scan's pick: the scan
  // route checks a SENT pick strictly (400), so it would refuse every scan. Start from the
  // default scan model instead — what a Re-scan does with the same stale setting (D18).
  // An EMPTY catalog is a failed GET, not an empty catalog: it condemns nothing.
  if (wizModelCatalog.length && !wizModelCatalog.some((m) => m && m.id === pick.scanModel)) {
    const def = scanModelsFrom({ workspaceScanDefault: data.workspaceScanDefault });
    pick = { ...pick, scanModel: def.scanModel, scanEffort: def.scanEffort };
  }
  paintScanModelPickers(WIZ_MODEL_IDS, pick, wizModelCatalog);
}
if (el.wizScanModel) el.wizScanModel.addEventListener('change', () => paintScanEffort(WIZ_MODEL_IDS, el.wizScanEffort?.value || '', wizModelCatalog));

// Render one checkbox per onboarded project (disabled for !exists). Pre-checks
// anything already in selectedPaths (re-scan). Enables Start only at 2+.
function renderWizardProjects() {
  const host = el.wizProjects;
  if (!host) return;
  host.innerHTML = '';
  const projects = Array.isArray(state.projects) ? state.projects : [];
  const usable = projects.filter((p) => p && p.exists);

  resetWizStep1Hint();

  projects.forEach((p) => {
    if (!p || !p.path) return;
    const row = document.createElement('label');
    // .opt-row puts the selection on the whole row, so a picked project reads
    // from across the list and "missing" stops looking like "just unchecked".
    row.className = 'wiz-proj opt-row' + (p.exists ? '' : ' missing');
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.className = 'wiz-proj-cb';
    cb.value = p.path;
    cb.disabled = !p.exists;
    cb.checked = state.wizard.selectedPaths.includes(p.path);
    cb.addEventListener('change', () => {
      const set = new Set(state.wizard.selectedPaths);
      if (cb.checked) set.add(p.path); else set.delete(p.path);
      state.wizard.selectedPaths = [...set];
      syncWizardStartEnabled();
    });
    const txt = document.createElement('span');
    txt.className = 'opt-name';
    txt.textContent = p.name;
    row.append(cb, txt);
    if (p.path) {
      const sub = document.createElement('span');
      sub.className = 'opt-sub';
      sub.textContent = p.path;
      row.appendChild(sub);
    }
    // the parenthetical became a badge: same word, but it now reads as state
    if (!p.exists) {
      const badge = document.createElement('span');
      badge.className = 'badge red';
      badge.textContent = 'missing';
      row.appendChild(badge);
    }
    host.appendChild(row);
  });
  syncWizardStartEnabled();
}

// Workspace size (D24): one line under the list once the pick passes 10 (a bit big) or 20 (big);
// past 40 it turns red and Scan stays off. data-level drives the tone; hidden when nothing to say.
const WIZ_SIZE_NOTES = {
  big: (n) => `A bit big — ${n} projects: the scan takes longer and costs more.`,
  'very-big': (n) => `Big workspace — ${n} projects: a long, costly scan, and a long description added to every run.`,
  over: (n) => `Too many — ${n} selected; a workspace holds up to ${WORKSPACE_MAX_PROJECTS} projects.`,
};

function paintWizardSizeNote() {
  const note = el.wizSizeNote;
  if (!note) return;
  const count = state.wizard.selectedPaths.length;
  const level = workspaceSizeLevel(count);
  note.dataset.level = level;
  note.textContent = level === 'ok' ? '' : WIZ_SIZE_NOTES[level](count);
  note.hidden = level === 'ok';
}

function syncWizardStartEnabled() {
  const next = document.getElementById('wiz-start-scan');
  const count = state.wizard.selectedPaths.length;
  // A workspace holds 2–40 projects (D22): Scan stays off outside that range.
  if (next) next.disabled = count < 2 || count > WORKSPACE_MAX_PROJECTS;
  paintWizardSizeNote();
  syncWizardSelectAll();
}

// The enabled (existing) project checkboxes: the only rows Select all may touch.
function wizardUsableBoxes() {
  return el.wizProjects ? [...el.wizProjects.querySelectorAll('.wiz-proj-cb:not(:disabled)')] : [];
}

// Select all reads checked when every usable project is picked, indeterminate when some are.
function syncWizardSelectAll() {
  const all = el.wizSelectAll;
  if (!all) return;
  const boxes = wizardUsableBoxes();
  const picked = boxes.filter((b) => b.checked).length;
  all.disabled = boxes.length < 2;
  all.checked = boxes.length > 0 && picked === boxes.length;
  all.indeterminate = picked > 0 && picked < boxes.length;
}

// Check or clear every usable project at once; a missing project's selection is left as is.
if (el.wizSelectAll) el.wizSelectAll.addEventListener('change', () => {
  const on = el.wizSelectAll.checked;
  const set = new Set(state.wizard.selectedPaths);
  for (const cb of wizardUsableBoxes()) {
    cb.checked = on;
    if (on) set.add(cb.value); else set.delete(cb.value);
  }
  state.wizard.selectedPaths = [...set];
  syncWizardStartEnabled();
});

// The team-metrics home is no longer a wizard step: POST /api/workspaces adopts the one
// member that already records (autoMetricsHome), and every other case is "Choose…" on the
// workspace card — so creating a workspace never blocks on a feature most users have not
// turned on, and a member that is not a git repository no longer fails the flow.

// Start the Workspace scan run and follow it on Running (D12). The server creates the
// workspace when the run finishes, so the wizard is done the moment the run starts.
async function startWizardScan() {
  const name = el.wizName ? el.wizName.value.trim() : '';
  if (!name) { if (el.wizName) el.wizName.focus(); return; }
  const count = state.wizard.selectedPaths.length;
  if (count < 2 || count > WORKSPACE_MAX_PROJECTS || state.wizard.starting) return;
  state.wizard.starting = true;
  if (el.wizStartScan) el.wizStartScan.disabled = true;
  try {
    await wizModelsPainted;   // never rejects (paintWizardModels catches its own fetches)
    const res = await fetch('/api/workspaces/scan', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectPaths: state.wizard.selectedPaths, name, models: readScanModelPickers(WIZ_MODEL_IDS) }),
    });
    const data = await safeJson(res);
    if (!res.ok || !data.runId) { setWizStep1Error(data.error || `Scan failed (${res.status})`, data.code); return; }
    beginScanRun(data, name);
  } catch (err) {
    setWizStep1Error(err.message);
  } finally {
    state.wizard.starting = false;
    syncWizardStartEnabled();
  }
}

function resetWizStep1Hint() {
  const hint = el.wizStep1Hint;
  if (!hint) return;
  const usable = (Array.isArray(state.projects) ? state.projects : []).filter((p) => p && p.exists);
  hint.classList.remove('err');
  claudeSignedOutHints.delete(hint);
  hint.textContent = usable.length < 2
    ? 'Onboard at least two projects (in New Pipeline) to create a workspace.'
    : 'Select two or more projects to scan their interconnections.';
}

// A signed-out Claude CLI (409 code 'claude-signed-out') gets one short red line
// whose link opens the Connect Claude Code dialog. `restore` repaints the hint's
// normal text once Check again there finds the CLI signed in (paintClaudeSetupStatus).
const claudeSignedOutHints = new Map();   // hint element -> restore()
function showClaudeSignedOut(hint, restore) {
  const link = document.createElement('a');
  link.href = '#';
  link.textContent = 'Sign in…';
  link.addEventListener('click', (e) => { e.preventDefault(); openClaudeSetup(); });
  hint.classList.add('err');
  hint.replaceChildren("Claude Code isn't signed in. ", link);
  claudeSignedOutHints.set(hint, restore);
}

// Any other refusal keeps the "Scan error: …" text.
function setWizStep1Error(message, code) {
  const hint = el.wizStep1Hint;
  if (!hint) return;
  if (code === 'claude-signed-out') { showClaudeSignedOut(hint, resetWizStep1Hint); return; }
  claudeSignedOutHints.delete(hint);
  hint.classList.add('err');
  hint.textContent = `Scan error: ${message}`;
}

// A scan run starts like any run this tab started: its card on Running.
function beginScanRun(data, name) {
  beginRun(data.runId, data.projectDir || '', data.title || `Workspace scan: ${name}`, {
    workspaceId: data.workspaceId, workspaceName: name, projectNames: data.projectNames,
  });
}

if (el.wizStartScan) el.wizStartScan.addEventListener('click', () => startWizardScan());
if (el.wizClose) el.wizClose.addEventListener('click', () => { location.hash = 'new'; });
if (el.wizName) el.wizName.addEventListener('input', () => { state.wizard.name = el.wizName.value; });

// A11y: Escape in the wizard view triggers #wiz-close (which navigates away;
// the showView leave-guard resets the wizard). Scoped to the wizard view so
// it never collides with the viewer-modal Escape handler.
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (currentView() !== 'workspace-create') return;
  if (e.target?.closest?.('.term-pane')) return;                     // Escape typed in the terminal (vim, less) is the shell's
  if (el.viewerCard && !el.viewerCard.classList.contains('hidden')) return; // modal owns Escape
  if (el.folderBrowser && !el.folderBrowser.classList.contains('hidden')) return; // modal owns Escape
  if (el.wizClose) el.wizClose.click();
});

// Test hook: expose the wizard helpers + workspace renderers for jsdom tests.
if (typeof window !== 'undefined') {
  window.__ws = {
    setRunTarget, ensureWorkspaceOptions, loadWorkspaces, loadWorkspacesView,
    renderWorkspaces, buildWorkspaceRow, routeWsDetail, enterWizard,
    renderWizardProjects, startWizardScan, resetWizard,
    renderWorkspaceSourceBranches,
  };
}

// ---- Agents management view -------------------------------------------------

// After any agent mutation: drop the new-pipeline config registry memo
// (getAgentsApi) and the run-graph agent-meta cache, so both refetch on demand.
function invalidateAgentCaches() {
  state.agents = {};
  agentMetaCache.clear();
  gvAgentsDirty = true;           // the composer re-reads /api/agents on re-entry
}

async function loadAgentsList() {
  try {
    const res = await fetch('/api/agents?all=1');
    const data = await safeJson(res);
    state.agentsList = res.ok && Array.isArray(data.agents) ? data.agents : [];
    if (res.ok && Array.isArray(data.mockWriterRoles)) state.mockWriterRoles = data.mockWriterRoles;
  } catch { state.agentsList = []; }
  return state.agentsList;
}

async function loadAgentsView() {
  await loadAgentsList();
  renderAgentsList();
}

function setAgentsMsg(text, kind) {
  reportStatus(el.agentsMsg, 'form-msg', text, kind);
}

function agentChip(text, cls) {
  const s = document.createElement('span');
  s.className = 'agent-chip ' + cls;
  s.textContent = text;
  return s;
}

// One pill per typed port: `id · type`, void ports dashed, loop inputs marked
// with ↺ (a loop input is optional and re-fires the agent on a fresh token).
function fillPortRow(container, ports, cls) {
  const list = Array.isArray(ports) ? ports : [];
  if (list.length === 0) {
    const none = document.createElement('span');
    none.className = 'agent-io-none';
    none.textContent = '—';
    container.appendChild(none);
    return;
  }
  for (const p of list) {
    if (!p || p.synthetic || p.id === 'await') continue; // the await gate is engine surface
    const text = `${p.loop ? '↺ ' : ''}${p.id} · ${p.type}`;
    container.appendChild(agentChip(text, `${cls}${p.type === 'void' ? ' void' : ''}`));
  }
}

function buildAgentCard(a) {
  const tpl = $('#agent-card-tpl');
  const node = tpl.content.firstElementChild.cloneNode(true);
  node.dataset.agentKey = a.key || '';
  node.querySelector('.agent-name').textContent = a.displayName || a.key;
  node.querySelector('.agent-origin').textContent = a.origin || 'builtin';
  node.querySelector('.agent-origin').classList.add(a.origin === 'user' ? 'origin-user' : 'origin-builtin');
  // placeable defaults TRUE; the badge says the agent runs off-pipeline (the
  // workspace scanner) and can never be dropped on a canvas.
  node.querySelector('.agent-not-placeable').hidden = a.placeable !== false;
  // The blurb the user authored wins; a port summary stands in when it is empty.
  node.querySelector('.agent-sub').textContent =
    `${a.key} · ${a.runnerType || 'producer'} — ${a.description || a.portSummary || ''}`;
  fillPortRow(node.querySelector('.agent-chips-in'), a.inputs, 'cons');   // INPUT row
  fillPortRow(node.querySelector('.agent-chips-out'), a.outputs, 'prod'); // OUTPUT row
  const isUser = a.origin === 'user';
  node.querySelector('.agent-edit').hidden = !isUser;
  node.querySelector('.agent-delete').hidden = !isUser;
  node.querySelector('.agent-duplicate').hidden = isUser;
  return node;
}

function renderAgentsList() {
  const host = el.agentsList;
  if (!host) return;
  host.innerHTML = '';
  if (!state.agentsList.length) {
    host.appendChild(histEmpty('No agents found — is the server running?'));
    return;
  }
  const groups = [
    ['Built-in agents', state.agentsList.filter((a) => a.origin !== 'user')],
    ['Your agents', state.agentsList.filter((a) => a.origin === 'user')],
  ];
  for (const [label, list] of groups) {
    if (!list.length) continue;
    const h = document.createElement('div');
    h.className = 'agents-group-label';
    h.textContent = label;
    host.appendChild(h);
    for (const a of list) host.appendChild(buildAgentCard(a));
  }
}

/**
 * The agent's forms, read-only, in the always-visible detail pane (spec §11).
 * This is the ONLY forms surface a built-in or plugin agent has: `buildAgentCard`
 * hides `.agent-edit` for every non-user origin and the store refuses the write
 * (BUILTIN / PLUGIN), so there is nothing to disable here — there is simply no
 * editor. Each row is the id, the title and a `readonly` preview.
 */
function paintAgentFormsView(host, meta) {
  if (!host) return;
  for (const v of host.__views || []) { try { v.dispose(); } catch { /* already gone */ } }
  host.__views = [];
  host.replaceChildren();
  const forms = meta && meta.ask && meta.ask.forms && typeof meta.ask.forms === 'object' ? meta.ask.forms : {};
  const ids = Object.keys(forms);
  if (!ids.length) { host.hidden = true; return; }
  host.hidden = false;
  for (const id of ids) {
    const row = document.createElement('div');
    row.className = 'afv-row';
    const head = document.createElement('div');
    head.className = 'afv-head';
    const b = document.createElement('b');
    b.className = 'afv-id mono';
    b.textContent = id;
    const t = document.createElement('span');
    t.className = 'afv-title';
    t.textContent = (forms[id] && forms[id].title) || '';
    head.append(b, t);
    const body = document.createElement('div');
    body.className = 'afv-preview';
    try {
      const view = renderAskForm(previewAskFromDef(id, forms[id]), {
        doc: document, fileUrl: previewFileUrl, readonly: true, values: null, onChange: null,
        markdown: pageMarkdown, highlight: (el) => hdMarkdown.highlight(el),   // the run's own seams
      });
      host.__views.push(view);
      body.appendChild(view.el);
      bindMarkdownReady().then((ok) => { if (ok) view.paintMarkdown(); });
    } catch { /* a stored form that no longer passes the catalog shows its head only */ }
    row.append(head, body);
    host.appendChild(row);
  }
}

function toggleAgentDetail(card) {
  const head = card.querySelector('.agent-head');
  const detail = card.querySelector('.agent-detail');
  const open = head.getAttribute('aria-expanded') === 'true';
  head.setAttribute('aria-expanded', String(!open));
  detail.hidden = open;
  if (!open && !detail.dataset.loaded) {
    detail.dataset.loaded = '1';
    fetchAgentFull(card.dataset.agentKey).then((data) => {
      const pre = card.querySelector('.agent-md-view');
      if (pre) pre.textContent = (data && data.markdown) || '(no markdown body)';
      paintAgentFormsView(card.querySelector('.agent-forms-view'), data && data.meta);
    });
  }
}

async function fetchAgentFull(key) {
  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(key)}`);
    const data = await safeJson(res);
    return res.ok ? data : null;
  } catch { return null; }
}

async function deleteAgentCard(card, a) {
  const ok = await confirmModal({
    title: 'Delete agent', danger: true, confirmLabel: 'Delete',
    message: `Delete agent "${a.displayName || a.key}"?\n\nThis removes its markdown + metadata pair. This cannot be undone.`,
  });
  if (!ok) return;
  try {
    const res = await fetch(`/api/agents/${encodeURIComponent(a.key)}`, { method: 'DELETE' });
    const data = await safeJson(res);
    if (!res.ok) { setAgentsMsg(data.error || `HTTP ${res.status}`, 'err'); return; }
    state.agentsList = state.agentsList.filter((x) => x.key !== a.key);
    invalidateAgentCaches();
    setAgentsMsg('Agent deleted.', 'ok');
    renderAgentsList();
  } catch (err) { setAgentsMsg(err.message, 'err'); }
}

async function duplicateAgentCard(a) {
  const full = await fetchAgentFull(a.key);
  if (!full) { setAgentsMsg('Could not load the agent to duplicate.', 'err'); return; }
  // Drop the computed fields (this path never goes through the form): the copy
  // gets its own key/agentFile, and a description derived from the source .md
  // frontmatter must not be copied in as authored sidecar text.
  const { key, origin, agentFile, agentPath, descriptionDerived, ...rest } = full.meta || {};
  const meta = { ...rest, displayName: `${full.meta.displayName || a.key} (copy)` };
  if (descriptionDerived) meta.description = '';
  try {
    const res = await fetch('/api/agents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ meta, markdown: full.markdown }),
    });
    const data = await safeJson(res);
    if (!res.ok) { setAgentsMsg(data.error || `HTTP ${res.status}`, 'err'); return; }
    invalidateAgentCaches();
    setAgentsMsg(`Duplicated as "${data.meta.key}".`, 'ok');
    await loadAgentsView();
  } catch (err) { setAgentsMsg(err.message, 'err'); }
}

// ---- Shared agent metadata form (used by the card editor AND wizard Step 3) ---

// One checkbox per option into host; values bound via .checked (never innerHTML).
function buildChipChecks(host, options, selected) {
  host.innerHTML = '';
  const sel = new Set(Array.isArray(selected) ? selected : []);
  for (const opt of options) {
    const row = document.createElement('label');
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.value = opt;
    cb.checked = sel.has(opt);
    const txt = document.createElement('span');
    txt.textContent = opt;
    row.append(cb, txt);
    host.appendChild(row);
  }
}
const chipValues = (host) => [...host.querySelectorAll('input:checked')].map((c) => c.value);

// ---- Shared agent metadata form (card editor AND wizard Step 3) --------------
// The form emits a meta v2 SIDECAR and nothing else. It never blocks a save:
// every rule below is a live .pf-hint mirroring the store's 400 text, and the
// PUT/POST always goes out — the server owns the verdict (spec §9).
// PORT_ID_RE, MAX_PORTS_PER_SIDE and PORT_TYPES are IMPORTED, never re-typed:
// a second copy of PORT_ID_RE is exactly how the editor's hint and the store's
// 400 start disagreeing. (They are imported at the top of this file.)
const PORT_TYPE_OPTIONS = PORT_TYPES.filter((t) => t !== 'any'); // `any` is engine-only
const OUTPUT_WHENS = ['always', 'blocking', 'clean'];
const PORT_STORES = ['run', 'project'];
const RUNNER_TYPES = ['producer', 'verifier', 'clarifier'];
const AGENT_COLORS = ['green', 'peach', 'red', 'blue', 'violet', 'amber'];
const AGENT_SCOPES = ['project', 'workspace-only'];
const WORKSPACE_STRATEGIES = ['explore', 'task', 'review'];
const PORT_OWN_KEYS = ['id', 'type', 'required', 'loop', 'expands', 'as', 'directive', 'when', 'filename', 'store'];
/**
 * Keys the form OWNS: it either surfaces them or deliberately drops them.
 * Anything NOT listed here rides through dataset.extra untouched, so a newer
 * worca's field survives an edit by an older one.
 */
const AGENT_OWN_KEYS = [
  'key', 'displayName', 'description', 'color', 'runnerType', 'order', 'domain', 'scope', 'icon',
  'fanOut', 'asksQuestions', 'questionsLocked', 'questionsDefault', 'inputs', 'outputs', 'verdict',
  'sideEffect', 'mockRole', 'wantsRequest', 'workspaceFanOut', 'workspaceStrategy',
  'workspaceVariantOf', 'placeable', 'requiresSkills', 'promptHints', 'metaVersion', 'ask',
  // Computed by the registry, never authored back into a sidecar.
  'origin', 'agentPath', 'agentFile', 'descriptionDerived', 'portSummary',
];
/**
 * The port type each non-default `as` renderer requires — a byte-for-byte copy
 * of AS_REQUIRES_TYPE in src/shared/graph/agent-meta.mjs. `file` is deliberately
 * ABSENT: it is the default, is materialized on non-void inputs only, and its
 * rule is therefore "non-void", not "md".
 */
const AS_REQUIRES_TYPE = { answers: 'json', 'fix-review': 'md', worktree: 'void' };
const PORT_AS = ['file', 'answers', 'fix-review', 'worktree'];
const FILENAME_TOKENS = ['cycle', 'vsuffix', 'base'];
/** readVerdict/readOutputs reject a path or a `..` in any filename template. */
const BASENAME_BAD = (f) => /[\\/]/.test(f) || f.includes('..');
// AS_REQUIRES_TYPE and the ~10 rule strings in refreshAgentForm are the only
// things this file still duplicates from src/shared/graph/agent-meta.mjs (that
// module exports neither). The hint test pins every string against the wording
// the store actually emits; P8 should export both and delete these copies.

/** The `.agent-form` host inside a pane (or the pane itself when it IS one). */
const formHost = (root) => root.querySelector('.agent-form') || root;

/** Paint a hint slot: the text, hidden when there is none. Module-level because the
 *  Forms section repaints from more than one function (refreshAgentForm keeps its own
 *  local copy of the same two lines). */
const fmSetText = (el, text) => { el.textContent = text; el.hidden = !text; };
/** dataset JSON never throws the form down: a hand-mangled attribute degrades to {}. */
const readExtra = (el) => { try { return el.dataset.extra ? JSON.parse(el.dataset.extra) : {}; } catch { return {}; } };

function fmField(labelText, control, cls) {
  const wrap = document.createElement('div');
  wrap.className = `field${cls ? ` ${cls}` : ''}`;
  const label = document.createElement('label');
  label.textContent = labelText;
  wrap.append(label, control);
  return wrap;
}
function fmInput(cls, value, { type = 'text', placeholder = '' } = {}) {
  const input = document.createElement('input');
  input.type = type;
  input.className = `${cls} input`;
  input.spellcheck = false;
  input.value = value == null ? '' : String(value);
  if (placeholder) input.placeholder = placeholder;
  return input;
}
function fmSelect(cls, options, value) {
  const sel = document.createElement('select');
  sel.className = `${cls} select`;
  for (const opt of options) {
    const o = document.createElement('option');
    o.value = typeof opt === 'string' ? opt : opt.value;
    o.textContent = typeof opt === 'string' ? opt : opt.text;
    sel.appendChild(o);
  }
  sel.value = value == null ? '' : String(value);
  return sel;
}
function fmCheck(cls, labelText, checked) {
  const label = document.createElement('label');
  label.className = 'fanout-toggle';
  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.className = cls;
  cb.checked = Boolean(checked);
  const txt = document.createElement('span');
  txt.textContent = labelText;
  label.append(cb, txt);
  return label;
}
/** A RULE the store would 400 on — red. */
function fmHint(cls) {
  const el = document.createElement('small');
  el.className = `pf-hint hint err ${cls}`.trim();
  el.hidden = true;
  return el;
}
/** An explanation, not a rule — same slot, neutral colour (never `err`). */
function fmNote(cls) {
  const el = document.createElement('small');
  el.className = `pf-note hint ${cls}`.trim();
  el.hidden = true;
  return el;
}
function fmMini(cls, text, title) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = `${cls} btn-ghost btn-mini`;
  b.textContent = text;
  if (title) b.title = title;
  return b;
}

/** One port row. `side` is 'in' | 'out'; the two sides carry different fields. */
function buildPortRow(side, port) {
  const p = port || {};
  const row = document.createElement('div');
  row.className = `port-row port-row-${side}`;
  // Unsurfaced sidecar keys (label, description, artifactKind, anything a newer
  // worca ships) ride ALONG so a save can never silently drop them.
  const extra = {};
  for (const [k, v] of Object.entries(p)) if (!PORT_OWN_KEYS.includes(k)) extra[k] = v;
  if (Object.keys(extra).length) row.dataset.extra = JSON.stringify(extra);

  const top = document.createElement('div');
  top.className = 'port-row-top';
  top.append(
    fmField('id', fmInput('pf-id', p.id, { placeholder: 'portId' }), 'pf-f-id'),
    fmField('type', fmSelect('pf-type', PORT_TYPE_OPTIONS, p.type || 'md'), 'pf-f-type'),
  );
  if (side === 'in') {
    // The blank option is "the store's default" (file on a non-void input,
    // nothing on a void one) — NOT the empty string. Without it a void input is
    // unauthorable: the form would always emit as:'file', which the store 400s.
    top.append(fmField('as', fmSelect('pf-as', [{ value: '', text: '— default' }, ...PORT_AS], p.as || ''), 'pf-f-as'));
  } else {
    top.append(
      fmField('when', fmSelect('pf-when', OUTPUT_WHENS, p.when || 'always'), 'pf-f-when'),
      fmField('filename', fmInput('pf-filename', p.filename, { placeholder: '{base}.md' }), 'pf-f-filename'),
      fmField('store', fmSelect('pf-store', PORT_STORES, p.store || 'run'), 'pf-f-store'),
    );
  }
  top.append(
    fmMini('pf-up', '▲', 'Move this port up'),
    fmMini('pf-down', '▼', 'Move this port down'),
    fmMini('pf-remove', '×', 'Remove this port'),
  );
  row.appendChild(top);

  if (side === 'in') {
    const flags = document.createElement('div');
    flags.className = 'port-row-flags';
    // loop coerces required:false in the registry — mirror it so the form never
    // shows a state the store would rewrite under the user.
    flags.append(
      fmCheck('pf-required', 'required', p.required !== false && !p.loop),
      fmCheck('pf-loop', 'loop', p.loop === true),
      fmCheck('pf-expands', 'expands', p.expands === true),
      fmMini('pf-directive-toggle', p.directive ? 'directive ✓' : 'directive', 'Prompt text injected when this port fires'),
    );
    row.appendChild(flags);
    const dirWrap = document.createElement('div');
    dirWrap.className = 'pf-directive-wrap';
    dirWrap.hidden = true;
    const dir = document.createElement('textarea');
    dir.className = 'pf-directive textarea';
    dir.rows = 4;
    dir.spellcheck = false;
    dir.placeholder = 'Markdown appended to the task prompt when this port fires ({path} substituted)';
    dir.value = p.directive || '';
    dirWrap.appendChild(dir);
    row.appendChild(dirWrap);
  }
  row.append(fmHint('pf-hint-row'), fmNote('pf-note-row'));
  syncPortRow(row);
  return row;
}

/** Per-row mirroring of the coercions the registry applies anyway. */
function syncPortRow(row) {
  const loop = row.querySelector('.pf-loop');
  const required = row.querySelector('.pf-required');
  if (loop && required) {
    required.disabled = loop.checked;
    if (loop.checked) required.checked = false;
  }
  const type = row.querySelector('.pf-type').value;
  // A void port carries no payload: hide the two fields the store would 400 on.
  for (const cls of ['.pf-f-filename', '.pf-f-store']) {
    const f = row.querySelector(cls);
    if (f) f.hidden = type === 'void';
  }
}

/**
 * The def a brand-new form row starts from. It PASSES gate 1 as written, which is
 * deliberate: `title` is mandatory (1–120 chars), `layout` must be non-empty and
 * `example` must validate against `data`, so a `{}` starter would open every new
 * row red and read as a bug. Verified against the executed `validateFormDef`.
 */
const BLANK_FORM_DEF = {
  version: 1,
  title: 'New form',
  data: { type: 'object', properties: { summary: { type: 'string', maxLength: 4000 } } },
  answer: { type: 'object', required: ['verdict'], properties: { verdict: { type: 'string', enum: ['yes', 'no'] } } },
  layout: [
    { widget: 'markdown', bind: 'data.summary' },
    { widget: 'select', field: 'verdict', label: 'Verdict' },
  ],
  example: { summary: '' },
};

/**
 * One form row: the id (the KEY of ask.forms, so it lives outside the JSON) and
 * a code editor over the def. `row.dataset.def` holds the LAST successfully
 * parsed def — text that is not JSON has no representation in a JSON payload, so
 * that is what a save carries while the editor text is broken, and `.afm-errors`
 * says so for as long as it is.
 */
function buildFormRow(id, def) {
  const row = document.createElement('div');
  row.className = 'agent-form-row';
  const body = def && typeof def === 'object' && !Array.isArray(def) ? def : BLANK_FORM_DEF;
  row.dataset.def = JSON.stringify(body);

  const head = document.createElement('div');
  head.className = 'afm-head';
  head.append(
    fmField('Form id', fmInput('afm-id', id || '', { placeholder: 'review-mockups' }), 'afm-f-id'),
    fmMini('afm-remove', 'Remove', 'Remove this form'),
  );

  const editor = document.createElement('div');
  editor.className = 'afm-editor';
  const ed = createCodeEditor({
    doc: document,
    value: JSON.stringify(body, null, 2),
    language: 'json',
    rows: 14,
    highlight: scriptHighlight,     // the app's one injected highlighter (C11)
    onInput: () => refreshAgentForm(formHost(row.closest('.agent-form') || row)),
  });
  row.__editor = ed;
  editor.appendChild(ed.el);

  const panes = document.createElement('div');
  panes.className = 'afm-panes';
  const preview = document.createElement('div');
  preview.className = 'afm-preview';
  const projection = document.createElement('pre');
  projection.className = 'afm-projection viewer';
  panes.append(preview, projection);

  row.append(head, editor, fmHint('afm-errors'), panes);
  return row;
}

/** The Forms section (spec §11): a list of the agent's forms and one add button.
 *  No prose — a label, ids, editors and error sentences. */
function buildFormsSection(ask) {
  const sec = document.createElement('div');
  sec.className = 'field agent-forms';
  const label = document.createElement('label');
  label.textContent = 'Forms';
  const list = document.createElement('div');
  list.className = 'agent-forms-list';
  const forms = ask && ask.forms && typeof ask.forms === 'object' ? ask.forms : {};
  for (const [id, def] of Object.entries(forms)) list.appendChild(buildFormRow(id, def));
  sec.append(label, list, fmMini('afm-add', '+ form', 'Add a question form'), fmHint('afm-hint-section'));
  return sec;
}

/** One row back as { id, def }, or null when the row is entirely blank. `def` is
 *  the last good parse (dataset.def), which is also the live text whenever the
 *  text parses. */
function readFormRow(row) {
  const id = row.querySelector('.afm-id').value.trim();
  const text = row.__editor ? row.__editor.getValue() : '';
  let def = null;
  try { def = JSON.parse(text); } catch { def = null; }
  if (def && typeof def === 'object' && !Array.isArray(def)) row.dataset.def = JSON.stringify(def);
  else { try { def = JSON.parse(row.dataset.def || 'null'); } catch { def = null; } }
  if (!id && !def) return null;
  return { id, def };
}

/** Gate 1 over every row, painted per row and once for the section. The SAME
 *  validator the store runs, so an inline error and the store's 422 can never
 *  disagree. */
function refreshFormsSection(host) {
  const sec = host.querySelector('.agent-forms');
  if (!sec) return;
  const rows = [...sec.querySelectorAll('.agent-form-row')];
  const ids = [];
  for (const row of rows) {
    const msgs = [];
    const id = row.querySelector('.afm-id').value.trim();
    ids.push(id);
    if (!id) msgs.push('a form id is required');
    else if (!FORM_ID_RE.test(id)) msgs.push(`form id "${id}" must match ${FORM_ID_RE}`);  // same sentence gate 1 emits
    let def = null;
    let parsed = false;
    try { def = JSON.parse(row.__editor.getValue()); parsed = true; }
    catch (e) { msgs.push(`invalid JSON: ${e.message}`); }
    // P10: the LAST successfully parsed def is what a save carries while the text is
    // broken, so it is refreshed on every good parse — not only when the form is read.
    if (def && typeof def === 'object' && !Array.isArray(def)) row.dataset.def = JSON.stringify(def);
    // `parsed`, not `def !== null`: the literal text `null` parses, and gate 1 is what
    // says "a form is an object". Unparseable text is the only case with no verdict.
    if (parsed) {
      // P1's paths are rendered VERBATIM: layout items are `layout#<n>` (depth-first,
      // 1-based; P1 C11), schema fields are `answer.verdict` / `example.summary`.
      // The store's 422 body carries the same strings, so the inline hint and the
      // server verdict name the same thing. The id was judged above (blank or
      // malformed); passing it here again would print the same sentence twice.
      for (const err of validateFormDef(def).errors) {
        msgs.push(`${err.path ? `${err.path}: ` : ''}${err.message}`);
      }
    }
    fmSetText(row.querySelector('.afm-errors'), msgs.join(' · '));
    paintFormPreview(row, id, def);
  }
  const secMsgs = [];
  if (rows.length > ASK_LIMITS.formsPerAgent) secMsgs.push(`at most ${ASK_LIMITS.formsPerAgent} forms per agent`);
  for (const dup of new Set(ids.filter((v, i) => v && ids.indexOf(v) !== i))) secMsgs.push(`duplicate form id "${dup}"`);
  fmSetText(sec.querySelector('.afm-hint-section'), secMsgs.join(' · '));
}

/**
 * The live preview + the text projection for one row, drawn from the form's own
 * `example` through the SAME renderer a run uses. Rebuilt only when the parsed
 * def actually CHANGED: a keystroke that reformats whitespace must not wipe a
 * half-scrolled preview or a partly-filled control. An unparseable def leaves
 * the last good picture standing — `.afm-errors` is what says the text is broken.
 */
function paintFormPreview(row, id, def) {
  if (def === null) return;                       // unparseable: keep the last good picture
  // One key per (id, def): JSON of the pair needs no separator byte, so nothing
  // here holds an escape an editor could turn into a raw control character.
  const key = JSON.stringify([id, def]);
  if (row.dataset.previewKey === key) return;
  row.dataset.previewKey = key;
  const host = row.querySelector('.afm-preview');
  try { row.__preview?.dispose(); } catch { /* already gone */ }
  row.__preview = null;
  const ask = previewAskFromDef(id || 'form', def);
  try {
    // `fileUrl: previewFileUrl` (always null) + the envelope's empty `files` are
    // what make the file widgets draw P3's `.af-nofile` tile (ruling X14).
    const view = renderAskForm(ask, {
      doc: document, fileUrl: previewFileUrl, readonly: false, values: null, onChange: null,
      // The run's own seams — the ask panel and History pass these same two — so the
      // markdown and code widgets draw what a run draws, not their source text.
      markdown: pageMarkdown, highlight: (el) => hdMarkdown.highlight(el),
    });
    row.__preview = view;
    host.replaceChildren(view.el);
    // The bundle is lazy: repaint once it can render, and only while THIS view is
    // still the row's preview (a later keystroke may already have replaced it).
    bindMarkdownReady().then((ok) => { if (ok && row.__preview === view) view.paintMarkdown(); });
  } catch {
    // A def that passes JSON.parse but not gate 1 can still reach the renderer
    // while the author types. The error line already names every failed rule;
    // the preview simply goes blank rather than throwing the form down.
    host.replaceChildren();
  }
  // No `ref`, so the projection carries no `/answer` reply line (P1 C17) — there
  // is nothing to reply to from an editor.
  let text = '';
  try { text = projectForm(ask); } catch { text = ''; }
  fmSetText(row.querySelector('.afm-projection'), text);
}

/** Destroy every editor (and, from Task 7, every preview) this form owns. A
 *  pending highlight debounce on a detached node is a leak, and `replaceChildren`
 *  detaches silently. */
function disposeAgentForm(root) {
  for (const row of root.querySelectorAll('.agent-form-row')) {
    try { row.__editor?.destroy(); } catch { /* already gone */ }
    try { row.__preview?.dispose(); } catch { /* Task 7; absent until then */ }
  }
}

/** One ports section (head + list + the section-level hint). */
function buildPortsSection(side, ports) {
  const sec = document.createElement('div');
  sec.className = `agent-ports agent-ports-${side}`;
  const head = document.createElement('div');
  head.className = 'agent-ports-head';
  const title = document.createElement('b');
  title.textContent = side === 'in' ? 'INPUTS' : 'OUTPUTS';
  const count = document.createElement('span');
  count.className = 'pf-count hint';
  const add = fmMini(`pf-add-${side}`, side === 'in' ? '+ input' : '+ output');
  head.append(title, add, count);
  sec.appendChild(head);
  const list = document.createElement('div');
  list.className = 'agent-ports-list';
  for (const p of Array.isArray(ports) ? ports : []) {
    // The synthesized `await` gate is engine surface, never editable — and the
    // registry never ships it on a sidecar, so this filter is belt-and-braces.
    if (p && (p.synthetic || p.id === 'await')) continue;
    list.appendChild(buildPortRow(side, p));
  }
  sec.append(list, fmHint('pf-hint-side'));
  return sec;
}

/**
 * Rebuild every hint + the two counters from the form's CURRENT state.
 * Wholesale is the point: a rule can be invalidated by an edit three rows away
 * (a cleared verdict filename invalidates every `when:'blocking'` output), and
 * recomputing the lot is the only formulation that cannot drift. Cost is bounded
 * by 2 × MAX_PORTS_PER_SIDE rows. It may mutate AUTHORED state only through the
 * two coercions the registry applies anyway (loop ⇒ required:false,
 * !asksQuestions ⇒ locked/default:false) and through `hidden`.
 */
function refreshAgentForm(host) {
  const setText = (el, text) => { el.textContent = text; el.hidden = !text; };
  const runner = host.querySelector('.agent-f-runner').value;
  const verdict = host.querySelector('.agent-f-verdict').value.trim();
  const agentMsgs = [];
  if (runner === 'verifier' && !verdict) agentMsgs.push('runnerType "verifier" requires verdict: { filename }');
  if (verdict && BASENAME_BAD(verdict)) agentMsgs.push(`verdict filename "${verdict}" must be a plain basename`);
  // The form ships BOTH controls side by side, so this 400 is one keystroke away.
  const variantOf = host.querySelector('.agent-f-ws-variantof').value.trim();
  if (variantOf && host.querySelector('.agent-f-scope').value !== 'workspace-only') {
    agentMsgs.push('workspaceVariantOf requires scope "workspace-only"');
  }
  for (const side of ['in', 'out']) {
    const sec = host.querySelector(`.agent-ports-${side}`);
    const rows = [...sec.querySelectorAll('.port-row')];
    const label = side === 'in' ? 'inputs' : 'outputs';
    sec.querySelector('.pf-count').textContent = `(${rows.length}/${MAX_PORTS_PER_SIDE})`;
    sec.querySelector(`.pf-add-${side}`).disabled = rows.length >= MAX_PORTS_PER_SIDE;
    const seen = new Set();
    const sideMsgs = [];
    for (const row of rows) {
      syncPortRow(row);
      const id = row.querySelector('.pf-id').value.trim();
      const type = row.querySelector('.pf-type').value;
      const msgs = [];   // rules the store would 400 on
      const notes = [];  // explanations
      if (id === 'await') {
        msgs.push(`${label}: port id "await" is reserved — the engine synthesizes the await gate port on every agent node`);
      } else if (id && !PORT_ID_RE.test(id)) {
        msgs.push(`${label}: bad port id "${id}"`);
      }
      if (id) {
        if (seen.has(id)) sideMsgs.push(`${label}: duplicate port id "${id}"`);
        seen.add(id);
      }
      if (side === 'in') {
        if (row.querySelector('.pf-expands').checked && type !== 'json') {
          msgs.push(`${label}.${id}: expands is only legal on json inputs`);
        }
        // Mirrors readInputs exactly: `file` has no entry in AS_REQUIRES_TYPE,
        // so its rule is "non-void"; every other renderer names a type.
        const as = row.querySelector('.pf-as').value;
        if (as) {
          const need = Object.hasOwn(AS_REQUIRES_TYPE, as) ? AS_REQUIRES_TYPE[as] : null;
          if (need ? type !== need : type === 'void') {
            msgs.push(`${label}.${id}: as "${as}" requires a ${need || 'non-void'} port (got ${type})`);
          }
        }
        if (row.querySelector('.pf-loop').checked) {
          notes.push('loop inputs are optional; a fresh token on this port re-fires the agent');
        }
      } else {
        const when = row.querySelector('.pf-when').value;
        if (when !== 'always' && !verdict) {
          msgs.push(`${label}.${id}: when "${when}" requires the agent to declare verdict: { filename }`);
        } else if (when !== 'always') {
          notes.push('"blocking"/"clean" branch on the verdict file above');
        }
        const fn = row.querySelector('.pf-filename').value.trim();
        if (type !== 'void' && !fn) {
          msgs.push(`${label}.${id}: ${type} outputs require a filename template`);
        } else if (fn) {
          if (BASENAME_BAD(fn)) msgs.push(`${label}.${id}: filename "${fn}" must be a plain basename`);
          const bad = [...fn.matchAll(/\{([^}]*)\}/g)].map((m) => m[1]).filter((t) => !FILENAME_TOKENS.includes(t));
          if (bad.length) msgs.push(`${label}.${id}: filename "${fn}" uses unknown token(s) ${bad.map((t) => `{${t}}`).join(', ')}`);
        }
      }
      setText(row.querySelector('.pf-hint-row'), msgs.join(' · '));
      setText(row.querySelector('.pf-note-row'), notes.join(' · '));
    }
    if (side === 'out') {
      if (!rows.length) sideMsgs.push('at least one output port is required');
      if (runner === 'clarifier' && !rows.some((r) => r.querySelector('.pf-type').value === 'json')) {
        agentMsgs.push('runnerType "clarifier" requires at least one json output port');
      }
    }
    setText(sec.querySelector('.pf-hint-side'), sideMsgs.join(' · '));
  }
  setText(host.querySelector('.pf-hint-agent'), agentMsgs.join(' · '));
  // The two questions sub-flags are meaningless (and normalizeMeta force-clears
  // them) when the agent cannot ask; mirror that.
  const asks = host.querySelector('.agent-f-questions');
  for (const cls of ['.agent-f-questions-locked', '.agent-f-questions-default']) {
    const cb = host.querySelector(cls);
    cb.disabled = !asks.checked;
    if (!asks.checked) cb.checked = false;
  }
  refreshFormsSection(host);
}

/**
 * Build the whole v2 form under `host` from `meta`.
 * @param {HTMLElement} host  a .agent-form element (or a container holding one)
 * @param {object} meta       a v2 sidecar (registry-normalized or a gen draft)
 * @param {{markdown?: string, mockWriterRoles?: string[], registryKeys?: string[]}} [opts]
 */
function agentFormRender(host, meta, opts = {}) {
  const root = formHost(host);
  disposeAgentForm(root);
  const m = meta || {};
  const roles = Array.isArray(opts.mockWriterRoles) ? opts.mockWriterRoles : state.mockWriterRoles;
  const keys = Array.isArray(opts.registryKeys) ? opts.registryKeys : state.agentsList.map((a) => a.key);
  root.dataset.agentKey = m.key || '';
  const extra = {};
  for (const [k, v] of Object.entries(m)) if (!AGENT_OWN_KEYS.includes(k)) extra[k] = v;
  root.dataset.extra = JSON.stringify(extra);

  const frag = document.createDocumentFragment();
  frag.appendChild(fmField('Display name', fmInput('agent-f-name', m.displayName)));
  // A description resolved from the .md frontmatter is computed, not authored:
  // show it as a placeholder, never as a value — pre-filling it would PUT it
  // straight back and freeze the fallback into the sidecar.
  const desc = fmInput('agent-f-desc', m.descriptionDerived ? '' : (m.description || ''));
  if (m.descriptionDerived) desc.placeholder = m.description || '';
  frag.appendChild(fmField('Description', desc));

  const row1 = document.createElement('div');
  row1.className = 'row-2';
  row1.append(
    fmField('Color', fmSelect('agent-f-color', AGENT_COLORS, m.color || 'amber')),
    fmField('Runner type', fmSelect('agent-f-runner', RUNNER_TYPES, m.runnerType || 'producer')),
  );
  const row2 = document.createElement('div');
  row2.className = 'row-2';
  row2.append(
    fmField('Order', fmInput('agent-f-order', m.order != null ? m.order : 99, { type: 'number' })),
    fmField('Verdict filename', fmInput('agent-f-verdict', (m.verdict && m.verdict.filename) || '', {
      placeholder: 'required for verifiers, e.g. review-cycle{cycle}.json',
    })),
  );
  const row3 = document.createElement('div');
  row3.className = 'row-3';
  row3.append(
    fmField('Domain', fmInput('agent-f-domain', m.domain || '', { placeholder: 'general' })),
    fmField('Scope', fmSelect('agent-f-scope', AGENT_SCOPES, m.scope || 'project')),
    fmField('Icon (SVG path)', fmInput('agent-f-icon', m.icon || '', { placeholder: '<path d="…"/>' })),
  );
  frag.append(row1, row2, row3, fmHint('pf-hint-agent'));
  frag.append(buildPortsSection('in', m.inputs), buildPortsSection('out', m.outputs));

  const caps = document.createElement('div');
  caps.className = 'field agent-caps';
  const capsLabel = document.createElement('label');
  capsLabel.textContent = 'Capabilities';
  caps.append(
    capsLabel,
    fmCheck('agent-f-fanout', 'Research fan-out', m.fanOut),
    fmCheck('agent-f-questions', 'Asks questions', m.asksQuestions),
    fmCheck('agent-f-questions-locked', 'Questions locked', m.questionsLocked),
    fmCheck('agent-f-questions-default', 'Questions on by default', m.questionsDefault),
    fmCheck('agent-f-wantsrequest', 'Carries the original request', m.wantsRequest === true),
    fmCheck('agent-f-placeable', 'Placeable on a canvas', m.placeable !== false),
  );
  frag.appendChild(caps);
  // sideEffect is a three-way value (agent-meta.mjs SIDE_EFFECTS): a checkbox could only write
  // 'code' and would silently drop 'memory' on the next save.
  frag.appendChild(fmField('Side effect', fmSelect('agent-f-sideeffect', [
    { value: '', text: 'none — writes only its output ports' },
    { value: 'code', text: 'code — edits the worktree (implementer tool set)' },
    { value: 'memory', text: 'memory — edits worca memory only (no Bash)' },
  ], m.sideEffect || '')));

  const row4 = document.createElement('div');
  row4.className = 'row-2';
  row4.append(
    fmField('Mock role', fmSelect('agent-f-mockrole', [{ value: '', text: 'auto' }, ...roles.map((r) => ({ value: r, text: r }))], m.mockRole || '')),
    fmField('Requires skills', fmInput('agent-f-skills', (m.requiresSkills || []).join(', '), { placeholder: 'skill-one, skill-two' })),
  );
  const hints = document.createElement('textarea');
  hints.className = 'agent-f-hints textarea';
  hints.rows = 3;
  hints.spellcheck = false;
  hints.value = m.promptHints || '';
  frag.append(row4, fmField('Prompt hints', hints));

  const ws = document.createElement('div');
  ws.className = 'field agent-workspace';
  // NB: the heading local is `wsHeadLabel` ON PURPOSE. Do NOT shorten it to the
  // ws + Label form: that token named the removed WS-status indicator. The
  // plain-text guard that kept it out of app.js is no longer tested, so keep
  // the token out by hand.
  const wsHeadLabel = document.createElement('label');
  wsHeadLabel.textContent = 'Workspace runs';
  const variant = fmInput('agent-f-ws-variantof', m.workspaceVariantOf || '', { placeholder: 'agent key' });
  variant.setAttribute('list', 'agent-f-ws-keys');
  const datalist = document.createElement('datalist');
  datalist.id = 'agent-f-ws-keys';
  for (const k of keys) {
    const o = document.createElement('option');
    o.value = k;
    datalist.appendChild(o);
  }
  const wsRow = document.createElement('div');
  wsRow.className = 'row-2';
  wsRow.append(
    fmField('Strategy', fmSelect('agent-f-ws-strategy', ['', ...WORKSPACE_STRATEGIES], m.workspaceStrategy || '')),
    fmField('Variant of', variant),
  );
  ws.append(wsHeadLabel, fmCheck('agent-f-ws-fanout', 'Force fan-out on workspace runs', m.workspaceFanOut === true), wsRow, datalist);
  frag.appendChild(ws);
  frag.appendChild(buildFormsSection(m.ask));

  const md = document.createElement('textarea');
  md.className = 'agent-f-md textarea';
  md.rows = 16;
  md.spellcheck = false;
  md.value = typeof opts.markdown === 'string' ? opts.markdown : '';
  frag.appendChild(fmField('System prompt (markdown)', md));

  // Interface mode (docs/ui-levels.md): the Agents page is expert, but the AI wizard is reachable
  // from the Composer at advanced — there the drafted form is just what a person can judge (name,
  // description, the prompt itself). Ports, runner type and the rest are the builder's draft, kept
  // and saved as drafted; expert shows all of it.
  for (const child of frag.children) {
    if (!child.querySelector('.agent-f-name, .agent-f-desc, .agent-f-md')) tagLevel(child, 'expert');
  }

  root.replaceChildren(frag);
  refreshAgentForm(root);
  bindAgentForm(root);
}

/** ONE delegated click + one change + one input listener per host — rows come and go. */
function bindAgentForm(host) {
  if (host.dataset.bound === '1') return;
  host.dataset.bound = '1';
  host.addEventListener('click', (ev) => {
    const t = ev.target;
    if (!t || !t.closest) return;
    const add = t.closest('.pf-add-in, .pf-add-out');
    if (add) {
      if (add.disabled) return;
      const side = add.classList.contains('pf-add-in') ? 'in' : 'out';
      host.querySelector(`.agent-ports-${side} .agent-ports-list`).appendChild(buildPortRow(side, null));
      refreshAgentForm(host);
      return;
    }
    if (t.closest('.afm-add')) {
      host.querySelector('.agent-forms .agent-forms-list').appendChild(buildFormRow('', null));
      refreshAgentForm(host);
      return;
    }
    const formRow = t.closest('.agent-form-row');
    if (formRow && t.closest('.afm-remove')) {
      try { formRow.__editor?.destroy(); } catch { /* already gone */ }
      try { formRow.__preview?.dispose(); } catch { /* Task 7 */ }
      formRow.remove();
      refreshAgentForm(host);
      return;
    }
    const row = t.closest('.port-row');
    if (!row) return;
    if (t.closest('.pf-remove')) { row.remove(); refreshAgentForm(host); return; }
    if (t.closest('.pf-up')) {
      if (row.previousElementSibling) row.parentNode.insertBefore(row, row.previousElementSibling);
      refreshAgentForm(host);
      return;
    }
    if (t.closest('.pf-down')) {
      if (row.nextElementSibling) row.parentNode.insertBefore(row.nextElementSibling, row);
      refreshAgentForm(host);
      return;
    }
    if (t.closest('.pf-directive-toggle')) {
      const wrap = row.querySelector('.pf-directive-wrap');
      wrap.hidden = !wrap.hidden;
    }
  });
  // One handler for every field: the hint set is a pure function of the form.
  host.addEventListener('change', () => refreshAgentForm(host));
  // `change` on a text input only fires on blur; the id/filename/verdict hints
  // must track typing, so mirror it on input.
  host.addEventListener('input', (ev) => {
    if (ev.target && ev.target.matches && ev.target.matches('.pf-id, .pf-filename, .agent-f-verdict, .afm-id')) {
      refreshAgentForm(host);
    }
  });
}

function readPortRow(row, side) {
  const extra = readExtra(row);
  const type = row.querySelector('.pf-type').value;
  const port = { ...extra, id: row.querySelector('.pf-id').value.trim(), type };
  if (side === 'in') {
    const loop = row.querySelector('.pf-loop').checked;
    port.required = loop ? false : row.querySelector('.pf-required').checked; // loop implies optional
    if (loop) port.loop = true;
    if (row.querySelector('.pf-expands').checked) port.expands = true;
    // Blank means "let the store default it" — which is how a void input is
    // authored. An explicitly chosen value is emitted as chosen, even when the
    // hint says the store will reject it: the client never pre-empts the store.
    const as = row.querySelector('.pf-as').value;
    if (as) port.as = as;
    const directive = row.querySelector('.pf-directive').value;
    if (directive.trim()) port.directive = directive;
  } else {
    port.when = row.querySelector('.pf-when').value;
    // A void port carries no payload — the store 400s on either field.
    if (type !== 'void') {
      const filename = row.querySelector('.pf-filename').value.trim();
      if (filename) port.filename = filename;
      port.store = row.querySelector('.pf-store').value;
    }
  }
  return port;
}

/** Read the form back into { meta, markdown } — a v2 sidecar, nothing else. */
function agentFormRead(host) {
  const root = formHost(host);
  const extra = readExtra(root);
  const val = (cls) => root.querySelector(`.${cls}`).value;
  const on = (cls) => root.querySelector(`.${cls}`).checked;
  // These five are written on EVERY save. agent-store merges {...existing, ...raw},
  // so a field the form omits keeps its stored value — an omitted `fanOut: false`
  // could never turn fan-out off, and an omitted `description` would freeze a
  // derived blurb into the sidecar.
  const meta = {
    ...extra,
    metaVersion: 2,
    displayName: val('agent-f-name').trim(),
    description: val('agent-f-desc').trim(),
    color: val('agent-f-color'),
    runnerType: val('agent-f-runner'),
    fanOut: on('agent-f-fanout'),
    asksQuestions: on('agent-f-questions'),
    questionsLocked: on('agent-f-questions-locked'),
    questionsDefault: on('agent-f-questions-default'),
    inputs: [...root.querySelectorAll('.agent-ports-in .port-row')].map((r) => readPortRow(r, 'in')),
    outputs: [...root.querySelectorAll('.agent-ports-out .port-row')].map((r) => readPortRow(r, 'out')),
  };
  // A blank Order reads back as NaN, not 0: `Number('')` is 0, which
  // agent-store's Number.isFinite check accepts and which silently sorts the
  // agent ahead of every builtin.
  const order = Number(val('agent-f-order').trim() === '' ? NaN : val('agent-f-order'));
  if (Number.isFinite(order)) meta.order = order;
  if (root.dataset.agentKey) meta.key = root.dataset.agentKey;
  // Everything below is OPTIONAL: absent when off, never `false`/`''`. The
  // schema reads presence, and an explicit falsy value is a different (invalid)
  // thing — `placeable: false` is the one value worth writing. Task 13 makes
  // this set CLEARABLE by having the store replace it on a metaVersion-2 PUT.
  const verdict = val('agent-f-verdict').trim();
  if (verdict) meta.verdict = { filename: verdict };
  const domain = val('agent-f-domain').trim();
  if (domain) meta.domain = domain;
  if (val('agent-f-scope') === 'workspace-only') meta.scope = 'workspace-only';
  const icon = val('agent-f-icon').trim();
  if (icon) meta.icon = icon;
  const sideEffect = val('agent-f-sideeffect');
  if (sideEffect) meta.sideEffect = sideEffect;
  const mockRole = val('agent-f-mockrole');
  if (mockRole) meta.mockRole = mockRole;
  if (on('agent-f-wantsrequest')) meta.wantsRequest = true;
  if (on('agent-f-ws-fanout')) meta.workspaceFanOut = true;
  const strategy = val('agent-f-ws-strategy');
  if (strategy) meta.workspaceStrategy = strategy;
  const variantOf = val('agent-f-ws-variantof').trim();
  if (variantOf) meta.workspaceVariantOf = variantOf;
  const skills = val('agent-f-skills').split(',').map((s) => s.trim()).filter(Boolean);
  if (skills.length) meta.requiresSkills = skills;
  const promptHints = val('agent-f-hints');
  if (promptHints.trim()) meta.promptHints = promptHints;
  if (!on('agent-f-placeable')) meta.placeable = false;
  // ask forms (spec §11). Omitting `ask` on a metaVersion-2 PUT is what CLEARS
  // them: the store lists `ask` in V2_CLEARABLE, so a complete v2 save REPLACES
  // this surface instead of merging into it.
  const forms = {};
  const problems = [];
  const problemFields = [];   // [id input, rule] per offending row, for the editor's field errors
  for (const row of root.querySelectorAll('.agent-form-row')) {
    const read = readFormRow(row);
    if (!read || !read.def) continue;
    // Two rules the store can never see, because the offending row is not in the
    // JSON payload at all: a row with NO id (it would simply vanish on Save, with
    // whatever the author typed into it — decision P21) and two rows with one id
    // (the later one silently replaced the stored form — decision P20). Keep the
    // first of a clash, name each rule once; both save paths refuse while
    // `problems` is non-empty.
    if (!read.id) {
      if (!problems.includes('a form id is required')) problems.push('a form id is required');
      problemFields.push([row.querySelector('.afm-id'), 'a form id is required']);
      continue;
    }
    if (Object.hasOwn(forms, read.id)) {
      problems.push(`duplicate form id "${read.id}"`);
      problemFields.push([row.querySelector('.afm-id'), `duplicate form id "${read.id}"`]);
      continue;
    }
    forms[read.id] = read.def;
  }
  if (Object.keys(forms).length) meta.ask = { forms };
  return { meta, markdown: root.querySelector('.agent-f-md').value, problems, problemFields };
}

async function openAgentEdit(card, a) {
  const detail = card.querySelector('.agent-detail');
  const head = card.querySelector('.agent-head');
  if (detail.hidden) { detail.hidden = false; head.setAttribute('aria-expanded', 'true'); }
  const full = await fetchAgentFull(a.key);
  if (!full) { setAgentsMsg('Could not load the agent.', 'err'); return; }
  const pane = card.querySelector('.agent-edit-pane');
  agentFormRender(pane, full.meta, {
    markdown: full.markdown,
    mockWriterRoles: state.mockWriterRoles,
    registryKeys: state.agentsList.map((x) => x.key).filter((k) => k !== a.key),
  });
  pane.hidden = false;
  pane.querySelector('.agent-edit-cancel').onclick = () => { disposeAgentForm(pane); pane.hidden = true; };
  // #555: a refusal is a card alert directly above this row of buttons.
  pane.querySelector('.agent-edit-save').closest('.actions')?.setAttribute('data-card-actions', '');
  pane.querySelector('.agent-edit-save').onclick = () => saveAgentEdit(card, a, pane);
}

// #555: Save shows busy → "Saved"; a client rule is a field error on the offending input, a
// server refusal a card alert above the buttons; success closes the pane and raises a toast.
async function saveAgentEdit(card, a, pane) {
  clearFieldErrors(pane);
  cardAlert(pane, null);
  const { problems, problemFields, ...body } = agentFormRead(pane);
  // The rules the store cannot see (decisions P20, P21): two rows with one form id, a row with none.
  if (problems.length) {
    problemFields.forEach(([input, rule], i) => fieldError(input, rule, { focus: i === 0 }));
    return;
  }
  const r = await withButton(pane.querySelector('.agent-edit-save'), async () => {
    const res = await fetch(`/api/agents/${encodeURIComponent(a.key)}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const data = await safeJson(res);
    if (!res.ok) return { ok: false, error: data.error || `HTTP ${res.status}` };
    return { ok: true, data };
  });
  if (r.skipped) return;
  if (!r.ok) { cardAlert(pane, { title: 'Not saved', detail: r.error }); return; }
  const { data } = r;
  disposeAgentForm(pane);   // the editors' highlight debounce must not outlive a pane loadAgentsView() replaces
  pane.hidden = true;
  invalidateAgentCaches();
  // The save SUCCEEDED. `updatedVariants` is the workspace variants this port
  // change was propagated into (a success); `warnings` names the saved pipelines
  // it stranded — the run gate refuses those until they are re-wired.
  const warns = Array.isArray(data.warnings) ? data.warnings : [];
  const variants = Array.isArray(data.updatedVariants) ? data.updatedVariants : [];
  const parts = ['Agent saved.'];
  if (variants.length) parts.push(`Workspace variants updated: ${variants.join(', ')}.`);
  parts.push(...warns);
  setAgentsMsg(parts.join(' '), warns.length ? 'warn' : 'ok');
  await loadAgentsView();
}

if (el.agentsList) {
  el.agentsList.addEventListener('click', (e) => {
    const card = e.target.closest && e.target.closest('.agent-card');
    if (!card) return;
    const a = state.agentsList.find((x) => x.key === card.dataset.agentKey);
    if (e.target.closest('.agent-delete')) { e.stopPropagation(); if (a) deleteAgentCard(card, a); return; }
    if (e.target.closest('.agent-duplicate')) { e.stopPropagation(); if (a) duplicateAgentCard(a); return; }
    if (e.target.closest('.agent-edit')) { e.stopPropagation(); if (a) openAgentEdit(card, a); return; }
    if (e.target.closest('.agent-head')) toggleAgentDetail(card);
  });
  // Keyboard access for the role=button header (mirrors the ws-head pattern).
  el.agentsList.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
    const head = e.target.closest && e.target.closest('.agent-head');
    if (!head) return;
    e.preventDefault();
    toggleAgentDetail(head.closest('.agent-card'));
  });
}
if (el.agentCreateBtn) el.agentCreateBtn.addEventListener('click', () => { location.hash = 'agent-create'; });

// Test hook (mirrors window.__ws).
if (typeof window !== 'undefined') {
  window.__agents = { loadAgentsList, loadAgentsView, renderAgentsList, buildAgentCard, deleteAgentCard,
    duplicateAgentCard, agentFormRender, agentFormRead, bindAgentForm, openAgentEdit, toggleAgentDetail,
    buildFormsSection, buildFormRow, readFormRow, disposeAgentForm, paintAgentFormsView };
}

// ---------------------------------------------------------------------------
// Projects management view (sidebar peer of Workspaces / Agents).
// Read-only list of {name, path, exists}; add via native picker, delete via a
// custom confirm modal. Shares state.projects with the New-pipeline dropdown.
// ---------------------------------------------------------------------------

// The one bin/trash icon used across the UI (mirrors app.js:1775). Static markup
// -> safe to assign via innerHTML.
const TRASH_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 7h16M9 7V5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2M6 7l1 13a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1l1-13M10 11v6M14 11v6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function setProjectsMsg(text, kind) {
  reportStatus(el.projectsMsg, 'form-msg', text, kind);
}

// Folder basename, tolerant of trailing slashes and either separator.
function basenameOf(p) {
  return String(p || '').replace(/[\\/]+$/, '').split(/[\\/]/).pop() || '';
}

// Thin wrapper over the native picker endpoint; never throws. `multiple` asks for a
// multi-select dialog where the OS has one (the reply then also carries `paths`).
async function pickFolder(purpose = 'project', { multiple = false } = {}) {
  try {
    const body = multiple ? { purpose, multiple: true } : { purpose };
    const res = await fetch('/api/fs/pick-folder', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    return await safeJson(res); // {status:'picked',path,paths?} | {status:'canceled'} | {status:'unsupported'} | {status:'busy'}
  } catch {
    return { status: 'unsupported' };
  }
}

// Every folder a 'picked' reply names: `paths` from a multi-select dialog, else the one `path`.
function pickedPaths(data) {
  if (data && Array.isArray(data.paths) && data.paths.length) return data.paths.filter((p) => typeof p === 'string' && p);
  return data && typeof data.path === 'string' && data.path ? [data.path] : [];
}

// One picked folder goes to the caller's single-folder form; several go to the review list.
function routePickedFolders(paths, { single, many }) {
  const list = [...new Set((paths || []).filter(Boolean))];
  if (list.length === 1) single(list[0]);
  else if (list.length > 1) many(list);
}

// #projects entry: refetch the registry, paint the list, then route the detail half of the hash
// (#projects/<key>[/memory[/<name>]]). In-view hops (list <-> page, tab <-> tab, the hashchange
// echo of a route the page itself wrote) skip the fetch — showView calls routeProjectDetail
// directly for those. The user may leave the view or hop within it while /api/projects is in
// flight: a superseded entry paints nothing (loadHistoryView's historyLoadToken idiom), a reply
// landing behind another view paints nothing, and the route half follows the hash as it is NOW,
// not the param captured at entry — an in-view hop already routed that one, and re-routing the
// same key is a no-op.
let projectsLoadToken = 0;
async function loadProjectsView() {
  const token = ++projectsLoadToken;
  await loadProjects();      // refresh shared state.projects from /api/projects
  if (token !== projectsLoadToken || currentShownView !== 'projects') return;
  renderProjectsList();
  const [view, param] = parseHash();
  if (view === 'projects') routeProjectDetail(param, { instant: true });
}

// A projects-changed frame while the page is open: rebuild the list under the user and keep
// the open page — unless its project left the registry, which closes it with a note. The
// header repaints from the NEW row (`exists` can flip). showView('projects', '') is called
// directly (not via the hash) so its own setProjectsMsg('') runs BEFORE the note is set.
// No entry token here: a frame reply that outlived a view entry must not cancel that entry's
// route, and everything below reads live state (never the reply), so a late one is harmless.
async function refreshProjectsPage() {
  await loadProjects();
  if (currentShownView !== 'projects') return;
  renderProjectsList();
  if (!projDetail) return;
  const p = projectByKey(projDetail.key);
  if (p) { paintProjHeader(projDetail.screen, p); refreshProjOverview(); return; }
  const name = projDetail.name;
  showView('projects', '');
  setProjectsMsg(`project "${name}" was removed`, 'err');
}

const CHEVRON_RIGHT_SVG =
  '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M9 6l6 6-6 6" stroke-linecap="round" stroke-linejoin="round"></path></svg>';

function buildProjectRow(p) {
  const item = document.createElement('div');
  item.className = 'pl-item';
  item.dataset.name = p.name;
  if (p.key) item.dataset.key = p.key;

  const row = document.createElement('div');
  row.className = 'pl-row';

  const main = document.createElement('div');
  main.className = 'pl-main';
  const name = document.createElement('div');
  name.className = 'pl-name';
  name.textContent = p.name;
  if (!p.exists) {
    const miss = document.createElement('span');
    miss.className = 'proj-missing';
    miss.textContent = 'missing';
    name.append(' ', miss);
  }
  const path = document.createElement('div');
  path.className = 'proj-path';
  appendBreakable(path, p.path);   // a narrow column breaks it after a /, not mid-name
  path.title = p.path;
  main.append(name, path);
  row.appendChild(main);
  // #527 / design 2026-10-01: the sync bar's own column (branch | origin status | action). A keyed
  // row's bar is always there; paintSyncChips fills it, and hides it only for a project the
  // status read skips (a folder that is gone).
  const sync = document.createElement('div');
  sync.className = 'pl-sync';
  if (p.key) {
    const syncSlot = document.createElement('div');
    syncSlot.className = 'proj-sync';
    syncSlot.dataset.key = p.key;
    syncSlot.hidden = true;
    sync.appendChild(syncSlot);
  }
  row.appendChild(sync);

  // The team column: two one-line chips (metrics, policy) that paintProjectTmCells /
  // paintProjectPolicyCells fill from the scopes payloads. Status only — every control and
  // every sentence behind a status lives on the project page's Team tab, so the row stays a
  // row and the whole of it opens the page. Team setup is expert (docs/ui-levels.md).
  const team = document.createElement('div');
  team.className = 'pl-team';
  tagLevel(team, 'expert');
  team.dataset.key = p.key;
  const tmChip = document.createElement('span'); tmChip.className = 'pl-team-item pl-tm';
  const tpChip = document.createElement('span'); tpChip.className = 'pl-team-item pl-tp';
  team.append(tmChip, tpChip);
  row.appendChild(team);
  // A keyed row IS the control (click / Enter / Space open the project page — the History
  // card's .hist-head idiom) and carries the chevron. A keyless row (a project registered
  // outside worca's store) has no page: no role, no chevron, default cursor.
  if (p.key) {
    row.setAttribute('role', 'button');
    row.tabIndex = 0;
    row.setAttribute('aria-label', `Open ${p.name}`);
    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'proj-open';
    open.setAttribute('aria-label', 'Open project details');
    open.innerHTML = CHEVRON_RIGHT_SVG;   // static markup
    row.appendChild(open);
  }
  item.appendChild(row);
  return item;
}

// ---- Sync chips (#527, plan §6.7): filled in place, like the team-metrics cells --------------
// Render creates empty slots; paintSyncChips() fills them from state.syncChips (no fetch);
// refreshSyncChips() is a coalesced local status read. They never refresh by polling.

function syncProjectName(key) {
  const p = state.projects.find((x) => x && x.key === key);
  return (p && p.name) || key;
}
function projBehindCount() {
  return Object.values(state.syncChips || {}).filter((b) => b && listRowModel(b).action === 'sync').length;
}
function paintSyncChips() {
  for (const slot of document.querySelectorAll('.proj-sync[data-key]')) paintProjSyncBar(slot);
  paintProjFilters();
  if (el.projectsSyncAll && !el.projectsSyncAll.classList.contains('busy')) {
    const behind = projBehindCount();
    el.projectsSyncAll.hidden = !behind;
    el.projectsSyncAll.textContent = `Sync all (${behind})`;
  }
  paintSyncChecked();
  for (const item of document.querySelectorAll('.ws-item[data-workspace-id]')) paintWsSyncItem(item);
  paintPdBranchCards();
}
/** A short name for the strip: "ACME Web" in workspace "ACME" reads "Web". */
function wsShortName(full, wsName) {
  const pre = `${wsName || ''} `;
  return wsName && full.toLowerCase().startsWith(pre.toLowerCase()) && full.length > pre.length ? full.slice(pre.length) : full;
}
function wsIcon(kind, size) {
  const span = document.createElement('span');
  span.className = 'ws-icon';
  if (OUTCOME_ICONS[kind]) span.innerHTML = `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${OUTCOME_ICONS[kind]}</svg>`;   // static markup
  return span;
}
function paintWsSyncItem(item) {
  const w = state.workspaces.find((x) => x && x.id === item.dataset.workspaceId);
  if (!w) return;
  const keys = Array.isArray(w.projectKeys) ? w.projectKeys : [];
  const rows = keys.map((k, i) => {
    const b = state.syncChips[k];
    const name = syncProjectName(k) === k && Array.isArray(w.projectPaths) ? wsBasename(w.projectPaths[i]) : syncProjectName(k);
    return { key: k, name, short: wsShortName(name, w.name), branch: (b && b.base) || '', m: b === undefined ? { icon: 'none', tone: 'muted', label: 'Checking…', hint: '', action: null, state: 'none' } : listRowModel(b) };
  });
  const roll = wsRollupModel(rows.map((r) => r.m));
  const rollEl = item.querySelector('.ws-rollup');
  if (rollEl) { rollEl.className = `ws-rollup tone-${roll.tone}`; rollEl.querySelector('.ws-rollup-txt').textContent = roll.text; }
  const strip = item.querySelector('.ws-strip-members');
  if (strip) {
    strip.replaceChildren(...rows.map((r) => {
      const s = document.createElement('span');
      s.className = `ws-strip-member tone-${r.m.tone}`;
      s.title = `${r.name}: ${r.m.label}`;
      const nm = document.createElement('span'); nm.className = 'ws-strip-name'; nm.textContent = r.short;
      s.append(wsIcon(r.m.icon, 14), nm);
      return s;
    }));
  }
  const behind = rows.filter((r) => r.m.action === 'sync').map((r) => r.key);
  const syncAll = item.querySelector('.ws-sync-all');
  if (syncAll && !syncAll.classList.contains('busy')) {
    syncAll.hidden = !behind.length;
    syncAll.textContent = `Sync all (${behind.length})`;
    syncAll.onclick = async (e) => {
      e.stopPropagation();
      syncAll.disabled = true; syncAll.classList.add('busy');
      await syncBehindProjects(behind);
      syncAll.disabled = false; syncAll.classList.remove('busy');
      paintWsSyncItem(item);
    };
  }
  const open = wsTableOpen.has(w.id) ? wsTableOpen.get(w.id) : rows.some((r) => r.m.state === 'diverged');
  const toggle = item.querySelector('.ws-toggle');
  const table = item.querySelector('.ws-table');
  if (toggle) {
    toggle.setAttribute('aria-expanded', String(open));
    toggle.replaceChildren(open ? 'Hide projects' : `Show ${rows.length} project${rows.length === 1 ? '' : 's'}`, wsIcon(open ? 'chevUp' : 'chevDown', 14));
    toggle.onclick = (e) => { e.stopPropagation(); wsTableOpen.set(w.id, !open); paintWsSyncItem(item); };
  }
  if (!table) return;
  table.hidden = !open;
  if (!open) return;
  table.replaceChildren(...rows.map((r) => {
    const tr = document.createElement('div');
    tr.className = `ws-trow tone-${r.m.tone}`;
    tr.dataset.key = r.key;
    const nm = document.createElement('span'); nm.className = 'ws-tname'; nm.textContent = r.name;
    const c = syncRowCells(r.key, r.m, r.branch, r.name);
    tr.append(c.icon, nm, c.branch, c.status, c.action);
    return tr;
  }));
}
/** The cells of a Workspaces table sync row: icon, branch, status + hint, and the one action Worca
 *  can take — Sync (behind), Details… (diverged), Retry (offline). The Projects list draws its own
 *  bar (paintProjSyncBar). */
function syncRowCells(key, m, branchName, name) {
  const branch = document.createElement('span'); branch.className = 'ws-tbranch';
  if (branchName) { branch.append(wsIcon('branch', 14)); const t = document.createElement('span'); t.textContent = branchName; branch.append(t); }
  const status = document.createElement('span'); status.className = 'ws-tstatus';
  const lab = document.createElement('span'); lab.className = 'ws-tlabel'; lab.textContent = m.label;
  status.append(lab);
  if (m.hint) { const hint = document.createElement('span'); hint.className = 'ws-thint'; hint.textContent = m.hint; status.append(hint); }
  const action = document.createElement('span'); action.className = 'ws-tact';
  if (m.action) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = `btn btn-mini ws-tbtn ws-tbtn-${m.action}`;
    btn.textContent = m.action === 'details' ? 'Details…' : m.action === 'retry' ? 'Retry' : 'Sync';
    btn.dataset.syncKey = key;
    btn.setAttribute('aria-label', `${btn.textContent.replace('…', '')} ${name}`);
    btn.addEventListener('click', (e) => {
      e.stopPropagation();   // a workspace row opens its page on click
      if (m.action === 'details') void openChipSyncDialog(key, btn);
      else void syncChipNow(key, btn);
    });
    action.append(btn);
  }
  return { icon: wsIcon(m.icon, 18), branch, status, action };
}

// ---- The Projects sync bar (design 2026-10-01): branch | origin status | action, one object
// tinted by state (projectBarModel). Every bar has the same inner columns, so Sync, Retry and
// Review… line up down the list. Text only ever via textContent.

/** Text that is never cut: it may break after / _ or -, and nowhere else unless it must. */
function appendBreakable(node, text) {
  for (const piece of String(text).split(/(?<=[/_-])/)) {
    node.append(piece);
    if (/[/_-]$/.test(piece)) node.append(document.createElement('wbr'));
  }
  return node;
}
/** A branch name never ends in "…" (design 2026-10-01). */
function projBranchName(name) {
  return appendBreakable(Object.assign(document.createElement('span'), { className: 'ps-bname' }), name);
}
// Keys whose row Sync / Retry is in flight: a repaint under it keeps the spinner.
const projSyncBusy = new Set();
async function projSyncNow(key) {
  if (projSyncBusy.has(key)) return;
  projSyncBusy.add(key);
  const repaint = () => {
    const slot = document.querySelector(`.proj-sync[data-key="${cssEscape(key)}"]`);
    if (slot) paintProjSyncBar(slot);
    return slot;
  };
  repaint();
  let synced = false;
  try { await postProjectSync(key); synced = true; } catch (e) {   // the bar keeps its last state
    notify({ tone: 'err', title: 'Sync failed', detail: e.message, key: `sync-${key}` });
  }
  projSyncBusy.delete(key);
  const slot = repaint();
  if (synced && slot) slot.querySelector('.ps-pill')?.classList.add('ps-flash');
  // Keyboard focus was on the button the repaint replaced: hand it to the new one, else the row.
  if (slot && document.activeElement === document.body) (slot.querySelector('.ps-btn') || slot.closest('.pl-row'))?.focus();
}
function paintProjSyncBar(slot) {
  const key = slot.dataset.key;
  const b = state.syncChips[key];
  // No answer after the first read: the status read skips a folder that is gone.
  if (b === undefined && syncChipsLoaded) { slot.hidden = true; slot.className = 'proj-sync'; slot.replaceChildren(); return; }
  const m = projectBarModel(b);
  slot.hidden = false;
  slot.className = `proj-sync tone-${m.tone}`;
  if (m.tone === 'none') {
    const empty = document.createElement('div');
    empty.className = 'ps-empty';
    const what = document.createElement('b');
    what.append(wsIcon(m.icon, 15), m.label);
    empty.append(what, m.hint);
    slot.replaceChildren(empty);
    return;
  }
  const branch = document.createElement('div');
  branch.className = 'ps-branch';
  if (b && b.base) {
    const line = document.createElement('div');
    line.className = 'ps-bline';
    line.title = b.base;
    line.append(wsIcon('branch', 15), projBranchName(b.base));
    branch.append(line);
    if (m.vs) {
      const vs = document.createElement('div');
      vs.className = 'ps-vs';
      const code = document.createElement('code');
      code.textContent = m.vs;
      vs.append('vs ', code);
      branch.append(vs);
    }
  } else {
    branch.append(Object.assign(document.createElement('span'), { className: 'ps-bnone', textContent: '—' }));
  }
  const status = document.createElement('div');
  status.className = 'ps-status';
  const pill = document.createElement('span');
  pill.className = 'ps-pill';
  const icon = wsIcon(m.icon, 15);
  if (m.icon === 'spin') icon.classList.add('ps-spin');
  pill.append(icon, Object.assign(document.createElement('span'), { className: 'ps-label', textContent: m.label }));
  status.append(pill);
  if (m.hint) status.append(Object.assign(document.createElement('div'), { className: 'ps-hint', textContent: m.hint }));
  const action = document.createElement('div');
  action.className = 'ps-act';
  if (m.action) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn btn-mini ps-btn';
    btn.dataset.syncKey = key;
    btn.setAttribute('aria-label', `${m.actionLabel.replace('…', '')} ${syncProjectName(key)}`);
    if (projSyncBusy.has(key)) {
      btn.disabled = true;
      btn.classList.add('busy');
      btn.append(wsIcon('spin', 14), m.action === 'retry' ? 'Retrying' : 'Syncing');
    } else {
      btn.textContent = m.actionLabel;
    }
    btn.addEventListener('click', (e) => {
      e.stopPropagation();   // the row opens its page on click
      if (m.action === 'details') void openChipSyncDialog(key, btn);
      else void projSyncNow(key);
    });
    action.append(btn);
  }
  slot.replaceChildren(branch, status, action);
}

// The head's counts double as filters (design 2026-10-01). A chip shows only while its state has a
// project; a filter whose last project leaves goes back to All. Rows without an answer count
// toward All only.
const PROJ_FILTERS = [
  ['behind', 'Behind', 'blue'], ['diverged', 'Diverged', 'amber'], ['dirty', 'Uncommitted', 'peach'],
  ['ok', 'Up to date', 'green'], ['offline', 'Offline', 'grey'], ['local', 'Local only', 'grey'],
];
let projFilter = 'all';
function paintProjFilters() {
  const card = el.projectsList && el.projectsList.querySelector('.proj-card');
  if (!card) return;
  const items = [...card.querySelectorAll('.pl-item')];
  const groups = items.map((it) => {
    const b = it.dataset.key ? state.syncChips[it.dataset.key] : undefined;
    return b === undefined ? null : projectBarModel(b).group;
  });
  const counts = {};
  for (const g of groups) if (g) counts[g] = (counts[g] || 0) + 1;
  if (projFilter !== 'all' && !counts[projFilter]) projFilter = 'all';
  const defs = PROJ_FILTERS.filter(([k]) => counts[k]);
  const host = card.querySelector('.proj-filters');
  host.hidden = !defs.length;
  host.replaceChildren(...[['all', 'All', '']].concat(defs).map(([k, label, dot]) => {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'proj-fchip';
    chip.dataset.filter = k;
    chip.setAttribute('aria-pressed', String(projFilter === k));
    if (dot) chip.append(Object.assign(document.createElement('span'), { className: `proj-fdot ${dot}` }));
    chip.append(`${label} `, Object.assign(document.createElement('span'), { className: 'n', textContent: String(k === 'all' ? items.length : counts[k]) }));
    chip.addEventListener('click', () => {
      projFilter = k;
      paintProjFilters();
      host.querySelector(`.proj-fchip[data-filter="${k}"]`)?.focus();
    });
    return chip;
  }));
  let shown = 0;
  items.forEach((it, i) => {
    it.hidden = projFilter !== 'all' && groups[i] !== projFilter;
    if (!it.hidden) shown++;
  });
  card.querySelector('.proj-empty').hidden = shown > 0;
}

// One "Checked 1 min ago ↻" per list (design board 1): the oldest fetch among the shown projects,
// and a button that fetches every project and moves nothing (POST /api/sync/all mode 'fetch').
function syncCheckedNodes() {
  const wrap = document.createElement('span');
  wrap.className = 'sync-checked';
  const txt = document.createElement('span');
  txt.className = 'sync-checked-txt';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'sync-check-now';
  btn.setAttribute('aria-label', 'Check origin now');
  btn.title = 'Fetch every project now; moves nothing';
  btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19.5 12a7.5 7.5 0 1 1-2.2-5.3"/><path d="M19.5 4.5v4h-4"/></svg>';   // static markup
  btn.addEventListener('click', async () => {
    if (btn.disabled) return;
    btn.disabled = true; btn.classList.add('busy');
    try {
      const res = await fetch('/api/sync/all', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'fetch' }) });
      const data = await safeJson(res);
      if (res.ok && data && data.projects && typeof data.projects === 'object') { state.syncChips = data.projects; paintSyncChips(); }
      else throw new Error((data && data.error) || `The server answered ${res.status}.`);
    } catch (e) {   // the rows keep their last state
      notify({ tone: 'err', title: 'Check origin failed', detail: e.message, key: 'check-origin' });
    }
    finally { btn.disabled = false; btn.classList.remove('busy'); }
  });
  wrap.append(txt, btn);
  return wrap;
}
function paintSyncChecked() {
  for (const wrap of document.querySelectorAll('.sync-checked')) {
    const blocks = Object.values(state.syncChips || {}).filter((b) => b && b.remote);
    const times = blocks.map((b) => Date.parse(b.fetchedAt || '')).filter(Number.isFinite);
    wrap.hidden = !blocks.length;
    const txt = wrap.querySelector('.sync-checked-txt');
    if (txt) txt.textContent = times.length ? `Checked ${ago(new Date(Math.min(...times)).toISOString())}` : 'Not checked yet';
  }
}
// unref: under Node (the jsdom tests) a bare interval would keep the process alive.
setInterval(() => { if (document.querySelector('.sync-checked:not([hidden])')) paintSyncChecked(); }, 30000).unref?.();
// Coalesced: Sync all and the background refresh emit one project-sync-changed per project.
const SYNC_CHIPS_MS = 300;
let syncChipsTimer = null;
let syncChipsLoaded = false;   // the Branch cards say "checking…" until the first status read lands
let syncChipsBusy = false;
let syncChipsQueued = false;
function refreshSyncChips() {
  if (syncChipsTimer) return;
  syncChipsTimer = setTimeout(async () => {
    syncChipsTimer = null;
    if (syncChipsBusy) { syncChipsQueued = true; return; }
    syncChipsBusy = true;
    try {
      const res = await fetch('/api/sync/projects');
      const data = await safeJson(res);
      // The server's status read reports a standing fetch failure (background or Sync) as stale.
      state.syncChips = data && data.projects && typeof data.projects === 'object' ? data.projects : {};
      syncChipsLoaded = true;
      paintSyncChips();
    } catch { /* the chips keep their last state */ }
    finally {
      syncChipsBusy = false;
      if (syncChipsQueued) { syncChipsQueued = false; refreshSyncChips(); }
    }
  }, SYNC_CHIPS_MS);
}
async function postProjectSync(key) {
  const res = await fetch(`/api/projects/${encodeURIComponent(key)}/sync`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'ff' }) });
  const data = await safeJson(res);
  if (!res.ok || !data || !data.sync) throw new Error((data && data.error) || `HTTP ${res.status}`);
  state.syncChips[key] = data.sync;
  paintSyncChips();
  return data.sync;
}
/** Sync the behind projects of a workspace or project page; one toast tells how it went. */
async function syncBehindProjects(behind) {
  const results = await Promise.allSettled(behind.map((k) => postProjectSync(k)));
  const failed = results.filter((x) => x.status === 'rejected');
  if (failed.length) notify({ tone: 'err', title: `${failed.length} of ${behind.length} could not sync`, detail: failed[0].reason?.message || '', key: 'ws-sync' });
  else if (behind.length) notify({ tone: 'ok', title: `Synced ${behind.length} ${behind.length === 1 ? 'project' : 'projects'}`, key: 'ws-sync' });
}
async function syncChipNow(key, btn) {
  btn.disabled = true;
  btn.classList.add('busy');
  try { await postProjectSync(key); } catch (e) {   // the chip keeps its last state
    notify({ tone: 'err', title: 'Sync failed', detail: e.message, key: `sync-${key}` });
  }
  // The chip was repainted (a new button) on success; this one only matters on failure.
  btn.disabled = false;
  btn.classList.remove('busy');
}
async function openChipSyncDialog(key, opener) {
  let sync = state.syncChips[key];
  try {
    const res = await fetch(`/api/projects/${encodeURIComponent(key)}/sync?details=1`);
    const data = await safeJson(res);
    if (res.ok && data && data.sync) sync = data.sync;
  } catch { /* the cached block is still worth showing */ }
  if (!sync) return;
  await openSyncDialog({
    title: 'Sync status', subtitle: `${syncProjectName(key)} · ${sync.base || ''}`, sync,
    autoSync: sync.settings ? sync.settings.beforeRun !== false : true, opener,
    // A project-sync-changed repaint can replace the opener while the dialog is open.
    fallbackFocus: () => document.querySelector(`.pl-item[data-key="${cssEscape(key)}"] .pl-row`),
    onSync: async () => {
      try { return await postProjectSync(key); } catch (e) {
        notify({ tone: 'err', title: 'Sync failed', detail: e.message, key: `sync-${key}` });
        return null;
      }
    },
    // The server's project-sync-changed frame repaints the chip after a save.
    prefs: projectSyncPrefs(key),
  });
}
if (el.projectsSyncAll) {
  el.projectsSyncAll.addEventListener('click', async () => {
    const btn = el.projectsSyncAll;
    if (btn.disabled) return;
    btn.disabled = true;
    btn.classList.add('busy');
    btn.textContent = `Syncing ${projBehindCount()}…`;
    const before = projBehindCount();
    const retry = { label: 'Retry', run: () => el.projectsSyncAll.click() };
    try {
      const res = await fetch('/api/sync/all', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'ff' }) });
      const data = await safeJson(res);
      if (res.ok && data && data.projects && typeof data.projects === 'object') {
        state.syncChips = data.projects;
        const left = projBehindCount();
        notify({ tone: left ? 'warn' : 'ok', title: `Synced ${before - left} ${before - left === 1 ? 'project' : 'projects'}`,
          detail: left ? `${left} could not be fast-forwarded. Open a project to see why.` : '', key: 'sync-all' });
      } else {
        notify({ tone: 'err', title: 'Sync all failed', detail: (data && data.error) || `The server answered ${res.status}.`, key: 'sync-all', action: retry });
      }
    } catch (e) {
      notify({ tone: 'err', title: 'Sync all failed', detail: e.message, key: 'sync-all', action: retry });
    } finally {
      btn.disabled = false;
      btn.classList.remove('busy');
      paintSyncChips();   // the label and count come back with the rows
    }
  });
}

function renderProjectsList() {
  const host = el.projectsList;
  if (!host) return;
  host.innerHTML = '';
  if (!state.projects.length) {
    host.appendChild(histEmpty('No projects yet — click “Add project” to register one.'));
    return;
  }
  const card = document.createElement('section');
  card.className = 'card saved-card proj-card';

  // Design 2026-10-01: title · state filters (paintProjFilters) · "Checked … ↻" and Sync all.
  const head = document.createElement('div');
  head.className = 'saved-head';
  const title = document.createElement('div');
  title.className = 'proj-head-title';
  const b = document.createElement('b');
  b.textContent = 'Projects';
  const cnt = document.createElement('span');
  cnt.className = 'cnt';
  cnt.textContent = String(state.projects.length);
  title.append(b, cnt);
  const filters = document.createElement('div');
  filters.className = 'proj-filters';
  filters.setAttribute('role', 'group');
  filters.setAttribute('aria-label', 'Filter by sync state');
  filters.hidden = true;
  const tools = document.createElement('div');
  tools.className = 'proj-head-tools';
  tools.append(syncCheckedNodes(), el.projectsSyncAll);
  head.append(title, filters, tools);

  // Column header, wide cards only; its sync cell shares the bars' inner columns.
  const cols = document.createElement('div');
  cols.className = 'proj-cols';
  cols.setAttribute('aria-hidden', 'true');
  const colSync = document.createElement('span');
  colSync.className = 'proj-cols-sync';
  colSync.append(...['Branch', 'Origin', ''].map((t) => Object.assign(document.createElement('span'), { textContent: t })));
  const colTeam = Object.assign(document.createElement('span'), { textContent: 'Team' });
  tagLevel(colTeam, 'expert');
  cols.append(Object.assign(document.createElement('span'), { textContent: 'Project' }), colSync, colTeam, document.createElement('span'));

  const list = document.createElement('div');
  list.className = 'saved-list';   // real, styled class (style.css:671)
  for (const p of state.projects) list.appendChild(buildProjectRow(p));
  const empty = Object.assign(document.createElement('div'), { className: 'proj-empty', textContent: 'No projects in this state.', hidden: true });

  card.append(head, cols, list, empty);
  host.appendChild(card);
  paintProjectTmCells();
  paintProjectPolicyCells();
  paintSyncChips();
  void refreshSyncChips();
}

// Fills the .pl-tm chips left by buildProjectRow, and the open project page's team-metrics
// block and Overview card. Called from renderProjectsList() (NOT loadProjectsView()):
// deleteProject and saveProjectAdd both repaint via renderProjectsList().
async function paintProjectTmCells(force = false) {
  const data = await loadTmScopes({ force });
  const byKey = new Map(data.projects.map((s) => [s.key, s]));
  for (const slot of document.querySelectorAll('#projects-list .pl-team')) {
    const s = byKey.get(slot.dataset.key);
    const old = slot.querySelector('.pl-tm');
    const next = s ? renderProjectTmChip(s, { doc: document }) : Object.assign(document.createElement('span'), { className: 'pl-team-item pl-tm' });
    if (old) old.replaceWith(next); else slot.prepend(next);
  }
  paintPdTeam('metrics', byKey.get(projDetail?.key));
}
// The project page's side of a team status: the Team tab's block (the full cell, its controls
// included) and the Overview's stat card. `which` is 'metrics' | 'policy'. A page that is not
// open, or whose tab is not built yet, paints nothing — the tab builder calls back in.
function paintPdTeam(which, s) {
  if (!projDetail || !projDetail.screen) return;
  const screen = projDetail.screen;
  const body = screen.querySelector(`.pd-team-${which} .pd-team-body`);
  if (body) {
    if (s) body.replaceChildren(which === 'metrics' ? renderProjectTmCell(s, { doc: document, heading: false }) : renderProjectTpCell(s, { doc: document, heading: false }));
    else body.replaceChildren(Object.assign(document.createElement('small'), { className: 'hint', textContent: which === 'metrics' ? 'Team metrics is not available for this project.' : 'Team policy is not available for this project.' }));
  }
  const card = screen.querySelector(`.pd-ov-card-${which}`);
  if (card) {
    const sum = s ? (which === 'metrics' ? projectTmSummary(s) : projectTpSummary(s)) : null;
    card.querySelector('.pd-ov-value').textContent = sum ? capFirst(sum.short) : '—';
    const sub = card.querySelector('.pd-ov-sub');
    if (sub) { sub.textContent = sum ? (sum.detail || 'Open the Team tab') : 'Not available here'; sub.classList.toggle('pd-ov-attn', !!sum && (sum.tone === 'red' || sum.tone === 'amber')); }
    card.dataset.kind = sum ? sum.kind : '';
  }
}
const capFirst = (t) => (t ? t[0].toUpperCase() + t.slice(1) : t);

// ---------------------------------------------------------------------------
// Project page (#projects/<key>[/memory[/<name>]]) — spec 2026-09-13-project-detail-design.md
// ---------------------------------------------------------------------------
// The param after "projects/" is "<key>" (Overview), "<key>/team" (Team tab), "<key>/memory"
// (Memory tab), "<key>/memory/<enc name>" (that file open) or "<key>/away" (Away mode tab). Keys are `<slug>-<8hex>`
// (store.mjs#projectKey) and never contain "/", so the first slash splits key from tab. An
// unknown tab word reads as Overview (the hash is left alone, as History leaves an odd param alone).
const PROJ_TABS = ['overview', 'team', 'memory', 'settings', 'away', 'mcp', 'actions'];
function parseProjParam(param = '') {
  const s = String(param || '');
  if (!s) return null;
  const i = s.indexOf('/');
  const key = i === -1 ? s : s.slice(0, i);
  const rest = i === -1 ? '' : s.slice(i + 1);
  const j = rest.indexOf('/');
  const tab = j === -1 ? rest : rest.slice(0, j);
  const sub = j === -1 ? '' : rest.slice(j + 1);
  if (tab === 'memory') return { key, tab, sub };
  return { key, tab: tab === 'away' ? 'settings' : (PROJ_TABS.includes(tab) && tab !== 'overview' ? tab : 'overview'), sub: '', redirected: tab === 'away' };
}
// The canonical param for a tab: Overview is plain '<key>', never '<key>/overview'.
function projParamFor(key, tab = 'overview', sub = '') {
  if (tab === 'team' || tab === 'settings' || tab === 'mcp' || tab === 'actions') return `${key}/${tab}`;
  if (tab !== 'memory') return key;
  return sub ? `${key}/memory/${encodeURIComponent(sub)}` : `${key}/memory`;
}
const projectByKey = (key) => state.projects.find((x) => x && x.key === key) || null;
const projectHistoryRows = (key) => (state.historyAll || []).filter((r) => r && r.projectKey === key);

let projDetail = null;      // { key, name, screen, memCtl } while a page is open
let projReturnFocus = '';   // the key of the row that opened the page; closeProjDetail hands focus back

function routeProjectDetail(param, { instant = false } = {}) {
  const parsed = parseProjParam(param);
  if (!parsed) { closeProjDetail({ instant }); return; }
  if (parsed.redirected) { try { window.history.replaceState(null, '', `#projects/${projParamFor(parsed.key, parsed.tab)}`); } catch { /* sandboxed */ } }
  const p = projectByKey(parsed.key);
  if (!p) {
    closeProjDetail({ instant });
    setProjectsMsg(`project "${parsed.key}" is not registered here`, 'err');
    return;
  }
  // The same project is already open: a tab hop, or the hashchange echo of a route the page
  // itself wrote (a pill click, a memory Save). Never remount — that would drop the editor.
  if (projDetail && projDetail.key === parsed.key) { activateProjTab(parsed.tab, parsed.sub); return; }
  openProjDetail(p, parsed, { instant });
}

function openProjDetail(p, parsed, { instant = false } = {}) {
  const host = el.projDetail;
  const shell = el.projShell;
  if (!host || !shell) return;
  teardownProjDetail();                     // a page->page hop never passes closeProjDetail
  host.innerHTML = '';
  host.scrollTop = 0;                       // a prior visit's scroll must not carry over
  const screen = $('#proj-detail-tpl').content.firstElementChild.cloneNode(true);
  host.appendChild(screen);
  projDetail = { key: p.key, name: p.name, screen, memCtl: null };

  // Handlers close over the KEY and re-resolve the row at click time: a projects-changed
  // rebuild replaces the object in state.projects.
  screen.querySelector('.pd-back').addEventListener('click', () => { void leaveProjDetail(); });
  screen.querySelector('.pd-new').addEventListener('click', () => { newPipelineForProject(p.key); });
  screen.querySelector('.pd-history').addEventListener('click', () => { openRunsForProject(p.key); });
  screen.querySelector('.pd-remove').addEventListener('click', () => { void removeProjectFromPage(p.key); });
  paintProjHeader(screen, p);
  terminalPane?.syncOpeners();             // the cloned header's terminal button says whether the pane is open
  initPdTabs(screen, p);
  activateProjTab(parsed.tab, parsed.sub);

  if (instant) shell.classList.add('no-anim');
  shell.classList.add('detail-open');
  host.setAttribute('aria-hidden', 'false');
  host.removeAttribute('inert');   // the previous close left it inert for the slide
  // `aria-hidden` alone does NOT remove focusability — only `inert` does, so set BOTH.
  const list = shell.querySelector('.proj-screen-list');
  if (list) { list.setAttribute('aria-hidden', 'true'); list.setAttribute('inert', ''); }
  // AFTER the mount and AFTER the list went inert; `.pd-back` is always present.
  screen.querySelector('.pd-back').focus({ preventScroll: true });
  if (instant) rafSafe(() => shell.classList.remove('no-anim'));
}

function paintProjHeader(screen, p) {
  const title = screen.querySelector('.pd-title');
  title.textContent = p.name;
  if (!p.exists) {
    const miss = document.createElement('span');
    miss.className = 'proj-missing';
    miss.textContent = 'missing';
    title.append(' ', miss);
  }
  const path = screen.querySelector('.pd-path');
  path.textContent = p.path;
  path.title = p.path;
  // The path lives here only (the Overview no longer repeats it): one line, and a copy button.
  const copy = screen.querySelector('.pd-path-copy');
  if (copy && !copy.dataset.wired) {
    copy.dataset.wired = '1';
    copy.addEventListener('click', async () => {
      const text = (projectByKey(projDetail && projDetail.key) || p).path;
      let ok = true;
      try {
        if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
        else ok = legacyCopy(text);
      } catch { ok = legacyCopy(text); }
      copy.classList.toggle('copied', ok);
      copy.setAttribute('aria-label', ok ? 'Path copied' : 'Copy failed');
      clearTimeout(copy._t);
      copy._t = setTimeout(() => { copy.classList.remove('copied'); copy.setAttribute('aria-label', 'Copy path'); }, 1200);
    });
  }
  const fresh = screen.querySelector('.pd-new');
  fresh.disabled = !p.exists;
  fresh.title = p.exists ? 'Start a pipeline in this project' : 'The folder is missing on disk';
  syncProjHistoryButton(screen, p.key);
}

// "Show in Runs" is live only while History has rows for this project: without rows the
// Runs list has no group of this project's to reveal.
function syncProjHistoryButton(screen, key) {
  const btn = screen.querySelector('.pd-history');
  if (!btn) return;
  const n = projectHistoryRows(key).length;
  btn.disabled = n === 0;
  btn.title = n === 0 ? 'No runs yet' : `${n} run${n === 1 ? '' : 's'} in Runs`;
}

function teardownProjDetail() {
  if (projDetail && projDetail.memCtl) projDetail.memCtl.destroy();
  projDetail = null;
}

// Back / Escape from a page whose Memory editor holds an unsaved draft asks first. Only the two
// exits the page itself owns pass through here — browser Back and a typed hash cannot be
// intercepted and leave without asking, exactly as the retired list expander did.
async function leaveProjDetail() {
  const ctl = projDetail && projDetail.memCtl;
  if (ctl && ctl.dirty()) {
    // One macrotask later, past the keystroke that got us here: the modal registers its own
    // document keydown listener while opening, and the Escape arm below runs in the CAPTURE pass
    // of that same keydown — the bubble pass at document would hand the key to the fresh listener
    // and close the prompt before it was seen. A click never reaches the modal's listeners.
    await new Promise((r) => setTimeout(r, 0));
    if (!projDetail || projDetail.memCtl !== ctl) return;   // the page went away meanwhile
    const ok = await confirmModal({
      title: 'Discard changes',
      message: 'The memory editor has unsaved changes. Leave the page and discard them?',
      confirmLabel: 'Discard', danger: true,
    });
    if (!ok || !projDetail) return;   // cancelled, or the page went away while the modal was up
  }
  location.hash = 'projects';
}

function closeProjDetail({ instant = false } = {}) {
  const shell = el.projShell;
  const host = el.projDetail;
  if (!shell || !host) return;
  if (!shell.classList.contains('detail-open')) { projReturnFocus = ''; teardownProjDetail(); return; }
  // The Memory controller stays mounted for the slide: the page must slide out showing its
  // content, not a blank body (closeHistDetail keeps its graph mounts the same way). `clear`
  // below destroys it; the state is dropped NOW so a frame poke paints nothing meanwhile.
  const ctl = projDetail && projDetail.memCtl;
  projDetail = null;
  host.setAttribute('aria-hidden', 'true');
  // Un-inert the list FIRST — focus() is a no-op inside an inert subtree.
  const list = shell.querySelector('.proj-screen-list');
  if (list) { list.removeAttribute('aria-hidden'); list.removeAttribute('inert'); }
  // Hand focus back to the row the page was opened from (re-queried: a rebuild may have replaced
  // the node). One-shot, and NOT on the instant path — that one runs from showView, which hides
  // the whole section a few lines later.
  const back = projReturnFocus;
  projReturnFocus = '';
  if (back && el.projectsList && !instant) {
    const row = el.projectsList.querySelector(`.pl-item[data-key="${cssEscape(back)}"] .pl-row`);
    if (row) row.focus({ preventScroll: true });
  }
  host.setAttribute('inert', '');
  if (instant) {
    shell.classList.add('no-anim');
    shell.classList.remove('detail-open');
    if (ctl) ctl.destroy();
    host.innerHTML = '';
    rafSafe(() => shell.classList.remove('no-anim'));
    return;
  }
  shell.classList.remove('detail-open');
  // Empty the screen after the slide (or via the timeout under reduced motion / jsdom). The
  // closed page's controller is destroyed either way; the host is emptied only if no NEW page
  // was mounted meanwhile (a page->page hop replaces the screen itself).
  const clear = () => { if (ctl) ctl.destroy(); if (!projDetail) host.innerHTML = ''; };
  const onEnd = (e) => {
    if (e.target !== host || e.propertyName !== 'transform') return;
    host.removeEventListener('transitionend', onEnd);
    clear();
  };
  host.addEventListener('transitionend', onEnd);
  const t = setTimeout(() => { host.removeEventListener('transitionend', onEnd); clear(); }, 600);
  if (t && typeof t.unref === 'function') t.unref();
}

// ---- header actions ----
// "New pipeline": pick the project in the New-pipeline select (it persists across views;
// renderProjectOptions -> onProjectChanged loads its config + branches and remembers it as the
// last project), make sure the target is a project, then go there. The target is flipped only
// when it is not already a project: setRunTarget('project') re-resolves the CURRENTLY selected
// project (a second config chain for the wrong project); the loaders' generation guards make a
// superseded chain a no-op, but there is no reason to issue it.
function newPipelineForProject(key) {
  const p = projectByKey(key);
  if (!p) return;
  if (state.runTarget !== 'project') setRunTarget('project');
  renderProjectOptions(p.name);
  location.hash = 'new';
}
async function removeProjectFromPage(key) {
  const p = projectByKey(key);
  if (!p || !projDetail) return;
  const screen = projDetail.screen;
  const btn = screen.querySelector('.pd-remove');
  btn.disabled = true;
  try {
    const removed = await deleteProject(p, screen.querySelector('.pd-error'));
    if (removed) location.hash = 'projects';
  } finally {
    if (btn.isConnected) btn.disabled = false;
  }
}

// ---- tabs ----
const PD_TAB_ICONS = {
  overview: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.5"></rect><rect x="14" y="3" width="7" height="7" rx="1.5"></rect><rect x="3" y="14" width="7" height="7" rx="1.5"></rect><rect x="14" y="14" width="7" height="7" rx="1.5"></rect></svg>',
  memory: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H6.5A2.5 2.5 0 0 0 4 20.5z"></path><path d="M4 20.5V5.5M8 7h8M8 10.5h6"></path></svg>',
  map: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="5" cy="12" r="2.5"></circle><circle cx="19" cy="5" r="2.5"></circle><circle cx="19" cy="19" r="2.5"></circle><path d="M7.3 10.9l9.4-4.8M7.3 13.1l9.4 4.8"></path></svg>',
  // Away mode: a door with an arrow leaving it (the developer is away).
  away: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 4h4a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-4"></path><path d="M10 16l-4-4 4-4M6 12h9"></path></svg>',
  settings: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h16"></path></svg>',
  team: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="3.2"></circle><path d="M3.5 19c.6-3 2.8-4.6 5.5-4.6S13.9 16 14.5 19"></path><circle cx="17.5" cy="9.5" r="2.4"></circle><path d="M15.5 14.6c2.7 0 4.4 1.4 5 4.4"></path></svg>',
  mcp: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3v5M15 3v5"></path><path d="M6 8h12v3a6 6 0 0 1-12 0z"></path><path d="M12 17v4"></path></svg>',
  actions: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 5l11 7-11 7z"></path></svg>',
};
// Table-driven, like HD_TABS. `build(sec, key)` takes the KEY (buildArgs), never the project object.
const PD_TABS = [
  { key: 'overview', label: 'Overview', level: 'simple', badge: () => null, visible: () => true, build: (sec, key) => buildPdOverview(sec, key) },
  { key: 'team', label: 'Team', level: 'expert', badge: () => null, visible: () => true, build: (sec, key) => buildPdTeam(sec, key) },
  { key: 'memory', label: 'Memory', level: 'advanced', badge: () => null, visible: () => true, build: (sec, key) => buildPdMemory(sec, key) },
  { key: 'settings', label: 'Settings', level: 'advanced', badge: () => null, visible: () => true, build: (sec, key) => buildPdSettings(sec, key) },
  { key: 'mcp', label: 'Sets', level: 'advanced', badge: () => null, visible: () => true, build: (sec, key) => buildPdMcp(sec, key) },
  { key: 'actions', label: 'Actions', level: 'advanced', badge: () => null, visible: () => true, build: (sec, key) => buildPdActions(sec, key) },
];
function initPdTabs(screen, p) {
  initDetailTabs(screen, PD_TABS.map((t) => ({ ...t, icon: PD_TAB_ICONS[t.key] })), p, {
    tabsSel: '.pd-tabs', secsSel: '.pd-sections',
    tabClass: 'pd-tab', secClass: 'pd-sec', badgeClass: 'pd-tab-badge',
    idPrefix: 'pd',
    buildArgs: () => [p.key],
    initial: () => 'overview',
  });
  // Hash-first pills (the Settings-tabs idiom): the engine's own click listener has already lit
  // the pill and built the section; this one puts the tab in the URL so Back and deep links agree
  // with the screen. The Memory pill names the file the controller shows, so a hop back lands on
  // it (and keeps a draft there — see activateProjTab). The hashchange echo lands in
  // routeProjectDetail -> activateProjTab. An unchanged hash fires no hashchange, and there is
  // nothing left to do in that case.
  screen.querySelector('.pd-tabs').addEventListener('click', (e) => {
    const btn = e.target.closest && e.target.closest('button[data-sec]');
    if (!btn || !projDetail) return;
    const sub = btn.dataset.sec === 'memory' && projDetail.memCtl ? projDetail.memCtl.selectedName() : '';
    const target = `projects/${projParamFor(projDetail.key, btn.dataset.sec, sub)}`;
    if (location.hash.slice(1) !== target) location.hash = target;
  });
}
// Every route into the Memory tab loads what the hash names — the same contract loadMemoryTab(sub)
// keeps for Settings, which is what lets the controller's own routes (Save, Delete, Cancel, a row)
// repaint on their hashchange echo. A route to the file the controller ALREADY shows (a tab hop
// back, the echo of a route the controller wrote) is a keepDraft reload: the card, list and
// history refresh, an unsaved draft or NEW file stays. The section (and so memCtl) exists by the
// time load() runs: activate() builds synchronously.
function activateProjTab(tab, sub = '') {
  const tabs = detailTabsOf(projDetail && projDetail.screen);
  if (!tabs) return;
  tabs.activate(tabs.cells.has(tab) ? tab : 'overview');
  if (tab !== 'memory' || !projDetail.memCtl) return;
  const ctl = projDetail.memCtl;
  const name = sub ? safeDecode(sub) : '';
  void ctl.load(name, { keepDraft: ctl.loaded() && name === ctl.selectedName() });
}

// ---- Overview tab ----
function pdStatCard(kind, label, value, sub, { tag = 'div' } = {}) {
  const card = document.createElement(tag);
  card.className = `pd-ov-card pd-ov-card-${kind}`;
  if (tag === 'button') card.type = 'button';
  const l = document.createElement('div'); l.className = 'pd-ov-label'; l.textContent = label;
  const v = document.createElement('div'); v.className = 'pd-ov-value mono'; v.textContent = value;
  card.append(l, v);
  if (sub) { const s = document.createElement('div'); s.className = 'pd-ov-sub'; s.textContent = sub; card.appendChild(s); }
  return card;
}
const histTs = (v) => (typeof v === 'number' ? v : (Date.parse(String(v || '')) || 0));

function buildPdOverview(sec, key) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-overview');
  const p = projectByKey(key);
  if (!p) return;
  const grid = document.createElement('div');
  grid.className = 'pd-ov-grid';

  // BRANCH replaces PATH (the header carries the path): the same row model as the Projects list,
  // painted by paintSyncChips from /api/sync/projects.
  grid.appendChild(pdBranchCard('branch', 'BRANCH'));

  const rows = projectHistoryRows(key);
  const fam = { done: 0, paused: 0, stopped: 0, error: 0 };
  for (const r of rows) { const f = histStatusMeta(r).family; if (f in fam) fam[f] += 1; }
  const live = [...runs.values()].filter((r) => r && r.projectDir === p.path && (r.status === 'running' || r.status === 'starting')).length;
  if (!rows.length && !live) {
    // Nothing to count yet: one wide card that says so and starts the first run, not "0" beside "—".
    const card = pdStatCard('runs', 'RUNS', 'No runs yet', p.exists ? 'Runs started here show up on this page.' : 'The folder is missing on disk.');
    card.classList.add('pd-ov-wide');
    card.querySelector('.pd-ov-value').classList.remove('mono');
    const start = document.createElement('button');
    start.type = 'button';
    start.className = 'btn btn-mini pd-ov-act pd-ov-start';
    start.textContent = 'Start one';
    start.disabled = !p.exists;
    start.addEventListener('click', () => { newPipelineForProject(key); });
    card.appendChild(start);
    grid.appendChild(card);
  } else {
    // Only the counts that are not zero: "10 done · 2 error", never five zeros.
    const parts = Object.entries(fam).filter(([, n]) => n).map(([f, n]) => `${n} ${f}`);
    if (live) parts.push(`${live} running now`);
    grid.appendChild(pdStatCard('runs', 'RUNS', String(rows.length), parts.join(' · ')));
    let last = null;
    for (const r of rows) { const t = histTs(r.startedAt || r.mtime); if (!last || t > last.t) last = { t, r }; }
    if (last) {
      const when = Number.isFinite(last.t) && last.t ? ago(new Date(last.t).toISOString()) : fmtDate(last.r.startedAt || last.r.mtime);
      const card = pdStatCard('last', 'LAST RUN', when, [last.r.title || last.r.id, histStatusMeta(last.r).family].filter(Boolean).join(' · '), { tag: 'button' });
      card.querySelector('.pd-ov-value').classList.remove('mono');
      card.classList.add('pd-ov-link');
      card.title = `Open this run · ${fmtDate(last.r.startedAt || last.r.mtime)}`;
      card.addEventListener('click', () => { location.hash = `history/${histDetailParam(last.r)}`; });
      grid.appendChild(card);
    }
  }
  grid.appendChild(tagLevel(pdStatCard('key', 'KEY', p.key, `memory scope projects/${p.key}`), 'expert'));
  // The team half (docs/team-metrics.md, docs/team-policy.md): one card each, filled by the
  // scopes painters, and a click lands on the Team tab where the controls are.
  for (const which of ['metrics', 'policy']) {
    const card = pdStatCard(which, which === 'metrics' ? 'TEAM METRICS' : 'TEAM POLICY', '…', 'checking…', { tag: 'button' });
    card.classList.add('pd-ov-link');
    card.title = 'Open the Team tab';
    card.addEventListener('click', () => { location.hash = `projects/${projParamFor(key, 'team')}`; });
    grid.appendChild(tagLevel(card, 'expert'));
  }
  sec.appendChild(grid);
  ensureHistoryLoaded();
  void paintProjectTmCells();
  void paintProjectPolicyCells();
  paintPdBranchCards();
  void refreshSyncChips();
}

// ---- Branch card (project page) / Branches card (workspace page) ----
// The stat-card shape (label, short value, one sub line) with the lists' one action. Filled from
// state.syncChips by paintPdBranchCards, which paintSyncChips calls after every status read.
function pdBranchCard(kind, label) {
  const card = pdStatCard(kind, label, '…', 'checking…');
  card.classList.add('pd-ov-branch');
  const value = card.querySelector('.pd-ov-value');
  value.classList.remove('mono');
  const status = document.createElement('div');
  status.className = 'pd-ov-status';
  card.insertBefore(status, card.querySelector('.pd-ov-sub'));
  const act = document.createElement('div');
  act.className = 'pd-ov-actrow';
  card.appendChild(act);
  return card;
}
function paintPdBranchCards() {
  const pcard = projDetail && projDetail.screen && projDetail.screen.querySelector('.pd-ov-card-branch');
  if (pcard) {
    const key = projDetail.key;
    const b = state.syncChips[key];
    const value = pcard.querySelector('.pd-ov-value');
    const status = pcard.querySelector('.pd-ov-status');
    const sub = pcard.querySelector('.pd-ov-sub');
    const act = pcard.querySelector('.pd-ov-actrow');
    if (!syncChipsLoaded) {
      value.textContent = '…'; status.replaceChildren(); sub.textContent = 'checking…'; act.replaceChildren();
    } else if (!b || !b.remote) {
      value.textContent = (b && b.base) || '—';
      status.replaceChildren(); sub.textContent = 'No remote · runs use your local copy'; act.replaceChildren();
    } else {
      const m = listRowModel(b);
      const c = syncRowCells(key, m, '', projDetail.name);
      value.replaceChildren(wsIcon('branch', 18), Object.assign(document.createElement('span'), { className: 'mono', textContent: b.base || '—' }));
      status.className = `pd-ov-status tone-${m.tone}`;
      status.replaceChildren(c.icon, c.status.querySelector('.ws-tlabel'));
      sub.textContent = m.hint || `Checked ${fetchedAgo(b)}`;
      act.replaceChildren(...c.action.childNodes);
    }
  }
  const wcard = wsDetail && wsDetail.screen && wsDetail.screen.querySelector('.pd-ov-card-branches');
  if (wcard) {
    const w = workspaceById(wsDetail.id);
    const keys = w && Array.isArray(w.projectKeys) ? w.projectKeys : [];
    const value = wcard.querySelector('.pd-ov-value');
    const status = wcard.querySelector('.pd-ov-status');
    const sub = wcard.querySelector('.pd-ov-sub');
    const act = wcard.querySelector('.pd-ov-actrow');
    if (!syncChipsLoaded) { value.textContent = '…'; sub.textContent = 'checking…'; status.replaceChildren(); act.replaceChildren(); return; }
    const models = keys.map((k) => (state.syncChips[k] ? listRowModel(state.syncChips[k]) : { state: 'none', action: null }));
    const roll = wsRollupModel(models);
    const [head, ...rest] = roll.text.split(' · ');
    value.textContent = head;
    value.className = `pd-ov-value tone-${roll.tone}`;
    status.replaceChildren();
    sub.textContent = rest.join(' · ') || (models.some((x) => x.state === 'none') ? 'Some projects have no remote' : '');
    const behind = keys.filter((k, i) => models[i].action === 'sync');
    if (!behind.length) { act.replaceChildren(); return; }
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn btn-mini pd-ov-act';
    btn.textContent = `Sync all (${behind.length})`;
    btn.addEventListener('click', async () => {
      btn.disabled = true; btn.classList.add('busy');
      await syncBehindProjects(behind);
      if (btn.isConnected) { btn.disabled = false; btn.classList.remove('busy'); }
    });
    act.replaceChildren(btn);
  }
}

// ---- Sets tab (key mcp; docs/mcp-servers.md, docs/skills.md): the project's sets and the servers and skills its runs get ----
function buildPdMcp(sec, key) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-mcp');
  const p = projectByKey(key);
  void mountProjectMcp(sec, { key, name: p ? p.name : key, api: mcpApi });
}

// ---- Away mode tab ----
function buildPdSettings(sec, key) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-settings');
  const p = projectByKey(key);
  if (!p) return;
  const host = document.createElement('div'); host.className = 'pd-settings'; sec.appendChild(host);
  mountProjectSettings(host, { projectKey: p.key, projectDir: p.path });
  sec.appendChild(buildPdNightCard(p));
}

// The project's Away mode layer (project_config.extra.nightMode): fields set here beat the
// developer's and the team's; empty fields read "Same as my settings (…)".
function buildPdNightCard(p) {
  const card = document.createElement('section');
  card.className = 'card pd-night-card';
  const head = document.createElement('div');
  head.className = 'card-head';
  const b = document.createElement('b'); b.textContent = 'Away mode for this project';
  const h = document.createElement('small'); h.className = 'hint';
  h.textContent = 'Anything left as "Same as my settings" uses your Settings page. Set a value here to override it for this project only.';
  head.append(b, h);
  const host = document.createElement('div');
  host.className = 'pd-night-form';
  const global = Object.assign(document.createElement('small'), { className: 'hint', textContent: '"I\'m away now" and "Pause" are global. Change them in Settings › Away mode.' });
  const actions = document.createElement('div');
  actions.className = 'add-project-actions';
  const reset = Object.assign(document.createElement('button'), { type: 'button', className: 'btn btn-ghost btn-mini pd-night-reset', textContent: 'Use my settings' });
  const save = Object.assign(document.createElement('button'), { type: 'button', className: 'btn btn-primary btn-mini pd-night-save', textContent: 'Save' });
  actions.append(reset, save);
  const msg = Object.assign(document.createElement('small'), { className: 'hint pd-night-msg' });
  card.append(head, host, global, actions, msg);
  let seq = 0;
  const load = async () => {
    const mine = ++seq;
    // Both guarded: null / [] on any failure. The catalog feeds the "Decided by" picker.
    const [d, models] = await Promise.all([fetchAwayMode(p.path), fetchTitleModelCatalog()]);
    if (mine !== seq || !d) return;
    awayModelCatalog = models;
    renderNightForm(host, { level: 'project', values: d.project || {}, effective: d.config, sources: d.sources, inherited: d.inherited, toggle: d.toggle, hereSince: d.hereSince ?? null, now: Date.now(), projectName: p.name, models });
  };
  const send = async (nightMode) => {
    msg.textContent = ''; msg.className = 'hint pd-night-msg';
    try {
      const res = await fetch('/api/config', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectDir: p.path, nightMode }) });
      const data = await safeJson(res);
      if (!res.ok) { msg.textContent = data.error || `HTTP ${res.status}`; msg.className = 'hint pd-night-msg err'; return; }
      delete state.awayModeByDir[p.path];                     // run pages refetch this project's body
      await load();
      msg.textContent = 'Saved.';
    } catch (err) { msg.textContent = err.message || 'network error'; msg.className = 'hint pd-night-msg err'; }
  };
  save.addEventListener('click', () => send(readNightForm(host, { level: 'project' })));
  reset.addEventListener('click', () => send(null));
  // Never a blank card before the GET lands: nothing is inherited yet, so every choice reads plainly.
  renderNightForm(host, { level: 'project', values: {}, inherited: { config: null, sources: {} }, projectName: p.name, models: awayModelCatalog });
  void load().catch(() => {});
  return card;
}

// ---- Team tab ----
// Two panels, one per feature, each holding the same block the Projects list used to carry per
// row — status, sentence, and the controls (Set up…, Include my runs, Push now, Open, Change…).
// The blocks are painted by the scopes painters, which also keep the list chips in step.
function buildPdTeam(sec, key) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-team');
  const panel = (which, title, hint) => {
    const card = document.createElement('section');
    card.className = `card pd-team-card pd-team-${which}`;
    card.dataset.key = key;
    const head = document.createElement('div');
    head.className = 'card-head';
    const b = document.createElement('b'); b.textContent = title;
    const h = document.createElement('small'); h.className = 'hint'; h.textContent = hint;
    head.append(b, h);
    const body = document.createElement('div');
    body.className = 'pd-team-body';
    body.appendChild(Object.assign(document.createElement('small'), { className: 'hint', textContent: 'checking…' }));
    card.append(head, body);
    return card;
  };
  sec.append(
    panel('metrics', 'Team metrics', 'Finished runs recorded on a shared worca-metrics branch, for the whole team.'),
    panel('policy', 'Team policy', 'Caps, plugins and models the team expects, read from a worca-policy branch.'),
  );
  void paintProjectTmCells();
  void paintProjectPolicyCells();
}

// A deep link into a project page can land before the socket's `hello` background-loads History;
// load it once here so the counts are real, not a permanent "0 runs". onHello's own
// `!historyBooted` guard then skips its load. `historyBooted` is declared with loadHistoryView.
function ensureHistoryLoaded() {
  if (historyBooted) return;
  historyBooted = true;
  void loadHistoryView();
}

// The Overview reads the History dataset; repaint it (and the header's History button) whenever
// that dataset changes. paintHistory() is the one funnel every history load/patch ends in.
function refreshProjOverview() {
  if (!projDetail || !projDetail.screen) return;
  const p = projectByKey(projDetail.key);
  if (!p) return;
  syncProjHistoryButton(projDetail.screen, p.key);
  const sec = projDetail.screen.querySelector('.pd-sec[data-sec="overview"]');
  if (sec && sec.dataset.loaded === '1') buildPdOverview(sec, p.key);
}

// ---- Memory tab ----
// The same grid Settings → Memory paints, for scope 'projects/<key>', hash-first (navigate: true):
// memoryRoute() yields 'projects/<key>/memory[/<name>]', so the controller's routes are this page's
// own routes. No load here — activateProjTab loads what the hash names.
function buildPdMemory(sec, key) {
  sec.innerHTML = '';
  sec.classList.add('pd-sec-memory');
  const msg = document.createElement('p');
  msg.className = 'form-msg';
  msg.setAttribute('aria-live', 'polite');
  const host = document.createElement('div');
  host.className = 'mem-host';
  sec.append(msg, host);
  if (!projDetail) return;
  if (projDetail.memCtl) projDetail.memCtl.destroy();
  projDetail.memCtl = createMemoryController({ host, msgEl: msg, scopeKey: `projects/${key}`, navigate: true });
}

// ---- Reusable confirm / prompt modal ---------------------------------------
// One shell, two public entry points:
//   confirmModal(opts) -> Promise<boolean>, or Promise<{ok, checked}> when
//     opts.checkbox is given. Contract unchanged from before promptModal existed.
//   promptModal(opts)  -> Promise<object|null> keyed by field id. This is what
//     replaced window.prompt: it takes an ARRAY of fields, so the two places
//     that used to fire two blocking prompts back to back (name + domain,
//     profile id + label) now ask once.
// opts.danger tints the title and the OK button red for a destructive action
// (opt-in). `done` always clears every opt-in again — the modal is shared, and
// neither the tint nor a leftover field may leak into the next, harmless call.
function modalShell({
  title = 'Confirm', message = '', confirmLabel = 'Confirm', cancelLabel = 'Cancel',
  checkbox = null, danger = false, fields = null, messageTone = null,
} = {}) {
  return new Promise((resolve) => {
    el.confirmTitle.textContent = title;
    el.confirmTitle.classList.toggle('danger', !!danger);
    // message: a string, or parts [text | { strong: text }] so the variable bits (a branch, a command)
    // stand out. Every part goes in as text, never as markup.
    if (Array.isArray(message)) {
      el.confirmMessage.replaceChildren(...message.map((p) => (typeof p === 'string' ? document.createTextNode(p)
        : Object.assign(document.createElement('strong'), { textContent: String(p?.strong ?? '') }))));
    } else el.confirmMessage.textContent = message;
    el.confirmMessage.hidden = Array.isArray(message) ? !message.length : !message;
    // messageTone:'err' paints the shared message in the app's error colour
    // (.confirm-message.err → --red-ink); done() always drops it again so the
    // tint never leaks to the next caller of this shared modal.
    el.confirmMessage.classList.toggle('err', messageTone === 'err');
    el.confirmOk.textContent = confirmLabel;
    el.confirmCancel.textContent = cancelLabel;
    el.confirmOk.classList.toggle('danger', !!danger);

    // prompt fields: built fresh each time, values bound via .value (never innerHTML)
    const inputs = [];
    el.confirmFields.replaceChildren();
    for (const f of fields || []) {
      const wrap = document.createElement('div');
      wrap.className = 'confirm-field';
      const lab = document.createElement('label');
      lab.textContent = f.label;
      lab.htmlFor = `confirm-f-${f.id}`;
      const inp = document.createElement('input');
      inp.type = 'text';
      inp.className = 'input';
      inp.id = `confirm-f-${f.id}`;
      inp.dataset.fieldId = f.id;
      inp.value = f.value || '';
      inp.placeholder = f.placeholder || '';
      inp.autocomplete = 'off';
      if (f.mono) inp.style.fontFamily = 'var(--mono)';
      wrap.append(lab, inp);
      if (f.hint) {
        const hint = document.createElement('small');
        hint.className = 'hint';
        hint.textContent = f.hint;
        wrap.appendChild(hint);
      }
      el.confirmFields.appendChild(wrap);
      inputs.push(inp);
      if (f.required) inp.addEventListener('input', syncOk);
    }
    // A required field with nothing in it is the old `if (!name) return` guard,
    // moved to where the user can see it.
    function syncOk() {
      el.confirmOk.disabled = (fields || []).some((f, i) => f.required && !inputs[i].value.trim());
    }
    syncOk();

    // opt-in checkbox: shown only when requested, always reset to unchecked
    el.confirmCheckboxWrap.classList.toggle('hidden', !checkbox);
    el.confirmCheckbox.checked = false;
    el.confirmCheckboxLabel.textContent = checkbox ? checkbox.label : '';
    el.confirmModal.classList.remove('hidden');
    (inputs[0] || el.confirmOk).focus();

    const done = (val) => {
      const checked = el.confirmCheckbox.checked;
      const values = {};
      for (const i of inputs) values[i.dataset.fieldId] = i.value.trim();
      el.confirmOk.classList.remove('danger');   // never leak the tint to the next caller
      el.confirmTitle.classList.remove('danger');
      el.confirmMessage.classList.remove('err');
      el.confirmOk.disabled = false;
      el.confirmMessage.hidden = false;
      el.confirmFields.replaceChildren();
      el.confirmModal.classList.add('hidden');
      el.confirmCheckboxWrap.classList.add('hidden');
      el.confirmOk.removeEventListener('click', onOk);
      el.confirmCancel.removeEventListener('click', onCancel);
      el.confirmModal.removeEventListener('click', onBackdrop);
      document.removeEventListener('keydown', onKey);
      if (fields) resolve(val ? values : null);
      else resolve(checkbox ? { ok: val, checked } : val);
    };
    const onOk = () => { if (!el.confirmOk.disabled) done(true); };
    const onCancel = () => done(false);
    const onBackdrop = (e) => { if (e.target === el.confirmModal) done(false); };
    const onKey = (e) => {
      if (e.key === 'Escape') done(false);
      // Enter submits a filled-in prompt, the way the native one did
      else if (e.key === 'Enter' && fields && !el.confirmOk.disabled) { e.preventDefault(); done(true); }
    };

    el.confirmOk.addEventListener('click', onOk);
    el.confirmCancel.addEventListener('click', onCancel);
    el.confirmModal.addEventListener('click', onBackdrop);
    document.addEventListener('keydown', onKey);
  });
}

function confirmModal(opts = {}) {
  return modalShell({ ...opts, fields: null });
}

// fields: [{ id, label, placeholder, value, hint, mono, required }]
function promptModal({ confirmLabel = 'Save', fields = [], ...rest } = {}) {
  return modalShell({ ...rest, confirmLabel, fields });
}

// Scheduled runs that depend on something about to be removed — so the confirmation can NAME
// them. `query` is one of workflowId= / projectDir= / workspaceId=. Never blocks the removal:
// a failed lookup just omits the note.
async function scheduleDependentsNote(query, consequence) {
  try {
    const res = await fetch(`/api/schedules/dependents?${query}`);
    if (!res.ok) return '';
    const { dependents } = await safeJson(res);
    if (!Array.isArray(dependents) || !dependents.length) return '';
    const names = dependents.slice(0, 4).map((d) => `“${d.title || (d.kind === 'recurring' ? 'repeating schedule' : 'scheduled run')}”`).join(', ');
    const more = dependents.length > 4 ? ` and ${dependents.length - 4} more` : '';
    return `\n\n${dependents.length === 1 ? 'A scheduled run depends' : `${dependents.length} scheduled runs depend`} on it: ${names}${more}. ${consequence}`;
  } catch { return ''; }
}

// Run chains: the runs that wait for a pipeline about to be archived. Its own sentence, not
// scheduleDependentsNote's — the Archive copy is pinned and this is appended to it verbatim.
async function afterDependentsNote(query) {
  try {
    const res = await fetch(`/api/schedules/dependents?${query}`);
    if (!res.ok) return '';
    const { dependents } = await safeJson(res);
    if (!Array.isArray(dependents) || !dependents.length) return '';
    const names = dependents.slice(0, 4).map((d) => `“${d.title || 'Scheduled run'}”`).join(', ');
    const more = dependents.length > 4 ? ` and ${dependents.length - 4} more` : '';
    return `\n\n${names}${more} ${dependents.length === 1 ? 'waits' : 'wait'} for this run and will be marked missed.`;
  } catch { return ''; }
}

// Remove a project. Returns true when the registry changed, false on cancel or failure. `errEl`
// (the project page's .pd-error) takes the failure text when given; the list message otherwise.
async function deleteProject(p, errEl = null) {
  const schedNote = await scheduleDependentsNote(`projectDir=${encodeURIComponent(p.path || '')}`, 'Removing the project cancels them.');
  const ok = await confirmModal({
    title: 'Remove project',
    message: `Remove “${p.name}” from the list?\nThe folder on disk and its run history are left untouched.${schedNote}`,
    confirmLabel: 'Remove project',
  });
  if (!ok) return false;
  const say = (text) => {
    if (errEl) { errEl.hidden = !text; errEl.textContent = text || ''; }
    else setProjectsMsg(text, text ? 'err' : '');
  };
  say('');
  try {
    const res = await fetch(`/api/projects?name=${encodeURIComponent(p.name)}`, { method: 'DELETE' });
    const data = await safeJson(res);
    if (!res.ok) { say(data.error || `HTTP ${res.status}`); return false; }
    state.projects = Array.isArray(data.projects) ? data.projects : [];
    if (localStorage.getItem(LAST_PROJECT_KEY) === p.name) localStorage.removeItem(LAST_PROJECT_KEY);
    renderProjectsList();
    renderProjectOptions(localStorage.getItem(LAST_PROJECT_KEY) || ''); // keep New-pipeline dropdown in sync
    return true;
  } catch (e) {
    say(e.message);
    return false;
  }
}

// ---- Add project (native picker first, manual fallback in the modal) --------
// NOTE: kind may be 'err' (maps to the existing .hint.err rule) or omitted.
// There is no .hint.warn rule, so informational hints pass NO kind (default
// neutral .hint styling) — do not pass 'warn'.
function setProjAddMsg(text, kind) {
  if (!el.projAddMsg) return;
  el.projAddMsg.textContent = text || '';
  el.projAddMsg.className = 'hint' + (kind ? ' ' + kind : '');
}

function openProjectAddModal(path, { mode = 'folder' } = {}) {
  el.projAddPath.value = path || '';
  el.projAddName.value = path ? basenameOf(path) : '';
  if (el.projCloneUrl) {
    el.projCloneUrl.value = '';
    el.projCloneBranch.value = '';
    el.projCloneName.value = '';
    el.projCloneName.placeholder = 'the repository name';
  }
  el.projectAddModal.classList.remove('hidden');
  setProjAddMode(mode);
  // A clone still in flight from an earlier open keeps its progress line.
  if (cloneFollow) { setProjAddMode('clone'); setProjAddMsg(`Cloning ${cloneFollow.url} …`); lockCloneForm(true); return; }
  // Informational hint only when there is no path (manual-entry fallback);
  // neutral default .hint styling (no .hint.warn class exists).
  if (mode === 'folder') {
    setProjAddMsg(path ? '' : 'Native folder picker unavailable — enter the project folder path, or browse with Choose folder….');
    el.projAddName.focus();
    el.projAddName.select();
  }
}

// ---- Add project: the Folder / Clone from URL tabs ------------------------------
let projAddMode = 'folder';

function setProjAddMode(mode) {
  projAddMode = mode === 'clone' && el.projAddClonePane ? 'clone' : 'folder';
  if (!el.projAddTabs) return;
  for (const t of el.projAddTabs.querySelectorAll('.md-tab')) t.setAttribute('aria-selected', String(t.dataset.mode === projAddMode));
  el.projAddFolderPane.hidden = projAddMode !== 'folder';
  el.projAddClonePane.hidden = projAddMode !== 'clone';
  el.projAddSave.textContent = projAddMode === 'clone' ? 'Clone and add' : 'Add project';
  setProjAddMsg(projAddMode === 'clone' ? 'Worca clones the repository into its projects folder with the deployment\'s credential for its host (GitHub or Azure DevOps).' : '');
  if (projAddMode === 'clone') el.projCloneUrl.focus();
}

/** The folder name worca will use for a clone URL (planClone's rule), or '' when the URL does not name one repository.
 *  "https://github.com/acme/api(.git)" -> "api"; "https://dev.azure.com/acme/Shop/_git/My%20Repo(.git)" -> "My-Repo". */
function repoNameFromUrl(url) {
  const s = String(url || '').trim();
  // [org@]dev.azure.com/org[/project]/_git/repo, org.visualstudio.com[/DefaultCollection][/project]/_git/repo
  const az = /^https:\/\/(?:[^@/\s]+@)?(?:dev\.azure\.com\/[^/\s]+|[^/\s]+\.visualstudio\.com(?:\/defaultcollection)?)(?:\/[^/\s]+)?\/_git\/([^/\s?#]+?)(?:\.git)?\/?$/i.exec(s);
  if (az) {
    let n; try { n = decodeURIComponent(az[1]); } catch { n = az[1]; }
    // the same fold as planClone's folderFrom (src/core/clone-project.mjs)
    return n.replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^[^A-Za-z0-9]+/, '').slice(0, 100);
  }
  const m = /^https:\/\/[^/\s]+\/[^/\s]+\/([^/\s?#]+?)(?:\.git)?\/?$/i.exec(s);
  return m ? m[1] : '';
}

// The clone being followed: { id, url } while a job runs. WS 'clone-changed' is the fast path,
// a GET every 2 s the fallback (a dropped socket must not strand the dialog).
let cloneFollow = null;
let clonePoll = null;

function lockCloneForm(locked) {
  for (const n of [el.projCloneUrl, el.projCloneBranch, el.projCloneName, el.projAddSave]) if (n) n.disabled = locked;
  if (el.projAddTabs) for (const t of el.projAddTabs.querySelectorAll('.md-tab')) t.disabled = locked;
}

async function saveProjectClone() {
  const url = el.projCloneUrl.value.trim();
  if (!url) return setProjAddMsg('Repository URL is required.', 'err');
  const body = { url };
  const branch = el.projCloneBranch.value.trim();
  const name = el.projCloneName.value.trim();
  if (branch) body.branch = branch;
  if (name) body.name = name;
  lockCloneForm(true);
  setProjAddMsg(`Cloning ${url} …`);
  try {
    const res = await fetch('/api/projects/clone', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const data = await safeJson(res);
    if (!res.ok || !data.jobId) { lockCloneForm(false); setProjAddMsg(data.error || `HTTP ${res.status}`, 'err'); return; }
    cloneFollow = { id: data.jobId, url };
    if (data.job && data.job.state !== 'running') { onCloneJob(data.job); return; }
    clonePoll = setInterval(pollCloneJob, 2000);
  } catch (e) {
    lockCloneForm(false);
    setProjAddMsg(e.message, 'err');
  }
}

async function pollCloneJob() {
  if (!cloneFollow) return;
  try {
    const res = await fetch(`/api/projects/clone/${encodeURIComponent(cloneFollow.id)}`);
    const data = await safeJson(res);
    if (res.ok && data.job) onCloneJob(data.job);
    else if (res.status === 404) onCloneJob({ id: cloneFollow.id, state: 'error', error: 'the clone job is gone (the server restarted?)' });
  } catch { /* the next tick retries */ }
}

/** A job update from the WS or the poll: only the one this dialog started counts. */
function onCloneJob(job) {
  if (!job || !cloneFollow || job.id !== cloneFollow.id || job.state === 'running') return;
  clearInterval(clonePoll);
  clonePoll = null;
  cloneFollow = null;
  lockCloneForm(false);
  const open = el.projectAddModal && !el.projectAddModal.classList.contains('hidden');
  if (job.state === 'error') {
    if (open) { setProjAddMode('clone'); setProjAddMsg(job.error || 'The clone failed.', 'err'); }
    else setProjectsMsg(`Clone failed: ${job.error || 'unknown error'}`, 'err');
    return;
  }
  const name = (job.project && job.project.name) || job.name || '';
  if (open) closeProjectAddModal();
  void (async () => {
    try {
      const res = await fetch('/api/projects');
      const data = await safeJson(res);
      if (res.ok && Array.isArray(data.projects)) state.projects = data.projects;
    } catch { /* the projects-changed frame refreshes it too */ }
    renderProjectsList();
    renderProjectOptions(localStorage.getItem(LAST_PROJECT_KEY) || '');
    setProjectsMsg(name ? `Cloned and added “${name}”.` : 'Cloned and added the project.', 'ok');
  })();
}

function closeProjectAddModal() {
  el.projectAddModal.classList.add('hidden');
}

async function addProjectFlow() {
  setProjectsMsg('');
  const data = await pickFolder('project', { multiple: true });
  if (data && data.status === 'picked') {
    const paths = pickedPaths(data);
    if (paths.length) { projectsViewPicks(paths); return; }   // one -> Add dialog, several -> review
  }
  if (data && data.status === 'canceled') return;                 // respect the cancel
  if (data && data.status === 'busy') { setProjectsMsg('A folder dialog is already open — finish or cancel it first.', 'err'); return; }
  // No folder picker at all (a container or hosted worca): the repository is the way in.
  if (data && data.status === 'unsupported') { openProjectAddModal('', { mode: 'clone' }); return; }
  openProjectAddModal('');                                        // error -> manual entry
}

async function saveProjectAdd() {
  if (projAddMode === 'clone') return saveProjectClone();
  const name = el.projAddName.value.trim();
  const path = el.projAddPath.value.trim();
  if (!name) return setProjAddMsg('Name is required.', 'err');
  if (!path) return setProjAddMsg('Folder is required.', 'err');
  el.projAddSave.disabled = true;
  try {
    const res = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, path }),
    });
    const data = await safeJson(res);
    if (!res.ok) { setProjAddMsg(data.error || `HTTP ${res.status}`, 'err'); return; }
    state.projects = Array.isArray(data.projects) ? data.projects : state.projects;
    closeProjectAddModal();
    renderProjectsList();
    renderProjectOptions(localStorage.getItem(LAST_PROJECT_KEY) || ''); // keep New-pipeline dropdown in sync
  } catch (e) {
    setProjAddMsg(e.message, 'err');
  } finally {
    el.projAddSave.disabled = false;
  }
}

// ---- Add several projects: the review list ------------------------------------
// Opened with 2+ picked folders (native multi-select, or the folder browser's ticks) from the
// Projects view or New Pipeline's inline form. `onDone({added, skipped})` runs ONCE when the
// dialog closes — however it closes — so each entry point repaints its own surface.
let projBulk = null;   // { rows:[{path, name, include, status:''|'added'|'skipped', reason}], addedNames, onDone, saving }

function setProjBulkMsg(text, kind) {
  if (!el.projBulkMsg) return;
  el.projBulkMsg.textContent = text || '';
  el.projBulkMsg.className = 'hint' + (kind ? ' ' + kind : '');
}
// #555: a refusal concerns the dialog the user is in — a card alert above its button row.
const projBulkCard = () => el.projectBulkModal && el.projectBulkModal.querySelector('.card');
function projBulkAlert(title, detail = '') {
  setProjBulkMsg('');
  cardAlert(projBulkCard(), { title, detail });
}

function openProjectBulkModal(paths, { onDone = null } = {}) {
  const known = new Map((state.projects || []).map((p) => [p.path, p.name]));
  const rows = [];
  for (const path of new Set((paths || []).filter(Boolean))) {
    const registeredAs = known.get(path);
    rows.push({
      path,
      name: basenameOf(path),
      include: !registeredAs,                           // an already-registered folder starts unticked
      status: '',
      reason: registeredAs ? `already registered as “${registeredAs}”` : '',
    });
  }
  projBulk = { rows, addedNames: [], onDone, saving: false };
  if (el.projBulkTitle) el.projBulkTitle.textContent = `Add ${rows.length} projects`;
  setProjBulkMsg('');
  cardAlert(projBulkCard(), null);
  renderProjectBulkRows();
  el.projectBulkModal.classList.remove('hidden');
  const first = el.projBulkList.querySelector('.pb-name:not(:disabled)');
  if (first) first.focus();
}

// Rows that the next Add sends: ticked and not added yet.
function projBulkPending() {
  return projBulk ? projBulk.rows.filter((r) => r.include && r.status !== 'added') : [];
}

function syncProjBulkSave() {
  const n = projBulkPending().length;
  el.projBulkSave.disabled = n === 0 || !!(projBulk && projBulk.saving);
  el.projBulkSave.textContent = n === 1 ? 'Add 1 project' : `Add ${n} projects`;
}

function renderProjectBulkRows() {
  el.projBulkList.textContent = '';
  if (!projBulk) return;
  for (const row of projBulk.rows) {
    const added = row.status === 'added';
    const li = document.createElement('li');
    li.className = 'pb-row' + (added ? ' added' : '') + (row.status === 'skipped' ? ' skipped' : '');
    li.dataset.path = row.path;
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.className = 'pb-include';
    cb.checked = row.include && !added;
    cb.disabled = added;
    cb.setAttribute('aria-label', `Add ${basenameOf(row.path)}`);
    cb.addEventListener('change', () => { row.include = cb.checked; syncProjBulkSave(); });
    const name = document.createElement('input');
    name.type = 'text';
    name.className = 'input pb-name';
    name.spellcheck = false;
    name.value = row.name;
    name.disabled = added;
    name.setAttribute('aria-label', `Project name for ${row.path}`);
    name.addEventListener('input', () => { row.name = name.value; });
    name.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); void saveProjectBulk(); } });
    const path = document.createElement('code');
    path.className = 'pb-path';
    path.textContent = row.path;
    path.title = row.path;
    const status = document.createElement('small');
    status.className = 'pb-status' + (row.status === 'skipped' ? ' err' : added ? ' ok' : '');
    status.textContent = added ? 'Added' : row.reason;
    li.append(cb, name, path, status);
    el.projBulkList.appendChild(li);
  }
  syncProjBulkSave();
}

async function saveProjectBulk() {
  if (!projBulk || projBulk.saving) return;
  const pending = projBulkPending();
  if (!pending.length) {
    fieldError(el.projBulkList.querySelector('.pb-include:not(:disabled)'), 'Tick at least one folder to add.');
    return;
  }
  projBulk.saving = true;
  syncProjBulkSave();
  cardAlert(projBulkCard(), null);
  setProjBulkMsg(`Adding ${pending.length} …`);
  const bulk = projBulk;
  try {
    const res = await fetch('/api/projects/bulk', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projects: pending.map((r) => ({ name: r.name.trim(), path: r.path })) }),
    });
    const data = await safeJson(res);
    if (!res.ok) { projBulkAlert('Projects not added', data.error || `HTTP ${res.status}`); return; }
    if (Array.isArray(data.projects)) state.projects = data.projects;
    let addedNow = 0;
    for (const r of Array.isArray(data.results) ? data.results : []) {
      const row = pending[r.index];                     // results answer the request BY INDEX
      if (!row) continue;
      if (r.status === 'added') {
        row.status = 'added'; row.reason = ''; row.name = r.name || row.name;
        bulk.addedNames.push(row.name);
        addedNow += 1;
      } else {
        row.status = 'skipped'; row.reason = r.reason || 'not added';
      }
    }
    if (projBulk !== bulk) return;                      // closed while the request was in flight
    const skipped = bulk.rows.filter((r) => r.status === 'skipped');
    if (!skipped.length) { closeProjectBulkModal(); return; }
    renderProjectBulkRows();
    projBulkAlert('Not every project was added',
      `${addedNow ? `Added ${addedNow}. ` : ''}${skipped.length} could not be added — see the reason on each row. Rename and press Add again, or close.`);
  } catch (e) {
    projBulkAlert('Projects not added', e.message);
  } finally {
    bulk.saving = false;
    if (projBulk === bulk) syncProjBulkSave();
  }
}

function closeProjectBulkModal() {
  if (!projBulk) return;
  const { onDone, addedNames, rows } = projBulk;
  projBulk = null;
  el.projectBulkModal.classList.add('hidden');
  el.projBulkList.textContent = '';
  if (onDone) onDone({ added: addedNames, skipped: rows.filter((r) => r.status === 'skipped') });
}

// "Added 3 projects. Skipped 1: beta (a project named "beta" already exists)."
function bulkAddSummary(added, skipped) {
  const parts = [];
  if (added.length === 1) parts.push(`Added “${added[0]}”.`);
  else if (added.length > 1) parts.push(`Added ${added.length} projects.`);
  if (skipped.length) {
    parts.push(`Skipped ${skipped.length}: ${skipped.map((r) => `${r.name.trim() || basenameOf(r.path)} (${r.reason})`).join('; ')}.`);
  }
  return parts.join(' ');
}

// Projects view: repaint the list + New Pipeline dropdown, and say what happened.
function onProjectsBulkDone({ added, skipped }) {
  if (added.length) {
    renderProjectsList();
    renderProjectOptions(localStorage.getItem(LAST_PROJECT_KEY) || ''); // keep New-pipeline dropdown in sync
  }
  const text = bulkAddSummary(added, skipped);
  if (text) setProjectsMsg(text, skipped.length ? 'warn' : 'ok');
}

// The Projects view's routing for picked folders: one -> the single Add dialog, several -> review.
function projectsViewPicks(paths, { fill } = {}) {
  routePickedFolders(paths, {
    single: fill || ((p) => openProjectAddModal(p)),
    many: (list) => { closeProjectAddModal(); openProjectBulkModal(list, { onDone: onProjectsBulkDone }); },
  });
}

// ---- Event wiring (guarded so non-UI test imports don't throw) --------------
if (el.projectsList) {
  const openRow = (row) => {
    const item = row.closest('.pl-item');
    if (!item || !item.dataset.key) return;
    projReturnFocus = item.dataset.key;                 // Back / Esc come home to this row
    location.hash = `projects/${item.dataset.key}`;
  };
  el.projectsList.addEventListener('click', (e) => {
    const row = e.target.closest && e.target.closest('.pl-row[role="button"]');
    if (row) openRow(row);                              // a chevron click bubbles here too — one open
  });
  el.projectsList.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
    const row = e.target.closest && e.target.closest('.pl-row[role="button"]');
    if (!row || e.target !== row) return;               // the chevron's own Enter/Space arrives as a click
    e.preventDefault();
    openRow(row);
  });

}
// The project page's Team tab: the metrics and policy blocks' controls. Delegated on the detail
// screen (the page is rebuilt per project), the same keys the list cells used to answer to.
if (el.projDetail) {
  el.projDetail.addEventListener('click', async (e) => {
    // Team policy block FIRST: it shares the .tm-cell grid class, so the metrics branch below
    // would otherwise swallow its clicks.
    const tpCell = e.target.closest && e.target.closest('.tp-cell');
    if (tpCell) {
      const key = tpCell.dataset.key;
      if (e.target.closest('.tp-enable')) return void openPolicyEnableDialog(key, { mode: 'here' });
      if (e.target.closest('.tp-change')) return void openPolicyEnableDialog(key, { mode: 'follow', change: true });
      if (e.target.closest('.tp-open')) { location.hash = `team-policy/project:${key}`; return; }
      return;
    }
    const tmCell = e.target.closest && e.target.closest('.tm-cell');
    if (!tmCell) return;
    const key = tmCell.dataset.key;
    if (e.target.closest('.tm-enable')) return void openTmEnableDialog(key, { mode: 'here' });
    if (e.target.closest('.tm-change')) return void openTmEnableDialog(key, { mode: 'delegate', change: true });
    if (e.target.closest('.tm-push')) {
      const s = tmCache.data?.projects.find((x) => x.key === key);
      const btnEl = e.target.closest('.tm-push');
      const res = await withButton(btnEl, async () => {
        const m = await tmPost('/api/team-metrics/flush', s?.sinkSlug ? { slug: s.sinkSlug } : { scope: `project:${key}` });
        return m ? { ok: false, error: m } : { ok: true };
      }, { busy: 'Pushing…', done: 'Pushed' });
      if (res.skipped) return;
      if (res.ok) setTimeout(() => paintProjectTmCells(true), BUTTON_DONE_MS);
      else {
        await paintProjectTmCells(true);
        notify({ tone: 'err', title: 'Push failed', detail: res.error, key: 'tm-push',
          action: { label: 'Retry', run: () => document.querySelector(`#proj-detail .tm-cell[data-key="${cssEscape(key)}"] .tm-push`)?.click() } });
      }
      return;
    }
    // clicks elsewhere in the block (labels, the switch) are handled by 'change'
  });
  // 'change' (not click) for the switch — a checkbox inside a <label>.
  el.projDetail.addEventListener('change', async (e) => {
    const cb = e.target.closest && e.target.closest('input.tm-record');
    if (!cb) return;
    cb.disabled = true;
    const r = await fetch(`/api/projects/${encodeURIComponent(cb.dataset.key)}/team-metrics`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ record: cb.checked }),
    }).catch(() => null);
    const err = !r ? 'Worca did not answer.' : !r.ok ? ((await safeJson(r))?.error || `The server answered ${r.status}.`) : null;
    if (err) cb.checked = !cb.checked;      // revert on failure
    cb.disabled = false;
    paintProjectTmCells(true);
    if (err) notify({ tone: 'err', title: 'Could not change “Include my runs”', detail: err, key: `tm-record-${cb.dataset.key}` });
  });
}
if (el.projectAddBtn) el.projectAddBtn.addEventListener('click', addProjectFlow);
if (el.projAddSave) {
  el.projAddSave.addEventListener('click', saveProjectAdd);
  el.projAddCancel.addEventListener('click', closeProjectAddModal);
  const fillProjAdd = (p) => {
    el.projAddPath.value = p;
    if (!el.projAddName.value.trim()) el.projAddName.value = basenameOf(p);
    setProjAddMsg('');
  };
  const browseProjAddInWorca = () => openFolderBrowser(el.projAddPath.value.trim(), fillProjAdd, {
    multiple: true, onSelectMany: (paths) => projectsViewPicks(paths, { fill: fillProjAdd }),
  });
  el.projAddBrowse.addEventListener('click', async () => {
    el.projAddBrowse.disabled = true;
    try {
      const data = await pickFolder('project', { multiple: true });
      if (data && data.status === 'picked' && pickedPaths(data).length) projectsViewPicks(pickedPaths(data), { fill: fillProjAdd });
      else if (data && data.status === 'canceled') { /* user dismissed the dialog */ }
      else if (data && data.status === 'busy') setProjAddMsg('A folder dialog is already open — finish or cancel it first.', 'err');
      else await browseProjAddInWorca();                          // unsupported / error -> in-app browser
    } finally {
      el.projAddBrowse.disabled = false;
    }
  });
  // Worca's own browser, straight away: multi-select where the native dialog has none (Windows).
  if (el.projAddBrowseMany) el.projAddBrowseMany.addEventListener('click', () => { void browseProjAddInWorca(); });
  if (el.projAddTabs) {
    el.projAddTabs.addEventListener('click', (e) => {
      const tab = e.target.closest && e.target.closest('.md-tab');
      if (tab && !tab.disabled) setProjAddMode(tab.dataset.mode);
    });
    el.projCloneUrl.addEventListener('input', () => {
      el.projCloneName.placeholder = repoNameFromUrl(el.projCloneUrl.value) || 'the repository name';
    });
    el.projCloneUrl.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); void saveProjectAdd(); } });
  }
  el.projectAddModal.addEventListener('click', (e) => { if (e.target === el.projectAddModal) closeProjectAddModal(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && el.projectAddModal && !el.projectAddModal.classList.contains('hidden')) closeProjectAddModal();
  });
}
if (el.projectBulkModal) {
  el.projBulkSave.addEventListener('click', () => { void saveProjectBulk(); });
  el.projBulkClose.addEventListener('click', closeProjectBulkModal);
  el.projectBulkModal.addEventListener('click', (e) => { if (e.target === el.projectBulkModal) closeProjectBulkModal(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !el.projectBulkModal.classList.contains('hidden')) closeProjectBulkModal();
  });
}

// Test hook (mirrors window.__agents at app.js:4219).
if (typeof window !== 'undefined') {
  window.__projects = {
    loadProjectsView, renderProjectsList, buildProjectRow, deleteProject,
    confirmModal, addProjectFlow, openProjectAddModal, saveProjectAdd,
    openProjectBulkModal, saveProjectBulk, closeProjectBulkModal, openFolderBrowser,
  };
}

// ---- Agent creation wizard ---------------------------------------------------

function resetAgentWizard() {
  state.agentWizard = { step: 1, genId: '', abort: null, draft: null, ownMd: false };
}

async function enterAgentWizard() {
  if (!state.agentWizard.genId && !state.agentWizard.abort) resetAgentWizard();
  if (!state.agentsList.length) await loadAgentsList();
  const keys = state.agentsList.filter((a) => a.scope !== 'workspace-only').map((a) => a.key);
  buildChipChecks(el.agwBefore, keys, []);
  buildChipChecks(el.agwAfter, keys, []);
  showAgentWizardStep(state.agentWizard.step || 1);
  syncAgwStartEnabled();
}

function showAgentWizardStep(step) {
  state.agentWizard.step = step;
  for (let i = 1; i <= 3; i++) {
    const pane = document.getElementById(`agw-step-${i}`);
    if (pane) pane.classList.toggle('hidden', i !== step);
  }
}

function syncAgwStartEnabled() {
  const name = el.agwName ? el.agwName.value.trim() : '';
  const purpose = el.agwPurpose ? el.agwPurpose.value.trim() : '';
  const own = state.agentWizard.ownMd;
  const md = el.agwOwnMd ? el.agwOwnMd.value.trim() : '';
  if (el.agwStart) el.agwStart.disabled = !(name && (own ? md : purpose));
}

async function startAgentGenerate() {
  state.agentWizard.genId = ''; // gate stale events before the POST resolves
  if (el.agwStatus) el.agwStatus.textContent = 'Starting…';
  if (el.agwMsg) el.agwMsg.textContent = '';
  showAgentWizardStep(2);
  const abort = new AbortController();
  state.agentWizard.abort = abort;
  const body = {
    name: el.agwName.value.trim(),
    purpose: el.agwPurpose.value.trim(),
    details: el.agwDetails.value,
    expectedBefore: chipValues(el.agwBefore),
    expectedAfter: chipValues(el.agwAfter),
  };
  if (state.agentWizard.ownMd && el.agwOwnMd.value.trim()) body.userMarkdown = el.agwOwnMd.value;
  try {
    const res = await fetch('/api/agents/generate', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body), signal: abort.signal,
    });
    const data = await safeJson(res);
    if (!res.ok || !data.genId) {
      state.agentWizard.abort = null;
      showAgentWizardStep(1);
      setAgwStep1Error(data.error || res.status, data.code);
      return;
    }
    state.agentWizard.genId = data.genId;
    const ws = state.ws;
    if (ws && state.wsReady) { try { ws.send(JSON.stringify({ type: 'subscribe', genId: data.genId })); } catch { /* ignore */ } }
  } catch (err) {
    if (err && err.name === 'AbortError') return;
    state.agentWizard.abort = null;
    showAgentWizardStep(1);
    setAgwStep1Error(err.message);
  }
}

const AGW_STEP1_HINT = 'Name + purpose are required (or paste your own markdown).';
function resetAgwStep1Hint() {
  const hint = el.agwStep1Hint;
  if (!hint) return;
  claudeSignedOutHints.delete(hint);
  hint.classList.remove('err');
  hint.textContent = AGW_STEP1_HINT;
}
function setAgwStep1Error(message, code) {
  const hint = el.agwStep1Hint;
  if (!hint) return;
  if (code === 'claude-signed-out') { showClaudeSignedOut(hint, resetAgwStep1Hint); return; }
  claudeSignedOutHints.delete(hint);
  hint.classList.add('err');
  hint.textContent = `Generation error: ${message}`;
}

function onAgentGenEvent(msg) {
  if (!msg || !msg.genId || msg.genId !== state.agentWizard.genId) return; // stale/aborted gen
  if (msg.type === 'agentgen-progress') {
    if (el.agwStatus) el.agwStatus.textContent = msg.message || '';
    return;
  }
  if (msg.type === 'agentgen-done') {
    state.agentWizard.abort = null;
    state.agentWizard.draft = msg.draft || null;
    const root = document.getElementById('agw-step-3');
    if (root && msg.draft) {
      agentFormRender(root, msg.draft.meta || {}, {
        markdown: msg.draft.markdown || '',
        mockWriterRoles: state.mockWriterRoles,
        registryKeys: state.agentsList.map((a) => a.key),
      });
    }
    showAgentWizardStep(3);
    return;
  }
  if (msg.type === 'agentgen-error') {
    state.agentWizard.abort = null;
    state.agentWizard.genId = '';
    showAgentWizardStep(1);
    setAgwStep1Error(msg.message || 'failed');
  }
}

async function saveGeneratedAgent() {
  const root = document.getElementById('agw-step-3');
  const { meta, markdown, problems } = agentFormRead(root);
  // The wizard derives the key from the FINAL display name (agent-store.mjs:56):
  // the user may rename the draft on Step 3, and the key must follow. Only the
  // card editor PUTs an existing key.
  delete meta.key;
  if (problems.length) {   // decision P20: two rows with one form id never reach the store
    if (el.agwMsg) { el.agwMsg.textContent = problems.join(' · '); el.agwMsg.className = 'form-msg err'; }
    return;
  }
  if (el.agwMsg) { el.agwMsg.textContent = ''; el.agwMsg.className = 'form-msg'; }
  if (el.agwSave) el.agwSave.disabled = true;
  try {
    const res = await fetch('/api/agents', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ meta, markdown }),
    });
    const data = await safeJson(res);
    if (!res.ok) { // 400/409 keep the user on Step 3 with the error verbatim
      if (el.agwMsg) { el.agwMsg.textContent = data.error || `HTTP ${res.status}`; el.agwMsg.className = 'form-msg err'; }
      return;
    }
    invalidateAgentCaches();
    resetAgentWizard();
    setAgentsMsg(`Agent "${data.meta.key}" created.`, 'ok');
    location.hash = agentWizardReturn();
  } catch (err) {
    if (el.agwMsg) { el.agwMsg.textContent = err.message; el.agwMsg.className = 'form-msg err'; }
  } finally {
    if (el.agwSave) el.agwSave.disabled = false;
  }
}

function abortAgentGen() {
  const genId = state.agentWizard.genId;
  if (state.agentWizard.abort) { try { state.agentWizard.abort.abort(); } catch { /* ignore */ } }
  if (genId) {
    fetch('/api/agents/generate/stop', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ genId }),
    }).catch((e) => notify({ tone: 'err', title: 'Could not stop the generation', detail: e.message, key: 'agent-gen-stop' }));
    const ws = state.ws;
    if (ws && state.wsReady) { try { ws.send(JSON.stringify({ type: 'unsubscribe', genId })); } catch { /* ignore */ } }
  }
  state.agentWizard.abort = null;
  state.agentWizard.genId = '';
}

if (el.agwStart) el.agwStart.addEventListener('click', () => startAgentGenerate());
if (el.agwAbort) el.agwAbort.addEventListener('click', () => { abortAgentGen(); showAgentWizardStep(1); });
if (el.agwRegen) el.agwRegen.addEventListener('click', () => startAgentGenerate());
if (el.agwSave) el.agwSave.addEventListener('click', () => saveGeneratedAgent());
if (el.agwClose) el.agwClose.addEventListener('click', () => { location.hash = agentWizardReturn(); });
// The wizard has two doors: the Agents page (expert) and the Composer palette's "Create agent…"
// (advanced, docs/ui-levels.md). Cancel and Save go back through the door that was used.
let agentWizardFrom = 'agents';
function agentWizardReturn() { const back = agentWizardFrom; agentWizardFrom = 'agents'; return back; }
document.getElementById('gv-create-agent')?.addEventListener('click', () => { agentWizardFrom = 'composer'; location.hash = 'agent-create'; });
for (const input of [el.agwName, el.agwPurpose, el.agwOwnMd]) {
  if (input) input.addEventListener('input', syncAgwStartEnabled);
}
if (el.agwOwnToggle) el.agwOwnToggle.addEventListener('click', () => {
  state.agentWizard.ownMd = !state.agentWizard.ownMd;
  el.agwOwnToggle.classList.toggle('on', state.agentWizard.ownMd);
  el.agwOwnToggle.setAttribute('aria-checked', String(state.agentWizard.ownMd));
  if (el.agwOwnPane) el.agwOwnPane.classList.toggle('hidden', !state.agentWizard.ownMd);
  syncAgwStartEnabled();
});
// role=switch needs Space/Enter (mirrors the mock + autoscroll switches).
if (el.agwOwnToggle) el.agwOwnToggle.addEventListener('keydown', (e) => {
  if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
  e.preventDefault();
  el.agwOwnToggle.click();
});

if (typeof window !== 'undefined') {
  window.__agw = { enterAgentWizard, showAgentWizardStep, startAgentGenerate, onAgentGenEvent, saveGeneratedAgent, abortAgentGen, resetAgentWizard };
}

// ---------------------------------------------------------------------------
// Start a run
// ---------------------------------------------------------------------------
el.form.addEventListener('submit', async (e) => {
  e.preventDefault();
  // Enter in any field submits the form directly, bypassing the disabled Start
  // button — so the in-flight window has to be closed here too, not only via
  // start.disabled, or a second Enter starts the same run twice.
  if (startSubmitInFlight) return;
  setFormMsg('', '');
  clearFieldErrors(el.form); cardAlert(newFormCard(), null);

  // Target branch (§5.4 mutual exclusivity): workspace mode sends {workspaceId}
  // and NO projectDir; project mode sends {projectDir} and NO workspaceId.
  const target = state.runTarget === 'workspace' ? 'workspace' : 'project';
  let projectDir = '';
  let workspaceId = '';
  let workspaceName = '';
  let workspaceProjectNames = null;
  if (target === 'workspace') {
    workspaceId = (el.workspaceSelect && el.workspaceSelect.value) || '';
    if (!workspaceId) return fieldError(el.workspaceSelect, 'Select a workspace first (or create one).');
    const ws = state.workspaces.find((w) => w && w.id === workspaceId);
    workspaceName = (ws && ws.name) || '';
    workspaceProjectNames = ws && Array.isArray(ws.projectPaths)
      ? ws.projectPaths.map(projectName) : null;
  } else {
    projectDir = selectedProjectPath();
    if (!projectDir) return fieldError(el.projectSelect, 'Select a project first (or add one).');
  }

  const source = (el.sourceRadios.find((r) => r.checked) || {}).value || 'prompt';
  const promptText = el.prompt.value.trim();
  const mdText = el.promptMarkdown.value.trim();
  const title = el.title.value.trim();

  // Memory defragment (agent memory §7.3): one scope, a synthesised brief, and the `normal`
  // guardrails the API wrappers use unless the user deliberately picked another set.
  const isDefragRun = state.workflowId === MEMORY_DEFRAG_WORKFLOW_ID;

  const body = {
    title: title || undefined,
    workflowId: state.workflowId || 'wf_default',
    // Omit-when-default: 'permissive' IS the server default, so the key is
    // absent on default runs — byte-identical legacy request bodies. (The
    // server normalizes omitted/''/null to 'permissive'; always-sending would
    // be equivalent but would change every legacy-shaped request for no gain.)
    guardrailsId: isDefragRun && state.guardrailsId === 'permissive' ? 'normal'
      : (state.guardrailsId !== 'permissive' ? state.guardrailsId : undefined),
    // MCP registry (§6.2): absent unless something is opted out, so default bodies stay byte-identical;
    // a memory-defrag run starts no registry servers (§6.1), so it sends none.
    mcpOptOut: state.mcpOptOut.length && !isDefragRun ? [...state.mcpOptOut] : undefined,
    mock: el.mock.checked,
    sourceBranch: (el.sourceBranch && el.sourceBranch.value) || undefined,
    featureBranch: (el.featureBranch && el.featureBranch.value.trim()) || undefined,
    // Auto only (spec §7.2): this run's switch; the server falls back to the project setting
    // when absent. JSON.stringify drops an own key whose value is `undefined`.
    humanInLoop: state.workflowId === AUTO_WORKFLOW_ID ? !!(el.humanInLoop && el.humanInLoop.checked) : undefined,
    // Only this workflow carries it: every other run body stays byte-identical to the legacy one.
    memoryScope: isDefragRun ? state.memoryScope : undefined,
    // Night mode per-run opt-in: only when ticked, so every other run body stays byte-identical.
    nightMode: el.nightMode && el.nightMode.checked ? true : undefined,
    // Engine: only a non-default one is sent, and the consent only with it and only when
    // ticked, so a Claude run's body stays byte-identical.
    // The engine shown is the engine that runs: Claude goes unsent only when the default is KNOWN
    // to be Claude (a failed or stale defaults read must not let the server pick a Codex default).
    engine: state.engine !== 'claude' ? state.engine : (state.runDefaults?.engine?.value === 'claude' ? undefined : 'claude'),
    allowUnguardedEngine: state.engine !== 'claude' && el.engineAllowUnguarded && el.engineAllowUnguarded.checked ? true : undefined,
  };
  if (target === 'workspace') {
    body.workspaceId = workspaceId;
    // Per-project source branches: { [projectKey]: branch }. Omit empties (the
    // "auto" placeholder) so the server falls back to each project's default.
    const byKey = {};
    if (el.wsSourceBranches) {
      el.wsSourceBranches.querySelectorAll('select.ws-src-select').forEach((s) => {
        const key = s.dataset.projectKey;
        const val = (s.value || '').trim();
        if (key && val) byKey[key] = val;
      });
    }
    if (Object.keys(byKey).length) body.sourceBranchByKey = byKey;
    // The single #sourceBranch is hidden in workspace mode — don't send it. (The
    // body literal sets `sourceBranch: ... || undefined`, so the key still EXISTS
    // with value undefined; delete it so `'sourceBranch' in body` is false.)
    delete body.sourceBranch;
  } else {
    body.projectDir = projectDir;
  }
  // Run chains: the previous run's branch is a flag on the wire, never a branch name.
  if (body.sourceBranch === PREVIOUS_BRANCH) { delete body.sourceBranch; body.sourceFromPrevious = true; }
  if (target === 'workspace' && el.wsSourcePrevious && el.wsSourcePrevious.classList.contains('on') && pendingSchedule && pendingSchedule.after) {
    delete body.sourceBranchByKey; body.sourceFromPrevious = true;
  }

  const psrc = state.activePluginSource;
  if (isDefragRun) {
    // A defragment run needs no task text: synthesise the same brief and title the API wrapper
    // sends, whatever the shared source switch says (the markdown / plugin panes are skipped).
    const pn = selectedProjectName();
    body.prompt = promptText || (state.memoryScope === 'project'
      ? `Defragment the memory of project ${pn}.` : 'Defragment global memory.');
    if (!title) body.title = state.memoryScope === 'project' ? `Memory defragment: ${pn}` : 'Memory defragment (global)';
  } else if (psrc) {
    const picked = collectSourcePane(el.pluginSourcePane);
    if (picked.error) return cardAlert(newFormCard(), { title: 'Run not started', detail: picked.error });
    // The profile travels with the run and is pinned onto the row, so a result
    // is reported back to the instance the task actually came from even if the
    // project is re-bound in the meantime.
    body.source = {
      type: 'plugin', plugin: psrc.plugin, sourceId: psrc.sourceId,
      taskId: picked.taskId, inputs: picked.inputs,
      profile: state.activePluginProfile || undefined,
    };
  } else if (source === 'markdown') {
    if (!mdText) return fieldError(el.promptMarkdown, 'Provide markdown text or load a .md file.');
    body.promptMarkdown = mdText;
  } else {
    if (!promptText) return fieldError(el.prompt, 'Provide a prompt describing the task.');
    body.prompt = promptText;
  }

  // A time picked earlier (Schedule… in the split menu, Schedules › Schedule a run, Change…)
  // rides the same POST /api/run body — `scheduledFor` (once) or `repeat` (recurring).
  const scheduling = !!pendingSchedule;
  // #527: Auto-sync only when the person touched the switch for this run (untouched, each
  // member follows its own sync.beforeRun). Before the schedule merge, so the sheet's choice wins.
  if (state.sync.blocked && levelAtLeast('advanced')) return cardAlert(newFormCard(), { title: 'Run not started', detail: `${state.sync.blocked} can’t start from origin yet. Push its commits, or use Local copy.` });
  if (state.sync.autoSync !== null && syncApplies() && levelAtLeast('advanced')) body.syncBeforeStart = state.sync.autoSync;
  if (scheduling) {
    const { sync: schedSync, ...schedRest } = pendingSchedule;
    Object.assign(body, schedRest);
    // branchGone is a form hint (openAfterForNew), never part of the wire's { kind, id, title }.
    if (body.after && 'branchGone' in body.after) { const { branchGone: _bg, ...a } = body.after; body.after = a; }
    if (schedSync && typeof schedSync.beforeRun === 'boolean') body.syncBeforeStart = schedSync.beforeRun;
    if (schedSync && (schedSync.onDiverged === 'origin' || schedSync.onDiverged === 'fail')) body.syncOnDiverged = schedSync.onDiverged;
  }

  // #555: withButton owns #start-btn from here, and reads undefined as success, so every exit
  // returns an explicit { ok }. A failed or cancelled start never shows "Started".
  const notStarted = (detail) => {
    cardAlert(newFormCard(), { title: scheduling ? 'Not scheduled' : 'Run not started', detail });
    return { ok: false };
  };

  await withButton(el.startBtn, async () => {
    // Guard the whole in-flight window: applyBudgetToNewView also drives
    // start.disabled, and this run's own creation event repaints it. Set INSIDE the callback:
    // idleDisabled reads it, so set before withButton it would make a second Start during the
    // previous one's "Started" look gated, skip it and leave the flag stuck.
    startSubmitInFlight = true;
    if (el.startMore) el.startMore.disabled = true;
    // Upload the selected extra files' bytes; the server writes them to a temp
    // dir and the orchestrator copies them into the pipeline's extras/ folder.
    let extras = [];
    try {
      extras = await collectExtras();
    } catch {
      extras = [];
    }
    if (extras.length) body.extras = extras;

    try {
      let res = await fetch('/api/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      let data = await safeJson(res);
      let lastSentBody = body;
      // Team total cap (team-policy design §7, board 9): soft — ask once, resend with the
      // acknowledgement (and its reason) recorded; a required reason re-asks.
      if (!res.ok && data && (data.needsPolicyAck || data.code === 'reason_required')) {
        const choice = await policyRefusalRetry(data, res.status);
        if (choice) {
          lastSentBody = { ...body, pastTeamCap: true, ...(choice.reason ? { policyReason: choice.reason } : {}) };
          res = await fetch('/api/run', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(lastSentBody),
          });
          data = await safeJson(res);
        }
      }
      // #527: the base diverged (or could not be fetched) — ask once, resend with the choice.
      if (!res.ok && data && (data.code === 'sync-diverged' || data.code === 'sync-fetch-failed')) {
        const choice = await chooseSyncRefusal(data);
        if (!choice) {
          startSubmitInFlight = false;
          if (el.startMore) el.startMore.disabled = false;
          notify({ tone: 'warn', title: 'Start cancelled' });
          return { ok: false, cancelled: true };
        }
        lastSentBody = { ...lastSentBody, syncPolicy: choice };   // keeps pastTeamCap/policyReason
        res = await fetch('/api/run', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(lastSentBody) });
        data = await safeJson(res);
      }
      if (el.startMore) el.startMore.disabled = false;
      // The engine gate refused before anything started: say why under the form, offer the
      // consent when it lifts the refusal, and let the user start again.
      if (!res.ok && data && data.code === 'engine-refused') {
        startSubmitInFlight = false;
        showEngineRefusal(data);
        return notStarted(data.overridable ? 'Tick Allow unguarded to run anyway, or pick Claude.' : (data.error || 'The engine cannot run this.'));
      }
      if (!res.ok || !data.runId) {
        startSubmitInFlight = false;
        // The alert title already says "Run not started" / "Not scheduled".
        return notStarted(data.error || `The server answered ${res.status}.`);
      }
      // 202: nothing is running — the request is a ticket now. Show it where it lives.
      if (data.status === 'scheduled') {
        startSubmitInFlight = false;
        setPendingSchedule(null);   // the form is a plain Start run form again
        resetSyncChoice();
        showEngineRefusal(null);
        // Keep the warn tone when the server attached a budget warning. showView('schedules')
        // already shows the ticket, so the toast needs no Open action.
        notify({ tone: data.budgetWarning ? 'warn' : 'ok', title: 'Scheduled', detail: data.budgetWarning || title || '' });
        showView('schedules');
        return { ok: true };
      }

      // begin tracking the new run (creates a local model + switches to Running)
      beginRun(data.runId, projectDir, title,
        target === 'workspace' ? { workspaceId, workspaceName, projectNames: workspaceProjectNames } : {});
      // Re-enable the form so more runs can be started concurrently — unless the
      // budget just went over, in which case idleDisabled keeps Start disabled.
      startSubmitInFlight = false;
      resetSyncChoice();
      showEngineRefusal(null);
      // D6: the user is on the run's page now, so the result is a toast, not a #form-msg line.
      notify({ tone: 'ok', title: 'Run started', detail: title || '', key: `run-${data.runId}`,
        action: { label: 'Open run', run: () => { location.hash = rdHash(data.runId); } } });
      if (extras.length) {
        appendLog({
          source: 'ui',
          level: 'system',
          text: `uploaded ${extras.length} extra file(s): ${extras.map((e) => e.name).join(', ')}`,
          ts: Date.now(),
        });
      }
      return { ok: true };
    } catch (err) {
      startSubmitInFlight = false;
      if (el.startMore) el.startMore.disabled = false;
      return notStarted(`Error: ${err.message}`);
    }
  }, { busy: scheduling ? 'Scheduling…' : 'Starting…', done: scheduling ? 'Scheduled' : 'Started',
    idleDisabled: () => !!budgetState.budget?.blocked || startSubmitInFlight });
});

// #555: card alerts for New pipeline go into #run-form, directly above its own action row
// (div.actions[data-card-actions], the parent of #start-split and a direct child of the form).
// cardAlert picks the form's OWN row (:scope >); the first descendant row in document order is
// the hidden inline add-project panel's .add-project-actions.
function newFormCard() { return el.form; }

// The split Start button's menu. "Schedule…" is a MODE, not a submit: it opens the sheet at
// once, before any prompt is typed, exactly like Schedules › Schedule a run (#new/schedule).
// A time picked before the task waits on the form; Change… on the line re-opens the sheet.
// The sheet's answer waits on the
// form ({scheduledFor}|{repeat}, ifMissed, graceMin) and Start run reads as Schedule until it
// is used or dropped. Never persisted: a reload is a plain form.
let pendingSchedule = null;
const newScheduleSheetOpts = (runTitle = '') => ({
  mode: 'create', runTitle, defaults: schedulesView.defaults, candidates: fetchAfterCandidates,
  warning: 'A scheduled run is unattended. If this workflow asks questions, the run waits for your answer — chat notifications can reach you.',
  sync: scheduleSyncOpt(),
});
/** The sheet's opt-in Sync block (#527, D16): form state, not server defaults. A scheduled run
 *  cannot ask, so the project's 'ask' reads as 'origin' (D2); workspace = each member's own. */
function scheduleSyncOpt() {
  const od = state.sync.block?.settings?.onDiverged;
  const projectOnDiverged = state.sync.block ? (od === 'fail' ? 'fail' : 'origin') : null;
  return {
    show: syncApplies() && levelAtLeast('advanced'),
    beforeRun: state.sync.autoSync,                 // null = untouched → each member's own sync.beforeRun
    shownBeforeRun: shownAutoSync(),
    onDiverged: state.runTarget === 'workspace' ? null : projectOnDiverged,
  };
}
const pendingScheduleInitial = () => (pendingSchedule
  ? {
    ...(pendingSchedule.after
      ? { after: pendingSchedule.after, afterPolicy: pendingSchedule.afterPolicy }
      : pendingSchedule.repeat
        ? { rule: pendingSchedule.repeat.rule, overlap: pendingSchedule.repeat.overlap, maxFailures: pendingSchedule.repeat.maxFailures, ifMissed: pendingSchedule.ifMissed, graceMin: pendingSchedule.graceMin }
        : { scheduledFor: pendingSchedule.scheduledFor, ifMissed: pendingSchedule.ifMissed, graceMin: pendingSchedule.graceMin }),
    // #527: reopening shows the previous Sync choice rather than the form's switch.
    ...(pendingSchedule.sync ? { sync: pendingSchedule.sync } : {}),
  }
  : {});
function setPendingSchedule(pick) {
  pendingSchedule = pick || null;
  if (!el.newSched) return;
  el.newSched.hidden = !pendingSchedule;
  if (el.startBtnLabel) el.startBtnLabel.textContent = pendingSchedule ? 'Schedule' : 'Start run';
  const play = document.getElementById('start-btn-play');
  const clock = document.getElementById('start-btn-clock');
  // toggleAttribute, not .hidden: an <svg> is not an HTMLElement, so the property is a no-op on it.
  if (play) play.toggleAttribute('hidden', !!pendingSchedule);
  if (clock) clock.toggleAttribute('hidden', !pendingSchedule);
  if (!pendingSchedule) { syncPreviousBranchEverywhere(); return; }
  if (pendingSchedule.after) {
    el.newSchedBadge.textContent = 'After run';
    el.newSchedText.textContent = `Starts when ‘${pendingSchedule.after.title || 'the run before it'}’ finishes`
      + (pendingSchedule.after.branchGone ? ' · its branch is gone, so pick a source branch' : '');
  } else if (pendingSchedule.repeat) {
    el.newSchedBadge.textContent = 'Repeats';
    el.newSchedText.textContent = describeRule(pendingSchedule.repeat.rule);
  } else {
    const ms = Date.parse(pendingSchedule.scheduledFor);
    el.newSchedBadge.textContent = 'Scheduled';
    el.newSchedText.textContent = Number.isFinite(ms) ? `Starts ${formatInstant(ms, browserTimeZone())}` : 'Starts later';
  }
  if (el.wsSourcePrevious) delete el.wsSourcePrevious.dataset.off;   // a NEW pick starts with the switch ON
  syncPreviousBranchEverywhere();
}
/** Schedules › Schedule a run (#new/schedule): pick the time first, then describe the task. */
async function openScheduleForNew() {
  const el0 = el.prompt;
  const titleEl = document.getElementById('title');
  const runTitle = titleEl && typeof titleEl.value === 'string' ? titleEl.value.trim() : '';
  const picked = await openScheduleSheet({ ...newScheduleSheetOpts(runTitle), initial: pendingScheduleInitial() });
  if (picked) setPendingSchedule(picked);
  try { el0?.focus(); } catch { /* jsdom */ }
}
el.newSchedChange?.addEventListener('click', () => { void openScheduleForNew(); });
el.newSchedClear?.addEventListener('click', () => setPendingSchedule(null));
// Run chains: with a predecessor picked, the project-mode Source branch select leads with
// "Branch of the run before it" (PREVIOUS_BRANCH), selected by default; dropping the pick removes
// it again. A workspace member select never gets it, and neither does the disabled stand-in the
// single select becomes in workspace mode — the switch below carries the flag there.
function syncPreviousBranchOption(select) {
  if (!select || select.classList.contains('ws-src-select')) return;
  const want = !!(pendingSchedule && pendingSchedule.after && !pendingSchedule.after.branchGone) && state.runTarget !== 'workspace';
  const has = [...select.options].find((o) => o.value === PREVIOUS_BRANCH);
  if (want && !has) {
    const opt = document.createElement('option');
    opt.value = PREVIOUS_BRANCH; opt.textContent = 'Branch of the run before it';
    select.insertBefore(opt, select.firstChild);
    select.value = PREVIOUS_BRANCH;
  } else if (!want && has) {
    const wasPrev = select.value === PREVIOUS_BRANCH;
    has.remove();
    if (wasPrev) {
      const cur = (select.dataset.current && [...select.options].find((o) => o.value === select.dataset.current)) || select.options[0];
      if (cur) select.value = cur.value;
    }
  }
}
function syncPreviousBranchEverywhere() {
  const before = el.sourceBranch ? el.sourceBranch.value : '';
  syncPreviousBranchOption(el.sourceBranch);
  // The value moved without a change event: repaint the Sync row (hidden for "the run before it",
  // which also keeps a touched Auto-sync switch out of the POST), or re-read HEAD's branch.
  if (el.sourceBranch && el.sourceBranch.value !== before && state.runTarget !== 'workspace') {
    if (el.sourceBranch.value === PREVIOUS_BRANCH || (state.sync.block && state.sync.block.base === effectiveBase())) paintSyncRowNow();
    else void refreshSyncStatusQuiet();
  }
  const wsPick = !!(pendingSchedule && pendingSchedule.after && !pendingSchedule.after.branchGone) && state.runTarget === 'workspace';
  if (el.wsSourcePreviousRow) el.wsSourcePreviousRow.classList.toggle('hidden', !wsPick);
  // ON by default with a pick in workspace mode; a deliberate OFF (the click handler marks it) survives
  // member re-renders and target switches, and the FRESH member selects follow whichever it is — every
  // renderWorkspaceSourceBranches() rebuilds them enabled, so this is the one place that re-applies it.
  if (el.wsSourcePrevious) setWsSourcePrevious(wsPick && el.wsSourcePrevious.dataset.off !== '1');
}
function setWsSourcePrevious(on) {
  if (!el.wsSourcePrevious) return;
  el.wsSourcePrevious.classList.toggle('on', on);
  el.wsSourcePrevious.setAttribute('aria-checked', on ? 'true' : 'false');
  el.wsSourceBranches?.querySelectorAll('select.ws-src-select').forEach((s) => { s.disabled = on || s.dataset.missing === '1'; });
  if (state.runTarget === 'workspace') paintBranches();
}
const flipWsSourcePrevious = () => {
  const on = !el.wsSourcePrevious.classList.contains('on');
  if (on) delete el.wsSourcePrevious.dataset.off; else el.wsSourcePrevious.dataset.off = '1';
  setWsSourcePrevious(on);
};
el.wsSourcePrevious?.addEventListener('click', flipWsSourcePrevious);
el.wsSourcePrevious?.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); flipWsSourcePrevious(); } });

async function fetchAfterCandidates() {
  const q = state.runTarget === 'workspace'
    ? (state.selectedWorkspaceId ? `workspaceId=${encodeURIComponent(state.selectedWorkspaceId)}` : '')
    : (selectedProjectPath() ? `projectDir=${encodeURIComponent(selectedProjectPath())}` : '');
  if (!q) return { runs: [], tickets: [] };
  const res = await fetch(`/api/schedules/after-candidates?${q}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

/** #new/after/<pipelineId> | #new/after/t:<ticketId>: pick the predecessor first, then describe the task. */
const ENDED_BADLY = ['error', 'stopped', 'interrupted'];
// A TICKET that ended this way can never be waited for (resolveAfterRef refuses it under either policy —
// scheduler.mjs BAD_TICKET_REASON, same words); say so here rather than at Start.
const ENDED_TICKET = { missed: 'was missed', canceled: 'was canceled', failed: 'could not start', skipped: 'was skipped' };
async function openAfterForNew(ref) {
  const id = ref.startsWith('t:') ? ref.slice(2) : ref;
  let r;
  try {
    const res = await fetch(`/api/schedules/after/${encodeURIComponent(id)}`);
    if (!res.ok) { setFormMsg((await safeJson(res)).error || 'That run was not found.', 'err'); return; }
    r = await res.json();
  } catch { setFormMsg('That run was not found.', 'err'); return; }
  if (r.kind === 'ticket' && ENDED_TICKET[r.status]) { setFormMsg(`‘${r.title || 'That run'}’ ${ENDED_TICKET[r.status]} — nothing to wait for.`, 'err'); return; }
  if (r.workspaceId) {
    // Load (or reuse) the workspace list BEFORE switching target: setRunTarget('workspace') calls
    // ensureWorkspaceOptions() un-awaited, and a second concurrent load would re-render the members.
    await ensureWorkspaceOptions();
    if (!state.workspaces.some((w) => w && w.id === r.workspaceId)) { setFormMsg('That run’s workspace is not registered.', 'err'); return; }
    setRunTarget('workspace');
    if (el.workspaceSelect) { el.workspaceSelect.value = r.workspaceId; el.workspaceSelect.dispatchEvent(new window.Event('change', { bubbles: true })); }
  } else if (r.projectDir) {
    // The boot-time loadProjects() is not awaited, and GET /api/schedules/after/:id is a sync DB
    // read that can answer before the async registry read — and a project registered after boot is
    // in the registry but not in state.projects yet. On a miss, reload the list once and look again.
    const find = () => state.projects.findIndex((x) => x && x.path === r.projectDir);
    let idx = find();
    if (idx < 0) { await loadProjects(); idx = find(); }
    // A TICKET predecessor answers with its own projectDir whether or not that project is
    // registered here, so "not registered" is the `idx < 0` case — not only a null projectDir.
    if (idx < 0) { setFormMsg('That run’s project is not registered.', 'err'); return; }
    setRunTarget('project');
    el.projectSelect.selectedIndex = idx + 1;      // +1 past the placeholder (the applyAskPrefill idiom)
    await onProjectChanged();
    await refreshBranches(selectedProjectPath());   // onProjectChanged does not await the branch fetch
  } else { setFormMsg('That run’s project is not registered.', 'err'); return; }
  // A predecessor that already ended badly can only be waited for under the any policy
  // (resolveAfterRef refuses it under done) — preset the switch the sheet would need.
  // branchGone: the predecessor finished but its feature branch no longer resolves (an archived
  // or restored run) — syncPreviousBranchOption then leaves "Branch of the run before it" out.
  setPendingSchedule({ after: { kind: r.kind, id: r.id, title: r.title || null, branchGone: !!r.branchGone }, afterPolicy: ENDED_BADLY.includes(r.status) ? 'any' : 'done' });
  try { el.prompt?.focus(); } catch { /* jsdom */ }
}
function closeStartMenu() {
  if (!el.startMenu || el.startMenu.hidden) return;
  el.startMenu.hidden = true;
  el.startMore?.setAttribute('aria-expanded', 'false');
}
if (el.startMore && el.startMenu) {
  el.startMore.addEventListener('click', (e) => {
    e.stopPropagation();
    const open = el.startMenu.hidden;
    el.startMenu.hidden = !open;
    el.startMore.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) el.startMenuSchedule?.focus();
  });
  el.startMenuNow?.addEventListener('click', () => { closeStartMenu(); setPendingSchedule(null); el.form.requestSubmit(el.startBtn); });
  el.startMenuSchedule?.addEventListener('click', () => { closeStartMenu(); void openScheduleForNew(); });
  document.addEventListener('click', (e) => { if (!e.target.closest('#start-split')) closeStartMenu(); });
  el.startMenu.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.stopPropagation(); closeStartMenu(); el.startMore.focus(); }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const items = [...el.startMenu.querySelectorAll('button')];
      const i = items.indexOf(document.activeElement);
      items[(i + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length].focus();
    }
  });
}

// Create the local run model for a run THIS tab just started and switch to the
// Running view. We do NOT send a subscribe here: live events arrive via the
// server's broadcast, and a subscribe would double-replay this run's buffer on
// the next hello.
// [v2/C2] beginRun is POSITIONAL. opts is an optional 4th arg carrying workspace
// attribution ({workspaceId, workspaceName}); in workspace mode the card label
// prefers the workspace name. Project mode passes {} and is byte-identical.
function beginRun(runId, projectDir, title, opts = {}) {
  const label = title || opts.workspaceName || '(untitled)';
  const r = upsertRun({
    runId,
    title: label,
    projectDir: projectDir || '',
    status: 'starting',
    local: true,
    kind: opts.workspaceId ? 'workspace-run' : 'run',
    workspaceId: opts.workspaceId || undefined,
    workspaceName: opts.workspaceName || undefined,
    projectNames: Array.isArray(opts.projectNames) && opts.projectNames.length ? opts.projectNames : undefined,
  });
  hideViewer();
  updateNavCounts();
  gs.startedRunId = runId;   // the Getting-started tours end on THIS run's page
  // Straight onto the new run's own page (its glance), not the Runs list: the list
  // is where you pick among runs, and you just picked this one. Name the run: a bare
  // route would first reopen (and acknowledge) the remembered run.
  showView('running', runId);
  renderRunningView();
  location.hash = rdHash(runId);
}

function setFormMsg(text, kind) {
  el.formMsg.textContent = text;
  el.formMsg.className = 'form-msg' + (kind ? ' ' + kind : '');
}

// ---------------------------------------------------------------------------
// Settings view: the machine-wide Worca root folder + the projects root
// (§5.1) whose CLAUDE.md / .claude/skills / .mcp.json every pipeline agent sees.
// ---------------------------------------------------------------------------
// One contract for both fields: value = the RAW setting (blank when unset),
// placeholder = what applies while it IS blank. `projectsRootDefault` is that
// fallback for the projects root — the WORCA_PROJECTS_ROOT override when it is
// exported, else the home folder — so a blank field really means "use the
// default", and Save round-trips a blank as a blank instead of persisting a path
// the user never typed.
function paintSettings(data) {
  el.settingsRoot.value = data.root || '';
  el.settingsRoot.placeholder = data.default || '';
  if (el.settingsProjectsRoot) {
    el.settingsProjectsRoot.value = data.projectsRoot || '';
    el.settingsProjectsRoot.placeholder = projectsRootFallback(data);
  }
  settingsCardPainted('settingsSave');
}

// `default` is the pre-projectsRoot payload's only default; keep it as the
// fallback so an older/partial response still fills the placeholder.
const projectsRootFallback = (data) => data.projectsRootDefault || data.default || '';

// About card: painted from the `app` block of GET /api/settings. A missing or
// malformed payload leaves the static markup (including target/rel) untouched.
function paintAbout(info) {
  if (!info) return;
  if (el.aboutVersion && info.version) {
    el.aboutVersion.textContent = info.version;
    // Links the version to its release tag; a missing/malformed URL leaves the
    // anchor href-less, i.e. plain text.
    if (typeof info.releaseUrl === 'string' && info.releaseUrl) el.aboutVersion.href = info.releaseUrl;
  }
  if (el.aboutRepoLink && typeof info.repoUrl === 'string' && info.repoUrl) {
    el.aboutRepoLink.href = info.repoUrl;
    el.aboutRepoLink.textContent = info.repoUrl.replace(/^https?:\/\//, '');
  }
  // The two feedback anchors (Task 8). Left alone when the server sends no bugsUrl,
  // so the static hrefs in index.html keep working.
  paintAboutInto(document, info);
}

// #555 D8: a failed Settings GET is shown above the tabs, at every UI level.
function setSettingsLoadMsg(text) {
  const n = document.getElementById('settingsLoadMsg');
  if (!n) return;
  n.textContent = text ? `Could not load settings: ${text}` : '';
  n.hidden = !text;
}

async function loadSettings() {
  if (!el.settingsRoot) return;
  try {
    const res = await fetch('/api/settings');
    const data = await safeJson(res);
    if (!res.ok) { setSettingsLoadMsg(data.error || `HTTP ${res.status}`); return; }
    paintSettings(data);
    paintTheme(data.theme);
    levelCtl.confirm(data.uiLevel);
    paintAbout(data.app);
    paintBudgetSettings(data);
    paintAskSettings(data);
    paintScheduleSettings(data);
    paintNightSettings(data);
    paintSyncSettings(data);
    paintActionsSettings(data);
    paintDebugSpawnSettings(data);
    await paintTitleModelSettings(data);
    await paintAutoModelSettings(data);
    await paintPrDescModelSettings(data);
    await paintEngineSettings(data);
    await paintWorkspaceScanModelsSettings(data);
    paintBudgetReadout();
    paintTeamCapsReadout();                 // team policy (design board 7): each home's caps, read-only
    refreshBudget();
    paintChatSettings(data.chat);
    paintCredentials();
    loadAskHistory();
    setSettingsLoadMsg('');
  } catch (e) { setSettingsLoadMsg(e.message || 'network error'); }
}

// ── Chat notifications card (chat-connectivity-design.md §4.8) ────────────────

// Settings › My model credentials (credential broker, docs/credential-broker.md): the card
// stays hidden unless worca runs with a broker. Status only; keys live on the key page.
async function paintCredentials() {
  const card = document.getElementById('credentials-card');
  const host = document.getElementById('credentialsHost');
  if (!card || !host) return;
  let data;
  try { data = await safeJson(await fetch('/api/credentials')); } catch { data = { enabled: false }; }
  card.hidden = !data || data.enabled !== true;
  if (card.hidden) return;
  host.replaceChildren(renderCredentials(data));
}

async function paintChatSettings(prefs) {
  if (!el.chatSettingsHost) return;
  let channels = [];
  try {
    const cs = await safeJson(await fetch('/api/chat/status'));
    channels = cs.channels || [];
  } catch { /* render prefs-only */ }
  el.chatSettingsHost.replaceChildren(renderChatSettings({ prefs, channels }));
  settingsCardPainted('chatSettingsSave');
}

// No repaint on success (and a chat-only POST sends no settings-changed): the tracker's
// markClean in postSettingsCard is what clears the card.
if (el.chatSettingsSave) {
  el.chatSettingsSave.addEventListener('click', (e) => postSettingsCard(
    { chat: collectChatSettings(el.chatSettingsHost) },
    { card: document.getElementById('chat-settings-card'), button: e.currentTarget, dirty: settingsCardDirty('chatSettingsSave') }));
  settingsCardDirty('chatSettingsSave');
}

// Delegated Test buttons: explicit user action -> POST /api/chat/test. The button shows
// Sending… → Delivered (#555); a failure is a card alert naming the chats it missed.
if (el.chatSettingsHost) el.chatSettingsHost.addEventListener('click', async (e) => {
  const t = e.target;
  if (!t || !t.classList || !t.classList.contains('chat-test')) return;
  const card = document.getElementById('chat-settings-card');
  cardAlert(card, null);
  await withButton(t, async () => {
    let res;
    try {
      res = await fetch('/api/chat/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ plugin: t.dataset.plugin, channelId: t.dataset.channelId }),
      });
    } catch (err) {
      cardAlert(card, { title: 'Test message not sent', detail: `Worca did not answer (${err.message}).` });
      return { ok: false, error: err.message };
    }
    const data = (await safeJson(res)) || {};
    if (!res.ok) {
      const error = data.error || `The server answered ${res.status}.`;
      cardAlert(card, { title: 'Test message not sent', detail: error });
      return { ok: false, error };
    }
    const failed = (data.results || []).filter((r) => !r.ok);
    if (!failed.length) return { ok: true };
    const detail = failed[0].error?.message || failed[0].error?.kind || '';
    cardAlert(card, { title: `Delivery failed for ${failed.map((f) => f.chatId).join(', ')}`, detail });
    return { ok: false, error: detail };
  }, { busy: 'Sending…', done: 'Delivered' });
});

// Live channel-status events patch every visible badge in place (plugins view
// cards + the settings card) without a refetch.
function onChannelStatus(msg) {
  const key = `${msg.plugin}/${msg.channelId}`;
  for (const b of document.querySelectorAll(`.pl-channel[data-channel-key="${CSS.escape(key)}"]`)) {
    b.replaceWith(channelBadge(document, { ...msg, displayName: b.textContent.split(' · ')[0] }));
  }
  for (const b of document.querySelectorAll(`.chat-state[data-channel-key="${CSS.escape(key)}"]`)) {
    const stateCls = { connected: 'green', degraded: 'waiting', connecting: 'waiting', unconfigured: 'waiting' }[msg.state] || 'red';
    b.className = `badge ${stateCls} chat-state`;
    b.textContent = msg.state;
    if (msg.detail) b.title = msg.detail;
  }
}

// POSTs both keys; the route writes only the keys present in the body, and an
// explicitly empty one resets that key to its default (ui/server.mjs:1656).
async function saveSettings(root, projectsRoot, opts = {}) {
  if (!el.settingsSave) return;
  const r = await postSettingsCard({ root, projectsRoot }, {
    card: document.getElementById('root-settings-card'), paint: paintSettings,
    dirty: settingsCardDirty('settingsSave'), appliesWhen: 'New runs use these folders.', ...opts });
  // The root relocates the project registry + workflows; reload projects so
  // the UI reflects what's available under the new root.
  if (r.ok) loadProjects();
}

const settingsFieldValue = (node) => (node && node.value ? node.value.trim() : '');

if (el.settingsSave) {
  el.settingsSave.addEventListener('click', (e) => saveSettings(
    settingsFieldValue(el.settingsRoot), settingsFieldValue(el.settingsProjectsRoot), { button: e.currentTarget },
  ));
}
if (el.settingsReset) el.settingsReset.addEventListener('click', (e) => saveSettings('', '',
  { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' }));
settingsCardDirty('settingsSave');

// ---------------------------------------------------------------------------
// ⓘ info tooltips (settings). Content lives in each icon's hidden .tip-content
// span; ONE shared fixed-position bubble is created lazily and repositioned per
// icon — same layering as the stats chart tip (z-index 70). Delegated so icons
// added by future markup need no extra wiring. pointer-events:none on the
// bubble keeps mouseout from flickering when the tip overlaps the icon.
// aria-describedby ties the active icon to the bubble's stable #info-bubble id
// so its text — otherwise display:none and shadowed by the icon's own
// aria-label — reaches screen readers; infoTipIcon tracks which icon currently
// holds that attribute so hideInfoTip can clear it with no event target to read
// (e.g. when the router hides the tip on view switch).
let infoBubble = null;
let infoTipIcon = null;
function showInfoTip(icon) {
  const content = icon.querySelector('.tip-content');
  if (!content) return;
  if (!infoBubble) {
    infoBubble = document.createElement('div');
    infoBubble.className = 'info-bubble';
    infoBubble.id = 'info-bubble';
    infoBubble.setAttribute('role', 'tooltip');
    document.body.appendChild(infoBubble);
  }
  infoBubble.innerHTML = content.innerHTML;
  infoBubble.classList.remove('hidden');
  if (infoTipIcon && infoTipIcon !== icon) infoTipIcon.removeAttribute('aria-describedby');
  infoTipIcon = icon;
  icon.setAttribute('aria-describedby', 'info-bubble');
  // Below the icon, left-aligned; clamp into the viewport, flip above if the
  // bottom would overflow. (Zero-size rects under jsdom fall through safely.)
  // Reset any inline position left over from the previous icon first: a stale
  // `left` parked near the right edge shrinks the shrink-to-fit width the
  // getBoundingClientRect() below measures, squeezing the clamp math for
  // whichever icon shows next on a narrower window.
  infoBubble.style.left = '0px';
  infoBubble.style.top = '0px';
  const r = icon.getBoundingClientRect();
  const b = infoBubble.getBoundingClientRect();
  let left = r.left;
  let top = r.bottom + 8;
  const vw = window.innerWidth || 0;
  const vh = window.innerHeight || 0;
  if (left + b.width > vw - 12) left = Math.max(12, vw - b.width - 12);
  if (top + b.height > vh - 12 && r.top - b.height - 8 > 0) top = r.top - b.height - 8;
  infoBubble.style.left = `${left}px`;
  infoBubble.style.top = `${top}px`;
}
const hideInfoTip = () => {
  if (infoBubble) infoBubble.classList.add('hidden');
  if (infoTipIcon) { infoTipIcon.removeAttribute('aria-describedby'); infoTipIcon = null; }
};

// Palette cards share the settings bubble. Hover uses a ~250ms intent delay so
// dragging across the palette doesn't strobe tooltips; keyboard focus is instant.
// relatedTarget guards: mouseover/mouseout bubble through child elements (.phead,
// .pdesc), so a cursor move BETWEEN children of the same trigger must be a no-op
// — without the guard the bubble hides and re-arms on every crossing (strobe).
// contains(null/undefined) is false, so events with no relatedTarget still work.
const TIP_SELECTOR = '.info-tip, #gv-palette .ap';
let pillTipTimer = null;
document.addEventListener('mouseover', (e) => {
  const t = e.target.closest?.(TIP_SELECTOR);
  if (!t) return;
  if (t.contains(e.relatedTarget)) return; // moved between children of the same trigger
  if (t.classList.contains('agent-pill')) {
    clearTimeout(pillTipTimer);
    pillTipTimer = setTimeout(() => showInfoTip(t), 250);
  } else {
    clearTimeout(pillTipTimer);
    showInfoTip(t);
  }
});
document.addEventListener('mouseout', (e) => {
  const t = e.target.closest?.(TIP_SELECTOR);
  if (!t) return;
  if (t.contains(e.relatedTarget)) return; // still inside the same trigger
  clearTimeout(pillTipTimer);
  hideInfoTip();
});
document.addEventListener('focusin', (e) => {
  const t = e.target.closest?.(TIP_SELECTOR);
  if (t) { clearTimeout(pillTipTimer); showInfoTip(t); }
});
document.addEventListener('focusout', (e) => {
  if (e.target.closest?.(TIP_SELECTOR)) { clearTimeout(pillTipTimer); hideInfoTip(); }
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') { clearTimeout(pillTipTimer); hideInfoTip(); } });

// ---------------------------------------------------------------------------
// Settings: budget & cost limits card. Reads the three limit keys off the same
// /api/settings payload the root card uses, and renders the live spend readout
// from the /api/budget snapshot paintBudget() already keeps fresh.
// ---------------------------------------------------------------------------
function paintBudgetSettings(data) {
  el.budgetPerPipeline.value = data.pipelineCostLimitUsd ?? '';
  el.budgetTotal.value = data.totalCostLimitUsd ?? '';
  el.budgetResetPeriod.value = data.costLimitResetPeriod || 'monthly';
  el.budgetHumanRate.value = data.humanRateUsdPerHour ?? '';
  settingsCardPainted('budgetSave');
}

function paintBudgetReadout() {
  const b = budgetState.budget;
  if (!b || !el.budgetReadout) return;
  el.budgetReadout.replaceChildren(renderBudgetReadout(b,
    { fmt: { usd: fmtUsd, usd4: fmtUsd4, duration: fmtDuration, estTitle } }));
}

// '' -> null (no limit). NaN is the validation-failure marker: anything that is
// not a finite number of at least one cent.
function readBudgetField(input) {
  const v = input.value.trim();
  if (v === '') return null;
  const n = Number(v);
  if (!Number.isFinite(n) || n < 0.01) return NaN;
  return n;
}

const budgetCard = () => document.getElementById('budget-settings-card');
async function saveBudgetSettings(payload, opts = {}) {
  const r = await postSettingsCard(payload, { card: budgetCard(), paint: paintBudgetSettings, dirty: settingsCardDirty('budgetSave'), ...opts });
  if (r.ok) refreshBudget();                 // sidebar + readout repaint immediately
  return r;
}

if (el.budgetSave) {
  el.budgetSave.addEventListener('click', (e) => {
    clearFieldErrors(budgetCard());
    const fields = [el.budgetPerPipeline, el.budgetTotal, el.budgetHumanRate];
    const vals = fields.map(readBudgetField);
    const bad = fields.filter((_, i) => Number.isNaN(vals[i]));
    const [per, total, rate] = vals;
    if (bad.length) {
      bad.forEach((n, i) => fieldError(n, 'Enter at least $0.01, or leave it blank.', { focus: i === 0 }));
      return;
    }
    saveBudgetSettings({
      pipelineCostLimitUsd: per, totalCostLimitUsd: total,
      costLimitResetPeriod: el.budgetResetPeriod.value,
      humanRateUsdPerHour: rate,
    }, { button: e.currentTarget });
  });
}
// Clears both limits and leaves the reset period alone: POSTing `null` deletes
// the key server-side (the REST arm passes `body.x ?? ''` to the setter).
// The inputs are emptied without an event: after a failed post postSettingsCard's
// refresh shows the card as dirty; after a success paintBudgetSettings re-cleans it.
if (el.budgetReset) {
  el.budgetReset.addEventListener('click', (e) => {
    el.budgetPerPipeline.value = '';
    el.budgetTotal.value = '';
    saveBudgetSettings({ pipelineCostLimitUsd: null, totalCostLimitUsd: null },
      { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' });
  });
}
settingsCardDirty('budgetSave');

// ---- Ask Worca limits card (budget-card pattern above) ---------------------
// Shared by the small Settings cards (Ask Worca, Spawn diagnostics): one hint
// setter and one "POST /api/settings → parse → paint or show the error" routine,
// so a fix to the fetch/parse/error path lands in every card at once.
function setHintMsg(id, text, kind) {
  const n = document.getElementById(id);
  if (n) { n.textContent = text || ''; n.className = `hint${kind ? ` ${kind}` : ''}`; }
}
// #555: list-view result lines. A result of a user action (ok / err / warn / info) becomes
// a toast, so a reload that clears the line can no longer erase it. Plain text (progress such
// as "Installing…") stays on the inline line; '' clears it. Load / refresh paths and standing
// states pass 'err-inline' / 'warn-inline': they stay on the inline line (red / amber), because
// a toast per background refresh (window focus, WS frame) would be noise the user never asked for.
function reportStatus(line, base, text, kind, extra = {}) {
  if (kind === 'ok' || kind === 'err' || kind === 'warn' || kind === 'info') {
    if (line) { line.textContent = ''; line.className = base; }
    if (text) notify({ tone: kind, ...splitMessage(text), ...extra });
    return;
  }
  const inline = kind === 'err-inline' ? 'err' : kind === 'warn-inline' ? 'warn' : '';
  if (line) { line.textContent = text || ''; line.className = inline ? `${base} ${inline}` : base; }
}
// One Settings card save (#555): the clicked button shows busy → done; a server error with a
// `field` lands on the input that carries it in data-setting; anything else is a card alert
// above the buttons; a change that applies elsewhere also raises a toast. Never throws;
// resolves to { ok:true, data } | { ok:false, error, field } | { ok:false, skipped:true }.
// `gate` = this button is the card's dirty-gated Save (Reset passes gate:false, so it never
// locks itself disabled on a clean card).
async function postSettingsCard(body, opts = {}) {
  const { card = null, button = null, paint = null, dirty = null, gate = true, done = 'Saved', busy = 'Saving…', appliesWhen = '' } = opts;
  if (card) { clearFieldErrors(card); cardAlert(card, null); }
  // Every Settings caller passes `dirty` (its card's tracker), Reset included: success is
  // the only thing that marks a card clean when nothing repaints it (Chat; Away when
  // fetchAwayMode fails).
  const r = await withButton(button, async () => {
    let res;
    try {
      res = await fetch('/api/settings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    } catch (e) {
      return { ok: false, error: `Worca did not answer (${e.message || 'network error'}). Check it is still running, then try again.` };
    }
    const data = (await safeJson(res)) || {};
    if (!res.ok) return { ok: false, error: data.error || `The server answered ${res.status}.`, field: data.field || null };
    return { ok: true, data };
  }, { busy, done, idleDisabled: () => (gate && dirty ? !dirty.isDirty() : false) });
  if (r.skipped) return r;
  if (r.ok) {
    // A 2xx with an unparsable body yields {}: leave the card as the user set it.
    // Await the paint: the model-picker paints are async and rebuild their selects, so the clean
    // snapshot must be taken after them.
    if (paint && r.data && Object.keys(r.data).length) await paint(r.data);
    dirty?.markClean();
    if (appliesWhen) notify({ tone: 'ok', title: 'Saved', detail: appliesWhen });
    return r;
  }
  dirty?.refresh();                           // still dirty after a failure: Save is offered again
  if (!card) return r;                        // the caller reports (Away status strip)
  const targets = settingsFieldEls(card, r.field);
  if (targets.length) fieldError(targets, r.error);
  else cardAlert(card, { title: 'Not saved', detail: r.error });
  return r;
}

// The inputs a server `field` names: [data-setting~="<path>"] (space-separated tokens, so a
// port pair can share actions.portRange). The Away form keeps its own data-field (it is the
// key readNightForm posts), so nightMode.<key> resolves inside #night-mode-host by data-field.
// Inputs hidden inside the card (another level, a collapsed row) are skipped → the error becomes
// a card alert. Only the card's own subtree counts: a closed Settings tab hides every card on it.
function settingsFieldEls(card, field) {
  const f = String(field || '').replace(/["\\]/g, '');
  if (!card || !f) return [];
  let els = [...card.querySelectorAll(`[data-setting~="${f}"]`)];
  if (!els.length && f.startsWith('nightMode.')) {
    els = [...card.querySelectorAll(`#night-mode-host [data-field="${f.slice('nightMode.'.length).split('.')[0]}"]`)];
  }
  const hiddenInCard = (n) => {
    for (let x = n; x && x !== card; x = x.parentElement) if (x.hidden || x.classList.contains('hidden')) return true;
    return false;
  };
  return els.filter((n) => !hiddenInCard(n));
}

// Dirty trackers for the Settings cards, keyed by card id. `section.card`, not
// `.settings-card`: the Defragment model card is `section.card.mem-model-card` on purpose
// (tooltips census) and must still get one.
function settingsCardDirty(saveId) {
  const save = document.getElementById(saveId);
  const card = save?.closest('section.card');
  if (!card || !card.id) return null;
  if (!settingsDirty.has(card.id)) settingsDirty.set(card.id, trackDirty(card, { saveBtn: save }));
  return settingsDirty.get(card.id);
}

// #555: a card's paint just wrote the stored values: they are the new clean base.
function settingsCardPainted(saveId) { settingsCardDirty(saveId)?.markClean(); }

// ── Appearance (dark-mode design §5.3) ──────────────────────────────────────
// The mode lives in settings.json and is server-rendered into <html data-theme>
// for the first paint; this block keeps it live: the segmented control, the
// theme-color meta, the `worca:theme` event the thinking orb listens to, and
// the OS-change listener for system mode. Nothing is stored in this browser.
const THEME_MODES = ['system', 'light', 'dark'];
function syncThemeColorMeta() {
  const meta = document.querySelector('meta[name="theme-color"]');
  // Resolved by the browser; never getPropertyValue('--bg'), which is the raw light-dark() text.
  // `window.` — the bare global is not the jsdom window's under the test boots (house rule, app.js:5115).
  let bg = '';
  try { bg = window.getComputedStyle(document.body).backgroundColor || ''; } catch { bg = ''; }
  // A fully transparent background is "no colour": read the alpha rather than comparing
  // against a literal — spec §4.2 bans `rgba(` followed by a digit in browser JS (no longer
  // tested: the ui-js-colors guard is gone).
  const alpha = Number((/^rgba\(\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*([\d.]+)\s*\)$/.exec(bg) || [])[1] ?? '1');
  if (meta && bg && alpha > 0) meta.setAttribute('content', bg);
}
function applyTheme(mode) {
  const m = THEME_MODES.includes(mode) ? mode : 'system';
  document.documentElement.dataset.theme = m;
  syncThemeColorMeta();
  document.dispatchEvent(new window.CustomEvent('worca:theme', { detail: { mode: m } }));   // window.CustomEvent: jsdom rejects Node's
  return m;
}
const themeNotSaved = (detail) => notify({ tone: 'err', title: 'Theme not saved', detail, key: 'theme' });
let confirmedTheme = 'system';       // the last SERVER-confirmed mode (GET, POST 200, settings-changed)
let themeSeq = 0;                    // out-of-order POST resolutions never repaint a stale answer
function paintTheme(mode) {
  const m = applyTheme(mode);
  confirmedTheme = m;
  for (const b of document.querySelectorAll('#theme-seg button[data-theme-mode]')) {
    const on = b.dataset.themeMode === m;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
}
async function chooseTheme(mode) {
  const mine = ++themeSeq;
  const previous = confirmedTheme;
  applyTheme(mode);                                                        // optimistic (not a confirmation)
  for (const b of document.querySelectorAll('#theme-seg button[data-theme-mode]')) {
    b.classList.toggle('on', b.dataset.themeMode === mode); b.setAttribute('aria-pressed', b.dataset.themeMode === mode ? 'true' : 'false');
  }
  let res; let data;
  try {
    res = await fetch('/api/settings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ theme: mode }) });
    data = await safeJson(res);
  } catch (e) { if (mine === themeSeq) { paintTheme(previous); themeNotSaved(e.message || 'network error'); } return; }
  if (mine !== themeSeq) return;                                           // a later click owns the paint now
  if (!res.ok) {
    themeNotSaved(data.error || `The server answered ${res.status}.`);
    // Spec §5.3: paint what the SERVER holds, not what this tab guessed.
    // A non-2xx on that re-fetch yields {error} (safeJson never throws): fall back to the last
    // CONFIRMED mode, never to an undefined theme (applyTheme would normalise it to 'system').
    try { const d2 = await safeJson(await fetch('/api/settings')); if (mine === themeSeq) paintTheme(THEME_MODES.includes(d2.theme) ? d2.theme : previous); }
    catch { if (mine === themeSeq) paintTheme(previous); }
    return;
  }
  paintTheme(data.theme);
}
document.getElementById('theme-seg')?.addEventListener('click', (e) => {
  const btn = e.target.closest && e.target.closest('button[data-theme-mode]');
  if (btn) chooseTheme(btn.dataset.themeMode);
});
// Boot: the shell arrived with the stored mode on <html>; normalise it, sync the
// meta, tell the orb, and seed `confirmedTheme` + the seg buttons from it (paintTheme,
// not applyTheme: otherwise a click before the General GET resolves would remember
// 'system' as `previous`). No fetch — the server already rendered the right attribute.
// One worca:theme event fires here and none elsewhere at boot (boot routes to 'new';
// loadSettings runs only on the General tab and on settings-changed).
paintTheme(document.documentElement.dataset.theme);
// System mode: the OS can flip underneath; the CSS follows on its own, the meta
// and the orb need a nudge. Guarded — jsdom has no matchMedia.
try {
  const mq = typeof window.matchMedia === 'function' ? window.matchMedia('(prefers-color-scheme: dark)') : null;
  if (mq && typeof mq.addEventListener === 'function') mq.addEventListener('change', () => applyTheme(document.documentElement.dataset.theme));
} catch { /* no media queries here */ }

// ---- Alerts (Settings › General) ----
// This browser's choices (localStorage, no server round trip): painted at boot, and the
// permission prompt is raised only by the switch's own click.
mountAlertsCard({ doc: document, alerts });

// ---- Away mode (Settings › Runs) ----
// Settings › Away mode: the user layer (night-mode-form.mjs), its live summary and the status strip.
/** A GET /api/away-mode body, or null. Other UI tests' fetch stubs answer unknown URLs with
 *  unrelated JSON (e.g. {config:{steps}}), so check the shape, never just `config`. */
const isAwayBody = (d) => !!(d && d.config && typeof d.config === 'object' && typeof d.toggle === 'string');
async function fetchAwayMode(dir = null) {
  try {
    const r = await fetch(dir ? `/api/away-mode?projectDir=${encodeURIComponent(dir)}` : '/api/away-mode');
    if (!r || !r.ok) return null;
    const d = await r.json();
    return isAwayBody(d) ? d : null;
  } catch { return null; }
}
let _awayPaintSeq = 0;
// The catalog the Away mode forms' "Decided by" picker offers (fetchTitleModelCatalog): the last one fetched.
let awayModelCatalog = [];
// Held by reference: renderNightForm moves it below the summary, and every re-render detaches it first.
const awayStatusEl = document.getElementById('awayStatus');
/** Spec §7: the card always renders its fields. Before the first GET answers, or when it fails, paint the
 *  stored user layer from the /api/settings body; the summary then says "Away mode settings could not be read." */
function paintNightFallback(host, data) {
  const user = (data && data.nightMode && typeof data.nightMode === 'object') ? data.nightMode : {};
  const toggle = typeof data?.nightModeToggle === 'string' ? data.nightModeToggle : 'auto';
  paintAwayStatus(toggle, !!parseWindow(user.window));
  renderNightForm(host, { level: 'user', values: user, effective: data?.nightModeEffective || user, sources: {}, inherited: { config: null, sources: {} }, toggle, now: Date.now(), statusEl: awayStatusEl, models: awayModelCatalog });
  settingsCardPainted('nightModeSave');
}
async function paintNightSettings(data) {
  try {
    const host = document.getElementById('night-mode-host');
    if (!host) return;
    const seq = ++_awayPaintSeq;
    if (!host.firstChild && host.dataset.dirty !== '1') paintNightFallback(host, data);   // never a blank card while the GET is in flight
    const [d, models] = await Promise.all([fetchAwayMode(), fetchTitleModelCatalog()]);
    if (seq !== _awayPaintSeq) return;                       // a newer paint won
    awayModelCatalog = models;
    if (!d) { if (host.dataset.dirty !== '1' && data) paintNightFallback(host, data); return; }
    state.awayMode = d;
    paintAwayStatus(d.toggle, !!parseWindow(d.config.window));
    paintSideAway();
    if (host.dataset.dirty === '1') { updateAwaySummary(host, { toggle: d.toggle, hereSince: d.hereSince ?? null, now: Date.now(), inherited: d.inherited }); return; }   // keep unsaved edits
    renderNightForm(host, { level: 'user', values: d.user, effective: d.config, sources: d.sources, inherited: d.inherited, toggle: d.toggle, hereSince: d.hereSince ?? null, now: Date.now(), statusEl: awayStatusEl, models });
    // Never on the keep-dirty branch above: settings-changed from another card's save lands
    // here too, and re-cleaning would hide unsaved Away edits.
    settingsCardPainted('nightModeSave');
  } catch { /* the card keeps what it shows; never an unhandled rejection */ }
}
/** `hours` = away hours are set: without them no tip mentions them. */
function paintAwayStatus(toggle, hours = true) {
  const bar = awayStatusEl;
  if (!bar) return;
  bar.replaceChildren(...statusActions(toggle, { hours }).map((a) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'btn btn-mini'; b.textContent = a.label; b.title = a.tip; b.dataset.mode = a.mode;
    return b;
  }));
}
awayStatusEl?.addEventListener('click', async (e) => {
  const b = e.target.closest('button[data-mode]'); if (!b) return;
  // Only the toggle: the paint callback repaints the strip and the summary, never the unsaved fields.
  // No card and no tracker: the Away tracker would mark unsaved form edits clean. paintAwayStatus
  // rebuilds these buttons, so no button state either.
  const r = await postSettingsCard({ nightModeToggle: b.dataset.mode }, { paint: () => paintNightSettings(null) });
  if (!r.ok) {
    void paintNightSettings(null);
    notify({ tone: 'err', title: 'Away mode not changed', detail: r.error, key: 'away-mode' });
  }
});
function postNightSettings(body, opts = {}) {
  // The server emits settings-changed BEFORE it answers the POST, so the event's paint can run after
  // this one. Clear the dirty flag synchronously on success: whichever paint runs last re-renders the
  // saved values, and the form never stays stuck "dirty". When fetchAwayMode fails the repaint returns
  // early, and postSettingsCard's own markClean is what clears the card.
  const host = document.getElementById('night-mode-host');
  return postSettingsCard(body, {
    card: document.getElementById('night-settings-card'), dirty: settingsCardDirty('nightModeSave'),
    paint: () => { if (host) delete host.dataset.dirty; void paintNightSettings(null); },
    appliesWhen: 'The summary above is what will happen.', ...opts });
}
document.getElementById('nightModeSave')?.addEventListener('click', (e) => {
  postNightSettings({ nightMode: readNightForm(document.getElementById('night-mode-host'), { level: 'user' }) }, { button: e.currentTarget });
});
// "Use defaults" keeps today's body: it also returns the status to "follow my away hours".
document.getElementById('nightModeReset')?.addEventListener('click', (e) => postNightSettings({ nightMode: null, nightModeToggle: 'auto' },
  { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' }));
settingsCardDirty('nightModeSave');

// Settings › Runs › Scheduled runs: the defaults a new schedule inherits.

function paintScheduleSettings(data) {
  const d = data && data.schedule;
  const missed = document.getElementById('schedIfMissed');
  const grace = document.getElementById('schedGraceMin');
  const fails = document.getElementById('schedMaxFailures');
  if (!d || !missed || !grace || !fails) return;
  missed.value = d.ifMissed;
  if (![...grace.options].some((o) => o.value === String(d.graceMin))) grace.add(new Option(`${d.graceMin} minutes`, String(d.graceMin)));
  grace.value = String(d.graceMin);
  grace.disabled = d.ifMissed !== 'run';
  fails.value = String(d.maxFailures);
  settingsCardPainted('schedDefaultsSave');
}
function scheduleSettingsCard() { return document.getElementById('schedule-settings-card'); }
function postScheduleDefaults(body, opts = {}) {
  return postSettingsCard(body, { card: scheduleSettingsCard(), paint: paintScheduleSettings, dirty: settingsCardDirty('schedDefaultsSave'), ...opts });
}
function saveScheduleDefaults(e) {
  clearFieldErrors(scheduleSettingsCard());
  const failsEl = document.getElementById('schedMaxFailures');
  const raw = failsEl.value.trim();
  const n = raw === '' ? '' : Number(raw);
  if (n !== '' && (!Number.isInteger(n) || n < 0 || n > 100)) { fieldError(failsEl, 'Enter a whole number from 0 to 100.'); return; }
  postScheduleDefaults({
    schedule: { ifMissed: document.getElementById('schedIfMissed').value, graceMin: Number(document.getElementById('schedGraceMin').value), maxFailures: n },
  }, { button: e?.currentTarget || null });
}
document.getElementById('schedDefaultsSave')?.addEventListener('click', saveScheduleDefaults);
document.getElementById('schedDefaultsReset')?.addEventListener('click', (e) => postScheduleDefaults(
  { schedule: { ifMissed: '', graceMin: '', maxFailures: '' } }, { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' }));
settingsCardDirty('schedDefaultsSave');
document.getElementById('schedIfMissed')?.addEventListener('change', (e) => {
  const grace = document.getElementById('schedGraceMin');
  if (grace) grace.disabled = e.target.value !== 'run';
});

// Settings › Runs › Sync before run (#527): the instance defaults every project inherits.
function paintSyncSettings(data) {
  const d = data && data.sync;
  const before = document.getElementById('syncDefBeforeRun');
  const diverged = document.getElementById('syncDefOnDiverged');
  const remote = document.getElementById('syncDefRemote');
  const refresh = document.getElementById('syncDefRefresh');
  if (!d || !before || !diverged || !remote || !refresh) return;
  before.checked = d.beforeRun !== false;
  diverged.value = d.onDiverged;
  remote.value = d.remote || '';
  const mins = String(d.refreshMinutes);
  if (![...refresh.options].some((o) => o.value === mins)) {
    const opt = document.createElement('option');
    opt.value = mins; opt.textContent = `Every ${mins} minutes`;
    refresh.append(opt);
  }
  refresh.value = mins;
  settingsCardPainted('syncDefaultsSave');
}
function postSyncDefaults(body, opts = {}) {
  return postSettingsCard(body, { card: document.getElementById('sync-settings-card'), paint: paintSyncSettings, dirty: settingsCardDirty('syncDefaultsSave'), ...opts });
}
function saveSyncDefaults(e) {
  const remote = document.getElementById('syncDefRemote').value.trim();
  postSyncDefaults({
    sync: {
      beforeRun: document.getElementById('syncDefBeforeRun').checked,
      onDiverged: document.getElementById('syncDefOnDiverged').value,
      remote: remote || null,                            // empty = back to the default remote
      refreshMinutes: Number(document.getElementById('syncDefRefresh').value),
    },
  }, { button: e?.currentTarget || null });
}
document.getElementById('syncDefaultsSave')?.addEventListener('click', saveSyncDefaults);
document.getElementById('syncDefaultsReset')?.addEventListener('click', (e) => postSyncDefaults(
  { sync: null }, { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' }));
settingsCardDirty('syncDefaultsSave');

function paintAskSettings(data) {
  const turns = document.getElementById('askMaxTurns');
  const budget = document.getElementById('askMaxBudgetUsd');
  const noCap = document.getElementById('askNoCap');
  if (!turns || !budget || !noCap) return;
  turns.value = data.askMaxTurns == null ? '' : String(data.askMaxTurns);
  noCap.checked = data.askMaxBudgetUsd === null;
  budget.disabled = noCap.checked;
  budget.value = data.askMaxBudgetUsd == null ? '' : String(data.askMaxBudgetUsd);
  // W20: the chat's script tools ride the same payload (`chat`), so the card paints from
  // the GET and from every save response without a second fetch.
  const scriptHost = document.getElementById('ask-script-tools-host');
  if (scriptHost) scriptHost.replaceChildren(renderScriptToolsToggle({ prefs: data.chat || {} }, { doc: document }));
  // Web access: repainted from every GET and save response, which also resets its dirty flag.
  const webHost = document.getElementById('ask-web-host');
  if (webHost) webHost.replaceChildren(renderAskWebFields({ askWeb: data.askWeb }, { doc: document }));
  settingsCardPainted('askLimitsSave');
  void paintAskEngine(data);
}
let askEnginePaintSeq = 0;
/** Settings › Ask Worca › Engine & models (D17): the catalog's per-engine defaults are the "Worca default" placeholders.
 *  Another card's save repaints the page: unsaved edits in this card survive it (`force` is this card's own save), and
 *  only the latest paint lands — an older catalog fetch that resolves late never paints stale settings. */
async function paintAskEngine(data, { force = false } = {}) {
  const root = document.getElementById('ask-engine-root');
  if (!root) return;
  if (!force && Object.keys(readAskEngineSection(root)).length) return;
  const seq = ++askEnginePaintSeq;
  let cat = null;
  try { cat = await safeJson(await fetch('/api/ask/models')); } catch { cat = null; }
  if (seq !== askEnginePaintSeq) return;
  if (!force && Object.keys(readAskEngineSection(root)).length) return;   // the user started editing while it loaded
  const catalog = Array.isArray(cat?.models) ? cat.models.map((m) => ({ ...m, engine: m.engine || 'claude' })) : [];
  renderAskEngineSection(root, { catalog, askEngine: data.askEngine ?? undefined, askModels: data.askModels || {}, defaults: cat?.defaults || {} });
}
function askLimitsCard() { return document.getElementById('ask-settings-card'); }
function postAskLimits(body, opts = {}) {
  return postSettingsCard(body, { card: askLimitsCard(), paint: paintAskSettings, dirty: settingsCardDirty('askLimitsSave'), ...opts });
}
function saveAskLimits(e) {
  clearFieldErrors(askLimitsCard());
  const turnsEl = document.getElementById('askMaxTurns');
  const capEl = document.getElementById('askMaxBudgetUsd');
  const turnsRaw = turnsEl.value.trim();
  const noCap = document.getElementById('askNoCap').checked;
  const budgetRaw = capEl.value.trim();
  let askMaxTurns = '';
  if (turnsRaw !== '') {
    const n = Number(turnsRaw);
    if (!Number.isInteger(n) || n < 1 || n > 500) { fieldError(turnsEl, 'Enter a whole number from 1 to 500, or leave it blank.'); return; }
    askMaxTurns = n;
  }
  let askMaxBudgetUsd = '';
  if (noCap) askMaxBudgetUsd = null;
  else if (budgetRaw !== '') {
    const b = Number(budgetRaw);
    if (!Number.isFinite(b) || b < 0.1 || b > 100) { fieldError(capEl, 'Enter an amount from 0.1 to 100, or tick No cap.'); return; }
    askMaxBudgetUsd = b;
  }
  const scriptHost = document.getElementById('ask-script-tools-host');
  const webHost = document.getElementById('ask-web-host');
  const askWebBody = webHost ? collectAskWebFields(webHost) : null;   // null = the web fields were not touched
  postAskLimits({ askMaxTurns, askMaxBudgetUsd,
    ...(scriptHost ? { chat: collectScriptToolsToggle(scriptHost) } : {}),
    ...(askWebBody ? { askWeb: askWebBody } : {}) }, { button: e?.currentTarget || null });
}
document.getElementById('askLimitsSave')?.addEventListener('click', saveAskLimits);
document.getElementById('askEngineSave')?.addEventListener('click', (e) => {
  const body = askPatchToSettingsBody(readAskEngineSection(document.getElementById('ask-engine-root')));
  if (!Object.keys(body).length) { setHintMsg('askEngineMsg', 'Nothing changed.', ''); return; }
  setHintMsg('askEngineMsg', '', '');
  // Only this card repaints: the other Ask cards keep whatever the user is editing there.
  postSettingsCard(body, { card: document.getElementById('ask-engine-card'), button: e.currentTarget, gate: false,
    paint: (data) => paintAskEngine(data, { force: true }), appliesWhen: 'New chats use this.' });
});
document.getElementById('askLimitsReset')?.addEventListener('click', (e) => postAskLimits(
  { askMaxTurns: '', askMaxBudgetUsd: '' },
  { button: e.currentTarget, gate: false, busy: 'Resetting…', done: 'Reset' }));
settingsCardDirty('askLimitsSave');
document.getElementById('askNoCap')?.addEventListener('change', () => {
  const budget = document.getElementById('askMaxBudgetUsd');
  if (budget) budget.disabled = document.getElementById('askNoCap').checked;
});

// ---- Ask Worca chat history (same card, same hint pattern) -----------------
// The counts line paints with the settings view; the destructive button refetches
// GET /api/ask/history so the dialog quotes what is about to go, then one bulk
// DELETE /api/ask/threads. The server broadcasts ask-history-cleared afterwards
// — the ask panel resets itself off that frame, nothing to do here.
function setAskHistoryMsg(text, kind) {
  reportStatus(document.getElementById('askHistoryMsg'), 'hint', text, kind);
}
function askHistoryCount(n, one, many = `${one}s`) {
  return `${n} ${n === 1 ? one : many}`;
}
function normalizeAskHistory(data) {
  const num = (v) => (Number.isInteger(v) && v > 0 ? v : 0);
  return { threads: num(data?.threads), worktrees: num(data?.worktrees), attachments: num(data?.attachments), inFlight: num(data?.inFlight) };
}
function paintAskHistory(counts) {
  const line = document.getElementById('askHistoryCounts');
  const btn = document.getElementById('askHistoryDelete');
  if (!line || !btn) return;
  line.textContent = counts.threads
    ? `${askHistoryCount(counts.threads, 'chat')} · ${askHistoryCount(counts.worktrees, 'worktree')}`
    : 'No saved chats.';
  btn.disabled = counts.threads === 0;
}
async function fetchAskHistory() {
  const res = await fetch('/api/ask/history');
  const data = await safeJson(res);
  if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
  return normalizeAskHistory(data);
}
async function loadAskHistory() {
  if (!document.getElementById('askHistoryCounts')) return;
  try { paintAskHistory(await fetchAskHistory()); } catch (e) { setAskHistoryMsg(e.message, 'err-inline'); }
}
// One bullet per non-zero count; the in-progress line only when a turn is live.
function askHistoryConfirmMessage(c) {
  const lines = ['This permanently deletes all Ask Worca chat history:'];
  if (c.threads) lines.push(`• ${askHistoryCount(c.threads, 'chat thread')} and ${c.threads === 1 ? 'its transcript' : 'their transcripts'}`);
  if (c.worktrees) {
    lines.push(`• ${askHistoryCount(c.worktrees, 'git worktree')} checked out for ${c.threads === 1 ? 'that chat' : 'those chats'} (removed from ${c.worktrees === 1 ? 'its source repo' : 'their source repos'})`);
  }
  if (c.attachments) lines.push(`• ${askHistoryCount(c.attachments, 'attachment')}`);
  if (c.inFlight) lines.push(`• ${askHistoryCount(c.inFlight, 'chat')} currently in progress will be stopped`);
  lines.push('Runs started from these chats are not affected. This cannot be undone.');
  return lines.join('\n');
}
async function deleteAskHistory() {
  setAskHistoryMsg('');
  let counts;
  try { counts = await fetchAskHistory(); } catch (e) { setAskHistoryMsg(e.message, 'err'); return; }
  paintAskHistory(counts);
  if (!counts.threads) return;   // emptied meanwhile — nothing to confirm
  const ok = await confirmModal({
    title: 'Delete all chat history?',
    message: askHistoryConfirmMessage(counts),
    confirmLabel: 'Delete everything',
    danger: true,
  });
  if (!ok) return;
  let res = null;
  try {
    res = await fetch('/api/ask/threads', { method: 'DELETE' });
  } catch { setAskHistoryMsg('network error', 'err'); return; }
  const data = await safeJson(res);
  if (!res.ok) { setAskHistoryMsg(data.error || `HTTP ${res.status}`, 'err'); await loadAskHistory(); return; }
  const removed = normalizeAskHistory(data.removed);
  const failed = Array.isArray(data.failed) ? data.failed.length : 0;
  const summary = `Deleted ${askHistoryCount(removed.threads, 'chat')} and ${askHistoryCount(removed.worktrees, 'worktree')}.`;
  if (failed) setAskHistoryMsg(`${summary} ${askHistoryCount(failed, 'chat')} could not be removed.`, 'err');
  else setAskHistoryMsg(summary, 'ok');
  await loadAskHistory();
}
document.getElementById('askHistoryDelete')?.addEventListener('click', deleteAskHistory);

// ---- Spawn-debug diagnostics card (shares the Ask card's helpers above) ----
// The checkbox is the STORED preference; the note says when the environment
